use super::kind::SyntaxKind;
use std::rc::Rc;

#[derive(Debug, Clone, PartialEq)]
pub struct SyntaxError {
    pub message: String,
    pub hints: Vec<String>,
}

#[derive(Debug, Clone)]
pub struct SyntaxNode {
    pub kind: SyntaxKind,
    pub text: Rc<str>,
    pub children: Vec<SyntaxNode>,
    pub len: usize,
    pub offset: usize,
    pub error: Option<Box<SyntaxError>>,
    pub erroneous: bool,
}

impl Default for SyntaxNode {
    fn default() -> Self {
        SyntaxNode::leaf(SyntaxKind::End, "")
    }
}

impl SyntaxNode {
    pub fn leaf(kind: SyntaxKind, text: &str) -> Self {
        SyntaxNode {
            kind,
            text: Rc::from(text),
            children: vec![],
            len: text.len(),
            offset: 0,
            error: None,
            erroneous: kind == SyntaxKind::Error,
        }
    }
    pub fn inner(kind: SyntaxKind, children: Vec<SyntaxNode>) -> Self {
        let len = children.iter().map(|c| c.len).sum();
        let erroneous = children.iter().any(|c| c.erroneous);
        SyntaxNode { kind, text: Rc::from(""), children, len, offset: 0, error: None, erroneous }
    }
    pub fn error(message: impl Into<String>, text: &str) -> Self {
        let mut n = SyntaxNode::leaf(SyntaxKind::Error, text);
        n.error = Some(Box::new(SyntaxError { message: message.into(), hints: vec![] }));
        n.erroneous = true;
        n
    }
    pub fn is_leaf(&self) -> bool {
        self.children.is_empty() && self.kind != SyntaxKind::Error || (self.kind == SyntaxKind::Error && self.children.is_empty())
    }
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    pub fn kind(&self) -> SyntaxKind {
        self.kind
    }
    pub fn text(&self) -> &str {
        &self.text
    }
    /// Full source text of this node (concatenation of leaves).
    pub fn full_text(&self) -> String {
        if self.children.is_empty() {
            self.text.to_string()
        } else {
            let mut s = String::new();
            for c in &self.children {
                s.push_str(&c.full_text());
            }
            s
        }
    }
    pub fn hint(&mut self, hint: impl Into<String>) {
        if let Some(e) = &mut self.error {
            e.hints.push(hint.into());
        }
    }
    pub fn convert_to_kind(&mut self, kind: SyntaxKind) {
        self.kind = kind;
    }
    pub fn convert_to_error(&mut self, message: impl Into<String>) {
        if self.kind != SyntaxKind::Error {
            let text = self.full_text();
            *self = SyntaxNode::error(message, &text);
        }
    }
    pub fn expected(&mut self, expected: &str) {
        let kind = self.kind;
        let text = self.full_text();
        self.convert_to_error(format!("expected {}, found {}", expected, kind.name()));
        if kind.is_keyword() && matches!(expected, "identifier" | "pattern") {
            self.hint(format!(
                "keyword `{text}` is not allowed as an identifier; try `{text}_` instead"
            ));
        }
    }
    pub fn unexpected(&mut self) {
        let kind = self.kind;
        self.convert_to_error(format!("unexpected {}", kind.name()));
    }

    /// Assign offsets to all nodes.
    pub fn number(&mut self, mut offset: usize) {
        self.offset = offset;
        if !self.children.is_empty() {
            for c in &mut self.children {
                c.number(offset);
                offset += c.len;
            }
        }
    }

    pub fn range(&self) -> (usize, usize) {
        (self.offset, self.offset + self.len)
    }

    /// Collect all syntax errors in tree order.
    pub fn errors(&self) -> Vec<(SyntaxError, usize, usize)> {
        let mut out = vec![];
        self.collect_errors(&mut out);
        out
    }
    fn collect_errors(&self, out: &mut Vec<(SyntaxError, usize, usize)>) {
        if !self.erroneous {
            return;
        }
        if let Some(e) = &self.error {
            out.push(((**e).clone(), self.offset, self.offset + self.len));
            return;
        }
        for c in &self.children {
            c.collect_errors(out);
        }
    }

    // Helpers for AST access
    pub fn cast_first(&self, kind: SyntaxKind) -> Option<&SyntaxNode> {
        self.children.iter().find(|c| c.kind == kind)
    }
    pub fn exprs(&self) -> impl Iterator<Item = &SyntaxNode> {
        self.children.iter().filter(|c| is_expr_kind(c.kind))
    }
}

pub fn is_expr_kind(k: SyntaxKind) -> bool {
    use SyntaxKind::*;
    matches!(
        k,
        Text | Space | Linebreak | Parbreak | Escape | Shorthand | SmartQuote | Strong | Emph
            | Raw | Link | Label | Ref | Heading | ListItem | EnumItem | TermItem | Equation
            | Math | MathText | MathIdent | MathShorthand | MathAlignPoint | MathDelimited
            | MathAttach | MathPrimes | MathFrac | MathRoot | Ident | None | Auto | Bool | Int
            | Float | Numeric | Str | CodeBlock | ContentBlock | Parenthesized | Array | Dict
            | Unary | Binary | FieldAccess | FuncCall | Closure | LetBinding | SetRule | ShowRule
            | Contextual | Conditional | WhileLoop | ForLoop | ModuleImport | ModuleInclude
            | LoopBreak | LoopContinue | FuncReturn | DestructAssignment
    )
}
EOF
echo ok"}

