use super::kind::SyntaxKind;
use super::node::SyntaxNode;

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum LexMode {
    Markup,
    Math,
    Code,
}

#[derive(Clone)]
pub struct Lexer<'s> {
    pub text: &'s str,
    pub cursor: usize,
    pub mode: LexMode,
    pub newline: bool,
    error: Option<(String, Vec<String>)>,
}

pub fn is_newline(c: char) -> bool {
    matches!(c, '\n' | '\x0B' | '\x0C' | '\r' | '\u{0085}' | '\u{2028}' | '\u{2029}')
}

pub fn is_combining(c: char) -> bool {
    let u = c as u32;
    matches!(u, 0x0300..=0x036F | 0x0483..=0x0489 | 0x0591..=0x05BD | 0x0610..=0x061A | 0x064B..=0x065F
        | 0x0670 | 0x06D6..=0x06DC | 0x06DF..=0x06E4 | 0x0900..=0x0903 | 0x093A..=0x094F
        | 0x0951..=0x0957 | 0x0962..=0x0963 | 0x0981..=0x0983 | 0x09BC..=0x09D7
        | 0x0E31 | 0x0E34..=0x0E3A | 0x0E47..=0x0E4E | 0x1AB0..=0x1AFF | 0x1DC0..=0x1DFF
        | 0x200C..=0x200D | 0x20D0..=0x20FF | 0xFE00..=0xFE0F | 0xFE20..=0xFE2F | 0xE0100..=0xE01EF
        | 0x302A..=0x302F | 0x3099..=0x309A)
}

pub fn is_xid_start(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphabetic();
    }
    c.is_alphabetic() && !is_combining(c)
}

pub fn is_xid_continue(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    (c.is_alphanumeric() || is_combining(c) || c == '\u{00B7}') && !matches!(c, '\u{200C}' | '\u{200D}')
        || (is_combining(c) && !matches!(c, '\u{200C}' | '\u{200D}' | '\u{FE00}'..='\u{FE0F}'))
}

pub fn is_id_start(c: char) -> bool {
    is_xid_start(c) || c == '_'
}

pub fn is_id_continue(c: char) -> bool {
    is_xid_continue(c) || c == '_' || c == '-'
}

pub fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    chars.next().is_some_and(is_id_start) && chars.all(is_id_continue)
}

pub fn is_math_id_start(c: char) -> bool {
    is_xid_start(c)
}

pub fn is_math_id_continue(c: char) -> bool {
    is_xid_continue(c) && c != '_'
}

pub fn is_valid_in_label_literal(c: char) -> bool {
    is_id_continue(c) || matches!(c, ':' | '.')
}

pub fn is_cjk_script(c: char) -> bool {
    let u = c as u32;
    matches!(u, 0x1100..=0x11FF | 0x2E80..=0x2FDF | 0x3005 | 0x3007 | 0x3021..=0x3029 | 0x3038..=0x303B
        | 0x3040..=0x30FF | 0x3130..=0x318F | 0x31A0..=0x31BF | 0x31F0..=0x31FF | 0x3400..=0x4DBF
        | 0x4E00..=0x9FFF | 0xA960..=0xA97F | 0xAC00..=0xD7FF | 0xF900..=0xFAFF | 0xFF66..=0xFF9F
        | 0xFFA0..=0xFFDC | 0x1B000..=0x1B16F | 0x20000..=0x3134F)
}

fn keyword(ident: &str) -> Option<SyntaxKind> {
    Some(match ident {
        "none" => SyntaxKind::None,
        "auto" => SyntaxKind::Auto,
        "true" => SyntaxKind::Bool,
        "false" => SyntaxKind::Bool,
        "not" => SyntaxKind::Not,
        "and" => SyntaxKind::And,
        "or" => SyntaxKind::Or,
        "let" => SyntaxKind::Let,
        "set" => SyntaxKind::Set,
        "show" => SyntaxKind::Show,
        "context" => SyntaxKind::Context,
        "if" => SyntaxKind::If,
        "else" => SyntaxKind::Else,
        "for" => SyntaxKind::For,
        "in" => SyntaxKind::In,
        "while" => SyntaxKind::While,
        "break" => SyntaxKind::Break,
        "continue" => SyntaxKind::Continue,
        "return" => SyntaxKind::Return,
        "import" => SyntaxKind::Import,
        "include" => SyntaxKind::Include,
        "as" => SyntaxKind::As,
        _ => return Option::None,
    })
}

pub fn count_newlines(s: &str) -> usize {
    let mut n = 0;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if is_newline(c) {
            if c == '\r' && chars.peek() == Some(&'\n') {
                chars.next();
            }
            n += 1;
        }
    }
    n
}

/// Split text at newlines (\r\n counts as one).
pub fn split_newlines(text: &str) -> Vec<&str> {
    let mut out = vec![];
    let bytes: Vec<(usize, char)> = text.char_indices().collect();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        let (idx, c) = bytes[i];
        if is_newline(c) {
            out.push(&text[start..idx]);
            let mut end = idx + c.len_utf8();
            if c == '\r' && i + 1 < bytes.len() && bytes[i + 1].1 == '\n' {
                end += 1;
                i += 1;
            }
            start = end;
        }
        i += 1;
    }
    out.push(&text[start..]);
    out
}

impl<'s> Lexer<'s> {
    pub fn new(text: &'s str, mode: LexMode) -> Self {
        Lexer { text, cursor: 0, mode, newline: false, error: None }
    }

    // ---- scanner helpers ----
    fn peek(&self) -> Option<char> {
        self.text[self.cursor..].chars().next()
    }
    fn after(&self) -> &'s str {
        &self.text[self.cursor..]
    }
    fn before(&self) -> &'s str {
        &self.text[..self.cursor]
    }
    fn done(&self) -> bool {
        self.cursor >= self.text.len()
    }
    fn eat(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.cursor += c.len_utf8();
        Some(c)
    }
    fn uneat(&mut self) {
        if let Some(c) = self.before().chars().next_back() {
            self.cursor -= c.len_utf8();
        }
    }
    fn at_str(&self, s: &str) -> bool {
        self.after().starts_with(s)
    }
    fn at_fn(&self, f: impl Fn(char) -> bool) -> bool {
        self.peek().is_some_and(f)
    }
    fn at_char(&self, c: char) -> bool {
        self.peek() == Some(c)
    }
    fn eat_if_str(&mut self, s: &str) -> bool {
        if self.at_str(s) {
            self.cursor += s.len();
            true
        } else {
            false
        }
    }
    fn eat_if_char(&mut self, c: char) -> bool {
        if self.at_char(c) {
            self.cursor += c.len_utf8();
            true
        } else {
            false
        }
    }
    fn eat_if_fn(&mut self, f: impl Fn(char) -> bool) -> bool {
        if let Some(c) = self.peek() {
            if f(c) {
                self.cursor += c.len_utf8();
                return true;
            }
        }
        false
    }
    fn eat_while(&mut self, f: impl Fn(char) -> bool) -> &'s str {
        let start = self.cursor;
        while let Some(c) = self.peek() {
            if f(c) {
                self.cursor += c.len_utf8();
            } else {
                break;
            }
        }
        &self.text[start..self.cursor]
    }
    fn eat_until(&mut self, mut f: impl FnMut(char) -> bool) -> &'s str {
        let start = self.cursor;
        while let Some(c) = self.peek() {
            if f(c) {
                break;
            }
            self.cursor += c.len_utf8();
        }
        &self.text[start..self.cursor]
    }
    /// scout(n): char at relative char offset n (n=-1 previous char, 0 next char, 1 the one after).
    fn scout(&self, n: isize) -> Option<char> {
        if n >= 0 {
            self.after().chars().nth(n as usize)
        } else {
            self.before().chars().rev().nth((-n - 1) as usize)
        }
    }
    fn from(&self, start: usize) -> &'s str {
        &self.text[start.min(self.cursor)..self.cursor]
    }
    fn eat_newline(&mut self) -> bool {
        if self.eat_if_str("\r\n") {
            return true;
        }
        self.eat_if_fn(is_newline)
    }

    pub fn jump(&mut self, idx: usize) {
        self.cursor = idx;
    }

    pub fn column(&self, index: usize) -> usize {
        self.text[..index].chars().rev().take_while(|&c| !is_newline(c)).count()
    }

    fn error(&mut self, msg: impl Into<String>) -> SyntaxKind {
        self.error = Some((msg.into(), vec![]));
        SyntaxKind::Error
    }
    fn hint(&mut self, h: impl Into<String>) {
        if let Some((_, hints)) = &mut self.error {
            hints.push(h.into());
        }
    }

    pub fn next(&mut self) -> (SyntaxKind, SyntaxNode) {
        self.newline = false;
        self.error = None;
        let start = self.cursor;
        let (kind, node) = match self.eat() {
            Some(c) if self.is_space(c) => (self.whitespace(start, c), None),
            Some('#') if start == 0 && self.eat_if_char('!') => (self.shebang(), None),
            Some('/') if self.eat_if_char('/') => (self.line_comment(), None),
            Some('/') if self.eat_if_char('*') => (self.block_comment(), None),
            Some('*') if self.eat_if_char('/') => {
                let k = self.error("unexpected end of block comment");
                self.hint("consider escaping the `*` with a backslash or opening the block comment with `/*`");
                (k, None)
            }
            Some('`') if self.mode != LexMode::Math => self.raw(start),
            Some(c) => match self.mode {
                LexMode::Markup => (self.markup(start, c), None),
                LexMode::Math => self.math(start, c),
                LexMode::Code => (self.code(start, c), None),
            },
            None => (SyntaxKind::End, None),
        };
        let text = self.from(start);
        let node = match node {
            Some(n) => n,
            None => match self.error.take() {
                Some((msg, hints)) => {
                    let mut n = SyntaxNode::error(msg, text);
                    for h in hints {
                        n.hint(h);
                    }
                    n
                }
                None => SyntaxNode::leaf(kind, text),
            },
        };
        (node.kind, node)
    }

    fn is_space(&self, c: char) -> bool {
        match self.mode {
            LexMode::Markup => matches!(c, ' ' | '\t') || is_newline(c),
            _ => c.is_whitespace(),
        }
    }

    fn whitespace(&mut self, start: usize, c: char) -> SyntaxKind {
        let mode = self.mode;
        let more = self.eat_while(|c| match mode {
            LexMode::Markup => matches!(c, ' ' | '\t') || is_newline(c),
            _ => c.is_whitespace(),
        });
        let newlines = match c {
            ' ' if more.is_empty() => 0,
            _ => count_newlines(self.from(start)),
        };
        self.newline = newlines > 0;
        if self.mode == LexMode::Markup && newlines >= 2 {
            SyntaxKind::Parbreak
        } else {
            SyntaxKind::Space
        }
    }

    fn shebang(&mut self) -> SyntaxKind {
        self.eat_until(is_newline);
        SyntaxKind::Shebang
    }

    fn line_comment(&mut self) -> SyntaxKind {
        self.eat_until(is_newline);
        SyntaxKind::LineComment
    }

    fn block_comment(&mut self) -> SyntaxKind {
        let mut state = '_';
        let mut depth = 1;
        while let Some(c) = self.eat() {
            state = match (state, c) {
                ('*', '/') => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                    '_'
                }
                ('/', '*') => {
                    depth += 1;
                    '_'
                }
                _ => c,
            }
        }
        SyntaxKind::BlockComment
    }

    // ---------------- raw ----------------
    fn raw(&mut self, start: usize) -> (SyntaxKind, Option<SyntaxNode>) {
        let mut backticks = 1;
        while self.eat_if_char('`') {
            backticks += 1;
        }
        if backticks == 2 {
            let nodes = vec![
                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
                SyntaxNode::leaf(SyntaxKind::RawDelim, "`"),
            ];
            return (SyntaxKind::Raw, Some(SyntaxNode::inner(SyntaxKind::Raw, nodes)));
        }
        let mut found = 0;
        while found < backticks {
            match self.eat() {
                Some('`') => found += 1,
                Some(_) => found = 0,
                None => {
                    let n = SyntaxNode::error("unclosed raw text", self.from(start));
                    return (SyntaxKind::Error, Some(n));
                }
            }
        }
        let end = self.cursor;
        let mut nodes: Vec<SyntaxNode> = Vec::new();
        let mut prev_start = start;
        // opening delim
        self.cursor = start + backticks;
        nodes.push(SyntaxNode::leaf(SyntaxKind::RawDelim, &self.text[prev_start..self.cursor]));
        prev_start = self.cursor;
        let inner_end = end - backticks;
        if backticks >= 3 {
            self.blocky_raw(inner_end, &mut nodes, &mut prev_start);
        } else {
            self.inline_raw(inner_end, &mut nodes, &mut prev_start);
        }
        self.cursor = end;
        nodes.push(SyntaxNode::leaf(SyntaxKind::RawDelim, &self.text[prev_start..self.cursor]));
        (SyntaxKind::Raw, Some(SyntaxNode::inner(SyntaxKind::Raw, nodes)))
    }

    fn push_raw(&self, kind: SyntaxKind, nodes: &mut Vec<SyntaxNode>, prev_start: &mut usize) {
        nodes.push(SyntaxNode::leaf(kind, &self.text[*prev_start..self.cursor]));
        *prev_start = self.cursor;
    }

    fn blocky_raw(&mut self, inner_end: usize, nodes: &mut Vec<SyntaxNode>, prev: &mut usize) {
        if self.eat_if_fn(is_id_start) {
            self.eat_while(is_id_continue);
            self.push_raw(SyntaxKind::RawLang, nodes, prev);
        }
        self.eat_if_char(' ');
        let inner = &self.text[self.cursor..inner_end];
        let mut lines = split_newlines(inner);
        let dedent = {
            let mut candidates: Vec<usize> = lines
                .iter()
                .skip(1)
                .filter(|line| !line.chars().all(char::is_whitespace))
                .map(|line| line.chars().take_while(|c| c.is_whitespace()).count())
                .collect();
            if let Some(last) = lines.last() {
                if lines.len() > 1 || true {
                    candidates.push(last.chars().take_while(|c| c.is_whitespace()).count());
                }
            }
            candidates.into_iter().min().unwrap_or(0)
        };
        if inner.trim_end().ends_with('`') {
            if let Some(last) = lines.last_mut() {
                *last = last.strip_suffix(' ').unwrap_or(last);
            }
        }
        let is_ws = |line: &str| line.chars().all(char::is_whitespace);
        let starts_whitespace = lines.first().is_some_and(|l| is_ws(l));
        let ends_whitespace = lines.last().is_some_and(|l| is_ws(l));
        let mut skipped = false;
        let mut idx = 0;
        let mut end_idx = lines.len();
        if starts_whitespace {
            self.cursor += lines[0].len();
            idx = 1;
            skipped = true;
        }
        if ends_whitespace && end_idx > idx {
            end_idx -= 1;
        }
        let mut i = 0;
        while idx < end_idx {
            let line = lines[idx];
            let d = if i == 0 && !skipped { 0 } else { dedent };
            let offset: usize = line.chars().take(d).map(char::len_utf8).sum();
            self.eat_newline();
            self.cursor += offset;
            self.push_raw(SyntaxKind::RawTrimmed, nodes, prev);
            self.cursor += line.len() - offset;
            self.push_raw(SyntaxKind::Text, nodes, prev);
            idx += 1;
            i += 1;
        }
        if self.cursor < inner_end {
            self.cursor = inner_end;
            self.push_raw(SyntaxKind::RawTrimmed, nodes, prev);
        }
    }

    fn inline_raw(&mut self, inner_end: usize, nodes: &mut Vec<SyntaxNode>, prev: &mut usize) {
        while self.cursor < inner_end {
            if self.at_fn(is_newline) {
                self.push_raw(SyntaxKind::Text, nodes, prev);
                self.eat_newline();
                self.push_raw(SyntaxKind::RawTrimmed, nodes, prev);
                continue;
            }
            self.eat();
        }
        self.push_raw(SyntaxKind::Text, nodes, prev);
    }

    // ---------------- markup ----------------
    fn markup(&mut self, start: usize, c: char) -> SyntaxKind {
        match c {
            '\\' => self.backslash(),
            'h' if self.eat_if_str("ttp://") => self.link(),
            'h' if self.eat_if_str("ttps://") => self.link(),
            '<' if self.at_fn(is_id_continue) => self.label(),
            '@' if self.at_fn(is_id_continue) => self.ref_marker(),
            '.' if self.eat_if_str("..") => SyntaxKind::Shorthand,
            '-' if self.eat_if_str("--") => SyntaxKind::Shorthand,
            '-' if self.eat_if_char('-') => SyntaxKind::Shorthand,
            '-' if self.eat_if_char('?') => SyntaxKind::Shorthand,
            '-' if self.at_fn(|c| c.is_numeric()) => SyntaxKind::Shorthand,
            '*' if !self.in_word() => SyntaxKind::Star,
            '_' if !self.in_word() => SyntaxKind::Underscore,
            '#' => SyntaxKind::Hash,
            '[' => SyntaxKind::LeftBracket,
            ']' => SyntaxKind::RightBracket,
            '\'' => SyntaxKind::SmartQuote,
            '"' => SyntaxKind::SmartQuote,
            '$' => SyntaxKind::Dollar,
            '~' => SyntaxKind::Shorthand,
            ':' => SyntaxKind::Colon,
            '=' => {
                self.eat_while(|c| c == '=');
                if self.space_or_end() {
                    SyntaxKind::HeadingMarker
                } else {
                    self.text()
                }
            }
            '-' if self.space_or_end() => SyntaxKind::ListMarker,
            '+' if self.space_or_end() => SyntaxKind::EnumMarker,
            '/' if self.space_or_end() => SyntaxKind::TermMarker,
            '0'..='9' => self.numbering(start),
            _ => self.text(),
        }
    }

    fn backslash(&mut self) -> SyntaxKind {
        if self.eat_if_str("u{") {
            let hex = self.eat_while(|c| c.is_ascii_alphanumeric());
            if !self.eat_if_char('}') {
                return self.error("unclosed Unicode escape sequence");
            }
            if u32::from_str_radix(hex, 16).ok().and_then(char::from_u32).is_none() {
                return self.error(format!("invalid Unicode codepoint: {}", hex));
            }
            return SyntaxKind::Escape;
        }
        if self.done() || self.at_fn(char::is_whitespace) {
            SyntaxKind::Linebreak
        } else {
            self.eat();
            SyntaxKind::Escape
        }
    }

    fn link(&mut self) -> SyntaxKind {
        let (link, balanced) = link_prefix(self.after());
        self.cursor += link.len();
        if !balanced {
            return self.error("automatic links cannot contain unbalanced brackets");
        }
        SyntaxKind::Link
    }

    fn numbering(&mut self, start: usize) -> SyntaxKind {
        self.eat_while(|c| c.is_ascii_digit());
        let read = self.from(start);
        if self.eat_if_char('.') && self.space_or_end() && read.parse::<u64>().is_ok() {
            return SyntaxKind::EnumMarker;
        }
        self.text()
    }

    fn ref_marker(&mut self) -> SyntaxKind {
        self.eat_while(is_valid_in_label_literal);
        while matches!(self.scout(-1), Some('.' | ':')) {
            self.uneat();
        }
        SyntaxKind::RefMarker
    }

    fn label(&mut self) -> SyntaxKind {
        let label = self.eat_while(is_valid_in_label_literal);
        if label.is_empty() {
            return self.error("label cannot be empty");
        }
        if !self.eat_if_char('>') {
            return self.error("unclosed label");
        }
        SyntaxKind::Label
    }

    fn text(&mut self) -> SyntaxKind {
        fn special(c: char) -> bool {
            c.is_whitespace()
                || matches!(
                    c,
                    '\\' | '/' | '[' | ']' | '~' | '-' | '.' | '\'' | '"' | '*' | '_' | ':' | 'h'
                        | '`' | '$' | '<' | '>' | '@' | '#'
                )
        }
        loop {
            self.eat_until(special);
            let save = self.cursor;
            let cont = match self.eat() {
                Some(' ') if self.at_fn(char::is_alphanumeric) => true,
                Some('/') if !self.at_char('/') && !self.at_char('*') => true,
                Some('-') if !self.at_char('-') && !self.at_char('?') => true,
                Some('.') if !self.at_str("..") => true,
                Some('h') if !self.at_str("ttp://") && !self.at_str("ttps://") => true,
                Some('@') if !self.at_fn(is_valid_in_label_literal) => true,
                _ => false,
            };
            if !cont {
                self.cursor = save;
                break;
            }
        }
        SyntaxKind::Text
    }

    fn in_word(&self) -> bool {
        let wordy = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() && !is_cjk_script(c));
        let prev = self.scout(-2);
        let next = self.peek();
        wordy(prev) && wordy(next)
    }

    fn space_or_end(&self) -> bool {
        self.done() || self.at_fn(char::is_whitespace) || self.at_str("//") || self.at_str("/*")
    }

    // ---------------- math ----------------
    fn math(&mut self, start: usize, c: char) -> (SyntaxKind, Option<SyntaxNode>) {
        let kind = match c {
            '\\' => self.backslash(),
            '"' => self.string(),
            '-' if self.eat_if_str(">>") => SyntaxKind::MathShorthand,
            '-' if self.eat_if_char('>') => SyntaxKind::MathShorthand,
            '-' if self.eat_if_str("->") => SyntaxKind::MathShorthand,
            ':' if self.eat_if_char('=') => SyntaxKind::MathShorthand,
            ':' if self.eat_if_str(":=") => SyntaxKind::MathShorthand,
            '!' if self.eat_if_char('=') => SyntaxKind::MathShorthand,
            '.' if self.eat_if_str("..") => SyntaxKind::MathShorthand,
            '[' if self.eat_if_char('|') => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("==>") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("-->") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("--") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("-<") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("->") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("<-") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("<<") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("=>") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("==") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_str("~~") => SyntaxKind::MathShorthand,
            '<' if self.eat_if_char('=') => SyntaxKind::MathShorthand,
            '<' if self.eat_if_char('<') => SyntaxKind::MathShorthand,
            '<' if self.eat_if_char('-') => SyntaxKind::MathShorthand,
            '<' if self.eat_if_char('~') => SyntaxKind::MathShorthand,
            '>' if self.eat_if_str("->") => SyntaxKind::MathShorthand,
            '>' if self.eat_if_str(">>") => SyntaxKind::MathShorthand,
            '=' if self.eat_if_str("=>") => SyntaxKind::MathShorthand,
            '=' if self.eat_if_char('>') => SyntaxKind::MathShorthand,
            '=' if self.eat_if_char(':') => SyntaxKind::MathShorthand,
            '>' if self.eat_if_char('=') => SyntaxKind::MathShorthand,
            '>' if self.eat_if_char('>') => SyntaxKind::MathShorthand,
            '|' if self.eat_if_str("->") => SyntaxKind::MathShorthand,
            '|' if self.eat_if_str("=>") => SyntaxKind::MathShorthand,
            '|' if self.eat_if_char(']') => SyntaxKind::MathShorthand,
            '|' if self.eat_if_char('|') => SyntaxKind::MathShorthand,
            '~' if self.eat_if_str("~>") => SyntaxKind::MathShorthand,
            '~' if self.eat_if_char('>') => SyntaxKind::MathShorthand,
            '*' | '-' | '~' => SyntaxKind::MathShorthand,
            '.' => SyntaxKind::Dot,
            ',' => SyntaxKind::Comma,
            ';' => SyntaxKind::Semicolon,
            ')' => SyntaxKind::RightParen,
            '#' => SyntaxKind::Hash,
            '_' => SyntaxKind::Underscore,
            '$' => SyntaxKind::Dollar,
            '/' => SyntaxKind::Slash,
            '^' => SyntaxKind::Hat,
            '\'' => SyntaxKind::Prime,
            '&' => SyntaxKind::MathAlignPoint,
            '√' | '∛' | '∜' => SyntaxKind::Root,
            c if is_math_id_start(c) && self.at_fn(is_math_id_continue) => {
                self.eat_while(is_math_id_continue);
                return self.math_ident_or_field(start);
            }
            _ => self.math_text(start, c),
        };
        (kind, None)
    }

    fn math_ident_or_field(&mut self, start: usize) -> (SyntaxKind, Option<SyntaxNode>) {
        let mut kind = SyntaxKind::MathIdent;
        let mut node = SyntaxNode::leaf(kind, self.from(start));
        while let Some(ident) = self.maybe_dot_ident() {
            kind = SyntaxKind::FieldAccess;
            let children = vec![
                node,
                SyntaxNode::leaf(SyntaxKind::Dot, "."),
                SyntaxNode::leaf(SyntaxKind::Ident, ident),
            ];
            node = SyntaxNode::inner(kind, children);
        }
        (kind, Some(node))
    }

    fn maybe_dot_ident(&mut self) -> Option<&'s str> {
        if self.scout(1).is_some_and(is_math_id_start) && self.eat_if_char('.') {
            let ident_start = self.cursor;
            self.eat();
            self.eat_while(is_math_id_continue);
            Some(&self.text[ident_start..self.cursor])
        } else {
            None
        }
    }

    fn math_text(&mut self, start: usize, c: char) -> SyntaxKind {
        if c.is_numeric() {
            self.eat_while(char::is_numeric);
            let save = self.cursor;
            if self.eat_if_char('.') && !self.eat_while(char::is_numeric).is_empty() {
            } else {
                self.cursor = save;
            }
            SyntaxKind::MathText
        } else {
            let len = crate::unicode::first_grapheme_len(&self.text[start..]);
            self.cursor = start + len;
            if len > c.len_utf8() {
                SyntaxKind::Text
            } else {
                SyntaxKind::MathText
            }
        }
    }

    pub fn maybe_math_named_arg(&mut self, start: usize) -> Option<SyntaxNode> {
        let cursor = self.cursor;
        self.cursor = start;
        if self.eat_if_fn(is_id_start) {
            self.eat_while(is_id_continue);
            if self.at_char(':') && !self.at_str(":=") && !self.at_str("::=") {
                let text = self.from(start);
                let node = if text != "_" {
                    SyntaxNode::leaf(SyntaxKind::Ident, text)
                } else {
                    SyntaxNode::error("expected identifier, found underscore", text)
                };
                return Some(node);
            }
        }
        self.cursor = cursor;
        None
    }

    pub fn maybe_math_spread_arg(&mut self, start: usize) -> Option<SyntaxNode> {
        let cursor = self.cursor;
        self.cursor = start;
        if self.eat_if_str("..") {
            if !self.space_or_end() && !self.at_char('.') {
                return Some(SyntaxNode::leaf(SyntaxKind::Dots, self.from(start)));
            }
        }
        self.cursor = cursor;
        None
    }

    // ---------------- code ----------------
    fn code(&mut self, start: usize, c: char) -> SyntaxKind {
        match c {
            '<' if self.at_fn(is_id_continue) => self.label(),
            '0'..='9' => self.number(start, c),
            '.' if self.at_fn(|c| c.is_ascii_digit()) => self.number(start, c),
            '"' => self.string(),
            '=' if self.eat_if_char('=') => SyntaxKind::EqEq,
            '!' if self.eat_if_char('=') => SyntaxKind::ExclEq,
            '<' if self.eat_if_char('=') => SyntaxKind::LtEq,
            '>' if self.eat_if_char('=') => SyntaxKind::GtEq,
            '+' if self.eat_if_char('=') => SyntaxKind::PlusEq,
            '-' | '\u{2212}' if self.eat_if_char('=') => SyntaxKind::HyphEq,
            '*' if self.eat_if_char('=') => SyntaxKind::StarEq,
            '/' if self.eat_if_char('=') => SyntaxKind::SlashEq,
            '.' if self.eat_if_char('.') => SyntaxKind::Dots,
            '=' if self.eat_if_char('>') => SyntaxKind::Arrow,
            '{' => SyntaxKind::LeftBrace,
            '}' => SyntaxKind::RightBrace,
            '[' => SyntaxKind::LeftBracket,
            ']' => SyntaxKind::RightBracket,
            '(' => SyntaxKind::LeftParen,
            ')' => SyntaxKind::RightParen,
            '$' => SyntaxKind::Dollar,
            ',' => SyntaxKind::Comma,
            ';' => SyntaxKind::Semicolon,
            ':' => SyntaxKind::Colon,
            '.' => SyntaxKind::Dot,
            '+' => SyntaxKind::Plus,
            '-' | '\u{2212}' => SyntaxKind::Minus,
            '*' => SyntaxKind::Star,
            '/' => SyntaxKind::Slash,
            '=' => SyntaxKind::Eq,
            '<' => SyntaxKind::Lt,
            '>' => SyntaxKind::Gt,
            c if is_id_start(c) => self.ident(start),
            c => self.error(format!("the character `{c}` is not valid in code")),
        }
    }

    fn ident(&mut self, start: usize) -> SyntaxKind {
        self.eat_while(is_id_continue);
        let ident = self.from(start);
        let prev = &self.text[..start];
        if !(prev.ends_with('.') || prev.ends_with('@')) || prev.ends_with("..") {
            if let Some(k) = keyword(ident) {
                return k;
            }
        }
        if ident == "_" {
            SyntaxKind::Underscore
        } else {
            SyntaxKind::Ident
        }
    }

    fn number(&mut self, mut start: usize, c: char) -> SyntaxKind {
        let mut base = 10;
        if c == '0' {
            if self.eat_if_char('b') {
                base = 2;
            } else if self.eat_if_char('o') {
                base = 8;
            } else if self.eat_if_char('x') {
                base = 16;
            }
            if base != 10 {
                start = self.cursor;
            }
        }
        if base == 16 {
            self.eat_while(|c| c.is_ascii_alphanumeric());
        } else {
            self.eat_while(|c| c.is_ascii_digit());
        }
        if c != '.'
            && !self.at_str("..")
            && !self.scout(1).is_some_and(is_id_start)
            && base == 10
            && self.eat_if_char('.')
        {
            self.eat_while(|c| c.is_ascii_digit());
        }
        if base == 10 && !self.at_str("em") && (self.at_char('e') || self.at_char('E')) {
            self.eat();
            if !self.eat_if_char('+') {
                self.eat_if_char('-');
            }
            self.eat_while(|c| c.is_ascii_digit());
        }
        let suffix_start = self.cursor;
        if !self.eat_if_char('%') {
            self.eat_while(|c| c.is_ascii_alphanumeric());
        }
        let number = &self.text[start..suffix_start];
        let suffix = &self.text[suffix_start..self.cursor];
        let kind = if i64::from_str_radix(number, base).is_ok() {
            SyntaxKind::Int
        } else if base == 10 && parse_float(number).is_some() {
            SyntaxKind::Float
        } else {
            return self.error(match base {
                2 => format!("invalid binary number: 0b{}", number),
                8 => format!("invalid octal number: 0o{}", number),
                16 => format!("invalid hexadecimal number: 0x{}", number),
                _ => format!("invalid floating point number: {}", number),
            });
        };
        if suffix.is_empty() {
            return kind;
        }
        if !matches!(suffix, "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "em" | "fr" | "%") {
            return self.error(format!("invalid number suffix: {}", suffix));
        }
        if base != 10 {
            let k = self.error(format!("invalid base-{base} prefix"));
            self.hint("numbers with a unit cannot have a base prefix");
            return k;
        }
        SyntaxKind::Numeric
    }

    fn string(&mut self) -> SyntaxKind {
        let mut escaped = false;
        self.eat_until(|c| {
            let stop = c == '"' && !escaped;
            escaped = c == '\\' && !escaped;
            stop
        });
        if !self.eat_if_char('"') {
            return self.error("unclosed string");
        }
        SyntaxKind::Str
    }
}

pub fn parse_float(s: &str) -> Option<f64> {
    if s.is_empty() {
        return None;
    }
    // Rust's parse accepts things like "inf"/"nan" which can't occur here.
    s.parse::<f64>().ok()
}

pub fn link_prefix(text: &str) -> (&str, bool) {
    let mut brackets: Vec<char> = Vec::new();
    let mut end = 0;
    for (i, c) in text.char_indices() {
        let ok = match c {
            '0'..='9' | 'a'..='z' | 'A'..='Z' | '!' | '#' | '$' | '%' | '&' | '*' | '+' | ','
            | '-' | '.' | '/' | ':' | ';' | '=' | '?' | '@' | '_' | '~' | '\'' => true,
            '[' => {
                brackets.push('[');
                true
            }
            '(' => {
                brackets.push('(');
                true
            }
            ']' => brackets.pop() == Some('['),
            ')' => brackets.pop() == Some('('),
            _ => false,
        };
        if !ok {
            break;
        }
        end = i + c.len_utf8();
    }
    let mut s = &text[..end];
    while let Some(c) = s.chars().next_back() {
        if matches!(c, '!' | ',' | '.' | ':' | ';' | '?' | '\'') {
            s = &s[..s.len() - 1];
        } else {
            break;
        }
    }
    (s, brackets.is_empty())
}
