/// Whether there is a grapheme boundary between `prev` and `next` given context.
fn is_boundary(chars: &[char], i: usize, ri_count: usize) -> bool {
    // boundary between chars[i-1] and chars[i]
    let prev = chars[i - 1];
    let next = chars[i];
    if prev == '\r' && next == '\n' {
        return false;
