//! Diagnostics.

#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, Default)]
pub struct Span {
    pub file: u16, // 0 = detached
    pub start: u32,
    pub end: u32,
}

impl Span {
    pub const fn detached() -> Self {
        Span { file: 0, start: 0, end: 0 }
    }
    pub fn new(file: u16, start: usize, end: usize) -> Self {
        Span { file, start: start as u32, end: end as u32 }
    }
    pub fn is_detached(&self) -> bool {
        self.file == 0
    }
    pub fn or(self, other: Span) -> Span {
        if self.is_detached() { other } else { self }
    }
}

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub severity: Severity,
    pub span: Span,
    pub message: String,
    pub hints: Vec<String>,
    pub trace: Vec<(Span, String)>,
}

impl Diag {
    pub fn error(span: Span, message: impl Into<String>) -> Self {
        Diag { severity: Severity::Error, span, message: message.into(), hints: vec![], trace: vec![] }
    }
    pub fn warning(span: Span, message: impl Into<String>) -> Self {
        Diag { severity: Severity::Warning, span, message: message.into(), hints: vec![], trace: vec![] }
    }
    pub fn with_hint(mut self, hint: impl Into<String>) -> Self {
        self.hints.push(hint.into());
        self
    }
}

pub type SourceResult<T> = Result<T, Vec<Diag>>;

/// An error message with hints, without span.
#[derive(Debug, Clone)]
pub struct HintedString {
    pub message: String,
    pub hints: Vec<String>,
}

impl HintedString {
    pub fn new(message: impl Into<String>) -> Self {
        HintedString { message: message.into(), hints: vec![] }
