/// Ordered dictionary.
#[derive(Debug, Clone, Default)]
pub struct Dict {
    entries: Vec<(Str, Value)>,
    index: HashMap<Str, usize>,
}

impl Dict {
    pub fn new() -> Self {
        Dict::default()
    }
    pub fn len(&self) -> usize {
        self.entries.len()
    }
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.index.get(key).map(|&i| &self.entries[i].1)
    }
    pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        match self.index.get(key) {
            Some(&i) => Some(&mut self.entries[i].1),
            None => None,
        }
    }
    pub fn contains(&self, key: &str) -> bool {
        self.index.contains_key(key)
    }
    pub fn insert(&mut self, key: Str, value: Value) {
        if let Some(&i) = self.index.get(&key) {
            self.entries[i].1 = value;
        } else {
            self.index.insert(key.clone(), self.entries.len());
            self.entries.push((key, value));
        }
    }
    pub fn remove(&mut self, key: &str) -> Option<Value> {
        let i = self.index.remove(key)?;
        let (_, v) = self.entries.remove(i);
        for (_, idx) in self.index.iter_mut() {
            if *idx > i {
                *idx -= 1;
            }
        }
        Some(v)
    }
    pub fn iter(&self) -> impl DoubleEndedIterator<Item = &(Str, Value)> {
        self.entries.iter()
    }
    pub fn keys(&self) -> impl Iterator<Item = &Str> {
        self.entries.iter().map(|(k, _)| k)
    }
    pub fn values(&self) -> impl Iterator<Item = &Value> {
        self.entries.iter().map(|(_, v)| v)
    }
    pub fn entries(&self) -> &[(Str, Value)] {
        &self.entries
    }
    pub fn from_vec(v: Vec<(Str, Value)>) -> Self {
        let mut d = Dict::new();
        for (k, val) in v {
            d.insert(k, val);
        }
        d
    }
    pub fn sort_by(&mut self, f: impl FnMut(&(Str, Value), &(Str, Value)) -> std::cmp::Ordering) {
        self.entries.sort_by(f);
        self.reindex();
    }
    pub fn retain(&mut self, mut f: impl FnMut(&Str, &Value) -> bool) {
        self.entries.retain(|(k, v)| f(k, v));
        self.reindex();
    }
    fn reindex(&mut self) {
        self.index.clear();
        for (i, (k, _)) in self.entries.iter().enumerate() {
            self.index.insert(k.clone(), i);
        }
    }
}

