//! Repr and display formatting.

use crate::value::*;

pub const MINUS: char = '\u{2212}';

pub fn round_prec(v: f64, p: i32) -> f64 {
    if v.is_infinite() || v.is_nan() {
        return v;
    }
    let off = 10f64.powi(p);
    let r = (v * off).round() / off;
    if r.is_finite() { r } else { v }
}

/// Rust Debug formatting of floats (always with separator).
pub fn float_debug(v: f64) -> String {
    format!("{:?}", v)
}

/// Rust Display formatting for floats.
pub fn float_display(v: f64) -> String {
    format!("{}", v)
}

pub fn repr_float(v: f64) -> String {
    if v.is_nan() {
        "float.nan".into()
    } else if v.is_infinite() {
        if v > 0.0 { "float.inf".into() } else { "-float.inf".into() }
    } else {
        float_debug(v)
    }
}

/// Display of a float (as with str()).
pub fn display_float(v: f64) -> String {
    if v.is_nan() {
        "NaN".into()
    } else if v.is_infinite() {
        if v > 0.0 { "∞".into() } else { format!("{MINUS}∞") }
    } else if v < 0.0 {
        format!("{MINUS}{}", float_display(-v))
    } else {
        float_display(v.abs())
    }
}

pub fn display_int(v: i64) -> String {
    if v < 0 {
        format!("{MINUS}{}", (v as i128).abs())
    } else {
        v.to_string()
    }
}

/// Format a float with precision 2 and a unit, using ASCII minus.
pub fn repr_with_unit(v: f64, unit: &str) -> String {
    let r = round_prec(v, 2);
    if r.is_nan() {
        return format!("NaN{unit}");
    }
    if r.is_infinite() {
        return format!("{}∞{unit}", if r < 0.0 { "-" } else { "" });
    }
    let s = float_display(r.abs());
    if r < 0.0 {
        format!("-{s}{unit}")
    } else {
        format!("{s}{unit}")
    }
}

pub fn repr_length(l: &Length) -> String {
    if l.em == 0.0 {
        repr_with_unit(l.abs, "pt")
    } else if l.abs == 0.0 {
        repr_with_unit(l.em, "em")
    } else {
        format!("{} + {}", repr_with_unit(l.abs, "pt"), repr_with_unit(l.em, "em"))
    }
}

pub fn repr_ratio(r: f64) -> String {
    repr_with_unit(r * 100.0, "%")
}

pub fn repr_angle(rad: f64) -> String {
    repr_with_unit(rad.to_degrees(), "deg")
}

pub fn repr_rel(r: &Rel) -> String {
    format!("{} + {}", repr_ratio(r.rel), repr_length(&r.abs))
}

pub fn repr_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\0' => out.push_str("\\u{0}"),
            '\'' => out.push('\''),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c if is_escaped_unicode(c) => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn is_escaped_unicode(c: char) -> bool {
    // Rust's char::escape_debug escapes grapheme extenders and non-printable chars.
    let u = c as u32;
    matches!(u, 0x80..=0x9f | 0xad | 0x300..=0x36f | 0x200b..=0x200f | 0x2028..=0x202e | 0x2060..=0x2064
        | 0xfe00..=0xfe0f | 0xfeff | 0xe0000..=0xe007f | 0xe0100..=0xe01ef)
}

pub fn pretty_array_like(parts: &[String], trailing_comma: bool) -> String {
    let list_width: usize = parts.iter().map(|s| s.len()).sum::<usize>() + 2 * parts.len().saturating_sub(1);
    let mut buf = String::from("(");
    if list_width > 50 || parts.iter().any(|p| p.contains('\n')) {
        buf.push('\n');
        for part in parts {
            for line in part.split('\n') {
                buf.push_str("  ");
                buf.push_str(line);
                buf.push('\n');
            }
            // put comma after the last line
            buf.pop();
            buf.push_str(",\n");
        }
    } else {
        buf.push_str(&parts.join(", "));
        if trailing_comma {
            buf.push(',');
        }
    }
    buf.push(')');
    buf
}

pub fn repr_dict_key(k: &str) -> String {
    if crate::syntax::lexer::is_ident(k) {
        k.to_string()
    } else {
        repr_str(k)
    }
}

pub fn repr(v: &Value) -> String {
    match v {
        Value::None => "none".into(),
        Value::Auto => "auto".into(),
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => repr_float(*f),
        Value::Length(l) => repr_length(l),
        Value::Angle(a) => repr_angle(*a),
        Value::Ratio(r) => repr_ratio(*r),
        Value::Relative(r) => repr_rel(r),
        Value::Fraction(f) => repr_with_unit(*f, "fr"),
        Value::Color(c) => crate::color::repr_color(c),
        Value::Gradient(g) => g.repr.clone(),
        Value::Tiling(t) => crate::visualize::repr_tiling(t),
        Value::Symbol(s) => crate::symbols::repr_symbol(s),
        Value::Version(v) => {
            let parts: Vec<String> = v.0.iter().map(|x| x.to_string()).collect();
            format!("version{}", pretty_array_like(&parts, false))
        }
        Value::Str(s) => repr_str(s),
        Value::Bytes(b) => format!("bytes({})", b.len()),
        Value::Label(l) => repr_label(l),
        Value::Datetime(d) => crate::datetime::repr_datetime(d),
        Value::Decimal(d) => format!("decimal({})", repr_str(&crate::decimal::display(d))),
        Value::Duration(d) => crate::datetime::repr_duration(d),
        Value::Content(c) => c.repr(),
        Value::Styles(_) => "styles(..)".into(),
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(repr).collect();
            pretty_array_like(&parts, a.len() == 1)
        }
        Value::Dict(d) => {
            if d.is_empty() {
                return "(:)".into();
            }
            let parts: Vec<String> =
                d.iter().map(|(k, v)| format!("{}: {}", repr_dict_key(k), repr(v))).collect();
            pretty_array_like(&parts, false)
        }
        Value::Func(f) => f.repr(),
        Value::Args(a) => {
            let mut parts = vec![];
            for arg in &a.items {
                match &arg.name {
                    Some(n) => parts.push(format!("{}: {}", n, repr(&arg.value))),
                    None => parts.push(repr(&arg.value)),
                }
            }
            format!("arguments{}", pretty_array_like(&parts, false))
        }
        Value::Type(t) => t.repr(),
        Value::Module(m) => format!("<module {}>", m.name),
        Value::Alignment(a) => repr_alignment(a),
        Value::Direction(d) => d.name().into(),
        Value::Stroke(s) => crate::visualize::repr_stroke(s),
        Value::Selector(s) => crate::introspect::repr_selector(s),
        Value::Counter(c) => crate::introspect::repr_counter(c),
        Value::State(s) => format!("state({}, {})", repr_str(&s.key), repr(&s.init)),
        Value::Location(_) => "location(..)".into(),
        Value::Regex(r) => format!("regex({})", repr_str(r.as_str())),
    }
}

pub fn repr_label(l: &str) -> String {
    if !l.is_empty() && l.chars().all(crate::syntax::lexer::is_valid_in_label_literal) {
        format!("<{l}>")
    } else {
        format!("label({})", repr_str(l))
    }
}

pub fn repr_alignment(a: &Alignment) -> String {
    match (a.x, a.y) {
        (Some(x), Some(y)) => format!("{} + {}", x.name(), y.name()),
        (Some(x), None) => x.name().into(),
        (None, Some(y)) => y.name().into(),
        (None, None) => "none".into(),
    }
}

/// Display for `str()` conversion (only for convertible types).
pub fn display_for_str(v: &Value) -> Option<String> {
    Some(match v {
        Value::Int(i) => display_int(*i),
        Value::Float(f) => display_float(*f),
        Value::Decimal(d) => crate::decimal::display_signed(d),
        Value::Version(v) => v.0.iter().map(|x| x.to_string()).collect::<Vec<_>>().join("."),
        Value::Str(s) => s.to_string(),
        Value::Label(l) => l.to_string(),
        Value::Type(t) => t.long_name().into(),
        Value::Symbol(s) => s.text.to_string(),
        _ => return None,
    })
}
