//! Content.

use crate::diag::Span;
use crate::elements::{self, Elem};
use crate::repr::{pretty_array_like, repr};
use crate::value::*;
use std::rc::Rc;

#[derive(Debug, Clone)]
pub struct Content(pub Rc<ContentInner>);

#[derive(Debug, Clone)]
pub struct ContentInner {
    pub elem: &'static Elem,
    pub fields: Vec<(&'static str, Value)>,
    pub label: Option<Str>,
    pub span: Span,
    pub location: Option<Location>,
    pub prepared: bool,
}

/// A style entry.
#[derive(Debug, Clone)]
pub enum Style {
    Property { elem: &'static Elem, field: &'static str, value: Value, span: Span },
    Recipe(Rc<Recipe>),
    /// Revocation or other internal markers.
    Internal(Str),
}

#[derive(Debug, Clone)]
pub struct Recipe {
    pub selector: Option<Value>,
    pub transform: Value,
    pub span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Styles(pub Rc<Vec<Style>>);

impl Styles {
    pub fn new() -> Self {
        Styles(Rc::new(vec![]))
    }
    pub fn from(v: Vec<Style>) -> Self {
        Styles(Rc::new(v))
    }
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
}

impl PartialEq for Content {
    fn eq(&self, other: &Self) -> bool {
        if Rc::ptr_eq(&self.0, &other.0) {
            return true;
        }
        if !std::ptr::eq(self.0.elem, other.0.elem) {
            return false;
        }
        if self.0.label != other.0.label {
            return false;
        }
        if self.0.fields.len() != other.0.fields.len() {
            return false;
        }
        for ((a, va), (b, vb)) in self.0.fields.iter().zip(other.0.fields.iter()) {
            if a != b || !crate::ops::equal(va, vb) {
                return false;
            }
        }
        true
    }
}

impl Content {
    pub fn new(elem: &'static Elem) -> Self {
        Content(Rc::new(ContentInner {
            elem,
            fields: vec![],
            label: None,
            span: Span::detached(),
            location: None,
            prepared: false,
        }))
    }

    pub fn empty() -> Self {
        Content::sequence(vec![])
    }

    pub fn elem(&self) -> &'static Elem {
        self.0.elem
    }

    pub fn is(&self, name: &str) -> bool {
        self.0.elem.name == name
    }

    pub fn func_name(&self) -> &'static str {
        self.0.elem.name
    }

    pub fn span(&self) -> Span {
        self.0.span
    }

    pub fn spanned(mut self, span: Span) -> Self {
        if self.0.span.is_detached() {
            Rc::make_mut(&mut self.0).span = span;
        }
        self
    }

    pub fn label(&self) -> Option<&Str> {
        self.0.label.as_ref()
    }

    pub fn labelled(mut self, label: Str) -> Self {
        Rc::make_mut(&mut self.0).label = Some(label);
        self
    }

    pub fn location(&self) -> Option<Location> {
        self.0.location
    }

    pub fn set_location(&mut self, loc: Location) {
        Rc::make_mut(&mut self.0).location = Some(loc);
    }

    pub fn get(&self, name: &str) -> Option<&Value> {
        self.0.fields.iter().find(|(n, _)| *n == name).map(|(_, v)| v)
    }

    pub fn has(&self, name: &str) -> bool {
        self.get(name).is_some() || (name == "label" && self.0.label.is_some())
    }

    pub fn fields_mut(&mut self) -> &mut Vec<(&'static str, Value)> {
        &mut Rc::make_mut(&mut self.0).fields
    }

    /// Set a field, keeping canonical order.
    pub fn set(&mut self, name: &str, value: Value) {
        let elem = self.0.elem;
        let inner = Rc::make_mut(&mut self.0);
        if let Some(slot) = inner.fields.iter_mut().find(|(n, _)| *n == name) {
            slot.1 = value;
            return;
        }
        let order = elem.field_index(name);
        let static_name = elem.field_name(name);
        let pos = inner
            .fields
            .iter()
            .position(|(n, _)| elem.field_index(n) > order)
            .unwrap_or(inner.fields.len());
        inner.fields.insert(pos, (static_name, value));
    }

    pub fn with(mut self, name: &str, value: impl Into<Value>) -> Self {
        self.set(name, value.into());
        self
    }

    pub fn remove(&mut self, name: &str) {
        let inner = Rc::make_mut(&mut self.0);
        inner.fields.retain(|(n, _)| *n != name);
    }

    pub fn text(s: impl AsRef<str>) -> Self {
        Content::new(&elements::TEXT).with("text", Value::str(s))
    }

    pub fn symbol(s: impl AsRef<str>) -> Self {
        Content::new(&elements::SYMBOL).with("text", Value::str(s))
    }

    pub fn space() -> Self {
        Content::new(&elements::SPACE)
    }

    pub fn sequence(children: Vec<Content>) -> Self {
        Content::new(&elements::SEQUENCE)
            .with("children", Value::array(children.into_iter().map(Value::Content).collect()))
    }

    /// Like sequence but returns the single child if only one.
    pub fn sequence_or_single(mut children: Vec<Content>) -> Self {
        if children.len() == 1 {
            children.pop().unwrap()
        } else {
            Content::sequence(children)
        }
    }

    pub fn styled(self, styles: Styles) -> Self {
        Content::new(&elements::STYLED).with("child", Value::Content(self)).with("styles", Value::Styles(styles))
    }

    pub fn is_sequence(&self) -> bool {
        std::ptr::eq(self.0.elem, &elements::SEQUENCE)
    }

    pub fn is_styled(&self) -> bool {
        std::ptr::eq(self.0.elem, &elements::STYLED)
    }

    pub fn children(&self) -> Vec<Content> {
        match self.get("children") {
            Some(Value::Array(a)) => a
                .iter()
                .filter_map(|v| match v {
                    Value::Content(c) => Some(c.clone()),
                    _ => None,
                })
                .collect(),
            _ => vec![],
        }
    }

    pub fn is_empty_seq(&self) -> bool {
        self.is_sequence() && self.children().is_empty()
    }

    /// Joining content: flatten sequences.
    pub fn add(self, other: Content) -> Content {
        let mut children = vec![];
        if self.is_sequence() && self.0.label.is_none() {
            children.extend(self.children());
        } else {
            children.push(self);
        }
        if other.is_sequence() && other.0.label.is_none() {
            children.extend(other.children());
        } else {
            children.push(other);
        }
        Content::sequence(children)
    }

    pub fn body(&self) -> Option<Content> {
        match self.get("body") {
            Some(Value::Content(c)) => Some(c.clone()),
            _ => None,
        }
    }

    pub fn get_str(&self, name: &str) -> Option<Str> {
        match self.get(name) {
            Some(Value::Str(s)) => Some(s.clone()),
            _ => None,
        }
    }

    pub fn repr(&self) -> String {
        let elem = self.0.elem;
        if std::ptr::eq(elem, &elements::TEXT) || std::ptr::eq(elem, &elements::SYMBOL) {
            if let Some(Value::Str(s)) = self.get("text") {
                return format!("[{}]", s);
            }
        }
        if std::ptr::eq(elem, &elements::SPACE) {
            return "[ ]".into();
        }
        if self.is_sequence() {
            let ch = self.children();
            if ch.is_empty() {
                return "[]".into();
            }
            let parts: Vec<String> = ch.iter().map(|c| c.repr()).collect();
            return format!("sequence{}", pretty_array_like(&parts, false));
        }
        if self.is_styled() {
            let child = match self.get("child") {
                Some(v) => repr(v),
                None => "[]".into(),
            };
            let parts = vec![format!("child: {}", child), "..".to_string()];
            return format!("styled{}", pretty_array_like(&parts, false));
        }
        let parts: Vec<String> = self
            .0
            .fields
            .iter()
            .filter(|(n, _)| elem.is_repr_field(n))
            .map(|(n, v)| format!("{}: {}", n, repr(v)))
            .collect();
        format!("{}{}", elem.name, pretty_array_like(&parts, false))
    }

    /// All fields as a dictionary (for `.fields()`).
    pub fn fields_dict(&self) -> Dict {
        let mut d = Dict::new();
        for (n, v) in &self.0.fields {
            if self.0.elem.is_visible_field(n) {
                d.insert(Rc::from(*n), v.clone());
            }
        }
        if let Some(l) = &self.0.label {
            d.insert(Rc::from("label"), Value::Label(l.clone()));
        }
        d
    }

    /// Plain text approximation.
    pub fn plain_text(&self) -> String {
        let mut s = String::new();
        self.plain_text_into(&mut s);
        s
    }

    fn plain_text_into(&self, out: &mut String) {
        let name = self.0.elem.name;
        match name {
            "text" | "symbol" => {
                if let Some(Value::Str(t)) = self.get("text") {
                    out.push_str(t);
                }
            }
            "space" => out.push(' '),
            "linebreak" => out.push('\n'),
            "parbreak" => out.push_str("\n\n"),
            "smartquote" => {
                let double = matches!(self.get("double"), Some(Value::Bool(true)) | None);
                out.push(if double { '"' } else { '\'' });
            }
            "raw" => {
                if let Some(Value::Str(t)) = self.get("text") {
                    out.push_str(t);
                }
            }
            "sequence" => {
                for c in self.children() {
                    c.plain_text_into(out);
                }
            }
            "styled" => {
                if let Some(Value::Content(c)) = self.get("child") {
                    c.plain_text_into(out);
                }
            }
            _ => {
                if let Some(Value::Content(c)) = self.get("body") {
                    c.plain_text_into(out);
                } else if let Some(Value::Content(c)) = self.get("child") {
                    c.plain_text_into(out);
                }
            }
        }
    }
}
