use crate::value::*;
use std::rc::Rc;

#[derive(Debug, Clone)]
pub struct Arg {
    pub span: Span,
    pub name: Option<Str>,
    pub value: Value,
    pub value_span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Args {
    pub span: Span,
    pub items: Vec<Arg>,
}

impl Args {
    pub fn new(span: Span, values: impl IntoIterator<Item = Value>) -> Self {
        Args {
            span,
            items: values
                .into_iter()
                .map(|v| Arg { span, name: None, value: v, value_span: span })
                .collect(),
        }
    }

    pub fn push(&mut self, span: Span, value: Value) {
        self.items.push(Arg { span, name: None, value, value_span: span });
    }

    pub fn push_named(&mut self, span: Span, name: Str, value: Value) {
        self.items.push(Arg { span, name: Some(name), value, value_span: span });
    }

    pub fn remaining_positional(&self) -> usize {
        self.items.iter().filter(|a| a.name.is_none()).count()
    }

    /// Take the next positional argument (without casting).
    pub fn eat_raw(&mut self) -> Option<Arg> {
        let idx = self.items.iter().position(|a| a.name.is_none())?;
        Some(self.items.remove(idx))
    }

    pub fn eat(&mut self, cast: &Cast) -> SourceResult<Option<Value>> {
        match self.eat_raw() {
            Some(arg) => {
                let v = cast.cast(arg.value).at(arg.value_span)?;
                Ok(Some(v))
            }
            None => Ok(None),
        }
    }

    pub fn eat_any(&mut self) -> Option<Value> {
        self.eat_raw().map(|a| a.value)
    }

    /// Expect a positional argument.
    pub fn expect(&mut self, what: &str, cast: &Cast) -> SourceResult<Value> {
        if let Some(v) = self.eat(cast)? {
            return Ok(v);
        }
        Err(self.missing_argument(what))
    }

    pub fn expect_any(&mut self, what: &str) -> SourceResult<Value> {
        self.expect(what, &Cast::Any)
    }

    pub fn missing_argument(&self, what: &str) -> Vec<Diag> {
        for item in &self.items {
            if item.name.as_deref() == Some(what) {
                let d = Diag::error(item.span, format!("the argument `{what}` is positional"))
                    .with_hint(format!("try removing `{what}:`"));
                return vec![d];
            }
        }
        vec![Diag::error(self.span, format!("missing argument: {what}"))]
    }

    /// Find and take the first positional argument castable to the given type.
    pub fn find(&mut self, cast: &Cast) -> SourceResult<Option<Value>> {
        for i in 0..self.items.len() {
            if self.items[i].name.is_none() && cast.is(&self.items[i].value) {
                let arg = self.items.remove(i);
                return cast.cast(arg.value).at(arg.value_span).map(Some);
            }
        }
        Ok(None)
    }

    /// Take all positional arguments castable to the type.
    pub fn all(&mut self, cast: &Cast) -> SourceResult<Vec<Value>> {
        let mut out = vec![];
        while let Some(v) = self.find(cast)? {
            out.push(v);
        }
        Ok(out)
    }

    /// Take all remaining positional args, casting each (error on failure).
    pub fn all_strict(&mut self, cast: &Cast) -> SourceResult<Vec<Value>> {
        let mut out = vec![];
        while let Some(v) = self.eat(cast)? {
            out.push(v);
        }
        Ok(out)
    }

    pub fn named(&mut self, name: &str, cast: &Cast) -> SourceResult<Option<Value>> {
        let mut found = None;
        let mut i = 0;
        while i < self.items.len() {
            if self.items[i].name.as_deref() == Some(name) {
                let arg = self.items.remove(i);
                let v = cast.cast(arg.value).at(arg.value_span)?;
                found = Some(v);
            } else {
                i += 1;
            }
        }
        Ok(found)
    }

    pub fn named_any(&mut self, name: &str) -> Option<Value> {
        self.named(name, &Cast::Any).ok().flatten()
    }

    pub fn named_span(&self, name: &str) -> Option<Span> {
        self.items.iter().rev().find(|a| a.name.as_deref() == Some(name)).map(|a| a.span)
    }

    pub fn has_named(&self, name: &str) -> bool {
        self.items.iter().any(|a| a.name.as_deref() == Some(name))
    }

    pub fn take(&mut self) -> Args {
        Args { span: self.span, items: std::mem::take(&mut self.items) }
    }

    pub fn finish(&mut self) -> SourceResult<()> {
        if let Some(arg) = self.items.first() {
            match &arg.name {
                Some(name) => bail!(arg.span, "unexpected argument: {}", name),
                None => bail!(arg.span, "unexpected argument"),
            }
        }
        Ok(())
    }

    pub fn to_named(&self) -> Dict {
        let mut d = Dict::new();
        for a in &self.items {
            if let Some(n) = &a.name {
                d.insert(n.clone(), a.value.clone());
            }
        }
        d
    }

    pub fn to_pos(&self) -> Vec<Value> {
        self.items.iter().filter(|a| a.name.is_none()).map(|a| a.value.clone()).collect()
    }
}

pub type NativeFn = fn(&mut crate::eval::Engine, &mut Args) -> SourceResult<Value>;

#[derive(Debug)]
pub struct NativeFunc {
    pub name: &'static str,
