pub struct Func {
    pub kind: FuncKind,
    pub span: Span,
}

impl Func {
    pub fn native(f: &'static NativeFunc) -> Self {
        Func { kind: FuncKind::Native(f), span: Span::detached() }
    }
    pub fn element(e: &'static Elem) -> Self {
        Func { kind: FuncKind::Element(e), span: Span::detached() }
    }
    pub fn name(&self) -> Option<String> {
        match &self.kind {
            FuncKind::Native(n) => Some(n.name.to_string()),
            FuncKind::Bound(b) => Some(b.name.to_string()),
            FuncKind::Element(e) => Some(e.name.to_string()),
            FuncKind::Closure(c) => c.name.as_ref().map(|s| s.to_string()),
            FuncKind::With(w) => w.0.name(),
            FuncKind::Type(t) => Some(t.short_name().to_string()),
        }
    }
    pub fn repr(&self) -> String {
        match self.name() {
            Some(n) => n,
            None => "(..) => ..".into(),
        }
    }
    pub fn element_def(&self) -> Option<&'static Elem> {
        match &self.kind {
            FuncKind::Element(e) => Some(e),
            _ => None,
        }
    }
    pub fn ptr_eq(&self, other: &Func) -> bool {
        match (&self.kind, &other.kind) {
            (FuncKind::Native(a), FuncKind::Native(b)) => std::ptr::eq(*a, *b),
            (FuncKind::Element(a), FuncKind::Element(b)) => std::ptr::eq(*a, *b),
            (FuncKind::Closure(a), FuncKind::Closure(b)) => Rc::ptr_eq(a, b),
            (FuncKind::With(a), FuncKind::With(b)) => Rc::ptr_eq(a, b),
            (FuncKind::Bound(a), FuncKind::Bound(b)) => Rc::ptr_eq(a, b),
            (FuncKind::Type(a), FuncKind::Type(b)) => a == b,
            _ => false,
        }
    }
    pub fn spanned(mut self, span: Span) -> Self {
        if self.span.is_detached() {
            self.span = span;
        }
        self
    }
}

pub fn cast_info_dummy() -> CastInfo {
    CastInfo::Any
}
