//! Casting values to expected types.

use crate::content::Content;
use crate::diag::*;
use crate::value::*;

#[derive(Debug)]
pub enum CastInfo {
    Any,
}

pub enum Cast {
    Any,
    Content,
    Bool,
    Int,
    PosInt,
    UInt,
    Float,
    Num,
    Str,
    Label,
    Length,
    Rel,
    Ratio,
    Angle,
    Fraction,
    Color,
    Paint,
    Stroke,
    Dir,
    Align,
    Func,
    Dict,
    Array,
    Location,
    Bytes,
    Datetime,
    Version,
    Type,
    Symbol,
    Selector,
    NoneOnly,
    AutoOnly,
    Smart(&'static Cast),
    Opt(&'static Cast),
    Or(&'static [Cast]),
    Strs(&'static [&'static str]),
    Custom {
        parts: &'static [&'static str],
        check: fn(&Value) -> bool,
        conv: fn(Value) -> StrResult<Value>,
    },
}

pub fn separated_list(pieces: &[String], last: &str) -> String {
    let mut buf = String::new();
    for (i, part) in pieces.iter().enumerate() {
        match i {
            0 => {}
            1 if pieces.len() == 2 => {
                buf.push(' ');
                buf.push_str(last);
                buf.push(' ');
            }
            i if i + 1 == pieces.len() => {
                buf.push_str(", ");
                buf.push_str(last);
                buf.push(' ');
            }
            _ => buf.push_str(", "),
        }
        buf.push_str(part);
    }
    buf
}

fn to_rel(v: Value) -> Value {
    match v {
        Value::Length(l) => Value::Relative(Rel { rel: 0.0, abs: l }),
        Value::Ratio(r) => Value::Relative(Rel { rel: r, abs: Length::zero() }),
        v => v,
    }
}

pub fn to_content(v: Value) -> Content {
    match v {
        Value::Content(c) => c,
        Value::Str(s) => Content::text(&*s),
