cd /workspace/src && cat > elements.rs <<'EOF'
//! Element definitions.

use crate::cast::*;

#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum FK {
    /// Required positional.
    R,
    /// Optional positional (found by type).
    P,
    /// Named.
    N,
    /// Variadic positional.
    V,
    /// Named or found positionally.
    NF,
    /// Synthesized.
    S,
    /// Internal.
    I,
}

pub struct Field {
    pub name: &'static str,
    pub kind: FK,
    pub cast: &'static Cast,
}

pub struct Elem {
    pub name: &'static str,
    pub fields: &'static [Field],
}

impl std::fmt::Debug for Elem {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Elem({})", self.name)
    }
}

impl Elem {
    pub fn field_index(&self, name: &str) -> usize {
        self.fields.iter().position(|f| f.name == name).unwrap_or(10000)
    }
    pub fn field_name(&self, name: &str) -> &'static str {
        match self.fields.iter().find(|f| f.name == name) {
            Some(f) => f.name,
            None => Box::leak(name.to_string().into_boxed_str()),
        }
    }
    pub fn field(&self, name: &str) -> Option<&'static Field> {
        self.fields.iter().find(|f| f.name == name)
    }
    pub fn is_repr_field(&self, name: &str) -> bool {
        match self.field(name) {
            Some(f) => f.kind != FK::I,
            None => true,
        }
    }
    pub fn is_visible_field(&self, name: &str) -> bool {
        self.is_repr_field(name)
    }
    pub fn has_field(&self, name: &str) -> bool {
        self.fields.iter().any(|f| f.name == name)
    }
}

macro_rules! field {
    ($name:literal, $kind:ident, $cast:expr) => {
        Field { name: $name, kind: FK::$kind, cast: &$cast }
    };
}

macro_rules! elem {
    ($id:ident, $name:literal, [$($fname:literal $kind:ident $cast:expr),* $(,)?]) => {
        pub static $id: Elem = Elem { name: $name, fields: &[$(field!($fname, $kind, $cast)),*] };
    };
}

