//! The evaluator.

use crate::cast::to_content;
use crate::content::{Content, Recipe, Style, Styles};
use crate::diag::*;
use crate::elements as el;
use crate::func::*;
use crate::syntax::kind::SyntaxKind as K;
use crate::syntax::node::{is_expr_kind, SyntaxNode};
use crate::value::*;
use std::rc::Rc;

#[derive(Debug, Clone, Default)]
pub struct ContextInfo {
    pub location: Option<Location>,
    pub styles: Option<Rc<Vec<Styles>>>,
}

pub struct Engine {
    pub std: Rc<Scope>,
    pub math: Rc<Scope>,
    pub warnings: Vec<Diag>,
    pub depth: usize,
    pub world: crate::world::World,
    pub introspector: Rc<crate::introspect::Introspector>,
    pub context: ContextInfo,
    pub html: bool,
}

impl Engine {
    pub fn warn(&mut self, d: Diag) {
        // Deduplicate identical warnings.
        if !self.warnings.iter().any(|w| w.span == d.span && w.message == d.message) {
            self.warnings.push(d);
        }
    }
}

#[derive(Debug, Clone)]
pub enum Flow {
    Break(Span),
    Continue(Span),
    Return(Span, Option<Value>),
}

pub struct Scopes {
    pub top: Scope,
    pub scopes: Vec<Scope>,
    pub base: Option<Rc<Scope>>,
    /// Captured scope of a closure (read-only).
    pub captured: Option<Rc<Scope>>,
}

impl Scopes {
    pub fn new(base: Option<Rc<Scope>>) -> Self {
        Scopes { top: Scope::new(), scopes: vec![], base, captured: None }
    }
    pub fn enter(&mut self) {
        self.scopes.push(std::mem::take(&mut self.top));
    }
    pub fn exit(&mut self) {
        self.top = self.scopes.pop().expect("no pushed scope");
    }
    pub fn define(&mut self, name: impl Into<Str>, value: Value) {
        self.top.define(name, value);
    }
    pub fn get(&self, name: &str) -> Option<&Value> {
        if let Some(v) = self.top.get(name) {
            return Some(v);
        }
        for s in self.scopes.iter().rev() {
            if let Some(v) = s.get(name) {
                return Some(v);
            }
        }
        if let Some(c) = &self.captured {
            if let Some(v) = c.get(name) {
                return Some(v);
            }
        }
        self.base.as_ref().and_then(|b| b.get(name))
    }
    pub fn get_mut(&mut self, name: &str) -> StrResult<&mut Value> {
        if self.top.get(name).is_some() {
            return Ok(self.top.get_mut(name).unwrap());
        }
        for s in self.scopes.iter_mut().rev() {
            if s.get(name).is_some() {
                return Ok(s.get_mut(name).unwrap());
            }
        }
        if let Some(c) = &self.captured {
            if c.get(name).is_some() {
                return Err(HintedString::new(
                    "variables from outside the function are read-only and cannot be modified",
                ));
            }
        }
        if let Some(b) = &self.base {
            if b.get(name).is_some() {
                return Err(HintedString::new(format!("cannot mutate a constant: {name}")));
            }
        }
        Err(HintedString::new(format!("unknown variable: {name}")))
    }
    /// All visible bindings (for capturing).
    pub fn visible(&self, name: &str) -> Option<Value> {
        if let Some(v) = self.top.get(name) {
            return Some(v.clone());
        }
        for s in self.scopes.iter().rev() {
            if let Some(v) = s.get(name) {
                return Some(v.clone());
            }
        }
        if let Some(c) = &self.captured {
            if let Some(v) = c.get(name) {
                return Some(v.clone());
            }
        }
        None
    }
}

pub struct Vm<'a> {
    pub engine: &'a mut Engine,
    pub scopes: Scopes,
    pub flow: Option<Flow>,
    pub file: u16,
    pub context: ContextInfo,
}

pub fn span_of(file: u16, node: &SyntaxNode) -> Span {
    if file == 0 {
        Span::detached()
    } else {
        Span::new(file, node.offset, node.offset + node.len)
    }
}

// ---------- AST helpers ----------

pub fn exprs(node: &SyntaxNode) -> impl Iterator<Item = &SyntaxNode> {
    node.children.iter().filter(|c| is_expr_kind(c.kind))
}

fn first_expr(node: &SyntaxNode) -> Option<&SyntaxNode> {
    node.children.iter().find(|c| is_expr_kind(c.kind))
}

fn last_expr(node: &SyntaxNode) -> Option<&SyntaxNode> {
    node.children.iter().rev().find(|c| is_expr_kind(c.kind))
}

fn child(node: &SyntaxNode, kind: K) -> Option<&SyntaxNode> {
    node.children.iter().find(|c| c.kind == kind)
}

fn child_rev(node: &SyntaxNode, kind: K) -> Option<&SyntaxNode> {
    node.children.iter().rev().find(|c| c.kind == kind)
}

pub fn is_pattern_kind(k: K) -> bool {
    is_expr_kind(k) || matches!(k, K::Underscore | K::Destructuring | K::Parenthesized)
}

/// Display a value as content.
pub fn display_value(v: &Value) -> Content {
    match v {
        Value::None => Content::empty(),
        Value::Int(i) => Content::text(crate::repr::display_int(*i)),
        Value::Float(f) => Content::text(crate::repr::display_float(*f)),
        Value::Decimal(d) => Content::text(crate::decimal::display_signed(d)),
        Value::Str(s) => Content::text(&**s),
        Value::Version(_) => Content::text(crate::repr::display_for_str(v).unwrap()),
        Value::Symbol(s) => Content::symbol(&*s.text),
        Value::Content(c) => c.clone(),
        Value::Module(m) => m.content.clone().unwrap_or_else(Content::empty),
        _ => Content::new(&el::RAW)
            .with("text", Value::str(crate::repr::repr(v)))
            .with("block", false)
            .with("lang", Value::str("typc")),
    }
}

pub fn is_unlabellable(c: &Content) -> bool {
    matches!(c.func_name(), "space" | "parbreak")
        || (c.is_sequence() && false)
}

impl<'a> Vm<'a> {
    pub fn span(&self, node: &SyntaxNode) -> Span {
        span_of(self.file, node)
    }

    pub fn define(&mut self, name: impl Into<Str>, value: Value) {
        self.scopes.define(name, value);
    }

    // ================= Markup =================

    pub fn eval_markup(&mut self, node: &SyntaxNode) -> SourceResult<Content> {
        let children: Vec<&SyntaxNode> = node.children.iter().filter(|c| is_expr_kind(c.kind)).collect();
        let mut idx = 0;
        self.eval_markup_seq(&children, &mut idx)
    }

    fn eval_markup_seq(&mut self, exprs: &[&SyntaxNode], idx: &mut usize) -> SourceResult<Content> {
        let flow = self.flow.take();
        let mut seq: Vec<Content> = Vec::new();
        while *idx < exprs.len() {
            let expr = exprs[*idx];
            *idx += 1;
            match expr.kind {
                K::SetRule => {
                    let styles = self.eval_set_rule(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = self.eval_markup_seq(exprs, idx)?;
                    seq.push(styled_with_map(tail, styles));
                }
                K::ShowRule => {
                    let recipe = self.eval_show_rule(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = self.eval_markup_seq(exprs, idx)?;
                    seq.push(styled_with_recipe(self.engine, tail, recipe)?);
                }
                _ => {
                    let value = self.eval_expr(expr)?;
                    match value {
                        Value::Label(label) => {
                            if let Some(elem) = seq.iter_mut().rev().find(|n| !is_unlabellable(n)) {
                                if elem.label().is_some() {
                                    let d = Diag::warning(elem.span(), "content labelled multiple times")
                                        .with_hint("only the last label is used, the rest are ignored");
                                    self.engine.warn(d);
                                }
                                *elem = std::mem::replace(elem, Content::empty()).labelled(label);
                            } else {
                                let d = Diag::warning(
                                    self.span(expr),
                                    format!("label `{}` is not attached to anything", crate::repr::repr_label(&label)),
                                );
                                self.engine.warn(d);
                            }
                        }
                        v => {
                            let span = self.span(expr);
                            seq.push(display_value(&v).spanned(span));
                        }
                    }
                }
            }
            if self.flow.is_some() {
                break;
            }
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(Content::sequence_or_single(seq))
    }

    // ================= Code =================

    pub fn eval_code(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let children: Vec<&SyntaxNode> = node.children.iter().filter(|c| is_expr_kind(c.kind)).collect();
        let mut idx = 0;
        self.eval_code_seq(&children, &mut idx)
    }

    fn eval_code_seq(&mut self, exprs: &[&SyntaxNode], idx: &mut usize) -> SourceResult<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        while *idx < exprs.len() {
            let expr = exprs[*idx];
            *idx += 1;
            let span = self.span(expr);
            let value = match expr.kind {
                K::SetRule => {
                    let styles = self.eval_set_rule(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = display_value(&self.eval_code_seq(exprs, idx)?);
                    Value::Content(styled_with_map(tail, styles))
                }
                K::ShowRule => {
                    let recipe = self.eval_show_rule(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = display_value(&self.eval_code_seq(exprs, idx)?);
                    Value::Content(styled_with_recipe(self.engine, tail, recipe)?)
                }
                _ => self.eval_expr(expr)?,
            };
            output = crate::ops::join(output, value).at(span)?;
            if self.flow.is_some() {
                break;
            }
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    // ================= Expressions =================

    pub fn eval_expr(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let span = self.span(node);
        let v = match node.kind {
            K::Text => Value::Content(Content::text(node.text()).spanned(span)),
            K::Space => {
                if node.text().contains(crate::syntax::lexer::is_newline) && false {
                    Value::None
                } else {
                    Value::Content(Content::space().spanned(span))
                }
            }
            K::Linebreak => Value::Content(Content::new(&el::LINEBREAK).spanned(span)),
            K::Parbreak => Value::Content(Content::new(&el::PARBREAK).spanned(span)),
            K::Escape => Value::Content(Content::symbol(escape_char(node.text()).to_string()).spanned(span)),
            K::Shorthand => Value::Content(Content::symbol(shorthand_char(node.text()).to_string()).spanned(span)),
            K::SmartQuote => {
                let double = node.text() == "\"";
                Value::Content(Content::new(&el::SMARTQUOTE).with("double", double).spanned(span))
            }
            K::Strong => {
                let body_node = child(node, K::Markup);
                if let Some(b) = body_node {
                    if !b.children.iter().any(|c| is_expr_kind(c.kind)) {
                        self.engine.warn(
                            Diag::warning(span, "no text within stars")
                                .with_hint("using multiple consecutive stars (e.g. **) has no additional effect"),
                        );
                    }
                }
                let body = match body_node {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                Value::Content(Content::new(&el::STRONG).with("body", body).spanned(span))
            }
            K::Emph => {
                let body_node = child(node, K::Markup);
                if let Some(b) = body_node {
                    if !b.children.iter().any(|c| is_expr_kind(c.kind)) {
                        self.engine.warn(
                            Diag::warning(span, "no text within underscores")
                                .with_hint("using multiple consecutive underscores (e.g. __) has no additional effect"),
                        );
                    }
                }
                let body = match body_node {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                Value::Content(Content::new(&el::EMPH).with("body", body).spanned(span))
            }
            K::Raw => Value::Content(eval_raw(node).spanned(span)),
            K::Link => {
                let url = node.text();
                Value::Content(
                    Content::new(&el::LINK)
                        .with("dest", Value::str(url))
                        .with("body", Content::text(crate::model::link_body_text(url)))
                        .spanned(span),
                )
            }
            K::Label => {
                let t = node.text();
                Value::Label(Rc::from(&t[1..t.len() - 1]))
            }
            K::Ref => {
                let marker = &node.children[0];
                let target = &marker.text()[1..];
                let mut c = Content::new(&el::REF).with("target", Value::Label(Rc::from(target)));
                if let Some(block) = child(node, K::ContentBlock) {
                    let sup = self.eval_expr(block)?;
                    c = c.with("supplement", sup);
                }
                Value::Content(c.spanned(span))
            }
            K::Heading => {
                let marker = child(node, K::HeadingMarker).unwrap();
                let depth = marker.text().len() as i64;
                let body = match child(node, K::Markup) {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                Value::Content(
                    Content::new(&el::HEADING).with("depth", Value::Int(depth)).with("body", body).spanned(span),
                )
            }
            K::ListItem => {
                let body = match child(node, K::Markup) {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                Value::Content(Content::new(&el::LIST_ITEM).with("body", body).spanned(span))
            }
            K::EnumItem => {
                let marker = child(node, K::EnumMarker).unwrap();
                let body = match child(node, K::Markup) {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                let mut c = Content::new(&el::ENUM_ITEM);
                let t = marker.text();
                if t.ends_with('.') {
                    if let Ok(n) = t[..t.len() - 1].parse::<i64>() {
                        c = c.with("number", Value::Int(n));
                    }
                }
                Value::Content(c.with("body", body).spanned(span))
            }
            K::TermItem => {
                let mut markups = node.children.iter().filter(|c| c.kind == K::Markup);
                let term = match markups.next() {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                let desc = match markups.next() {
                    Some(b) => self.eval_markup(b)?,
                    None => Content::empty(),
                };
                Value::Content(
                    Content::new(&el::TERMS_ITEM).with("term", term).with("description", desc).spanned(span),
                )
            }
            K::Equation => {
                let block = {
                    let ch = &node.children;
                    ch.len() >= 3 && ch[1].kind == K::Space && ch[ch.len() - 2].kind == K::Space
                };
                let body = match child(node, K::Math) {
                    Some(m) => self.eval_math_node(m)?,
                    None => Content::empty(),
                };
                Value::Content(
                    Content::new(&el::EQUATION).with("block", block).with("body", body).spanned(span),
                )
            }
            K::Math
            | K::MathText
            | K::MathIdent
            | K::MathShorthand
            | K::MathAlignPoint
            | K::MathDelimited
            | K::MathAttach
            | K::MathPrimes
            | K::MathFrac
            | K::MathRoot => crate::math::eval_math_expr(self, node)?,
            K::Ident => {
                let name = node.text();
                match self.scopes.get(name) {
                    Some(v) => v.clone(),
                    None => {
                        let mut d = Diag::error(span, format!("unknown variable: {name}"));
                        if name.contains('-') {
                            d = d.with_hint(format!(
                                "if you meant to use subtraction, try adding spaces around the minus sign{}",
                                if name.len() > 0 { format!(": `{}`", name.replace('-', " - ")) } else { String::new() }
                            ));
                        }
                        return Err(vec![d]);
                    }
                }
            }
            K::None => Value::None,
            K::Auto => Value::Auto,
            K::Bool => Value::Bool(node.text() == "true"),
            K::Int => Value::Int(parse_int(node.text())),
            K::Float => Value::Float(crate::syntax::lexer::parse_float(node.text()).unwrap_or(0.0)),
            K::Numeric => eval_numeric(node.text()),
            K::Str => Value::str(crate::syntax::ast::unescape_string(node.text())),
            K::CodeBlock => {
                self.scopes.enter();
                let r = match child(node, K::Code) {
                    Some(code) => self.eval_code(code),
                    None => Ok(Value::None),
                };
                self.scopes.exit();
                r?
            }
            K::ContentBlock => {
                self.scopes.enter();
                let r = match child(node, K::Markup) {
                    Some(m) => self.eval_markup(m),
                    None => Ok(Content::empty()),
                };
                self.scopes.exit();
                Value::Content(r?)
            }
            K::Parenthesized => {
                let inner = first_expr(node).unwrap();
                self.eval_expr(inner)?
            }
            K::Array => self.eval_array(node)?,
            K::Dict => self.eval_dict(node)?,
            K::Unary => self.eval_unary(node)?,
            K::Binary => self.eval_binary(node)?,
            K::FieldAccess => self.eval_field_access(node)?,
            K::FuncCall => self.eval_call(node)?,
            K::Closure => self.eval_closure(node)?,
            K::LetBinding => self.eval_let(node)?,
            K::DestructAssignment => {
                let pattern = node.children.iter().find(|c| is_pattern_kind(c.kind)).unwrap();
                let value_node = last_expr(node).unwrap();
                let value = self.eval_expr(value_node)?;
                self.destructure(pattern, value, true)?;
                Value::None
            }
            K::SetRule => {
                let styles = self.eval_set_rule(node)?;
                let _ = styles;
                Value::None
            }
            K::ShowRule => {
                let _ = self.eval_show_rule(node)?;
                Value::None
            }
            K::Contextual => {
                let body = last_expr(node).unwrap();
                let closure = self.make_closure_from_body(body)?;
                Value::Content(
                    Content::new(&el::CONTEXT).with("func", Value::Func(closure)).spanned(span),
                )
            }
            K::Conditional => self.eval_conditional(node)?,
            K::WhileLoop => self.eval_while(node)?,
            K::ForLoop => self.eval_for(node)?,
            K::ModuleImport => self.eval_import(node)?,
            K::ModuleInclude => self.eval_include(node)?,
            K::LoopBreak => {
                if self.flow.is_none() {
                    self.flow = Some(Flow::Break(span));
                }
                Value::None
            }
            K::LoopContinue => {
                if self.flow.is_none() {
                    self.flow = Some(Flow::Continue(span));
                }
                Value::None
            }
            K::FuncReturn => {
                let value = match first_expr(node) {
                    Some(e) => Some(self.eval_expr(e)?),
                    None => None,
                };
                if self.flow.is_none() {
                    self.flow = Some(Flow::Return(span, value));
                }
                Value::None
            }
            K::Markup => Value::Content(self.eval_markup(node)?),
            K::Code => self.eval_code(node)?,
            _ => bail!(span, "cannot evaluate {}", node.kind.name()),
        };
        Ok(v)
    }

    fn eval_array(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let mut vec = Vec::new();
        for item in node.children.iter() {
            match item.kind {
                K::Spread => {
                    let inner = first_expr(item).unwrap();
                    match self.eval_expr(inner)? {
                        Value::None => {}
                        Value::Array(a) => vec.extend(a.iter().cloned()),
                        v => bail!(self.span(item), "cannot spread {} into array", v.type_name()),
                    }
                }
                k if is_expr_kind(k) => vec.push(self.eval_expr(item)?),
                _ => {}
            }
        }
        Ok(Value::array(vec))
    }

    fn eval_dict(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let mut map = Dict::new();
        let mut invalid_keys: Vec<Diag> = vec![];
        for item in node.children.iter() {
            match item.kind {
                K::Named => {
                    let name = child(item, K::Ident).unwrap().text();
                    let value = self.eval_expr(last_expr(item).unwrap())?;
                    map.insert(Rc::from(name), value);
                }
                K::Keyed => {
                    let key_node = first_expr(item).unwrap();
                    let key = self.eval_expr(key_node)?;
                    let value = self.eval_expr(last_expr(item).unwrap())?;
                    match key {
                        Value::Str(s) => map.insert(s, value),
                        other => {
                            let msg = crate::cast::Cast::Str.error(&other);
                            invalid_keys.push(Diag::error(self.span(key_node), msg.message));
                        }
                    }
                }
                K::Spread => {
                    let inner = first_expr(item).unwrap();
                    match self.eval_expr(inner)? {
                        Value::None => {}
                        Value::Dict(d) => {
                            for (k, v) in d.iter() {
                                map.insert(k.clone(), v.clone());
                            }
                        }
                        v => bail!(self.span(item), "cannot spread {} into dictionary", v.type_name()),
                    }
                }
                _ => {}
            }
        }
        if !invalid_keys.is_empty() {
            return Err(invalid_keys);
        }
        Ok(Value::dict(map))
    }

    fn eval_unary(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let op = node.children[0].kind;
        let operand = last_expr(node).unwrap();
        let value = self.eval_expr(operand)?;
        let span = self.span(node);
        let r = match op {
            K::Plus => crate::ops::pos(value),
            K::Minus => crate::ops::neg(value),
            K::Not => crate::ops::not(value),
            _ => unreachable!(),
        };
        r.at(span)
    }

    fn binop_of(node: &SyntaxNode) -> (K, bool) {
        // returns (op kind, is_not_in)
        let mut not = false;
        for c in &node.children {
            match c.kind {
                K::Not => not = true,
                K::In => return (K::In, not),
                K::Plus | K::Minus | K::Star | K::Slash | K::And | K::Or | K::EqEq | K::ExclEq | K::Lt
                | K::LtEq | K::Gt | K::GtEq | K::Eq | K::PlusEq | K::HyphEq | K::StarEq | K::SlashEq => {
                    return (c.kind, false)
                }
                _ => {}
            }
        }
        (K::Error, false)
    }

    fn eval_binary(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let (op, not_in) = Self::binop_of(node);
        let lhs = first_expr(node).unwrap();
        let rhs = last_expr(node).unwrap();
        let span = self.span(node);
        match op {
            K::And => {
                let l = self.eval_expr(lhs)?;
                if let Value::Bool(false) = l {
                    return Ok(Value::Bool(false));
                }
                let r = self.eval_expr(rhs)?;
                return crate::ops::and(l, r).at(span);
            }
            K::Or => {
                let l = self.eval_expr(lhs)?;
                if let Value::Bool(true) = l {
                    return Ok(Value::Bool(true));
                }
                let r = self.eval_expr(rhs)?;
                return crate::ops::or(l, r).at(span);
            }
            K::Eq | K::PlusEq | K::HyphEq | K::StarEq | K::SlashEq => {
                let r = self.eval_expr(rhs)?;
                if op == K::Eq {
                    if lhs.kind == K::Underscore {
                        return Ok(Value::None);
                    }
                    let slot = self.access(lhs)?;
                    *slot = r;
                    return Ok(Value::None);
                }
                let slot = self.access(lhs)?;
                let l = std::mem::take(slot);
                let res = match op {
                    K::PlusEq => crate::ops::add(l.clone(), r),
                    K::HyphEq => crate::ops::sub(l.clone(), r),
                    K::StarEq => crate::ops::mul(l.clone(), r),
                    K::SlashEq => crate::ops::div(l.clone(), r),
                    _ => unreachable!(),
                };
                match res {
                    Ok(v) => {
                        *slot = v;
                        return Ok(Value::None);
                    }
                    Err(e) => {
                        *slot = l;
                        return Err(e).at(span);
                    }
                }
            }
            _ => {}
        }
        let l = self.eval_expr(lhs)?;
        let r = self.eval_expr(rhs)?;
        let res = match op {
            K::Plus => crate::ops::add(l, r),
            K::Minus => crate::ops::sub(l, r),
            K::Star => crate::ops::mul(l, r),
            K::Slash => crate::ops::div(l, r),
            K::EqEq => Ok(Value::Bool(crate::ops::equal(&l, &r))),
            K::ExclEq => Ok(Value::Bool(!crate::ops::equal(&l, &r))),
            K::Lt => crate::ops::lt(l, r),
            K::LtEq => crate::ops::leq(l, r),
            K::Gt => crate::ops::gt(l, r),
            K::GtEq => crate::ops::geq(l, r),
            K::In => {
                if not_in {
                    crate::ops::not_in(l, r)
                } else {
                    crate::ops::in_(l, r)
                }
            }
            _ => bail!(span, "unknown operator"),
        };
        res.at(span)
    }

    /// Access an lvalue.
    pub fn access(&mut self, node: &SyntaxNode) -> SourceResult<&mut Value> {
        let span = self.span(node);
        match node.kind {
            K::Ident => {
                let name = node.text().to_string();
                self.scopes.get_mut(&name).at(span)
            }
            K::Parenthesized => {
                let inner = first_expr(node).unwrap();
                self.access(inner)
            }
            K::FieldAccess => {
                let target = first_expr(node).unwrap();
                let field = child_rev(node, K::Ident).unwrap().text().to_string();
                let field_span = span;
                let _ = field_span;
                let tspan = self.span(target);
                let val = self.access(target)?;
                match val {
                    Value::Dict(d) => {
                        let d = Rc::make_mut(d);
                        if d.get(&field).is_none() {
                            d.insert(Rc::from(field.as_str()), Value::None);
                        }
                        Ok(d.get_mut(&field).unwrap())
                    }
                    v => {
                        let _ = tspan;
                        let msg = if crate::fields::field_exists(v, &field) {
                            format!("cannot mutate fields on {}", v.type_name())
                        } else {
                            format!("cannot mutate fields on {}", v.type_name())
                        };
                        bail!(span, "{}", msg)
                    }
                }
            }
            K::FuncCall => {
                // Method call like arr.at(0), arr.first(), arr.last()
                let callee = first_expr(node).unwrap();
                if callee.kind == K::FieldAccess {
                    let method = child_rev(callee, K::Ident).unwrap().text().to_string();
                    let target = first_expr(callee).unwrap();
                    let args_node = child_rev(node, K::Args).unwrap();
                    if matches!(method.as_str(), "at" | "first" | "last") {
                        let mut args = self.eval_args(args_node)?;
                        args.span = span;
                        let target_val = self.access(target)?;
                        return crate::methods::access_method(target_val, &method, &mut args, span);
                    }
                }
                let v = self.eval_expr(node)?;
                let _ = v;
                bail!(span, "cannot mutate a temporary value")
            }
            _ => {
                let _ = self.eval_expr(node)?;
                bail!(span, "cannot mutate a temporary value")
            }
        }
    }

    fn eval_field_access(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let target = first_expr(node).unwrap();
        let field_node = child_rev(node, K::Ident).unwrap();
        let field = field_node.text();
        let value = self.eval_expr(target)?;
        let span = self.span(field_node);
        crate::fields::field(self.engine, &value, field).at(span)
    }

    pub fn eval_args(&mut self, node: &SyntaxNode) -> SourceResult<Args> {
        let mut args = Args { span: self.span(node), items: vec![] };
        for item in &node.children {
            let ispan = self.span(item);
            match item.kind {
                K::Named => {
                    let name = child(item, K::Ident).map(|n| n.text()).unwrap_or("");
                    let vnode = last_expr(item).unwrap();
                    let value = self.eval_expr(vnode)?;
                    let vspan = self.span(vnode);
                    args.items.push(Arg { span: ispan, name: Some(Rc::from(name)), value, value_span: vspan });
                }
                K::Spread => {
                    let inner = first_expr(item).unwrap();
                    match self.eval_expr(inner)? {
                        Value::None => {}
                        Value::Array(a) => {
                            for v in a.iter() {
                                args.items.push(Arg { span: ispan, name: None, value: v.clone(), value_span: ispan });
                            }
                        }
                        Value::Dict(d) => {
                            for (k, v) in d.iter() {
                                args.items.push(Arg {
                                    span: ispan,
                                    name: Some(k.clone()),
                                    value: v.clone(),
                                    value_span: ispan,
                                });
                            }
                        }
                        Value::Args(a) => {
                            for it in a.items.iter() {
                                args.items.push(it.clone());
                            }
                        }
                        v => bail!(ispan, "cannot spread {}", v.type_name()),
                    }
                }
                k if is_expr_kind(k) => {
                    let value = self.eval_expr(item)?;
                    args.items.push(Arg { span: ispan, name: None, value, value_span: ispan });
                }
                _ => {}
            }
        }
        Ok(args)
    }

    fn eval_call(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let span = self.span(node);
        let callee = first_expr(node).unwrap();
        let args_node = child_rev(node, K::Args).unwrap();
        let in_math = matches!(callee.kind, K::MathIdent) || (callee.kind == K::FieldAccess && in_math_field(callee));
        let callee_span = self.span(callee);

        if self.engine.depth >= crate::func_call::MAX_DEPTH {
            bail!(span, "maximum function call depth exceeded");
        }

        let (func_val, mut args) = if callee.kind == K::FieldAccess {
            let target = first_expr(callee).unwrap();
            let field_node = child_rev(callee, K::Ident).unwrap();
            let field = field_node.text().to_string();
            let field_span = self.span(field_node);
            if crate::methods::is_mutating_method(&field) {
                let mut args = self.eval_args(args_node)?;
                args.span = span;
                let tspan = self.span(target);
                let target_val = self.access(target);
                match target_val {
                    Ok(tv) => {
                        if matches!(tv, Value::Array(_) | Value::Dict(_)) {
                            let r = crate::methods::call_method_mut(tv, &field, &mut args, span);
                            return r;
                        }
                        let tv = tv.clone();
                        match crate::methods::method_func(&tv, &field) {
                            Some(f) => {
                                args.items.insert(0, Arg { span: tspan, name: None, value: tv, value_span: tspan });
                                (Value::Func(f), args)
                            }
                            None => return Err(vec![crate::methods::missing_method_error(&tv, &field, field_span)]),
                        }
                    }
                    Err(e) => {
                        // Temporary value: if it's an array/dict, error.
                        let msg = &e[0].message;
                        if msg == "cannot mutate a temporary value" {
                            let tv = self.eval_expr(target)?;
                            if matches!(tv, Value::Array(_) | Value::Dict(_)) {
                                bail!(tspan, "cannot mutate a temporary value");
                            }
                            match crate::methods::method_func(&tv, &field) {
                                Some(f) => {
                                    args.items.insert(0, Arg { span: tspan, name: None, value: tv, value_span: tspan });
                                    (Value::Func(f), args)
                                }
                                None => return Err(vec![crate::methods::missing_method_error(&tv, &field, field_span)]),
                            }
                        } else {
                            return Err(e);
                        }
                    }
                }
            } else {
                let tspan = self.span(target);
                let tv = self.eval_expr(target)?;
                let mut args = self.eval_args(args_node)?;
                args.span = span;
                if let Some(f) = crate::methods::method_func(&tv, &field) {
                    args.items.insert(0, Arg { span: tspan, name: None, value: tv, value_span: tspan });
                    (Value::Func(f), args)
                } else if matches!(tv, Value::Symbol(_) | Value::Func(_) | Value::Type(_) | Value::Module(_)) {
                    let f = crate::fields::field(self.engine, &tv, &field).at(field_span)?;
                    (f, args)
                } else {
                    return Err(vec![crate::methods::missing_method_error(&tv, &field, field_span)]);
                }
            }
        } else {
            let f = self.eval_expr(callee)?;
            let mut args = self.eval_args(args_node)?;
            args.span = span;
            (f, args)
        };

        let func = match func_val {
            Value::Func(f) => f,
            Value::Type(t) => Func { kind: FuncKind::Type(t), span: callee_span },
            other => {
                if in_math {
                    return crate::math::wrap_args_in_math(self, other, callee_span, args, args_node);
                }
                bail!(callee_span, "expected function, found {}", other.type_name())
            }
        };
        args.span = span;
        let name = func.name();
        let result = crate::func_call::call_func(self.engine, &func, args, &self.context);
        add_trace(result, span, || match &name {
            Some(n) => format!("error occurred in this call of function `{n}`"),
            None => "error occurred in this function call".into(),
        })
    }

    fn eval_closure(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let name = node
            .children
            .iter()
            .take_while(|c| c.kind != K::Params)
            .find(|c| c.kind == K::Ident)
            .map(|n| Rc::from(n.text()));
        let f = self.make_closure(node, name)?;
        Ok(Value::Func(f))
    }

    pub fn make_closure(&mut self, node: &SyntaxNode, name: Option<Str>) -> SourceResult<Func> {
        // Evaluate default values of named parameters.
        let params = child(node, K::Params).unwrap();
        let mut defaults = vec![];
        let mut num_pos = 0;
        for p in &params.children {
            match p.kind {
                K::Named => {
                    let v = self.eval_expr(last_expr(p).unwrap())?;
                    defaults.push(v);
                }
                K::Spread => {}
                k if is_pattern_kind(k) => num_pos += 1,
                _ => {}
            }
        }
        // Capture variables.
        let mut captured = Scope::new();
        let mut names = vec![];
        collect_idents(node, &mut names);
        for n in names {
            if captured.get(&n).is_none() {
                if let Some(v) = self.scopes.visible(&n) {
                    captured.define(n.as_str(), v);
                }
            }
        }
        let closure = Closure {
            name,
            node: node.clone(),
            captured,
            file: self.file,
            defaults,
            num_pos_params: num_pos,
            context: None,
        };
        Ok(Func { kind: FuncKind::Closure(Rc::new(closure)), span: self.span(node) })
    }

    pub fn make_closure_from_body(&mut self, body: &SyntaxNode) -> SourceResult<Func> {
        // Build a synthetic closure with no params.
        let params = SyntaxNode::inner(K::Params, vec![]);
        let mut node = SyntaxNode::inner(K::Closure, vec![params, body.clone()]);
        node.offset = body.offset;
        node.children[0].offset = body.offset;
        let mut captured = Scope::new();
        let mut names = vec![];
        collect_idents(body, &mut names);
        for n in names {
            if captured.get(&n).is_none() {
                if let Some(v) = self.scopes.visible(&n) {
                    captured.define(n.as_str(), v);
                }
            }
        }
        let closure = Closure {
            name: None,
            node,
            captured,
            file: self.file,
            defaults: vec![],
            num_pos_params: 0,
            context: None,
        };
        Ok(Func { kind: FuncKind::Closure(Rc::new(closure)), span: self.span(body) })
    }

    fn eval_let(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        // let binding: either closure or pattern
        let after_let: Vec<&SyntaxNode> =
            node.children.iter().skip(1).filter(|c| !c.kind.is_trivia()).collect();
        if let Some(first) = after_let.first() {
            if first.kind == K::Closure {
                let name = child(first, K::Ident).map(|n| Rc::from(n.text()));
                let f = self.make_closure(first, name.clone())?;
                if let Some(n) = name {
                    self.define(n, Value::Func(f));
                }
                return Ok(Value::None);
            }
        }
        // Pattern binding
        let pattern = match after_let.first() {
            Some(p) => *p,
            None => return Ok(Value::None),
        };
        let has_eq = node.children.iter().any(|c| c.kind == K::Eq);
        let value = if has_eq {
            let init = node.children.iter().skip_while(|c| c.kind != K::Eq).skip(1).find(|c| is_expr_kind(c.kind));
            match init {
                Some(e) => self.eval_expr(e)?,
                None => Value::None,
            }
        } else {
            Value::None
        };
        if self.flow.is_some() {
            return Ok(Value::None);
        }
        self.destructure(pattern, value, false)?;
        Ok(Value::None)
    }

    pub fn destructure(&mut self, pattern: &SyntaxNode, value: Value, reassign: bool) -> SourceResult<()> {
        let span = self.span(pattern);
        match pattern.kind {
            K::Ident if !reassign => {
                self.define(pattern.text(), value);
                Ok(())
            }
            K::Underscore => Ok(()),
            K::Parenthesized => {
                let inner = pattern.children.iter().find(|c| is_pattern_kind(c.kind)).unwrap();
                self.destructure(inner, value, reassign)
            }
            K::Destructuring => self.destructure_impl(pattern, value, reassign),
            _ if reassign => {
                let slot = self.access(pattern)?;
                *slot = value;
                Ok(())
            }
            _ => bail!(span, "cannot destructure {}", value.type_name()),
        }
    }

    fn destructure_impl(&mut self, pattern: &SyntaxNode, value: Value, reassign: bool) -> SourceResult<()> {
        let span = self.span(pattern);
        let items: Vec<&SyntaxNode> = pattern
            .children
            .iter()
            .filter(|c| is_pattern_kind(c.kind) || matches!(c.kind, K::Named | K::Spread))
            .collect();
        match value {
            Value::Array(arr) => {
                let len = arr.len();
                let count = items.iter().filter(|i| i.kind != K::Spread).count();
                let has_sink = items.iter().any(|i| i.kind == K::Spread);
                let mut i = 0;
                for item in &items {
                    match item.kind {
                        K::Named => {
                            bail!(self.span(item), "cannot destructure named pattern from an array");
                        }
                        K::Spread => {
                            let sink_size = (1 + len).checked_sub(count + 1).unwrap_or(0);
                            let sink_size = if len >= count { len - count } else { 0 };
                            let _ = sink_size;
                            let take = len.saturating_sub(count);
                            let sink: Vec<Value> = arr.iter().skip(i).take(take).cloned().collect();
                            if let Some(target) = item.children.iter().find(|c| is_pattern_kind(c.kind)) {
                                self.destructure(target, Value::array(sink), reassign)?;
                            }
                            i += take;
                        }
                        _ => {
                            if i < len {
                                let v = arr[i].clone();
                                self.destructure(item, v, reassign)?;
                                i += 1;
                            } else {
                                return Err(vec![wrong_number(span, len, count, has_sink, false)]);
                            }
                        }
                    }
                }
                if i < len {
                    return Err(vec![wrong_number(span, len, count, has_sink, true)]);
                }
                Ok(())
            }
            Value::Dict(dict) => {
                let mut used = std::collections::HashSet::new();
                for item in &items {
                    match item.kind {
                        K::Ident => {
                            let key = item.text();
                            let v = match dict.get(key) {
                                Some(v) => v.clone(),
                                None => bail!(self.span(item), "dictionary does not contain key {}", crate::repr::repr_str(key)),
                            };
                            used.insert(key.to_string());
                            self.destructure(item, v, reassign)?;
                        }
                        K::Named => {
                            let key_node = child(item, K::Ident).unwrap();
                            let key = key_node.text();
                            let v = match dict.get(key) {
                                Some(v) => v.clone(),
                                None => bail!(self.span(key_node), "dictionary does not contain key {}", crate::repr::repr_str(key)),
                            };
                            used.insert(key.to_string());
                            let target = item.children.iter().rev().find(|c| is_pattern_kind(c.kind)).unwrap();
                            self.destructure(target, v, reassign)?;
                        }
                        K::Spread => {
                            let mut rest = Dict::new();
                            for (k, v) in dict.iter() {
                                if !used.contains(&**k) {
                                    rest.insert(k.clone(), v.clone());
                                }
                            }
                            if let Some(target) = item.children.iter().find(|c| is_pattern_kind(c.kind)) {
                                self.destructure(target, Value::dict(rest), reassign)?;
                            }
                        }
                        K::Underscore => {}
                        _ => bail!(self.span(item), "cannot destructure unnamed pattern from dictionary"),
                    }
                }
                Ok(())
            }
            v => bail!(span, "cannot destructure {}", v.type_name()),
        }
    }

    fn eval_conditional(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let es: Vec<&SyntaxNode> = exprs(node).collect();
        let cond_node = es[0];
        let cond = self.eval_expr(cond_node)?;
        let cond = match cond {
            Value::Bool(b) => b,
            v => bail!(self.span(cond_node), "expected boolean, found {}", v.type_name()),
        };
        if cond {
            match es.get(1) {
                Some(b) => self.eval_expr(b),
                None => Ok(Value::None),
            }
        } else {
            match es.get(2) {
                Some(b) => self.eval_expr(b),
                None => Ok(Value::None),
            }
        }
    }

    fn eval_while(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        let es: Vec<&SyntaxNode> = exprs(node).collect();
        let cond_node = es[0];
        let body = es[1];
        let mut i = 0;
        loop {
            let c = self.eval_expr(cond_node)?;
            let c = match c {
                Value::Bool(b) => b,
                v => bail!(self.span(cond_node), "expected boolean, found {}", v.type_name()),
            };
            if !c {
                break;
            }
            if i == 0 && is_invariant(cond_node) && !can_diverge(body) {
                bail!(self.span(cond_node), "condition is always true");
            } else if i >= 10_000 {
                bail!(self.span(node), "loop seems to be infinite");
            }
            let value = self.eval_expr(body)?;
            let span = self.span(body);
            output = crate::ops::join(output, value).at(span)?;
            match self.flow {
                Some(Flow::Break(_)) => {
                    self.flow = None;
                    break;
                }
                Some(Flow::Continue(_)) => self.flow = None,
                Some(Flow::Return(..)) => break,
                None => {}
            }
            i += 1;
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    fn eval_for(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        // children: for, pattern, in, iterable, body
        let mut it = node.children.iter().filter(|c| !c.kind.is_trivia());
        it.next(); // for
        let pattern = it.next().unwrap();
        let mut rest = node.children.iter().skip_while(|c| c.kind != K::In).skip(1).filter(|c| is_expr_kind(c.kind));
        let iter_node = rest.next().unwrap();
        let body = rest.next().unwrap();
        let iterable = self.eval_expr(iter_node)?;
        let iter_span = self.span(iter_node);
        let items: Vec<Value> = match &iterable {
            Value::Array(a) => a.iter().cloned().collect(),
            Value::Dict(d) => d.iter().map(|(k, v)| Value::array(vec![Value::Str(k.clone()), v.clone()])).collect(),
            Value::Str(s) => crate::unicode::graphemes(s).into_iter().map(Value::str).collect(),
            Value::Bytes(b) => b.iter().map(|x| Value::Int(*x as i64)).collect(),
            Value::Args(_) => bail!(iter_span, "cannot loop over arguments"),
            v => bail!(iter_span, "cannot loop over {}", v.type_name()),
        };
        if matches!(iterable, Value::Str(_)) && pattern.kind == K::Destructuring {
            bail!(self.span(pattern), "cannot destructure values of string");
        }
        self.scopes.enter();
        for item in items {
            self.destructure(pattern, item, false)?;
            let value = self.eval_expr(body)?;
            let span = self.span(body);
            output = crate::ops::join(output, value).at(span)?;
            match self.flow {
                Some(Flow::Break(_)) => {
                    self.flow = None;
                    break;
                }
                Some(Flow::Continue(_)) => self.flow = None,
                Some(Flow::Return(..)) => break,
                None => {}
            }
        }
        self.scopes.exit();
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    fn eval_set_rule(&mut self, node: &SyntaxNode) -> SourceResult<Styles> {
        // set target(args) [if cond]
        let target_node = node.children.iter().find(|c| matches!(c.kind, K::Ident | K::FieldAccess)).unwrap();
        let args_node = child(node, K::Args).unwrap();
        if let Some(cond_pos) = node.children.iter().position(|c| c.kind == K::If) {
            let cond_node = node.children[cond_pos..].iter().find(|c| is_expr_kind(c.kind)).unwrap();
            let c = self.eval_expr(cond_node)?;
            match c {
                Value::Bool(false) => return Ok(Styles::new()),
                Value::Bool(true) => {}
                v => bail!(self.span(cond_node), "expected boolean, found {}", v.type_name()),
            }
        }
        let target = self.eval_expr(target_node)?;
        let tspan = self.span(target_node);
        let mut args = self.eval_args(args_node)?;
        args.span = self.span(args_node);
        let func = match target {
            Value::Func(f) => f,
            Value::Type(t) => Func { kind: FuncKind::Type(t), span: tspan },
            v => bail!(tspan, "expected function, found {}", v.type_name()),
        };
        crate::styles::set_rule(self.engine, &func, tspan, args)
    }

    fn eval_show_rule(&mut self, node: &SyntaxNode) -> SourceResult<Recipe> {
        let colon = node.children.iter().position(|c| c.kind == K::Colon);
        let (selector_node, transform_node) = match colon {
            Some(ci) => {
                let sel = node.children[..ci].iter().find(|c| is_expr_kind(c.kind));
                let tr = node.children[ci..].iter().find(|c| is_expr_kind(c.kind));
                (sel, tr.unwrap())
            }
            None => (None, last_expr(node).unwrap()),
        };
        let selector = match selector_node {
            Some(s) => {
                let v = self.eval_expr(s)?;
                Some(crate::styles::cast_show_selector(v).at(self.span(s))?)
            }
            None => None,
        };
        let transform = self.eval_expr(transform_node)?;
        let tspan = self.span(transform_node);
        let transform = match transform {
            Value::Func(_) | Value::Content(_) | Value::Str(_) | Value::Symbol(_) | Value::None | Value::Styles(_) => transform,
            Value::Type(t) => Value::Func(Func { kind: FuncKind::Type(t), span: tspan }),
            v => bail!(tspan, "expected content or function, found {}", v.type_name()),
        };
        Ok(Recipe { selector, transform, span: self.span(node) })
    }

    fn eval_import(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        crate::module::eval_import(self, node)
    }

    fn eval_include(&mut self, node: &SyntaxNode) -> SourceResult<Value> {
        crate::module::eval_include(self, node)
    }
}

fn in_math_field(node: &SyntaxNode) -> bool {
    match node.kind {
        K::MathIdent => true,
        K::FieldAccess => node.children.first().is_some_and(in_math_field),
        _ => false,
    }
}

fn wrong_number(span: Span, len: usize, count: usize, has_sink: bool, too_many: bool) -> Diag {
    let quantifier = if too_many { "too many" } else { "not enough" };
    let mut d = Diag::error(span, format!("{quantifier} elements to destructure"));
    let elems = if count == 1 { "element" } else { "elements" };
    let hint = if has_sink {
        format!("the provided array has a length of {len}, but the pattern expects at least {count} {elems}")
    } else if len == 0 {
        format!("the provided array is empty, but the pattern expects {count} {elems}")
    } else {
        format!("the provided array has a length of {len}, but the pattern expects {count} {elems}")
    };
    d.hints.push(hint);
    d
}

fn is_invariant(node: &SyntaxNode) -> bool {
    match node.kind {
        K::Ident => false,
        K::Bool | K::None | K::Auto | K::Int | K::Float | K::Str | K::Numeric => true,
        K::Parenthesized | K::Unary | K::Binary => exprs(node).all(is_invariant),
        K::FieldAccess => first_expr(node).is_some_and(is_invariant),
        K::FuncCall => false,
        K::CodeBlock => node.children.iter().find(|c| c.kind == K::Code).is_some_and(|c| exprs(c).all(is_invariant)),
        K::ContentBlock => false,
        _ => false,
    }
}

fn can_diverge(node: &SyntaxNode) -> bool {
    matches!(node.kind, K::LoopBreak | K::FuncReturn) || node.children.iter().any(can_diverge)
}

fn collect_idents(node: &SyntaxNode, out: &mut Vec<String>) {
    match node.kind {
        K::Ident | K::MathIdent => out.push(node.text().to_string()),
        _ => {
            for c in &node.children {
                collect_idents(c, out);
            }
        }
    }
}

pub fn add_trace<T>(result: SourceResult<T>, span: Span, msg: impl Fn() -> String) -> SourceResult<T> {
    result.map_err(|mut errors| {
        if span.is_detached() {
            return errors;
        }
        for e in errors.iter_mut() {
            if e.span.file == span.file && span.start <= e.span.start && span.end >= e.span.end {
                continue;
            }
            e.trace.push((span, msg()));
        }
        errors
    })
}

pub fn parse_int(s: &str) -> i64 {
    if let Some(h) = s.strip_prefix("0x") {
        i64::from_str_radix(h, 16).unwrap_or(0)
    } else if let Some(o) = s.strip_prefix("0o") {
        i64::from_str_radix(o, 8).unwrap_or(0)
    } else if let Some(b) = s.strip_prefix("0b") {
        i64::from_str_radix(b, 2).unwrap_or(0)
    } else {
        s.parse().unwrap_or(0)
    }
}

pub fn eval_numeric(text: &str) -> Value {
    let split = text
        .char_indices()
        .rev()
        .take_while(|(_, c)| c.is_ascii_alphabetic() || *c == '%')
        .last()
        .map(|(i, _)| i)
        .unwrap_or(text.len());
    let (num, unit) = text.split_at(split);
    let v: f64 = num.parse().unwrap_or(0.0);
    match unit {
        "pt" => Value::Length(Length::pt(v)),
        "mm" => Value::Length(Length::pt(v * 2.83465)),
        "cm" => Value::Length(Length::pt(v * 28.3465)),
        "in" => Value::Length(Length::pt(v * 72.0)),
        "em" => Value::Length(Length::em(v)),
        "deg" => Value::Angle(v.to_radians()),
        "rad" => Value::Angle(v),
        "fr" => Value::Fraction(v),
        "%" => Value::Ratio(v / 100.0),
        _ => Value::Float(v),
    }
}

pub fn escape_char(text: &str) -> char {
    let rest = &text[1..];
    if let Some(hex) = rest.strip_prefix("u{") {
        let hex = hex.trim_end_matches('}');
        u32::from_str_radix(hex, 16).ok().and_then(char::from_u32).unwrap_or('\u{FFFD}')
    } else {
        rest.chars().next().unwrap_or(' ')
    }
}

pub fn shorthand_char(text: &str) -> char {
    match text {
        "~" => '\u{00A0}',
        "--" => '\u{2013}',
        "---" => '\u{2014}',
        "-?" => '\u{00AD}',
        "..." => '…',
        "-" => '\u{2212}',
        _ => '?',
    }
}

pub fn eval_raw(node: &SyntaxNode) -> Content {
    let mut lines = vec![];
    let mut lang = None;
    let mut backticks = 0;
    let mut has_newline = false;
    for c in &node.children {
        match c.kind {
            K::RawDelim => {
                if backticks == 0 {
                    backticks = c.text().len();
                }
            }
            K::RawLang => lang = Some(c.text().to_string()),
            K::Text => lines.push(c.text().to_string()),
            K::RawTrimmed => {
                if c.text().contains(crate::syntax::lexer::is_newline) {
                    has_newline = true;
                }
            }
            _ => {}
        }
    }
    let text = lines.join("\n");
    let block = backticks >= 3 && has_newline;
    let mut c = Content::new(&el::RAW).with("text", Value::str(text)).with("block", block);
    if let Some(l) = lang {
        c = c.with("lang", Value::str(l));
    }
    c
}

pub fn styled_with_map(content: Content, styles: Styles) -> Content {
    if styles.is_empty() {
        content
    } else if content.is_styled() {
        // merge: outer styles first
        let inner_styles = match content.get("styles") {
            Some(Value::Styles(s)) => s.clone(),
            _ => Styles::new(),
        };
        let child = match content.get("child") {
            Some(Value::Content(c)) => c.clone(),
            _ => Content::empty(),
        };
        let mut v: Vec<Style> = (*styles.0).clone();
        v.extend(inner_styles.0.iter().cloned());
        let _ = &v;
        child.styled(Styles::from(v))
    } else {
        content.styled(styles)
    }
}

pub fn styled_with_recipe(engine: &mut Engine, content: Content, recipe: Recipe) -> SourceResult<Content> {
    if recipe.selector.is_none() {
        // Apply transform directly.
        return match &recipe.transform {
            Value::Func(f) => {
                let args = Args::new(recipe.span, vec![Value::Content(content)]);
                let v = crate::func_call::call_func(engine, f, args, &ContextInfo::default())?;
                Ok(to_content(v))
            }
            Value::Styles(s) => Ok(styled_with_map(content, s.clone())),
            other => Ok(to_content(other.clone())),
        };
    }
    Ok(styled_with_map(content, Styles::from(vec![Style::Recipe(Rc::new(recipe))])))
}
