cd /workspace/src && cat > ops.rs <<'EOF'
//! Operators.

use crate::content::Content;
use crate::diag::*;
use crate::value::*;
use std::cmp::Ordering;
use std::rc::Rc;

fn too_large() -> HintedString {
    HintedString::new("value is too large")
}

fn rel_of(v: &Value) -> Option<Rel> {
    match v {
        Value::Length(l) => Some(Rel { rel: 0.0, abs: *l }),
        Value::Ratio(r) => Some(Rel { rel: *r, abs: Length::zero() }),
        Value::Relative(r) => Some(*r),
        _ => None,
    }
}

fn num(v: &Value) -> Option<f64> {
    match v {
        Value::Int(i) => Some(*i as f64),
        Value::Float(f) => Some(*f),
        _ => None,
    }
}

fn len_add(a: Length, b: Length) -> Length {
    Length { abs: a.abs + b.abs, em: a.em + b.em }
}

fn len_scale(a: Length, s: f64) -> Length {
    Length { abs: a.abs * s, em: a.em * s }
}

fn rel_add(a: Rel, b: Rel) -> Value {
    Value::Relative(Rel { rel: a.rel + b.rel, abs: len_add(a.abs, b.abs) })
}

pub fn join(lhs: Value, rhs: Value) -> StrResult<Value> {
    Ok(match (lhs, rhs) {
        (a, Value::None) => a,
        (Value::None, b) => b,
        (Value::Symbol(a), Value::Symbol(b)) => Value::str(format!("{}{}", a.text, b.text)),
        (Value::Str(a), Value::Str(b)) => Value::str(format!("{a}{b}")),
        (Value::Str(a), Value::Symbol(b)) => Value::str(format!("{a}{}", b.text)),
        (Value::Symbol(a), Value::Str(b)) => Value::str(format!("{}{b}", a.text)),
        (Value::Bytes(a), Value::Bytes(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter());
            Value::Bytes(Rc::new(v))
        }
        (Value::Content(a), Value::Content(b)) => Value::Content(a.add(b)),
        (Value::Content(a), Value::Symbol(b)) => Value::Content(a.add(Content::symbol(&*b.text))),
        (Value::Content(a), Value::Str(b)) => Value::Content(a.add(Content::text(&*b))),
        (Value::Str(a), Value::Content(b)) => Value::Content(Content::text(&*a).add(b)),
        (Value::Symbol(a), Value::Content(b)) => Value::Content(Content::symbol(&*a.text).add(b)),
        (Value::Array(a), Value::Array(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter().cloned());
            Value::array(v)
        }
        (Value::Dict(a), Value::Dict(b)) => {
            let mut d = (*a).clone();
            for (k, v) in b.iter() {
                d.insert(k.clone(), v.clone());
            }
            Value::dict(d)
        }
        (Value::Args(a), Value::Args(b)) => {
            let mut a2 = (*a).clone();
            a2.items.extend(b.items.iter().cloned());
            Value::Args(Rc::new(a2))
        }
        (Value::Styles(a), Value::Styles(b)) => {
            let mut v = (*a.0).clone();
            v.extend(b.0.iter().cloned());
            Value::Styles(crate::content::Styles::from(v))
        }
        (a, b) => return Err(format!("cannot join {} with {}", a.type_name(), b.type_name()).into()),
    })
}

pub fn pos(v: Value) -> StrResult<Value> {
    Ok(match v {
        Value::Int(_) | Value::Float(_) | Value::Decimal(_) | Value::Length(_) | Value::Angle(_)
        | Value::Ratio(_) | Value::Relative(_) | Value::Fraction(_) => v,
        _ => return Err(format!("cannot apply unary '+' to {}", v.type_name()).into()),
    })
}

pub fn neg(v: Value) -> StrResult<Value> {
    Ok(match v {
        Value::Int(i) => Value::Int(i.checked_neg().ok_or_else(too_large)?),
        Value::Float(f) => Value::Float(-f),
        Value::Decimal(d) => Value::Decimal(crate::decimal::neg(&d)),
        Value::Length(l) => Value::Length(len_scale(l, -1.0)),
        Value::Angle(a) => Value::Angle(-a),
        Value::Ratio(r) => Value::Ratio(-r),
        Value::Relative(r) => Value::Relative(Rel { rel: -r.rel, abs: len_scale(r.abs, -1.0) }),
        Value::Fraction(f) => Value::Fraction(-f),
        Value::Duration(d) => Value::Duration(Duration(-d.0)),
        _ => return Err(format!("cannot apply '-' to {}", v.type_name()).into()),
    })
}

pub fn not(v: Value) -> StrResult<Value> {
    match v {
        Value::Bool(b) => Ok(Value::Bool(!b)),
        _ => Err(format!("cannot apply 'not' to {}", v.type_name()).into()),
    }
}

pub fn and(a: Value, b: Value) -> StrResult<Value> {
    match (&a, &b) {
        (Value::Bool(x), Value::Bool(y)) => Ok(Value::Bool(*x && *y)),
        _ => Err(format!("cannot apply 'and' to {} and {}", a.type_name(), b.type_name()).into()),
    }
}

pub fn or(a: Value, b: Value) -> StrResult<Value> {
    match (&a, &b) {
        (Value::Bool(x), Value::Bool(y)) => Ok(Value::Bool(*x || *y)),
        _ => Err(format!("cannot apply 'or' to {} and {}", a.type_name(), b.type_name()).into()),
    }
}

pub fn add(lhs: Value, rhs: Value) -> StrResult<Value> {
    use Value::*;
    Ok(match (lhs, rhs) {
        (a, None) => a,
        (None, b) => b,
        (Int(a), Int(b)) => Int(a.checked_add(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 + b),
        (Float(a), Int(b)) => Float(a + b as f64),
        (Float(a), Float(b)) => Float(a + b),
        (Decimal(a), Decimal(b)) => Decimal(crate::decimal::add(&a, &b).ok_or_else(too_large)?),
        (Decimal(a), Int(b)) => Decimal(crate::decimal::add(&a, &crate::decimal::from_int(b)).ok_or_else(too_large)?),
        (Int(a), Decimal(b)) => Decimal(crate::decimal::add(&crate::decimal::from_int(a), &b).ok_or_else(too_large)?),
        (Angle(a), Angle(b)) => Angle(a + b),
        (Length(a), Length(b)) => Length(len_add(a, b)),
        (Fraction(a), Fraction(b)) => Fraction(a + b),
        (a @ (Length(_) | Ratio(_) | Relative(_)), b @ (Length(_) | Ratio(_) | Relative(_))) => {
            if let (Ratio(x), Ratio(y)) = (&a, &b) {
                return Ok(Ratio(x + y));
            }
            rel_add(rel_of(&a).unwrap(), rel_of(&b).unwrap())
        }
        (Symbol(a), Symbol(b)) => Value::str(format!("{}{}", a.text, b.text)),
        (Str(a), Str(b)) => Value::str(format!("{a}{b}")),
        (Str(a), Symbol(b)) => Value::str(format!("{a}{}", b.text)),
        (Symbol(a), Str(b)) => Value::str(format!("{}{b}", a.text)),
        (Bytes(a), Bytes(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter());
            Bytes(Rc::new(v))
        }
        (Content(a), Content(b)) => Content(a.add(b)),
        (Content(a), Symbol(b)) => Content(a.add(crate::content::Content::symbol(&*b.text))),
        (Content(a), Str(b)) => Content(a.add(crate::content::Content::text(&*b))),
        (Str(a), Content(b)) => Content(crate::content::Content::text(&*a).add(b)),
        (Symbol(a), Content(b)) => Content(crate::content::Content::symbol(&*a.text).add(b)),
        (Array(a), Array(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter().cloned());
            Value::array(v)
        }
        (Dict(a), Dict(b)) => {
            let mut d = (*a).clone();
            for (k, v) in b.iter() {
                d.insert(k.clone(), v.clone());
            }
            Value::dict(d)
        }
        (Args(a), Args(b)) => {
            let mut a2 = (*a).clone();
            a2.items.extend(b.items.iter().cloned());
            Args(Rc::new(a2))
        }
        (a @ (Color(_) | Gradient(_) | Tiling(_)), Length(l)) | (Length(l), a @ (Color(_) | Gradient(_) | Tiling(_))) => {
            Stroke(Rc::new(crate::value::Stroke {
                paint: Some(a),
                thickness: Some(Length(l)),
                cap: Option::None,
                join: Option::None,
                dash: Option::None,
                miter_limit: Option::None,
            }))
        }
        (Datetime(a), Duration(b)) => Datetime(crate::datetime::add_duration(&a, b.0)?),
        (Duration(a), Datetime(b)) => Datetime(crate::datetime::add_duration(&b, a.0)?),
        (Duration(a), Duration(b)) => Duration(crate::value::Duration(a.0 + b.0)),
        (Alignment(a), Alignment(b)) => Alignment(add_align(a, b)?),
        (a, b) => return Err(format!("cannot add {} and {}", a.type_name(), b.type_name()).into()),
    })
}

fn add_align(a: crate::value::Alignment, b: crate::value::Alignment) -> StrResult<crate::value::Alignment> {
    let a2d = a.x.is_some() && a.y.is_some();
    let b2d = b.x.is_some() && b.y.is_some();
    if a2d && b2d {
        return Err("cannot add two 2D alignments".into());
    }
    if a2d || b2d {
        let (first, second) = if a2d { ("2D", if b.x.is_some() { "horizontal" } else { "vertical" }) } else {
            (if a.x.is_some() { "horizontal" } else { "vertical" }, "2D")
        };
        return Err(format!("cannot add a {first} and a {second} alignment").into());
    }
    match (a.x, a.y, b.x, b.y) {
        (Some(_), _, Some(_), _) => Err("cannot add two horizontal alignments".into()),
        (_, Some(_), _, Some(_)) => Err("cannot add two vertical alignments".into()),
        (x, None, None, y) => Ok(crate::value::Alignment { x, y }),
        (None, y, x, None) => Ok(crate::value::Alignment { x, y }),
        _ => Err("cannot add alignments".into()),
    }
}

pub fn sub(lhs: Value, rhs: Value) -> StrResult<Value> {
    use Value::*;
    Ok(match (lhs, rhs) {
        (Int(a), Int(b)) => Int(a.checked_sub(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 - b),
        (Float(a), Int(b)) => Float(a - b as f64),
        (Float(a), Float(b)) => Float(a - b),
        (Decimal(a), Decimal(b)) => Decimal(crate::decimal::sub(&a, &b).ok_or_else(too_large)?),
        (Decimal(a), Int(b)) => Decimal(crate::decimal::sub(&a, &crate::decimal::from_int(b)).ok_or_else(too_large)?),
        (Int(a), Decimal(b)) => Decimal(crate::decimal::sub(&crate::decimal::from_int(a), &b).ok_or_else(too_large)?),
        (Angle(a), Angle(b)) => Angle(a - b),
        (Length(a), Length(b)) => Length(len_add(a, len_scale(b, -1.0))),
        (Fraction(a), Fraction(b)) => Fraction(a - b),
        (a @ (Length(_) | Ratio(_) | Relative(_)), b @ (Length(_) | Ratio(_) | Relative(_))) => {
            if let (Ratio(x), Ratio(y)) = (&a, &b) {
                return Ok(Ratio(x - y));
            }
            let rb = rel_of(&b).unwrap();
            rel_add(rel_of(&a).unwrap(), Rel { rel: -rb.rel, abs: len_scale(rb.abs, -1.0) })
        }
        (Datetime(a), Duration(b)) => Datetime(crate::datetime::add_duration(&a, -b.0)?),
        (Datetime(a), Datetime(b)) => Duration(crate::datetime::sub_datetimes(&a, &b)?),
        (Duration(a), Duration(b)) => Duration(crate::value::Duration(a.0 - b.0)),
        (a, b) => return Err(format!("cannot subtract {1} from {0}", a.type_name(), b.type_name()).into()),
    })
}

fn repeat_count(n: i64) -> StrResult<usize> {
    if n < 0 {
        Err("number must be at least zero".into())
    } else {
        Ok(n as usize)
    }
}

pub fn mul(lhs: Value, rhs: Value) -> StrResult<Value> {
    use Value::*;
    Ok(match (lhs, rhs) {
        (Int(a), Int(b)) => Int(a.checked_mul(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 * b),
        (Float(a), Int(b)) => Float(a * b as f64),
        (Float(a), Float(b)) => Float(a * b),
        (Decimal(a), Decimal(b)) => Decimal(crate::decimal::mul(&a, &b).ok_or_else(too_large)?),
        (Decimal(a), Int(b)) => Decimal(crate::decimal::mul(&a, &crate::decimal::from_int(b)).ok_or_else(too_large)?),
        (Int(a), Decimal(b)) => Decimal(crate::decimal::mul(&crate::decimal::from_int(a), &b).ok_or_else(too_large)?),
        (Length(a), b @ (Int(_) | Float(_))) => Length(len_scale(a, num(&b).unwrap())),
        (a @ (Int(_) | Float(_)), Length(b)) => Length(len_scale(b, num(&a).unwrap())),
        (Angle(a), b @ (Int(_) | Float(_))) => Angle(a * num(&b).unwrap()),
        (a @ (Int(_) | Float(_)), Angle(b)) => Angle(b * num(&a).unwrap()),
        (Ratio(a), b @ (Int(_) | Float(_))) => Ratio(a * num(&b).unwrap()),
        (a @ (Int(_) | Float(_)), Ratio(b)) => Ratio(b * num(&a).unwrap()),
        (Relative(a), b @ (Int(_) | Float(_))) => {
            let s = num(&b).unwrap();
            Relative(Rel { rel: a.rel * s, abs: len_scale(a.abs, s) })
        }
        (a @ (Int(_) | Float(_)), Relative(b)) => {
            let s = num(&a).unwrap();
            Relative(Rel { rel: b.rel * s, abs: len_scale(b.abs, s) })
        }
        (Fraction(a), b @ (Int(_) | Float(_))) => Fraction(a * num(&b).unwrap()),
        (a @ (Int(_) | Float(_)), Fraction(b)) => Fraction(b * num(&a).unwrap()),
        (Ratio(a), Ratio(b)) => Ratio(a * b),
        (Ratio(a), Length(b)) => Length(len_scale(b, a)),
        (Length(a), Ratio(b)) => Length(len_scale(a, b)),
        (Ratio(a), Fraction(b)) => Fraction(a * b),
        (Fraction(a), Ratio(b)) => Fraction(a * b),
        (Ratio(a), Relative(b)) => Relative(Rel { rel: b.rel * a, abs: len_scale(b.abs, a) }),
        (Relative(a), Ratio(b)) => Relative(Rel { rel: a.rel * b, abs: len_scale(a.abs, b) }),
        (Str(a), Int(b)) => Value::str(a.repeat(repeat_count(b)?)),
        (Int(a), Str(b)) => Value::str(b.repeat(repeat_count(a)?)),
        (Array(a), Int(b)) => {
            let n = repeat_count(b)?;
            let mut v = Vec::with_capacity(a.len() * n);
            for _ in 0..n {
                v.extend(a.iter().cloned());
            }
            Value::array(v)
        }
        (Int(a), Array(b)) => {
            let n = repeat_count(a)?;
            let mut v = Vec::with_capacity(b.len() * n);
            for _ in 0..n {
                v.extend(b.iter().cloned());
            }
            Value::array(v)
        }
        (Content(a), Int(b)) => {
            let n = repeat_count(b)?;
            Content(crate::content::Content::sequence(std::iter::repeat(a).take(n).collect()))
        }
        (Int(a), Content(b)) => {
            let n = repeat_count(a)?;
            Content(crate::content::Content::sequence(std::iter::repeat(b).take(n).collect()))
        }
        (Duration(a), b @ (Int(_) | Float(_))) => Duration(crate::value::Duration(a.0 * num(&b).unwrap())),
        (a @ (Int(_) | Float(_)), Duration(b)) => Duration(crate::value::Duration(b.0 * num(&a).unwrap())),
        (a, b) => return Err(format!("cannot multiply {} with {}", a.type_name(), b.type_name()).into()),
    })
}

fn is_zero(v: &Value) -> bool {
    match v {
        Value::Int(0) => true,
        Value::Float(f) => *f == 0.0,
        Value::Decimal(d) => d.mantissa == 0,
        Value::Length(l) => l.is_zero(),
        Value::Angle(a) => *a == 0.0,
        Value::Ratio(r) => *r == 0.0,
        Value::Relative(r) => r.rel == 0.0 && r.abs.is_zero(),
        Value::Fraction(f) => *f == 0.0,
        Value::Duration(d) => d.0 == 0.0,
        _ => false,
    }
}

fn try_div_length(a: Length, b: Length) -> StrResult<f64> {
    if a.em == 0.0 && b.em == 0.0 {
        Ok(a.abs / b.abs)
    } else if a.abs == 0.0 && b.abs == 0.0 {
        Ok(a.em / b.em)
    } else {
        Err("cannot divide these two lengths".into())
    }
}

pub fn div(lhs: Value, rhs: Value) -> StrResult<Value> {
    use Value::*;
    if is_zero(&rhs) {
        return Err("cannot divide by zero".into());
    }
    Ok(match (lhs, rhs) {
        (a @ (Int(_) | Float(_)), b @ (Int(_) | Float(_))) => Float(num(&a).unwrap() / num(&b).unwrap()),
        (Decimal(a), Decimal(b)) => Decimal(crate::decimal::div(&a, &b).ok_or_else(too_large)?),
        (Decimal(a), Int(b)) => Decimal(crate::decimal::div(&a, &crate::decimal::from_int(b)).ok_or_else(too_large)?),
        (Int(a), Decimal(b)) => Decimal(crate::decimal::div(&crate::decimal::from_int(a), &b).ok_or_else(too_large)?),
        (Length(a), b @ (Int(_) | Float(_))) => Length(len_scale(a, 1.0 / num(&b).unwrap())),
        (Length(a), Length(b)) => Float(try_div_length(a, b)?),
        (Angle(a), b @ (Int(_) | Float(_))) => Angle(a / num(&b).unwrap()),
        (Angle(a), Angle(b)) => Float(a / b),
        (Ratio(a), b @ (Int(_) | Float(_))) => Ratio(a / num(&b).unwrap()),
        (Ratio(a), Ratio(b)) => Float(a / b),
        (Relative(a), b @ (Int(_) | Float(_))) => {
            let s = num(&b).unwrap();
            Relative(Rel { rel: a.rel / s, abs: len_scale(a.abs, 1.0 / s) })
        }
        (Relative(a), Ratio(b)) if a.abs.is_zero() => Float(a.rel / b),
        (Relative(a), Length(b)) if a.rel == 0.0 => Float(try_div_length(a.abs, b)?),
        (Relative(a), Relative(b)) if a.rel == 0.0 && b.rel == 0.0 => Float(try_div_length(a.abs, b.abs)?),
        (Relative(a), Relative(b)) if a.abs.is_zero() && b.abs.is_zero() => Float(a.rel / b.rel),
        (Fraction(a), b @ (Int(_) | Float(_))) => Fraction(a / num(&b).unwrap()),
        (Fraction(a), Fraction(b)) => Float(a / b),
        (Duration(a), b @ (Int(_) | Float(_))) => Duration(crate::value::Duration(a.0 / num(&b).unwrap())),
        (Duration(a), Duration(b)) => Float(a.0 / b.0),
        (a, b) => return Err(format!("cannot divide {} by {}", a.type_name(), b.type_name()).into()),
    })
}

pub fn equal(a: &Value, b: &Value) -> bool {
    use Value::*;
    match (a, b) {
        (None, None) | (Auto, Auto) => true,
        (Bool(x), Bool(y)) => x == y,
        (Int(x), Int(y)) => x == y,
        (Float(x), Float(y)) => x == y,
        (Int(x), Float(y)) | (Float(y), Int(x)) => *x as f64 == *y,
        (Decimal(x), Decimal(y)) => crate::decimal::cmp(x, y) == Ordering::Equal,
        (Decimal(x), Int(y)) | (Int(y), Decimal(x)) => {
            crate::decimal::cmp(x, &crate::decimal::from_int(*y)) == Ordering::Equal
        }
        (Length(x), Length(y)) => x == y,
        (Angle(x), Angle(y)) => x == y,
        (Ratio(x), Ratio(y)) => x == y,
        (Relative(x), Relative(y)) => x == y,
        (Length(_) | Ratio(_) | Relative(_), Length(_) | Ratio(_) | Relative(_)) => rel_of(a) == rel_of(b),
        (Fraction(x), Fraction(y)) => x == y,
        (Color(x), Color(y)) => crate::color::color_eq(x, y),
        (Gradient(x), Gradient(y)) => x.repr == y.repr,
        (Tiling(x), Tiling(y)) => Rc::ptr_eq(x, y),
        (Symbol(x), Symbol(y)) => x.text == y.text,
        (Version(x), Version(y)) => crate::version::cmp(x, y) == Ordering::Equal,
        (Str(x), Str(y)) => x == y,
        (Bytes(x), Bytes(y)) => x == y,
        (Label(x), Label(y)) => x == y,
        (Datetime(x), Datetime(y)) => x == y,
        (Duration(x), Duration(y)) => x == y,
        (Content(x), Content(y)) => x == y,
        (Styles(_), Styles(_)) => false,
        (Array(x), Array(y)) => x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| equal(p, q)),
        (Dict(x), Dict(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| equal(v, w)))
        }
        (Func(x), Func(y)) => x.ptr_eq(y),
        (Args(x), Args(y)) => {
            x.items.len() == y.items.len()
                && x.items.iter().zip(y.items.iter()).all(|(p, q)| p.name == q.name && equal(&p.value, &q.value))
        }
        (Type(x), Type(y)) => x == y,
        (Module(x), Module(y)) => Rc::ptr_eq(x, y) || x.name == y.name,
        (Alignment(x), Alignment(y)) => x == y,
        (Direction(x), Direction(y)) => x == y,
        (Stroke(x), Stroke(y)) => crate::repr::repr(a) == crate::repr::repr(b) && Rc::ptr_eq(x, x) && Rc::ptr_eq(y, y),
        (Selector(_), Selector(_)) => crate::repr::repr(a) == crate::repr::repr(b),
        (Counter(_), Counter(_)) => crate::repr::repr(a) == crate::repr::repr(b),
        (State(x), State(y)) => x.key == y.key && equal(&x.init, &y.init),
        (Location(x), Location(y)) => x == y,
        (Regex(x), Regex(y)) => x.as_str() == y.as_str(),
        _ => false,
    }
}

pub fn compare(a: &Value, b: &Value) -> StrResult<Ordering> {
    use Value::*;
    let mismatch = || HintedString::new(format!("cannot compare {} and {}", a.type_name(), b.type_name()));
    Ok(match (a, b) {
        (Bool(x), Bool(y)) => x.cmp(y),
        (Int(x), Int(y)) => x.cmp(y),
        (Float(x), Float(y)) => x.partial_cmp(y).ok_or_else(|| cannot_compare_nan(a, b))?,
        (Int(x), Float(y)) => (*x as f64).partial_cmp(y).ok_or_else(|| cannot_compare_nan(a, b))?,
        (Float(x), Int(y)) => x.partial_cmp(&(*y as f64)).ok_or_else(|| cannot_compare_nan(a, b))?,
        (Decimal(x), Decimal(y)) => crate::decimal::cmp(x, y),
        (Decimal(x), Int(y)) => crate::decimal::cmp(x, &crate::decimal::from_int(*y)),
        (Int(x), Decimal(y)) => crate::decimal::cmp(&crate::decimal::from_int(*x), y),
        (Length(x), Length(y)) => {
            if x.em == 0.0 && y.em == 0.0 {
                x.abs.partial_cmp(&y.abs).unwrap_or(Ordering::Equal)
            } else if x.abs == 0.0 && y.abs == 0.0 {
                x.em.partial_cmp(&y.em).unwrap_or(Ordering::Equal)
            } else {
                return Err(format!("cannot compare {} with {}", crate::repr::repr(a), crate::repr::repr(b)).into());
            }
        }
        (Angle(x), Angle(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Ratio(x), Ratio(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Relative(x), Relative(y)) => {
            if x.rel == y.rel {
                compare(&Length(x.abs), &Length(y.abs))?
            } else if x.abs == y.abs {
                x.rel.partial_cmp(&y.rel).unwrap_or(Ordering::Equal)
            } else {
                return Err(format!("cannot compare {} with {}", crate::repr::repr(a), crate::repr::repr(b)).into());
            }
        }
        (Fraction(x), Fraction(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Str(x), Str(y)) => x.cmp(y),
        (Version(x), Version(y)) => crate::version::cmp(x, y),
        (Datetime(x), Datetime(y)) => crate::datetime::cmp(x, y).ok_or_else(mismatch)?,
        (Duration(x), Duration(y)) => x.0.partial_cmp(&y.0).unwrap_or(Ordering::Equal),
        (Array(x), Array(y)) => {
            for (p, q) in x.iter().zip(y.iter()) {
                let o = compare(p, q)?;
                if o != Ordering::Equal {
                    return Ok(o);
                }
            }
            x.len().cmp(&y.len())
        }
        _ => return Err(mismatch()),
    })
}

fn cannot_compare_nan(a: &Value, b: &Value) -> HintedString {
    HintedString::new(format!("cannot compare {} with {}", crate::repr::repr(a), crate::repr::repr(b)))
}

pub fn lt(a: Value, b: Value) -> StrResult<Value> {
    Ok(Value::Bool(compare(&a, &b)? == Ordering::Less))
}
pub fn leq(a: Value, b: Value) -> StrResult<Value> {
    Ok(Value::Bool(compare(&a, &b)? != Ordering::Greater))
}
pub fn gt(a: Value, b: Value) -> StrResult<Value> {
    Ok(Value::Bool(compare(&a, &b)? == Ordering::Greater))
}
pub fn geq(a: Value, b: Value) -> StrResult<Value> {
    Ok(Value::Bool(compare(&a, &b)? != Ordering::Less))
}

pub fn contains(a: &Value, b: &Value) -> Option<bool> {
    use Value::*;
    match (a, b) {
        (Str(x), Str(y)) => Some(y.contains(&**x)),
        (Symbol(x), Str(y)) => Some(y.contains(&*x.text)),
        (Regex(r), Str(y)) => Some(r.is_match(y)),
        (Str(x), Dict(d)) => Some(d.contains(x)),
        (x, Array(arr)) => Some(arr.iter().any(|v| equal(v, x))),
        _ => Option::None,
    }
}

pub fn in_(a: Value, b: Value) -> StrResult<Value> {
    match contains(&a, &b) {
        Some(r) => Ok(Value::Bool(r)),
        None => Err(format!("cannot apply 'in' to {} and {}", a.type_name(), b.type_name()).into()),
    }
}

pub fn not_in(a: Value, b: Value) -> StrResult<Value> {
    match contains(&a, &b) {
        Some(r) => Ok(Value::Bool(!r)),
        None => Err(format!("cannot apply 'not in' to {} and {}", a.type_name(), b.type_name()).into()),
    }
}
