//! Calling functions.

use crate::diag::*;
use crate::eval::*;
use crate::func::*;
use crate::syntax::kind::SyntaxKind as K;
use crate::syntax::node::is_expr_kind;
use crate::value::*;
use std::rc::Rc;

pub const MAX_DEPTH: usize = 80;

pub fn call_func(engine: &mut Engine, func: &Func, mut args: Args, context: &ContextInfo) -> SourceResult<Value> {
    if engine.depth >= MAX_DEPTH {
        bail!(args.span, "maximum function call depth exceeded");
    }
    engine.depth += 1;
    let r = call_func_inner(engine, func, &mut args, context);
    engine.depth -= 1;
    r
}

fn call_func_inner(engine: &mut Engine, func: &Func, args: &mut Args, context: &ContextInfo) -> SourceResult<Value> {
    match &func.kind {
        FuncKind::Native(n) => {
            if n.contextual && context.location.is_none() && engine.context.location.is_none() {
                let d = Diag::error(args.span, "can only be used when context is known")
                    .with_hint("try wrapping this in a `context` expression")
                    .with_hint("the `context` expression should wrap everything that depends on this function");
                return Err(vec![d]);
            }
            (n.func)(engine, args)
        }
        FuncKind::Bound(b) => (b.func)(engine, b.this.clone(), args),
        FuncKind::Element(e) => {
            let c = crate::construct::construct(engine, e, args)?;
            Ok(Value::Content(c))
        }
        FuncKind::Closure(c) => call_closure(engine, func, c, std::mem::take(args), context),
        FuncKind::With(w) => {
            let mut a = w.1.clone();
            a.items.extend(std::mem::take(&mut args.items));
            a.span = args.span;
            call_func_inner(engine, &w.0, &mut a, context)
        }
        FuncKind::Type(t) => crate::constructors::construct_type(engine, *t, args),
    }
}

pub fn call_closure(
    engine: &mut Engine,
    func: &Func,
    closure: &Rc<Closure>,
    mut args: Args,
    context: &ContextInfo,
) -> SourceResult<Value> {
    let node = &closure.node;
    let params = node.children.iter().find(|c| c.kind == K::Params).unwrap();
    let body = node.children.iter().rev().find(|c| is_expr_kind(c.kind)).unwrap();

    let mut scopes = Scopes::new(Some(engine.std.clone()));
    scopes.captured = Some(Rc::new(closure.captured.clone()));
    let mut ctx = context.clone();
    if let Some(c) = &closure.context {
        ctx = c.clone();
    }
    let file = closure.file;
    let mut vm = Vm { engine, scopes, flow: None, file, context: ctx };

    if let Some(name) = &closure.name {
        vm.define(name.clone(), Value::Func(func.clone()));
    }

    let num_pos_args = args.items.iter().filter(|a| a.name.is_none()).count();
    let sink_size = num_pos_args.checked_sub(closure.num_pos_params);
    let mut sink: Option<Option<String>> = None;
    let mut sink_pos_values: Option<Vec<Arg>> = None;
    let mut defaults = closure.defaults.iter();

    // A simple params node (from `x => ...`) is just an Ident.
    let param_nodes: Vec<&crate::syntax::node::SyntaxNode> = if params.children.iter().any(|c| c.kind == K::LeftParen) {
        params
            .children
            .iter()
            .filter(|c| crate::eval::is_pattern_kind(c.kind) || matches!(c.kind, K::Named | K::Spread))
            .collect()
    } else {
        params
            .children
            .iter()
            .filter(|c| crate::eval::is_pattern_kind(c.kind) || matches!(c.kind, K::Named | K::Spread))
            .collect()
    };

    for p in param_nodes {
        match p.kind {
            K::Ident => {
                let name = p.text();
                let v = args.expect_any(name)?;
                vm.define(name, v);
            }
            K::Underscore => {
                let _ = args.expect_any("argument")?;
            }
            K::Spread => {
                let name = p.children.iter().find(|c| c.kind == K::Ident).map(|n| n.text().to_string());
                sink = Some(name);
                if let Some(size) = sink_size {
                    let mut taken = vec![];
                    let mut i = 0;
                    while taken.len() < size && i < args.items.len() {
                        if args.items[i].name.is_none() {
                            taken.push(args.items.remove(i));
                        } else {
                            i += 1;
                        }
                    }
                    sink_pos_values = Some(taken);
                }
            }
            K::Named => {
                let name = p.children.iter().find(|c| c.kind == K::Ident).unwrap().text();
                let default = defaults.next().cloned().unwrap_or(Value::None);
                let v = args.named_any(name).unwrap_or(default);
                vm.define(name, v);
            }
            _ => {
                let v = args.expect_any("pattern parameter")?;
                vm.destructure(p, v, false)?;
            }
        }
    }

    if let Some(sink) = sink {
        let mut remaining = args.take();
        if let Some(name) = sink {
            if let Some(vals) = sink_pos_values {
                remaining.items.extend(vals);
            }
            vm.define(name.as_str(), Value::Args(Rc::new(remaining)));
        }
    }

    args.finish()?;

    let output = vm.eval_expr(body)?;
    match vm.flow.take() {
        Some(Flow::Return(_, Some(v))) => return Ok(v),
        Some(Flow::Return(_, None)) => {}
        Some(Flow::Break(span)) => bail!(span, "cannot break outside of loop"),
        Some(Flow::Continue(span)) => bail!(span, "cannot continue outside of loop"),
        None => {}
    }
    Ok(output)
}

/// Call a function value with positional arguments.
pub fn call_value(engine: &mut Engine, f: &Value, span: Span, args: Vec<Value>) -> SourceResult<Value> {
    match f {
        Value::Func(func) => {
            let a = Args::new(span, args);
            call_func(engine, func, a, &engine.context.clone())
        }
        Value::Type(t) => {
            let func = Func { kind: FuncKind::Type(*t), span };
            let a = Args::new(span, args);
            call_func(engine, &func, a, &engine.context.clone())
        }
        v => bail!(span, "expected function, found {}", v.type_name()),
    }
}
