//! Field access.

use crate::diag::*;
use crate::eval::Engine;
use crate::func::FuncKind;
use crate::value::*;

pub fn field_exists(v: &Value, name: &str) -> bool {
    matches!(v, Value::Dict(_)) || {
        let mut e = None::<()>;
        let _ = &mut e;
        false
    } || matches!(v, Value::Content(c) if c.has(name))
}

pub fn field(engine: &mut Engine, value: &Value, name: &str) -> StrResult<Value> {
    let _ = &engine;
    match value {
        Value::Dict(d) => match d.get(name) {
            Some(v) => Ok(v.clone()),
            None => Err(format!("dictionary does not contain key {}", crate::repr::repr_str(name)).into()),
        },
        Value::Content(c) => content_field(c, name),
        Value::Module(m) => match m.scope.get(name) {
            Some(v) => Ok(v.clone()),
            None => Err(format!("module `{}` does not contain `{}`", m.name, name).into()),
        },
        Value::Func(f) => {
            if let FuncKind::Closure(_) = &f.kind {
                return Err("cannot access fields on user-defined functions".into());
            }
            if let FuncKind::With(_) = &f.kind {
                return Err("cannot access fields on user-defined functions".into());
            }
            match crate::library::func_scope_get(f, name) {
                Some(v) => Ok(v),
                None => Err(format!("function `{}` does not contain field `{}`", f.name().unwrap_or_default(), name).into()),
            }
        }
        Value::Type(t) => match crate::methods::type_scope_get(*t, name) {
            Some(v) => Ok(v),
            None => Err(format!("type {} does not contain field `{}`", t.long_name(), name).into()),
        },
        Value::Symbol(s) => crate::symbols::symbol_modified(s, name).map(Value::Symbol),
        Value::Length(l) => match name {
            "abs" => Ok(Value::Length(Length::pt(l.abs))),
            "em" => Ok(Value::Float(l.em)),
            _ => Err(format!("length does not contain field {}", crate::repr::repr_str(name)).into()),
        },
        Value::Relative(r) => match name {
            "ratio" => Ok(Value::Ratio(r.rel)),
            "length" => Ok(Value::Length(r.abs)),
            _ => Err(format!("relative length does not contain field {}", crate::repr::repr_str(name)).into()),
        },
        Value::Alignment(a) => match name {
            "x" => Ok(a.x.map(|x| Value::Alignment(Alignment { x: Some(x), y: None })).unwrap_or(Value::None)),
            "y" => Ok(a.y.map(|y| Value::Alignment(Alignment { x: None, y: Some(y) })).unwrap_or(Value::None)),
            _ => Err(format!("alignment does not contain field {}", crate::repr::repr_str(name)).into()),
        },
        Value::Version(v) => {
            let idx = match name {
                "major" => 0,
                "minor" => 1,
                "patch" => 2,
                _ => return Err(format!("version does not contain field {}", crate::repr::repr_str(name)).into()),
            };
            match v.0.get(idx) {
                Some(x) => Ok(Value::Int(*x as i64)),
                None => Err("unknown version component".into()),
            }
        }
        Value::Stroke(s) => {
            let get = |o: &Option<Value>| o.clone().unwrap_or(Value::Auto);
            match name {
                "paint" => Ok(get(&s.paint)),
                "thickness" => Ok(get(&s.thickness)),
                "cap" => Ok(get(&s.cap)),
                "join" => Ok(get(&s.join)),
                "dash" => Ok(get(&s.dash)),
                "miter-limit" => Ok(get(&s.miter_limit)),
                _ => Err(format!("stroke does not contain field {}", crate::repr::repr_str(name)).into()),
            }
        }
        Value::Gradient(_) | Value::Datetime(_) | Value::Duration(_) | Value::Color(_) => {
            Err(format!("cannot access fields on type {}", value.type_name()).into())
        }
        _ => Err(format!("cannot access fields on type {}", value.type_name()).into()),
    }
}

pub fn content_field(c: &crate::content::Content, name: &str) -> StrResult<Value> {
    if name == "label" {
        if let Some(l) = c.label() {
            return Ok(Value::Label(l.clone()));
        }
    }
    if let Some(v) = c.get(name) {
        if c.elem().is_visible_field(name) {
            return Ok(v.clone());
        }
    }
    let elem = c.elem();
    if elem.has_field(name) && elem.is_visible_field(name) || name == "label" {
        return Err(format!("field {} in {} is not known at this point", crate::repr::repr_str(name), elem.name).into());
    }
    Err(format!("{} does not have field {}", elem.name, crate::repr::repr_str(name)).into())
}
