fn static_name(t: Type, name: &str) -> Option<&'static str> {
    type_methods(t).iter().find(|m| **m == name).copied()
}

pub fn type_scope_get(t: Type, name: &str) -> Option<Value> {
    static_name(t, name).map(|n| Value::Func(Func::builtin(type_group(t), n)))
}

pub fn method_func(v: &Value, name: &str) -> Option<Func> {
    let t = v.ty();
    static_name(t, name).map(|n| Func::builtin(type_group(t), n))
}

pub fn missing_method_error(target: &Value, field: &str, span: Span) -> Diag {
    let mut d = match target {
        Value::Content(c) => Diag::error(span, format!("element {} has no method `{}`", c.func_name(), field)),
        _ => Diag::error(span, format!("type {} has no method `{}`", target.type_name(), field)),
    };
    match target {
        Value::Dict(dict) if matches!(dict.get(field), Some(Value::Func(_))) => {
            d.hints.push(format!(
                "to call the function stored in the dictionary, surround the field access with parentheses, e.g. `(dict.{field})(..)`"
            ));
        }
        Value::Dict(dict) if dict.get(field).is_some() => {
            d.hints.push(format!("did you mean to access the field `{field}`?"));
        }
        Value::Content(c) if c.has(field) => {
            d.hints.push(format!("did you mean to access the field `{field}`?"));
        }
        _ => {}
    }
    d
}

fn out_of_bounds(index: i64, len: usize) -> HintedString {
    HintedString::new(format!("array index out of bounds (index: {index}, len: {len})"))
}

fn out_of_bounds_no_default(index: i64, len: usize) -> HintedString {
    HintedString::new(format!(
        "array index out of bounds (index: {index}, len: {len}) and no default value was specified"
    ))
}

pub fn locate_index(index: i64, len: usize, end_ok: bool) -> Option<usize> {
    let wrapped = if index >= 0 { Some(index) } else { (len as i64).checked_add(index) };
    let w = wrapped?;
    if w < 0 {
        return None;
    }
    let w = w as usize;
    if w < len || (end_ok && w == len) {
        Some(w)
    } else {
        None
    }
}

/// Access methods returning lvalues (at, first, last).
pub fn access_method<'a>(target: &'a mut Value, method: &str, args: &mut Args, span: Span) -> SourceResult<&'a mut Value> {
    let ty = target.type_name();
    match target {
        Value::Array(arr) => {
            let arr = Rc::make_mut(arr);
            let len = arr.len();
            match method {
                "first" => {
                    args.finish()?;
                    if len == 0 {
                        bail!(span, "array is empty");
                    }
                    Ok(&mut arr[0])
                }
                "last" => {
                    args.finish()?;
                    if len == 0 {
                        bail!(span, "array is empty");
                    }
                    Ok(&mut arr[len - 1])
                }
                _ => {
                    let index = args.expect("index", &INT)?;
                    args.finish()?;
                    let Value::Int(i) = index else { unreachable!() };
                    match locate_index(i, len, false) {
                        Some(idx) => Ok(&mut arr[idx]),
                        None => Err(out_of_bounds(i, len)).at(span),
                    }
                }
            }
        }
        Value::Dict(dict) => {
            if method != "at" {
                bail!(span, "type dictionary has no method `{}`", method);
            }
            let key = args.expect("key", &STR)?;
            args.finish()?;
            let key = key.as_str().unwrap().to_string();
            let d = Rc::make_mut(dict);
            match d.get_mut(&key) {
                Some(v) => Ok(v),
                None => {
                    let d = Diag::error(span, format!("dictionary does not contain key {}", crate::repr::repr_str(&key)))
                        .with_hint("use `insert` to add or update values");
                    Err(vec![d])
                }
            }
        }
        _ => bail!(span, "type {} has no method `{}`", ty, method),
    }
}

pub fn call_method_mut(target: &mut Value, method: &str, args: &mut Args, span: Span) -> SourceResult<Value> {
    match target {
        Value::Array(arr) => {
            let arr = Rc::make_mut(arr);
            match method {
                "push" => {
                    let v = args.expect_any("value")?;
                    args.finish()?;
                    arr.push(v);
                    Ok(Value::None)
                }
                "pop" => {
                    args.finish()?;
                    arr.pop().ok_or_else(|| HintedString::new("array is empty")).at(span)
                }
                "insert" => {
                    let index = args.expect("index", &INT)?;
                    let value = args.expect_any("value")?;
                    args.finish()?;
                    let Value::Int(i) = index else { unreachable!() };
                    let len = arr.len();
                    match locate_index(i, len, true) {
                        Some(idx) => {
                            arr.insert(idx, value);
                            Ok(Value::None)
                        }
                        None => Err(out_of_bounds(i, len)).at(span),
                    }
                }
                "remove" => {
                    let index = args.expect("index", &INT)?;
                    let default = args.named_any("default");
                    args.finish()?;
                    let Value::Int(i) = index else { unreachable!() };
                    let len = arr.len();
                    match locate_index(i, len, false) {
                        Some(idx) => Ok(arr.remove(idx)),
                        None => match default {
                            Some(d) => Ok(d),
                            None => Err(out_of_bounds_no_default(i, len)).at(span),
                        },
                    }
                }
                _ => bail!(span, "type array has no method `{}`", method),
            }
        }
        Value::Dict(dict) => {
            let d = Rc::make_mut(dict);
            match method {
                "insert" => {
                    let key = args.expect("key", &STR)?;
                    let value = args.expect_any("value")?;
                    args.finish()?;
                    d.insert(Rc::from(key.as_str().unwrap()), value);
                    Ok(Value::None)
                }
                "remove" => {
                    let key = args.expect("key", &STR)?;
                    let default = args.named_any("default");
                    args.finish()?;
                    let k = key.as_str().unwrap();
                    match d.remove(k) {
                        Some(v) => Ok(v),
                        None => match default {
                            Some(v) => Ok(v),
                            None => bail!(span, "dictionary does not contain key {} and no default value was specified", crate::repr::repr_str(k)),
                        },
                    }
                }
                _ => bail!(span, "type dictionary has no method `{}`", method),
            }
        }
        _ => unreachable!(),
    }
}

/// Dispatch a type method call (self is first positional arg if a method).
pub fn call_type_method(engine: &mut Engine, group: &str, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    // static functions first
    match (group, name) {
        ("str", "from-unicode") => {
            let v = args.expect("value", &UINT)?;
            args.finish()?;
            let Value::Int(i) = v else { unreachable!() };
            return match char::from_u32(i as u32) {
                Some(c) if i <= u32::MAX as i64 => Ok(Value::str(c.to_string())),
                _ => bail!(span, "{:#x} is not a valid codepoint", i),
            };
        }
        ("str", "to-unicode") => {
            let v = args.expect("character", &STR)?;
            args.finish()?;
            let s = v.as_str().unwrap();
            let mut chars = s.chars();
            return match (chars.next(), chars.next()) {
                (Some(c), None) => Ok(Value::Int(c as i64)),
                _ => bail!(span, "expected exactly one character"),
            };
        }
        ("array", "range") => return crate::library::range(args),
        ("datetime", "today") => return crate::datetime::today(engine, args),
        ("int", "from-bytes") => return crate::numbers::int_from_bytes(args),
        ("float", "from-bytes") => return crate::numbers::float_from_bytes(args),
        ("color", n) if matches!(n, "luma" | "oklab" | "oklch" | "rgb" | "linear-rgb" | "cmyk" | "hsl" | "hsv" | "mix") => {
            // could be a method call on a color too (e.g. red.rgb()) -> conversion
            if let Some(Arg { value: Value::Color(_), name: None, .. }) = args.items.first() {
                if n != "mix" && args.items.len() == 1 && !matches!(n, "luma" | "rgb") {
                    let c = args.eat_any().unwrap();
                    return crate::color::convert_method(c, n).at(span);
                }
                if n != "mix" && args.items.len() == 1 {
                    let c = args.eat_any().unwrap();
                    return crate::color::convert_method(c, n).at(span);
                }
            }
            return crate::color::construct(engine, n, args);
        }
        ("gradient", n) if matches!(n, "linear" | "radial" | "conic") => {
            return crate::visualize::gradient_construct(engine, n, args);
        }
        ("direction", "from") | ("direction", "to") => {
            let v = args.expect("side", &ALIGN)?;
            args.finish()?;
            let Value::Alignment(a) = v else { unreachable!() };
            let side = a.x.or(a.y);
            let d = match (name, side) {
                ("from", Some(Align::Left)) => Dir::LTR,
                ("from", Some(Align::Right)) => Dir::RTL,
                ("from", Some(Align::Top)) => Dir::TTB,
                ("from", Some(Align::Bottom)) => Dir::BTT,
                ("to", Some(Align::Left)) => Dir::RTL,
                ("to", Some(Align::Right)) => Dir::LTR,
                ("to", Some(Align::Top)) => Dir::BTT,
                ("to", Some(Align::Bottom)) => Dir::TTB,
                _ => bail!(span, "cannot convert this alignment to a side"),
            };
            return Ok(Value::Direction(d));
        }
        _ => {}
    }
    let this = match args.eat_raw() {
        Some(a) => a.value,
        None => return Err(args.missing_argument("self")),
    };
    match (group, this) {
        ("str", Value::Str(s)) => str_method(engine, &s, name, args),
        ("str", Value::Symbol(s)) => str_method(engine, &s.text, name, args),
        ("array", Value::Array(a)) => array_method(engine, a, name, args),
        ("dictionary", Value::Dict(d)) => dict_method(d, name, args),
        ("content", Value::Content(c)) => content_method(engine, c, name, args),
        ("function", Value::Func(f)) => func_method(engine, f, name, args),
        ("function", Value::Type(t)) => func_method(engine, Func { kind: FuncKind::Type(t), span: Span::detached() }, name, args),
        ("arguments", Value::Args(a)) => args_method(&a, name, args),
        ("int", Value::Int(i)) => crate::numbers::int_method(i, name, args),
        ("float", v @ (Value::Float(_) | Value::Int(_))) => {
            let f = match v {
                Value::Float(f) => f,
                Value::Int(i) => i as f64,
                _ => unreachable!(),
            };
            crate::numbers::float_method(f, name, args)
        }
        ("bytes", Value::Bytes(b)) => bytes_method(&b, name, args),
        ("version", Value::Version(v)) => {
            let index = args.expect("index", &INT)?;
            args.finish()?;
            let Value::Int(i) = index else { unreachable!() };
            match locate_index(i, v.0.len(), false) {
                Some(idx) => Ok(Value::Int(v.0[idx] as i64)),
                None => {
                    if i >= 0 {
                        Ok(Value::Int(0))
                    } else {
                        bail!(span, "component index out of bounds (index: {}, len: {})", i, v.0.len())
                    }
                }
            }
        }
        ("datetime", Value::Datetime(d)) => crate::datetime::datetime_method(&d, name, args),
        ("duration", Value::Duration(d)) => crate::datetime::duration_method(d, name, args),
        ("length", Value::Length(l)) => length_method(engine, l, name, args),
        ("angle", Value::Angle(a)) => {
            args.finish()?;
            match name {
                "rad" => Ok(Value::Float(a)),
                "deg" => Ok(Value::Float(a.to_degrees())),
                _ => unreachable!(),
            }
        }
        ("alignment", Value::Alignment(a)) => {
            args.finish()?;
            match name {
                "axis" => {
                    if a.x.is_some() && a.y.is_some() {
                        Ok(Value::None)
                    } else if a.x.is_some() {
                        Ok(Value::str("horizontal"))
                    } else {
                        Ok(Value::str("vertical"))
                    }
                }
                "inv" => {
                    let inv = |x: Align| match x {
                        Align::Start => Align::End,
                        Align::End => Align::Start,
                        Align::Left => Align::Right,
                        Align::Right => Align::Left,
                        Align::Center => Align::Center,
                        Align::Top => Align::Bottom,
                        Align::Bottom => Align::Top,
                        Align::Horizon => Align::Horizon,
                    };
                    Ok(Value::Alignment(Alignment { x: a.x.map(inv), y: a.y.map(inv) }))
                }
                _ => unreachable!(),
            }
        }
        ("direction", Value::Direction(d)) => {
            args.finish()?;
            let al = |x| Value::Alignment(if matches!(x, Align::Left | Align::Right) {
                Alignment { x: Some(x), y: None }
            } else {
                Alignment { x: None, y: Some(x) }
            });
            Ok(match name {
                "axis" => Value::str(if matches!(d, Dir::LTR | Dir::RTL) { "horizontal" } else { "vertical" }),
                "sign" => Value::Int(if matches!(d, Dir::LTR | Dir::TTB) { 1 } else { -1 }),
                "start" => al(match d {
                    Dir::LTR => Align::Left,
                    Dir::RTL => Align::Right,
                    Dir::TTB => Align::Top,
                    Dir::BTT => Align::Bottom,
                }),
                "end" => al(match d {
                    Dir::LTR => Align::Right,
                    Dir::RTL => Align::Left,
                    Dir::TTB => Align::Bottom,
                    Dir::BTT => Align::Top,
                }),
                "inv" => Value::Direction(match d {
                    Dir::LTR => Dir::RTL,
                    Dir::RTL => Dir::LTR,
                    Dir::TTB => Dir::BTT,
                    Dir::BTT => Dir::TTB,
                }),
                _ => unreachable!(),
            })
        }
        ("color", Value::Color(c)) => crate::color::color_method(&c, name, args),
        ("selector", v) => crate::introspect::selector_method(v, name, args),
        ("counter", Value::Counter(c)) => crate::introspect::counter_method(engine, &c, name, args),
        ("state", Value::State(s)) => crate::introspect::state_method(engine, &s, name, args),
        ("location", Value::Location(l)) => crate::introspect::location_method(engine, l, name, args),
        ("gradient", Value::Gradient(g)) => crate::visualize::gradient_method(&g, name, args),
        (_, v) => {
            let expected = match group {
                "dictionary" => "dictionary",
                "function" => "function",
                "arguments" => "arguments",
                g => crate::library::type_from_short(g).map(|t| t.long_name()).unwrap_or(g),
            };
            bail!(span, "expected {}, found {}", expected, v.type_name())
        }
    }
}

fn str_index_err(index: i64, len: usize) -> HintedString {
    HintedString::new(format!("string index out of bounds (index: {index}, len: {len})"))
}

fn str_locate(s: &str, index: i64) -> StrResult<usize> {
    let len = s.len();
    let wrapped = if index >= 0 { Some(index) } else { (len as i64).checked_add(index) };
    let resolved = wrapped.and_then(|w| usize::try_from(w).ok()).filter(|w| *w <= len);
    match resolved {
        Some(i) => {
            if s.is_char_boundary(i) {
                Ok(i)
            } else {
                Err(format!("string index {index} is not a character boundary").into())
            }
        }
        None => Err(str_index_err(index, len)),
    }
}

pub enum Pattern {
    Str(String),
    Regex(Rc<crate::regex::Regex>),
}

fn cast_pattern(v: Value) -> StrResult<Pattern> {
    match v {
        Value::Str(s) => Ok(Pattern::Str(s.to_string())),
        Value::Symbol(s) => Ok(Pattern::Str(s.text.to_string())),
        Value::Regex(r) => Ok(Pattern::Regex(r)),
        v => Err(format!("expected string or regex, found {}", v.type_name()).into()),
    }
}

fn expect_pattern(args: &mut Args, what: &str) -> SourceResult<Pattern> {
    match args.eat_raw() {
        Some(a) => cast_pattern(a.value).at(a.value_span),
        None => Err(args.missing_argument(what)),
    }
}

fn match_dict(s: &str, start: usize, end: usize, caps: Vec<Option<(usize, usize)>>) -> Value {
    let mut d = Dict::new();
    d.insert(Rc::from("start"), Value::Int(start as i64));
    d.insert(Rc::from("end"), Value::Int(end as i64));
    d.insert(Rc::from("text"), Value::str(&s[start..end]));
    let captures: Vec<Value> = caps
        .into_iter()
        .map(|c| match c {
            Some((a, b)) => Value::str(&s[a..b]),
            None => Value::None,
        })
        .collect();
    d.insert(Rc::from("captures"), Value::array(captures));
    Value::dict(d)
}

/// Find all matches: (start, end, captures)
pub fn find_all(s: &str, pat: &Pattern) -> Vec<(usize, usize, Vec<Option<(usize, usize)>>)> {
    match pat {
        Pattern::Str(p) => {
            if p.is_empty() {
                let mut out = vec![];
                let mut i = 0;
                loop {
                    out.push((i, i, vec![]));
                    if i >= s.len() {
                        break;
                    }
                    i += s[i..].chars().next().unwrap().len_utf8();
                }
                return out;
            }
            s.match_indices(p.as_str()).map(|(i, m)| (i, i + m.len(), vec![])).collect()
        }
        Pattern::Regex(r) => r.find_all(s),
    }
}

fn find_first(s: &str, pat: &Pattern) -> Option<(usize, usize, Vec<Option<(usize, usize)>>)> {
    match pat {
        Pattern::Str(p) => s.find(p.as_str()).map(|i| (i, i + p.len(), vec![])),
        Pattern::Regex(r) => r.find_at(s, 0),
    }
}

fn str_method(engine: &mut Engine, s: &str, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "len" => {
            args.finish()?;
            Ok(Value::Int(s.len() as i64))
        }
        "first" | "last" => {
            args.finish()?;
            let g = crate::unicode::graphemes(s);
            let r = if name == "first" { g.first() } else { g.last() };
            match r {
                Some(x) => Ok(Value::str(x)),
                None => bail!(span, "string is empty"),
            }
        }
        "at" => {
            let index = args.expect("index", &INT)?;
            let default = args.named_any("default");
            args.finish()?;
            let Value::Int(i) = index else { unreachable!() };
            let len = s.len();
            let wrapped = if i >= 0 { Some(i) } else { (len as i64).checked_add(i) };
            let resolved = wrapped.and_then(|w| usize::try_from(w).ok()).filter(|w| *w < len);
            match resolved {
                Some(idx) => {
                    if !s.is_char_boundary(idx) {
                        bail!(span, "string index {} is not a character boundary", i);
                    }
                    let g = crate::unicode::first_grapheme_len(&s[idx..]);
                    Ok(Value::str(&s[idx..idx + g]))
                }
                None => match default {
                    Some(d) => Ok(d),
                    None => bail!(span, "no default value was specified and string index out of bounds (index: {}, len: {})", i, len),
                },
            }
        }
        "slice" => {
            let start = args.expect("start", &INT)?;
            let end = args.eat(&Cast::Opt(&Cast::Int))?;
            let count = args.named("count", &INT)?;
            args.finish()?;
            let Value::Int(st) = start else { unreachable!() };
            let start_i = str_locate(s, st).at(span)?;
            let end_i = match (end, count) {
                (Some(Value::Int(e)), None) => str_locate(s, e).at(span)?,
                (Some(Value::Int(_)), Some(_)) => bail!(span, "`end` and `count` are mutually exclusive"),
                (_, Some(Value::Int(c))) => str_locate(s, st + c).at(span)?,
                _ => s.len(),
            };
            let end_i = end_i.max(start_i);
            Ok(Value::str(&s[start_i..end_i]))
        }
        "clusters" => {
            args.finish()?;
            Ok(Value::array(crate::unicode::graphemes(s).into_iter().map(Value::str).collect()))
        }
        "codepoints" => {
            args.finish()?;
            Ok(Value::array(s.chars().map(|c| Value::str(c.to_string())).collect()))
        }
        "normalize" => {
            let form = args.named("form", &Cast::Strs(&["nfc", "nfd", "nfkc", "nfkd"]))?;
            args.finish()?;
            Ok(Value::str(crate::unicode_norm::normalize(s, form.as_ref().and_then(|v| v.as_str()).unwrap_or("nfc"))))
        }
        "contains" | "starts-with" | "ends-with" => {
            let pat = expect_pattern(args, "pattern")?;
            args.finish()?;
            let r = match (&pat, name) {
                (Pattern::Str(p), "contains") => s.contains(p.as_str()),
                (Pattern::Str(p), "starts-with") => s.starts_with(p.as_str()),
                (Pattern::Str(p), _) => s.ends_with(p.as_str()),
                (Pattern::Regex(r), "contains") => r.is_match(s),
                (Pattern::Regex(r), "starts-with") => r.find_at(s, 0).is_some_and(|m| m.0 == 0),
                (Pattern::Regex(r), _) => r.find_all(s).iter().any(|m| m.1 == s.len()),
            };
            Ok(Value::Bool(r))
        }
        "find" => {
            let pat = expect_pattern(args, "pattern")?;
            args.finish()?;
            Ok(find_first(s, &pat).map(|m| Value::str(&s[m.0..m.1])).unwrap_or(Value::None))
        }
        "position" => {
            let pat = expect_pattern(args, "pattern")?;
            args.finish()?;
            Ok(find_first(s, &pat).map(|m| Value::Int(m.0 as i64)).unwrap_or(Value::None))
        }
        "match" => {
            let pat = expect_pattern(args, "pattern")?;
            args.finish()?;
            Ok(find_first(s, &pat).map(|m| match_dict(s, m.0, m.1, m.2)).unwrap_or(Value::None))
        }
        "matches" => {
            let pat = expect_pattern(args, "pattern")?;
            args.finish()?;
            Ok(Value::array(find_all(s, &pat).into_iter().map(|m| match_dict(s, m.0, m.1, m.2)).collect()))
        }
        "replace" => {
            let pat = expect_pattern(args, "pattern")?;
            let repl = args.expect("replacement", &Cast::Or(&[Cast::Str, Cast::Func]))?;
            let count = args.named("count", &INT)?;
            args.finish()?;
            let count = match count {
                Some(Value::Int(c)) => c.max(0) as usize,
                _ => usize::MAX,
            };
            let mut out = String::new();
            let mut last = 0;
            for (i, m) in find_all(s, &pat).into_iter().enumerate() {
                if i >= count {
                    break;
                }
                out.push_str(&s[last..m.0]);
                match &repl {
                    Value::Str(r) => {
                        match &pat {
                            Pattern::Regex(_) => out.push_str(&expand_replacement(r, s, &m)),
                            Pattern::Str(_) => out.push_str(r),
                        }
                    }
                    f => {
                        let d = match_dict(s, m.0, m.1, m.2.clone());
                        let v = call_value(engine, f, span, vec![d])?;
                        match v {
                            Value::Str(x) => out.push_str(&x),
                            other => bail!(span, "expected string, found {}", other.type_name()),
                        }
                    }
                }
                last = m.1;
            }
            out.push_str(&s[last..]);
            Ok(Value::str(out))
        }
        "rev" => {
            args.finish()?;
            let mut g = crate::unicode::graphemes(s);
            g.reverse();
            Ok(Value::str(g.concat()))
        }
        "split" => {
            let pat = args.eat(&Cast::Any)?;
            args.finish()?;
            let parts: Vec<Value> = match pat {
                None | Some(Value::None) => s.split_whitespace().map(Value::str).collect(),
                Some(v) => {
                    let p = cast_pattern(v).at(span)?;
                    match &p {
                        Pattern::Str(ps) if !ps.is_empty() => s.split(ps.as_str()).map(Value::str).collect(),
                        _ => {
                            let mut out = vec![];
                            let mut last = 0;
                            for m in find_all(s, &p) {
                                out.push(Value::str(&s[last..m.0]));
                                last = m.1;
                            }
                            out.push(Value::str(&s[last..]));
                            out
                        }
                    }
                }
            };
            Ok(Value::array(parts))
        }
        "trim" => {
            let pat = args.eat(&Cast::Any)?;
            let at = args.named("at", &ALIGN)?;
            let repeat = args.named("repeat", &BOOL)?;
            args.finish()?;
            let repeat = !matches!(repeat, Some(Value::Bool(false)));
            let (start, end) = match at {
                None => (true, true),
                Some(Value::Alignment(a)) => match a.x {
                    Some(Align::Start) => (true, false),
                    Some(Align::End) => (false, true),
                    _ => bail!(span, "expected either `start` or `end`"),
                },
                _ => (true, true),
            };
            let pat = match pat {
                None | Some(Value::None) => None,
                Some(v) => Some(cast_pattern(v).at(span)?),
            };
            let mut t: &str = s;
            match pat {
                None => {
                    if start {
                        t = t.trim_start();
                    }
                    if end {
                        t = t.trim_end();
                    }
                }
                Some(Pattern::Str(p)) => {
                    if !p.is_empty() {
                        if start {
                            if repeat {
                                while let Some(r) = t.strip_prefix(p.as_str()) {
                                    t = r;
                                }
                            } else if let Some(r) = t.strip_prefix(p.as_str()) {
                                t = r;
                            }
                        }
                        if end {
                            if repeat {
                                while let Some(r) = t.strip_suffix(p.as_str()) {
                                    t = r;
                                }
                            } else if let Some(r) = t.strip_suffix(p.as_str()) {
                                t = r;
                            }
                        }
                    }
                }
                Some(Pattern::Regex(r)) => {
                    let ms = r.find_all(t);
                    let mut st = 0;
                    let mut en = t.len();
                    if start {
                        for m in &ms {
                            if m.0 == st && m.1 > m.0 {
                                st = m.1;
                                if !repeat {
                                    break;
                                }
                            } else {
                                break;
                            }
                        }
                    }
                    if end {
                        for m in ms.iter().rev() {
                            if m.1 == en && m.0 >= st && m.1 > m.0 {
                                en = m.0;
                                if !repeat {
                                    break;
                                }
                            } else {
                                break;
                            }
                        }
                    }
                    t = &t[st..en.max(st)];
                }
            }
            Ok(Value::str(t))
        }
        _ => bail!(span, "type string has no method `{}`", name),
    }
}

fn expand_replacement(r: &str, s: &str, m: &(usize, usize, Vec<Option<(usize, usize)>>)) -> String {
    let mut out = String::new();
    let chars: Vec<char> = r.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '$' && i + 1 < chars.len() {
            if chars[i + 1] == '$' {
                out.push('$');
                i += 2;
                continue;
            }
            let mut j = i + 1;
            let braced = chars[j] == '{';
            if braced {
                j += 1;
            }
            let st = j;
            while j < chars.len() && (chars[j].is_ascii_alphanumeric() || chars[j] == '_') {
                j += 1;
            }
            let name: String = chars[st..j].iter().collect();
            if braced {
                if j < chars.len() && chars[j] == '}' {
                    j += 1;
                } else {
                    out.push('$');
                    i += 1;
                    continue;
                }
            }
            if name.is_empty() {
                out.push('$');
                i += 1;
                continue;
            }
            if let Ok(n) = name.parse::<usize>() {
                if n == 0 {
                    out.push_str(&s[m.0..m.1]);
                } else if let Some(Some((a, b))) = m.2.get(n - 1) {
                    out.push_str(&s[*a..*b]);
                }
            }
            i = j;
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn call_bool(engine: &mut Engine, f: &Value, span: Span, args: Vec<Value>) -> SourceResult<bool> {
    match call_value(engine, f, span, args)? {
        Value::Bool(b) => Ok(b),
        v => bail!(span, "expected boolean, found {}", v.type_name()),
    }
}

fn array_method(engine: &mut Engine, arr: Rc<Vec<Value>>, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let len = arr.len();
    match name {
        "len" => {
            args.finish()?;
            Ok(Value::Int(len as i64))
        }
        "first" | "last" => {
            args.finish()?;
            let r = if name == "first" { arr.first() } else { arr.last() };
            r.cloned().ok_or_else(|| HintedString::new("array is empty")).at(span)
        }
        "at" => {
            let index = args.expect("index", &INT)?;
            let default = args.named_any("default");
            args.finish()?;
            let Value::Int(i) = index else { unreachable!() };
            match locate_index(i, len, false) {
                Some(idx) => Ok(arr[idx].clone()),
                None => match default {
                    Some(d) => Ok(d),
                    None => Err(out_of_bounds_no_default(i, len)).at(span),
                },
            }
        }
        "push" | "pop" | "insert" | "remove" => {
            bail!(span, "cannot mutate a temporary value")
        }
        "slice" => {
            let start = args.expect("start", &INT)?;
            let end = args.eat(&Cast::Opt(&Cast::Int))?;
            let count = args.named("count", &INT)?;
            args.finish()?;
            let Value::Int(st) = start else { unreachable!() };
            let start_i = locate_index(st, len, true).ok_or_else(|| out_of_bounds(st, len)).at(span)?;
            let end_i = match (end, count) {
                (Some(Value::Int(e)), None) => locate_index(e, len, true).ok_or_else(|| out_of_bounds(e, len)).at(span)?,
                (Some(Value::Int(_)), Some(_)) => bail!(span, "`end` and `count` are mutually exclusive"),
                (_, Some(Value::Int(c))) => {
                    let e = st + c;
                    locate_index(e, len, true).ok_or_else(|| out_of_bounds(e, len)).at(span)?
                }
                _ => len,
            };
            let end_i = end_i.max(start_i);
            Ok(Value::array(arr[start_i..end_i].to_vec()))
        }
        "contains" => {
            let v = args.expect_any("value")?;
            args.finish()?;
            Ok(Value::Bool(arr.iter().any(|x| ops::equal(x, &v))))
        }
        "find" | "position" => {
            let f = args.expect("searcher", &FUNC)?;
            args.finish()?;
            for (i, x) in arr.iter().enumerate() {
                if call_bool(engine, &f, span, vec![x.clone()])? {
                    return Ok(if name == "find" { x.clone() } else { Value::Int(i as i64) });
                }
            }
            Ok(Value::None)
        }
        "filter" => {
            let f = args.expect("test", &FUNC)?;
            args.finish()?;
            let mut out = vec![];
            for x in arr.iter() {
                if call_bool(engine, &f, span, vec![x.clone()])? {
                    out.push(x.clone());
                }
            }
            Ok(Value::array(out))
        }
        "map" => {
            let f = args.expect("mapper", &FUNC)?;
            args.finish()?;
            let mut out = Vec::with_capacity(len);
            for x in arr.iter() {
                out.push(call_value(engine, &f, span, vec![x.clone()])?);
            }
            Ok(Value::array(out))
        }
        "enumerate" => {
            let start = args.named("start", &INT)?;
            args.finish()?;
            let st = match start {
                Some(Value::Int(s)) => s,
                _ => 0,
            };
            Ok(Value::array(
                arr.iter().enumerate().map(|(i, x)| Value::array(vec![Value::Int(st + i as i64), x.clone()])).collect(),
            ))
        }
        "zip" => {
            let exact = args.named("exact", &BOOL)?;
            let others = args.all_strict(&ARRAY)?;
            args.finish()?;
            let exact = matches!(exact, Some(Value::Bool(true)));
            let others: Vec<Rc<Vec<Value>>> = others
                .into_iter()
                .map(|v| match v {
                    Value::Array(a) => a,
                    _ => unreachable!(),
                })
                .collect();
            if others.is_empty() {
                return Ok(Value::array(arr.iter().map(|x| Value::array(vec![x.clone()])).collect()));
            }
            if exact {
                for (i, o) in others.iter().enumerate() {
                    if o.len() != len {
                        let ord = match i {
                            0 => "second".to_string(),
                            1 => "third".to_string(),
                            n => format!("{}th", n + 2),
                        };
                        bail!(span, "{} array has different length ({}) from first array ({})", ord, o.len(), len);
                    }
                }
            }
            let min = others.iter().map(|o| o.len()).min().unwrap_or(0).min(len);
            let mut out = vec![];
            for i in 0..min {
                let mut row = vec![arr[i].clone()];
                for o in &others {
                    row.push(o[i].clone());
                }
                out.push(Value::array(row));
            }
            Ok(Value::array(out))
        }
        "fold" => {
            let init = args.expect_any("init")?;
            let f = args.expect("folder", &FUNC)?;
            args.finish()?;
            let mut acc = init;
            for x in arr.iter() {
                acc = call_value(engine, &f, span, vec![acc, x.clone()])?;
            }
            Ok(acc)
        }
        "reduce" => {
            let f = args.expect("reducer", &FUNC)?;
            args.finish()?;
            let mut it = arr.iter();
            let Some(first) = it.next() else { return Ok(Value::None) };
            let mut acc = first.clone();
            for x in it {
                acc = call_value(engine, &f, span, vec![acc, x.clone()])?;
            }
            Ok(acc)
        }
        "sum" | "product" => {
            let default = args.named_any("default");
            args.finish()?;
            let mut it = arr.iter();
            let Some(first) = it.next() else {
                return match default {
                    Some(d) => Ok(d),
                    None => bail!(span, "cannot calculate {} of empty array with no default", if name == "sum" { "sum" } else { "product" }),
                };
            };
            let mut acc = first.clone();
            for x in it {
                acc = if name == "sum" { ops::add(acc, x.clone()) } else { ops::mul(acc, x.clone()) }.at(span)?;
            }
            Ok(acc)
        }
        "any" | "all" => {
            let f = args.expect("test", &FUNC)?;
            args.finish()?;
            for x in arr.iter() {
                let b = call_bool(engine, &f, span, vec![x.clone()])?;
                if name == "any" && b {
                    return Ok(Value::Bool(true));
                }
                if name == "all" && !b {
                    return Ok(Value::Bool(false));
                }
            }
            Ok(Value::Bool(name == "all"))
        }
        "flatten" => {
            args.finish()?;
            fn flat(v: &[Value], out: &mut Vec<Value>) {
                for x in v {
                    match x {
                        Value::Array(a) => flat(a, out),
                        _ => out.push(x.clone()),
                    }
                }
            }
            let mut out = vec![];
            flat(&arr, &mut out);
            Ok(Value::array(out))
        }
        "rev" => {
            args.finish()?;
            let mut v = (*arr).clone();
            v.reverse();
            Ok(Value::array(v))
        }
        "split" => {
            let at = args.expect_any("at")?;
            args.finish()?;
            let mut out = vec![];
            let mut cur = vec![];
            for x in arr.iter() {
                if ops::equal(x, &at) {
                    out.push(Value::array(std::mem::take(&mut cur)));
                } else {
                    cur.push(x.clone());
                }
            }
            out.push(Value::array(cur));
            Ok(Value::array(out))
        }
        "join" => {
            let sep = args.eat(&Cast::Any)?;
            let last = args.named_any("last");
            let default = args.named_any("default");
            args.finish()?;
            if len == 0 {
                return Ok(default.unwrap_or(Value::None));
            }
            let mut acc = Value::None;
            for (i, x) in arr.iter().enumerate() {
                if i > 0 {
                    if i == len - 1 {
                        if let Some(l) = &last {
                            acc = ops::join(acc, l.clone()).at(span)?;
                        } else if let Some(s) = &sep {
                            acc = ops::join(acc, s.clone()).at(span)?;
                        }
                    } else if let Some(s) = &sep {
                        acc = ops::join(acc, s.clone()).at(span)?;
                    }
                }
                acc = ops::join(acc, x.clone()).at(span)?;
            }
            Ok(acc)
        }
        "intersperse" => {
            let sep = args.expect_any("separator")?;
            args.finish()?;
            let mut out = vec![];
            for (i, x) in arr.iter().enumerate() {
                if i > 0 {
                    out.push(sep.clone());
                }
                out.push(x.clone());
            }
            Ok(Value::array(out))
        }
        "chunks" | "windows" => {
            let size = args.expect("chunk-size", &POSINT)?;
            let exact = if name == "chunks" { args.named("exact", &BOOL)? } else { None };
            args.finish()?;
            let Value::Int(n) = size else { unreachable!() };
            let n = n as usize;
            let exact = matches!(exact, Some(Value::Bool(true)));
            let out: Vec<Value> = if name == "chunks" {
                arr.chunks(n).filter(|c| !exact || c.len() == n).map(|c| Value::array(c.to_vec())).collect()
            } else {
                arr.windows(n).map(|c| Value::array(c.to_vec())).collect()
            };
            Ok(Value::array(out))
        }
        "sorted" => {
            let key = args.named("key", &FUNC)?;
            let by = args.named("by", &FUNC)?;
            args.finish()?;
            let mut items: Vec<(Value, Value)> = vec![];
            for x in arr.iter() {
                let k = match &key {
                    Some(f) => call_value(engine, f, span, vec![x.clone()])?,
                    None => x.clone(),
                };
                items.push((k, x.clone()));
            }
            // merge sort for stability with fallible comparator
            let mut err: Option<Vec<Diag>> = None;
            if let Some(by) = &by {
                let r = merge_sort(&mut items, &mut |a, b| {
                    let v = call_value(engine, by, span, vec![a.1.clone(), b.1.clone()])?;
                    match v {
                        Value::Bool(true) => Ok(std::cmp::Ordering::Less),
                        Value::Bool(false) => {
                            // check reverse for equality
                            Ok(std::cmp::Ordering::Greater)
                        }
                        v => bail!(span, "expected boolean, found {}", v.type_name()),
                    }
                });
                if let Err(e) = r {
                    err = Some(e);
                }
            } else {
                let r = merge_sort(&mut items, &mut |a, b| {
                    ops::compare(&a.0, &b.0).map_err(|e| {
                        let mut d = Diag::error(span, e.message);
                        d.hints.push("consider choosing a `key` or defining the comparison with `by`".into());
                        vec![d]
                    })
                });
                if let Err(e) = r {
                    err = Some(e);
                }
            }
            if let Some(e) = err {
                return Err(e);
            }
            Ok(Value::array(items.into_iter().map(|x| x.1).collect()))
        }
        "dedup" => {
            let key = args.named("key", &FUNC)?;
            args.finish()?;
            let mut out: Vec<Value> = vec![];
            let mut keys: Vec<Value> = vec![];
            for x in arr.iter() {
                let k = match &key {
                    Some(f) => call_value(engine, f, span, vec![x.clone()])?,
                    None => x.clone(),
                };
                if !keys.iter().any(|y| ops::equal(y, &k)) {
                    keys.push(k);
                    out.push(x.clone());
                }
            }
            Ok(Value::array(out))
        }
        "to-dict" => {
            args.finish()?;
            let mut d = Dict::new();
            for x in arr.iter() {
                match x {
                    Value::Array(p) if p.len() == 2 => match &p[0] {
                        Value::Str(k) => d.insert(k.clone(), p[1].clone()),
                        v => bail!(span, "expected (str, any) pairs, found {}", v.type_name()),
                    },
                    Value::Array(p) => bail!(span, "array with {} elements is not a pair", p.len()),
                    v => bail!(span, "expected (str, any) pairs, found {}", v.type_name()),
                }
            }
            Ok(Value::dict(d))
        }
        _ => bail!(span, "type array has no method `{}`", name),
    }
}

fn merge_sort<T: Clone>(
    v: &mut Vec<T>,
    cmp: &mut dyn FnMut(&T, &T) -> SourceResult<std::cmp::Ordering>,
) -> SourceResult<()> {
    let n = v.len();
    if n <= 1 {
        return Ok(());
    }
    // insertion sort for small arrays, else merge
    if n <= 16 {
        for i in 1..n {
            let mut j = i;
            while j > 0 {
                if cmp(&v[j], &v[j - 1])? == std::cmp::Ordering::Less {
                    v.swap(j, j - 1);
                    j -= 1;
                } else {
                    break;
                }
            }
        }
        return Ok(());
    }
    let mut right = v.split_off(n / 2);
    merge_sort(v, cmp)?;
    merge_sort(&mut right, cmp)?;
    let left = std::mem::take(v);
    let mut i = 0;
    let mut j = 0;
    while i < left.len() && j < right.len() {
        if cmp(&right[j], &left[i])? == std::cmp::Ordering::Less {
            v.push(right[j].clone());
            j += 1;
        } else {
            v.push(left[i].clone());
            i += 1;
        }
    }
    v.extend_from_slice(&left[i..]);
    v.extend_from_slice(&right[j..]);
    Ok(())
}

fn dict_method(d: Rc<Dict>, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "len" => {
            args.finish()?;
            Ok(Value::Int(d.len() as i64))
        }
        "at" => {
            let key = args.expect("key", &STR)?;
            let default = args.named_any("default");
            args.finish()?;
            let k = key.as_str().unwrap();
            match d.get(k) {
                Some(v) => Ok(v.clone()),
                None => match default {
                    Some(v) => Ok(v),
                    None => bail!(span, "dictionary does not contain key {} and no default value was specified", crate::repr::repr_str(k)),
                },
            }
        }
        "insert" | "remove" => bail!(span, "cannot mutate a temporary value"),
        "keys" => {
            args.finish()?;
            Ok(Value::array(d.keys().map(|k| Value::Str(k.clone())).collect()))
        }
        "values" => {
            args.finish()?;
            Ok(Value::array(d.values().cloned().collect()))
        }
        "pairs" => {
            args.finish()?;
            Ok(Value::array(d.iter().map(|(k, v)| Value::array(vec![Value::Str(k.clone()), v.clone()])).collect()))
        }
        _ => bail!(span, "type dictionary has no method `{}`", name),
    }
}

fn content_method(engine: &mut Engine, c: Content, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let _ = engine;
    match name {
        "func" => {
            args.finish()?;
            Ok(Value::Func(Func::element(c.elem())))
        }
        "has" => {
            let f = args.expect("field", &STR)?;
            args.finish()?;
            let f = f.as_str().unwrap();
            Ok(Value::Bool(c.has(f) && (c.elem().is_visible_field(f) || f == "label")))
        }
        "at" => {
            let f = args.expect("field", &STR)?;
            let default = args.named_any("default");
            args.finish()?;
            let f = f.as_str().unwrap();
            match crate::fields::content_field(&c, f) {
                Ok(v) => Ok(v),
                Err(e) => match default {
                    Some(d) => Ok(d),
                    None => {
                        let msg = if c.elem().has_field(f) {
                            e.message
                        } else {
                            format!("{} and no default was specified", e.message)
                        };
                        bail!(span, "{}", msg)
                    }
                },
            }
        }
        "fields" => {
            args.finish()?;
            Ok(Value::dict(c.fields_dict()))
        }
        "location" => {
            args.finish()?;
            Ok(c.location().map(Value::Location).unwrap_or(Value::None))
        }
        _ => bail!(span, "element {} has no method `{}`", c.func_name(), name),
    }
}

fn func_method(engine: &mut Engine, f: Func, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let _ = engine;
    match name {
        "with" => {
            let rest = args.take();
            Ok(Value::Func(Func { kind: FuncKind::With(Rc::new((f, rest))), span }))
        }
        "where" => {
            let Some(elem) = f.element_def() else {
                bail!(span, "`where()` can only be called on element functions");
            };
            let fields = args.take();
            let mut list = vec![];
            for a in fields.items {
                match a.name {
                    Some(n) => {
                        if !elem.has_field(&n) {
                            bail!(a.span, "element `{}` does not have field `{}`", elem.name, n);
                        }
                        list.push((n, a.value));
                    }
                    None => bail!(a.span, "unexpected argument"),
                }
            }
            Ok(Value::Selector(Rc::new(Selector::Elem(elem, Some(list)))))
        }
        _ => bail!(span, "type function has no method `{}`", name),
    }
}

fn args_method(a: &Args, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "pos" => {
            args.finish()?;
            Ok(Value::array(a.to_pos()))
        }
        "named" => {
            args.finish()?;
            Ok(Value::dict(a.to_named()))
        }
        "at" => {
            let key = args.expect("key", &Cast::Or(&[Cast::Int, Cast::Str]))?;
            let default = args.named_any("default");
            args.finish()?;
            match key {
                Value::Int(i) => {
                    let pos = a.to_pos();
                    match locate_index(i, pos.len(), false) {
                        Some(idx) => Ok(pos[idx].clone()),
                        None => match default {
                            Some(d) => Ok(d),
                            None => Err(out_of_bounds_no_default(i, pos.len())).at(span),
                        },
                    }
                }
                Value::Str(k) => match a.to_named().get(&k) {
                    Some(v) => Ok(v.clone()),
                    None => match default {
                        Some(d) => Ok(d),
                        None => bail!(span, "arguments do not contain key {} and no default value was specified", crate::repr::repr_str(&k)),
                    },
                },
                _ => unreachable!(),
            }
        }
        _ => bail!(span, "type arguments has no method `{}`", name),
    }
}

fn bytes_method(b: &Rc<Vec<u8>>, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let len = b.len();
    match name {
        "len" => {
            args.finish()?;
            Ok(Value::Int(len as i64))
        }
        "at" => {
            let index = args.expect("index", &INT)?;
            let default = args.named_any("default");
            args.finish()?;
            let Value::Int(i) = index else { unreachable!() };
            match locate_index(i, len, false) {
                Some(idx) => Ok(Value::Int(b[idx] as i64)),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail!(span, "byte index out of bounds (index: {}, len: {}) and no default value was specified", i, len),
                },
            }
        }
        "slice" => {
            let start = args.expect("start", &INT)?;
            let end = args.eat(&Cast::Opt(&Cast::Int))?;
            let count = args.named("count", &INT)?;
            args.finish()?;
            let Value::Int(st) = start else { unreachable!() };
            let oob = |i: i64| HintedString::new(format!("byte index out of bounds (index: {i}, len: {len})"));
            let s = locate_index(st, len, true).ok_or_else(|| oob(st)).at(span)?;
            let e = match (end, count) {
                (Some(Value::Int(e)), _) => locate_index(e, len, true).ok_or_else(|| oob(e)).at(span)?,
                (_, Some(Value::Int(c))) => locate_index(st + c, len, true).ok_or_else(|| oob(st + c)).at(span)?,
                _ => len,
            };
            Ok(Value::Bytes(Rc::new(b[s..e.max(s)].to_vec())))
        }
        _ => bail!(span, "type bytes has no method `{}`", name),
    }
}

fn length_method(engine: &mut Engine, l: Length, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let _ = engine;
    args.finish()?;
    if name == "to-absolute" {
        return Ok(Value::Length(Length::pt(l.abs + l.em * 11.0)));
    }
    if l.em != 0.0 {
        let mut d = Diag::error(span, "cannot convert a length with non-zero em units (`{}`) to {}");
        let unit = match name {
            "pt" => "pt",
            "mm" => "mm",
            "cm" => "cm",
            _ => "inches",
        };
        d.message = format!("cannot convert a length with non-zero em units (`{}`) to {}", repr(&Value::Length(l)), unit);
        d.hints.push(format!("use `length.to-absolute()` to resolve its em component (requires context)"));
        d.hints.push(format!("or use `length.abs.{}()` instead to ignore its em component", name));
        return Err(vec![d]);
    }
    Ok(Value::Float(match name {
        "pt" => l.abs,
        "mm" => l.abs / 2.83465,
        "cm" => l.abs / 28.3465,
        "inches" => l.abs / 72.0,
        _ => unreachable!(),
    }))
}
