/// Scope of a function (e.g. `grid.cell`, `assert.eq`).
pub fn func_scope_get(f: &Func, name: &str) -> Option<Value> {
    match &f.kind {
        FuncKind::Element(elem) => {
            let r: Option<&'static el::Elem> = match (elem.name, name) {
                ("table", "cell") => Some(&el::TABLE_CELL),
                ("table", "header") => Some(&el::TABLE_HEADER),
                ("table", "footer") => Some(&el::TABLE_FOOTER),
                ("table", "hline") => Some(&el::TABLE_HLINE),
                ("table", "vline") => Some(&el::TABLE_VLINE),
                ("grid", "cell") => Some(&el::GRID_CELL),
                ("grid", "header") => Some(&el::TABLE_HEADER),
                ("grid", "footer") => Some(&el::TABLE_FOOTER),
                ("grid", "hline") => Some(&el::TABLE_HLINE),
                ("grid", "vline") => Some(&el::TABLE_VLINE),
                ("list", "item") => Some(&el::LIST_ITEM),
                ("enum", "item") => Some(&el::ENUM_ITEM),
                ("terms", "item") => Some(&el::TERMS_ITEM),
                ("figure", "caption") => Some(&el::FIGURE_CAPTION),
                ("footnote", "entry") => Some(&el::FOOTNOTE_ENTRY),
                ("outline", "entry") => Some(&el::OUTLINE_ENTRY),
                ("par", "line") => Some(&el::PAR_LINE),
                ("place", "flush") => Some(&el::PLACE_FLUSH),
                ("raw", "line") => Some(&el::RAW_LINE),
                _ => None,
            };
            if let Some(r) = r {
                return Some(e(r));
            }
            if elem.name == "image" && name == "decode" {
                return Some(b("image", "decode"));
            }
            if elem.name == "curve" && matches!(name, "move" | "line" | "quad" | "cubic" | "close") {
                return Some(b("curve", leak(name)));
            }
            if elem.name == "polygon" && name == "regular" {
                return Some(b("polygon", "regular"));
            }
            // Field defaults.
            crate::defaults::elem_field_default(elem, name)
        }
        FuncKind::Builtin("std", "assert") => match name {
            "eq" => Some(b("assert", "eq")),
            "ne" => Some(b("assert", "ne")),
            _ => None,
        },
        FuncKind::Type(t) => crate::methods::type_scope_get(*t, name),
        _ => None,
