//! The calc module.

use crate::cast::*;
use crate::diag::*;
use crate::func::Args;
use crate::value::*;

static NUMV: Cast = Cast::Or(&[Cast::Int, Cast::Float, Cast::Custom {
    parts: &["decimal"],
    check: |v| matches!(v, Value::Decimal(_)),
    conv: |v| Ok(v),
}]);
static NUM2: Cast = Cast::Num;
static ANGLE_OR_NUM: Cast = Cast::Or(&[Cast::Int, Cast::Float, Cast::Angle]);

fn f(v: &Value) -> f64 {
    match v {
        Value::Int(i) => *i as f64,
        Value::Float(f) => *f,
        Value::Decimal(d) => crate::decimal::to_f64(d),
        _ => 0.0,
    }
}

fn angle_val(v: &Value) -> f64 {
    match v {
        Value::Angle(a) => *a,
        other => f(other),
    }
}

pub fn call(name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "abs" => {
            let v = args.expect("value", &Cast::Custom {
                parts: &["integer", "float", "length", "angle", "ratio", "fraction", "decimal"],
                check: |v| matches!(v, Value::Int(_) | Value::Float(_) | Value::Length(_) | Value::Angle(_) | Value::Ratio(_) | Value::Fraction(_) | Value::Decimal(_)),
                conv: |v| Ok(v),
            })?;
            args.finish()?;
            Ok(match v {
                Value::Int(i) => Value::Int(i.checked_abs().ok_or_else(|| HintedString::new("value is too large")).at(span)?),
                Value::Float(x) => Value::Float(x.abs()),
                Value::Length(l) => Value::Length(Length { abs: l.abs.abs(), em: l.em.abs() }),
                Value::Angle(a) => Value::Angle(a.abs()),
                Value::Ratio(r) => Value::Ratio(r.abs()),
                Value::Fraction(x) => Value::Fraction(x.abs()),
                Value::Decimal(d) => Value::Decimal(crate::decimal::abs(&d)),
                v => v,
            })
        }
        "pow" => {
            let base = args.expect("base", &NUMV)?;
            let exp = args.expect("exponent", &NUM2)?;
            args.finish()?;
            match (&base, &exp) {
                (Value::Int(0), Value::Int(e)) if *e < 0 => Ok(Value::Float(f64::INFINITY)),
                (Value::Int(b), Value::Int(e)) if *e >= 0 => {
                    let r = (*e as u64).try_into().ok().and_then(|e: u32| b.checked_pow(e));
                    match r {
                        Some(r) => Ok(Value::Int(r)),
                        None => bail!(span, "the result is too large"),
                    }
                }
                (Value::Decimal(d), Value::Int(e)) => {
                    match crate::decimal::pow(d, *e) {
                        Some(r) => Ok(Value::Decimal(r)),
                        None => bail!(span, "the result is too large"),
                    }
                }
                _ => {
                    let b = f(&base);
                    let e = f(&exp);
                    if b == 0.0 && e < 0.0 {
                        return Ok(Value::Float(f64::INFINITY));
                    }
                    let r = if let Value::Int(ei) = exp { b.powi(ei as i32) } else { b.powf(e) };
                    if r.is_nan() {
                        bail!(span, "the result is not a real number");
                    }
                    Ok(Value::Float(r))
                }
            }
        }
        "exp" => {
            let v = args.expect("exponent", &NUM2)?;
            args.finish()?;
            let r = f(&v).exp();
            if r.is_infinite() {
                bail!(span, "the result is too large");
            }
            Ok(Value::Float(r))
        }
        "sqrt" => {
            let v = args.expect("value", &NUM2)?;
            args.finish()?;
            let x = f(&v);
            if x < 0.0 {
                bail!(span, "cannot take square root of negative number");
            }
            Ok(Value::Float(x.sqrt()))
        }
        "root" => {
