            Ok(Value::Bool((i % 2 == 0) == (name == "even")))
        }
        "rem" | "div-euclid" | "rem-euclid" | "quo" => {
            let a = args.expect("dividend", &NUMV)?;
            let bv = args.expect("divisor", &NUMV)?;
            args.finish()?;
            if f(&bv) == 0.0 {
                bail!(span, "divisor must not be zero");
            }
            match (&a, &bv) {
                (Value::Int(x), Value::Int(y)) => Ok(Value::Int(match name {
                    "rem" => x.checked_rem(*y),
                    "div-euclid" => x.checked_div_euclid(*y),
                    "rem-euclid" => x.checked_rem_euclid(*y),
                    _ => Some((*x as f64 / *y as f64).floor() as i64),
                }.ok_or_else(|| HintedString::new("the result is too large")).at(span)?)),
                (Value::Decimal(_), _) | (_, Value::Decimal(_)) => {
                    let x = f(&a);
                    let y = f(&bv);
                    let r = match name {
                        "rem" => x % y,
                        "div-euclid" => x.div_euclid(y),
                        "rem-euclid" => x.rem_euclid(y),
                        _ => (x / y).floor(),
                    };
                    Ok(Value::Decimal(crate::decimal::from_f64(r)))
                }
                _ => {
                    let x = f(&a);
                    let y = f(&bv);
                    Ok(match name {
                        "rem" => Value::Float(x % y),
                        "div-euclid" => Value::Float(x.div_euclid(y)),
                        "rem-euclid" => Value::Float(x.rem_euclid(y)),
                        _ => Value::Int((x / y).floor() as i64),
                    })
                }
            }
        }
        "norm" => {
            let p = args.named("p", &NUM2)?;
            let vals = args.all_strict(&NUM2)?;
            args.finish()?;
            let p = p.map(|x| f(&x)).unwrap_or(2.0);
            if p <= 0.0 {
                bail!(span, "p must be greater than zero");
            }
            if p.is_infinite() {
                return Ok(Value::Float(vals.iter().map(|v| f(v).abs()).fold(0.0, f64::max)));
            }
            let s: f64 = vals.iter().map(|v| f(v).abs().powf(p)).sum();
            Ok(Value::Float(s.powf(1.0 / p)))
        }
        _ => bail!(span, "unknown calc function"),
    }
}

fn promote(v: Value, like: &Value) -> Value {
    match (v, like) {
        (Value::Int(i), Value::Float(_)) => Value::Float(i as f64),
        (v, _) => v,
    }
}
