//! Colors.

use crate::cast::*;
use crate::diag::*;
use crate::eval::Engine;
use crate::func::Args;
use crate::repr::{round_prec, float_display};
use crate::value::*;

fn pct(v: f32) -> String {
    let r = round_prec(v as f64 * 100.0, 2);
    format!("{}%", fmt_num(r))
}

fn fmt_num(r: f64) -> String {
    if r == 0.0 {
        return "0".into();
    }
    if r < 0.0 {
        format!("-{}", float_display(-r))
    } else {
        float_display(r)
    }
}

fn num3(v: f32) -> String {
    fmt_num(round_prec(v as f64, 3))
}

fn deg(v: f32) -> String {
    format!("{}deg", fmt_num(round_prec(v as f64, 2)))
}

pub fn to_u8(v: f32) -> u8 {
    (v.clamp(0.0, 1.0) * 255.0).round() as u8
}

pub fn repr_color(c: &Color) -> String {
    match c {
        Color::Luma(l, a) => {
            if *a == 1.0 {
                format!("luma({})", pct(*l))
            } else {
                format!("luma({}, {})", pct(*l), pct(*a))
            }
        }
        Color::Rgb(..) => format!("rgb(\"{}\")", to_hex(c)),
        Color::Cmyk(cc, m, y, k) => format!("cmyk({}, {}, {}, {})", pct(*cc), pct(*m), pct(*y), pct(*k)),
        Color::Oklab(l, a, b, al) => {
            if *al == 1.0 {
                format!("oklab({}, {}, {})", pct(*l), num3(*a), num3(*b))
            } else {
                format!("oklab({}, {}, {}, {})", pct(*l), num3(*a), num3(*b), pct(*al))
            }
        }
        Color::Oklch(l, ch, h, al) => {
            if *al == 1.0 {
                format!("oklch({}, {}, {})", pct(*l), num3(*ch), deg(*h))
            } else {
                format!("oklch({}, {}, {}, {})", pct(*l), num3(*ch), deg(*h), pct(*al))
            }
        }
        Color::LinearRgb(r, g, b, a) => {
            if *a == 1.0 {
                format!("color.linear-rgb({}, {}, {})", pct(*r), pct(*g), pct(*b))
            } else {
                format!("color.linear-rgb({}, {}, {}, {})", pct(*r), pct(*g), pct(*b), pct(*a))
            }
        }
        Color::Hsl(h, s, l, a) => {
            if *a == 1.0 {
                format!("color.hsl({}, {}, {})", deg(*h), pct(*s), pct(*l))
            } else {
                format!("color.hsl({}, {}, {}, {})", deg(*h), pct(*s), pct(*l), pct(*a))
            }
        }
        Color::Hsv(h, s, v, a) => {
            if *a == 1.0 {
                format!("color.hsv({}, {}, {})", deg(*h), pct(*s), pct(*v))
            } else {
                format!("color.hsv({}, {}, {}, {})", deg(*h), pct(*s), pct(*v), pct(*a))
            }
        }
    }
}

pub fn to_hex(c: &Color) -> String {
    let (r, g, b, a) = to_rgb(c);
    let mut s = format!("#{:02x}{:02x}{:02x}", to_u8(r), to_u8(g), to_u8(b));
    if a != 1.0 {
        s.push_str(&format!("{:02x}", to_u8(a)));
    }
    s
}

pub fn color_eq(a: &Color, b: &Color) -> bool {
    a == b
}

fn srgb_to_lin(c: f32) -> f32 {
    if c <= 0.04045 {
        c / 12.92
    } else {
        ((c + 0.055) / 1.055).powf(2.4)
    }
}

fn lin_to_srgb(c: f32) -> f32 {
    if c <= 0.0031308 {
        c * 12.92
    } else {
        1.055 * c.powf(1.0 / 2.4) - 0.055
    }
}

fn hsv_to_rgb(h: f32, s: f32, v: f32) -> (f32, f32, f32) {
    let h = ((h % 360.0) + 360.0) % 360.0;
    let c = v * s;
    let hp = h / 60.0;
    let x = c * (1.0 - ((hp % 2.0) - 1.0).abs());
    let (r, g, b) = match hp as i32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = v - c;
    (r + m, g + m, b + m)
}

fn rgb_to_hsv(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;
    let h = if d == 0.0 {
        0.0
    } else if max == r {
        60.0 * (((g - b) / d) % 6.0)
    } else if max == g {
        60.0 * ((b - r) / d + 2.0)
    } else {
        60.0 * ((r - g) / d + 4.0)
    };
    let h = if h < 0.0 { h + 360.0 } else { h };
    let s = if max == 0.0 { 0.0 } else { d / max };
    (h, s, max)
}

fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
    let v = l + s * l.min(1.0 - l);
    let sv = if v == 0.0 { 0.0 } else { 2.0 * (1.0 - l / v) };
    hsv_to_rgb(h, sv, v)
}

fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let (h, sv, v) = rgb_to_hsv(r, g, b);
    let l = v * (1.0 - sv / 2.0);
    let s = if l == 0.0 || l == 1.0 { 0.0 } else { (v - l) / l.min(1.0 - l) };
    (h, s, l)
}

fn lin_to_oklab(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let (r, g, b) = (r as f64, g as f64, b as f64);
    let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
    let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
    let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
    let (l, m, s) = (l.cbrt(), m.cbrt(), s.cbrt());
    (
        (0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s) as f32,
        (1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s) as f32,
        (0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s) as f32,
    )
}

fn oklab_to_lin(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
    let (l, a, b) = (l as f64, a as f64, b as f64);
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;
    let (l, m, s) = (l_ * l_ * l_, m_ * m_ * m_, s_ * s_ * s_);
    (
        (4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s) as f32,
        (-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s) as f32,
        (-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s) as f32,
    )
}

/// Convert to sRGB components (r, g, b, a).
pub fn to_rgb(c: &Color) -> (f32, f32, f32, f32) {
    match *c {
        Color::Luma(l, a) => (l, l, l, a),
        Color::Rgb(r, g, b, a) => (r, g, b, a),
        Color::LinearRgb(r, g, b, a) => (lin_to_srgb(r), lin_to_srgb(g), lin_to_srgb(b), a),
        Color::Cmyk(cc, m, y, k) => ((1.0 - cc) * (1.0 - k), (1.0 - m) * (1.0 - k), (1.0 - y) * (1.0 - k), 1.0),
        Color::Hsl(h, s, l, a) => {
            let (r, g, b) = hsl_to_rgb(h, s, l);
            (r, g, b, a)
        }
        Color::Hsv(h, s, v, a) => {
            let (r, g, b) = hsv_to_rgb(h, s, v);
            (r, g, b, a)
        }
        Color::Oklab(l, aa, bb, a) => {
            let (r, g, b) = oklab_to_lin(l, aa, bb);
            (lin_to_srgb(r.clamp(0.0, 1.0)), lin_to_srgb(g.clamp(0.0, 1.0)), lin_to_srgb(b.clamp(0.0, 1.0)), a)
        }
        Color::Oklch(l, ch, h, a) => {
            let hr = h.to_radians();
            to_rgb(&Color::Oklab(l, ch * hr.cos(), ch * hr.sin(), a))
        }
    }
}

pub fn to_oklab(c: &Color) -> (f32, f32, f32, f32) {
    match *c {
        Color::Oklab(l, a, b, al) => (l, a, b, al),
        Color::Oklch(l, ch, h, al) => {
            let hr = h.to_radians();
            (l, ch * hr.cos(), ch * hr.sin(), al)
        }
        Color::LinearRgb(r, g, b, al) => {
            let (l, a, bb) = lin_to_oklab(r, g, b);
            (l, a, bb, al)
        }
        _ => {
            let (r, g, b, al) = to_rgb(c);
            let (l, a, bb) = lin_to_oklab(srgb_to_lin(r), srgb_to_lin(g), srgb_to_lin(b));
            (l, a, bb, al)
        }
    }
}

fn space_name(c: &Color) -> &'static str {
    match c {
        Color::Luma(..) => "luma",
        Color::Oklab(..) => "oklab",
        Color::Oklch(..) => "oklch",
        Color::Rgb(..) => "rgb",
        Color::LinearRgb(..) => "linear-rgb",
        Color::Cmyk(..) => "cmyk",
        Color::Hsl(..) => "hsl",
        Color::Hsv(..) => "hsv",
    }
}

fn alpha(c: &Color) -> f32 {
    match *c {
        Color::Luma(_, a) | Color::Oklab(_, _, _, a) | Color::Oklch(_, _, _, a) | Color::Rgb(_, _, _, a)
        | Color::LinearRgb(_, _, _, a) | Color::Hsl(_, _, _, a) | Color::Hsv(_, _, _, a) => a,
        Color::Cmyk(..) => 1.0,
    }
}

pub fn convert(c: &Color, space: &str) -> Color {
    let (r, g, b, a) = to_rgb(c);
    match space {
        "rgb" => Color::Rgb(r, g, b, a),
        "luma" => {
            let y = 0.2126 * srgb_to_lin(r) + 0.7152 * srgb_to_lin(g) + 0.0722 * srgb_to_lin(b);
            Color::Luma(lin_to_srgb(y), a)
        }
        "linear-rgb" => match c {
            Color::LinearRgb(..) => c.clone(),
            _ => Color::LinearRgb(srgb_to_lin(r), srgb_to_lin(g), srgb_to_lin(b), a),
        },
        "cmyk" => {
            let k = 1.0 - r.max(g).max(b);
            if k >= 1.0 {
                Color::Cmyk(0.0, 0.0, 0.0, 1.0)
            } else {
                Color::Cmyk((1.0 - r - k) / (1.0 - k), (1.0 - g - k) / (1.0 - k), (1.0 - b - k) / (1.0 - k), k)
            }
        }
        "hsl" => {
            let (h, s, l) = rgb_to_hsl(r, g, b);
            Color::Hsl(h, s, l, a)
        }
        "hsv" => {
            let (h, s, v) = rgb_to_hsv(r, g, b);
            Color::Hsv(h, s, v, a)
        }
        "oklab" => {
            let (l, aa, bb, al) = to_oklab(c);
            Color::Oklab(l, aa, bb, al)
        }
        "oklch" => {
            let (l, aa, bb, al) = to_oklab(c);
            let ch = (aa * aa + bb * bb).sqrt();
            let mut h = bb.atan2(aa).to_degrees();
            if h < 0.0 {
                h += 360.0;
            }
            Color::Oklch(l, ch, h, al)
        }
        _ => c.clone(),
    }
}

pub fn convert_method(v: Value, space: &str) -> StrResult<Value> {
    match v {
        Value::Color(c) => Ok(Value::Color(convert(&c, space))),
        _ => Err("expected color".into()),
    }
}

