            (h & 0xff) as f32 / 255.0,
            1.0,
        )
    };
    vec![
        ("black", Color::Luma(0.0, 1.0)),
        ("gray", Color::Luma(170.0 / 255.0, 1.0)),
        ("silver", Color::Luma(221.0 / 255.0, 1.0)),
        ("white", Color::Luma(1.0, 1.0)),
        ("navy", rgb(0x001f3f)),
        ("blue", rgb(0x0074d9)),
        ("aqua", rgb(0x7fdbff)),
        ("teal", rgb(0x39cccc)),
        ("eastern", rgb(0x239dad)),
        ("purple", rgb(0xb10dc9)),
        ("fuchsia", rgb(0xf012be)),
        ("maroon", rgb(0x85144b)),
        ("red", rgb(0xff4136)),
