static COMPONENT: Cast = Cast::Or(&[Cast::Int, Cast::Ratio]);

fn component(v: Value) -> StrResult<f32> {
    match v {
        Value::Int(i) => {
            if (0..=255).contains(&i) {
                Ok(i as f32 / 255.0)
            } else {
                Err("number must be between 0 and 255".into())
            }
        }
        Value::Ratio(r) => {
            if (0.0..=1.0).contains(&r) {
                Ok(r as f32)
            } else {
                Err("ratio must be between 0% and 100%".into())
            }
        }
        _ => Err("expected integer or ratio".into()),
    }
}

fn ratio_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Ratio(r) => {
            if (0.0..=1.0).contains(&r) {
                Ok(r as f32)
            } else {
                Err("ratio must be between 0% and 100%".into())
            }
        }
        _ => Err("expected ratio".into()),
    }
}

fn float_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Int(i) => Ok(i as f32),
        Value::Float(f) => Ok(f as f32),
        Value::Ratio(r) => Ok(r as f32),
        _ => Err("expected float or ratio".into()),
    }
}

fn angle_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Angle(a) => {
            let mut d = a.to_degrees() % 360.0;
            if d < 0.0 {
                d += 360.0;
            }
            Ok(d as f32)
        }
        _ => Err("expected angle".into()),
    }
}

pub fn parse_hex(s: &str) -> StrResult<Color> {
    let h = s.strip_prefix('#').unwrap_or(s);
    if !h.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err("color string contains non-hexadecimal letters".into());
    }
    let digits: Vec<u8> = h.chars().map(|c| c.to_digit(16).unwrap() as u8).collect();
    let comps: Vec<u8> = match digits.len() {
        3 | 4 => digits.iter().map(|d| d * 17).collect(),
        6 | 8 => digits.chunks(2).map(|p| p[0] * 16 + p[1]).collect(),
        _ => return Err("color string has wrong length".into()),
    };
    let a = if comps.len() == 4 { comps[3] as f32 / 255.0 } else { 1.0 };
    Ok(Color::Rgb(comps[0] as f32 / 255.0, comps[1] as f32 / 255.0, comps[2] as f32 / 255.0, a))
}

pub fn construct(engine: &mut Engine, name: &str, args: &mut Args) -> SourceResult<Value> {
    let _ = engine;
    let span = args.span;
    // Conversion from an existing color.
    if name != "mix" {
        if let Some(first) = args.items.iter().find(|a| a.name.is_none()) {
            if let Value::Color(c) = &first.value {
                let c = c.clone();
                args.eat_raw();
                args.finish()?;
                return Ok(Value::Color(convert(&c, name)));
            }
        }
    }
    match name {
        "rgb" => {
            if let Some(a) = args.items.iter().find(|a| a.name.is_none()) {
                if let Value::Str(s) = &a.value {
                    let s = s.clone();
                    let vs = a.value_span;
                    args.eat_raw();
                    args.finish()?;
                    return parse_hex(&s).map(Value::Color).at(vs);
                }
            }
            let r = expect_comp(args, "red component", &COMPONENT, component)?;
            let g = expect_comp(args, "green component", &COMPONENT, component)?;
            let b = expect_comp(args, "blue component", &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Rgb(r, g, b, a)))
        }
        "linear-rgb" => {
            let r = expect_comp(args, "red component", &COMPONENT, component)?;
            let g = expect_comp(args, "green component", &COMPONENT, component)?;
            let b = expect_comp(args, "blue component", &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::LinearRgb(r, g, b, a)))
        }
        "luma" => {
            let l = expect_comp(args, "lightness", &COMPONENT, component)?;
            let a = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Luma(l, a)))
        }
        "cmyk" => {
            let c = expect_comp(args, "cyan component", &RATIO, ratio_comp)?;
            let m = expect_comp(args, "magenta component", &RATIO, ratio_comp)?;
            let y = expect_comp(args, "yellow component", &RATIO, ratio_comp)?;
            let k = expect_comp(args, "key component", &RATIO, ratio_comp)?;
            args.finish()?;
            Ok(Value::Color(Color::Cmyk(c, m, y, k)))
        }
        "oklab" => {
            let l = expect_comp(args, "lightness", &RATIO, ratio_comp)?;
            static F: Cast = Cast::Or(&[Cast::Float, Cast::Ratio]);
            let a = expect_comp(args, "a component", &F, float_comp)?;
            let b = expect_comp(args, "b component", &F, float_comp)?;
            let al = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Oklab(l, a, b, al)))
        }
        "oklch" => {
            let l = expect_comp(args, "lightness", &RATIO, ratio_comp)?;
            static F: Cast = Cast::Or(&[Cast::Float, Cast::Ratio]);
            let c = expect_comp(args, "chroma", &F, float_comp)?;
            let h = expect_comp(args, "hue", &ANGLE, angle_comp)?;
            let al = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Oklch(l, c, h, al)))
        }
        "hsl" | "hsv" => {
            let h = expect_comp(args, "hue", &ANGLE, angle_comp)?;
            let s = expect_comp(args, "saturation", &COMPONENT, component)?;
            let l = expect_comp(args, if name == "hsl" { "lightness" } else { "value" }, &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(if name == "hsl" { Color::Hsl(h, s, l, a) } else { Color::Hsv(h, s, l, a) }))
        }
        "mix" => {
            let space = args.named("space", &ANY)?;
            let colors = args.all_strict(&ANY)?;
            args.finish()?;
            let space_name = match &space {
                Some(Value::Func(f)) => f.name().unwrap_or_else(|| "oklab".into()),
                Some(Value::Type(_)) => "oklab".into(),
                _ => "oklab".into(),
            };
            let mut items: Vec<(Color, f64)> = vec![];
            for c in colors {
                match c {
                    Value::Color(c) => items.push((c, 1.0)),
                    Value::Array(a) if a.len() == 2 => match (&a[0], &a[1]) {
                        (Value::Color(c), Value::Ratio(w)) => items.push((c.clone(), *w)),
                        (Value::Color(c), Value::Int(w)) => items.push((c.clone(), *w as f64)),
                        (Value::Color(c), Value::Float(w)) => items.push((c.clone(), *w)),
                        _ => bail!(span, "expected a color or color-weight pair"),
                    },
                    _ => bail!(span, "expected a color or color-weight pair"),
                }
            }
            if items.is_empty() {
                bail!(span, "cannot mix zero colors");
            }
            let total: f64 = items.iter().map(|x| x.1).sum();
            let conv: Vec<(Color, f64)> = items.iter().map(|(c, w)| (convert(c, &space_name), *w)).collect();
            let comps: Vec<(Vec<f32>, f64)> = conv.iter().map(|(c, w)| (components_raw(c), *w)).collect();
            let n = comps[0].0.len();
            let mut res = vec![0f32; n];
            for (cs, w) in &comps {
                for i in 0..n {
                    res[i] += cs[i] * (*w / total) as f32;
                }
            }
            Ok(Value::Color(from_components(&space_name, &res)))
        }
        _ => bail!(span, "unknown color space"),
    }
}

fn components_raw(c: &Color) -> Vec<f32> {
    match *c {
        Color::Luma(l, a) => vec![l, a],
        Color::Oklab(l, x, y, a) | Color::Oklch(l, x, y, a) | Color::Rgb(l, x, y, a) | Color::LinearRgb(l, x, y, a)
        | Color::Hsl(l, x, y, a) | Color::Hsv(l, x, y, a) => vec![l, x, y, a],
        Color::Cmyk(cc, m, y, k) => vec![cc, m, y, k],
    }
}

fn from_components(space: &str, v: &[f32]) -> Color {
    match space {
        "luma" => Color::Luma(v[0], v[1]),
        "oklch" => Color::Oklch(v[0], v[1], v[2], v[3]),
        "rgb" => Color::Rgb(v[0], v[1], v[2], v[3]),
        "linear-rgb" => Color::LinearRgb(v[0], v[1], v[2], v[3]),
        "cmyk" => Color::Cmyk(v[0], v[1], v[2], v[3]),
        "hsl" => Color::Hsl(v[0], v[1], v[2], v[3]),
        "hsv" => Color::Hsv(v[0], v[1], v[2], v[3]),
        _ => Color::Oklab(v[0], v[1], v[2], v[3]),
    }
}

fn expect_comp(args: &mut Args, what: &str, cast: &Cast, f: fn(Value) -> StrResult<f32>) -> SourceResult<f32> {
    match args.eat_raw() {
        Some(a) => {
            let v = cast.cast(a.value).at(a.value_span)?;
            f(v).at(a.value_span)
        }
        None => Err(args.missing_argument(what)),
    }
}

fn opt_comp(args: &mut Args, cast: &Cast, f: fn(Value) -> StrResult<f32>) -> SourceResult<Option<f32>> {
    match args.eat_raw() {
        Some(a) => {
            let v = cast.cast(a.value).at(a.value_span)?;
            f(v).at(a.value_span).map(Some)
        }
        None => Ok(None),
    }
}

fn map_space(c: &Color, f: impl Fn(Color) -> Color) -> Color {
    f(c.clone())
}

pub fn color_method(c: &Color, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "components" => {
            let alpha_arg = args.named("alpha", &BOOL)?;
            args.finish()?;
            let with_alpha = !matches!(alpha_arg, Some(Value::Bool(false)));
            let r = |x: f32| Value::Ratio(x as f64);
            let fl = |x: f32| Value::Float(x as f64);
            let ang = |x: f32| Value::Angle((x as f64).to_radians());
            let mut v = match *c {
                Color::Luma(l, a) => vec![r(l), r(a)],
                Color::Oklab(l, aa, bb, al) => vec![r(l), fl(aa), fl(bb), r(al)],
                Color::Oklch(l, ch, h, al) => vec![r(l), fl(ch), ang(h), r(al)],
                Color::Rgb(x, y, z, a) | Color::LinearRgb(x, y, z, a) => vec![r(x), r(y), r(z), r(a)],
                Color::Cmyk(cc, m, y, k) => vec![r(cc), r(m), r(y), r(k)],
                Color::Hsl(h, s, l, a) | Color::Hsv(h, s, l, a) => vec![ang(h), r(s), r(l), r(a)],
            };
            if !with_alpha && !matches!(c, Color::Cmyk(..)) {
                v.pop();
            }
            Ok(Value::array(v))
        }
        "space" => {
            args.finish()?;
            Ok(match space_name(c) {
                "luma" => Value::Func(crate::func::Func::builtin("std", "luma")),
                "rgb" => Value::Func(crate::func::Func::builtin("std", "rgb")),
                "cmyk" => Value::Func(crate::func::Func::builtin("std", "cmyk")),
                "oklab" => Value::Func(crate::func::Func::builtin("std", "oklab")),
                "oklch" => Value::Func(crate::func::Func::builtin("std", "oklch")),
                "linear-rgb" => Value::Func(crate::func::Func::builtin("color", "linear-rgb")),
                "hsl" => Value::Func(crate::func::Func::builtin("color", "hsl")),
                _ => Value::Func(crate::func::Func::builtin("color", "hsv")),
            })
        }
        "to-hex" => {
            args.finish()?;
            Ok(Value::str(to_hex(c)))
        }
        "lighten" | "darken" | "saturate" | "desaturate" | "transparentize" | "opacify" => {
            let f = args.expect("factor", &RATIO)?;
            args.finish()?;
            let Value::Ratio(f) = f else { unreachable!() };
            let f = f as f32;
            let res = match name {
                "lighten" => map_space(c, |c| match c {
                    Color::Luma(l, a) => Color::Luma(l + (1.0 - l) * f, a),
                    Color::Oklab(l, x, y, a) => Color::Oklab(l + (1.0 - l) * f, x, y, a),
                    Color::Oklch(l, x, y, a) => Color::Oklch(l + (1.0 - l) * f, x, y, a),
                    Color::Rgb(r, g, b, a) => Color::Rgb(r + (1.0 - r) * f, g + (1.0 - g) * f, b + (1.0 - b) * f, a),
                    Color::LinearRgb(r, g, b, a) => Color::LinearRgb(r + (1.0 - r) * f, g + (1.0 - g) * f, b + (1.0 - b) * f, a),
                    Color::Cmyk(cc, m, y, k) => Color::Cmyk(cc * (1.0 - f), m * (1.0 - f), y * (1.0 - f), k * (1.0 - f)),
                    Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l + (1.0 - l) * f, a),
                    Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v + (1.0 - v) * f, a),
                }),
                "darken" => map_space(c, |c| match c {
                    Color::Luma(l, a) => Color::Luma(l * (1.0 - f), a),
                    Color::Oklab(l, x, y, a) => Color::Oklab(l * (1.0 - f), x, y, a),
                    Color::Oklch(l, x, y, a) => Color::Oklch(l * (1.0 - f), x, y, a),
                    Color::Rgb(r, g, b, a) => Color::Rgb(r * (1.0 - f), g * (1.0 - f), b * (1.0 - f), a),
                    Color::LinearRgb(r, g, b, a) => Color::LinearRgb(r * (1.0 - f), g * (1.0 - f), b * (1.0 - f), a),
                    Color::Cmyk(cc, m, y, k) => Color::Cmyk(cc + (1.0 - cc) * f, m + (1.0 - m) * f, y + (1.0 - y) * f, k + (1.0 - k) * f),
                    Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l * (1.0 - f), a),
                    Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v * (1.0 - f), a),
                }),
                "saturate" | "desaturate" => {
                    let sat = |s: f32| if name == "saturate" { s + (1.0 - s) * f } else { s * (1.0 - f) };
                    match c {
                        Color::Hsl(h, s, l, a) => Color::Hsl(*h, sat(*s), *l, *a),
                        Color::Hsv(h, s, v, a) => Color::Hsv(*h, sat(*s), *v, *a),
                        Color::Luma(..) | Color::Cmyk(..) | Color::Oklab(..) | Color::Oklch(..) | Color::LinearRgb(..) | Color::Rgb(..) => {
                            if matches!(c, Color::Luma(..)) {
                                bail!(span, "cannot {} grayscale color", name);
                            }
                            let hsv = convert(c, "hsv");
                            let Color::Hsv(h, s, v, a) = hsv else { unreachable!() };
                            convert(&Color::Hsv(h, sat(s), v, a), space_name(c))
                        }
                    }
                }
                "transparentize" => set_alpha(c, alpha(c) * (1.0 - f)),
                _ => set_alpha(c, alpha(c) + (1.0 - alpha(c)) * f),
            };
            Ok(Value::Color(res))
        }
        "negate" => {
            let space = args.named("space", &ANY)?;
            args.finish()?;
            let sp = match &space {
                Some(Value::Func(f)) => f.name().unwrap_or_else(|| "oklab".into()),
                _ => "oklab".into(),
            };
            let res = match sp.as_str() {
                "rgb" => {
                    let (r, g, b, a) = to_rgb(c);
                    convert(&Color::Rgb(1.0 - r, 1.0 - g, 1.0 - b, a), space_name(c))
                }
                _ => {
                    let (l, aa, bb, al) = to_oklab(c);
                    let n = Color::Oklab(1.0 - l, -aa, -bb, al);
                    convert(&n, space_name(c))
                }
            };
            Ok(Value::Color(res))
        }
        "rotate" => {
            let ang = args.expect("angle", &ANGLE)?;
            let _space = args.named("space", &ANY)?;
            args.finish()?;
            let Value::Angle(a) = ang else { unreachable!() };
            let d = a.to_degrees() as f32;
            let lch = convert(c, "oklch");
            let Color::Oklch(l, ch, h, al) = lch else { unreachable!() };
            let mut nh = (h + d) % 360.0;
            if nh < 0.0 {
                nh += 360.0;
            }
            Ok(Value::Color(convert(&Color::Oklch(l, ch, nh, al), space_name(c))))
        }
        n => {
            args.finish()?;
            Ok(Value::Color(convert(c, n)))
        }
    }
}

fn set_alpha(c: &Color, a: f32) -> Color {
    match *c {
        Color::Luma(l, _) => Color::Luma(l, a),
        Color::Oklab(l, x, y, _) => Color::Oklab(l, x, y, a),
        Color::Oklch(l, x, y, _) => Color::Oklch(l, x, y, a),
        Color::Rgb(r, g, b, _) => Color::Rgb(r, g, b, a),
        Color::LinearRgb(r, g, b, _) => Color::LinearRgb(r, g, b, a),
        Color::Cmyk(..) => c.clone(),
        Color::Hsl(h, s, l, _) => Color::Hsl(h, s, l, a),
        Color::Hsv(h, s, v, _) => Color::Hsv(h, s, v, a),
    }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > color.rs <<'EOF'
//! Colors.

use crate::cast::*;
use crate::diag::*;
use crate::eval::Engine;
use crate::func::Args;
use crate::repr::{round_prec, float_display};
use crate::value::*;

fn pct(v: f32) -> String {
    let r = round_prec(v as f64 * 100.0, 2);
    format!("{}%", fmt_num(r))
}

fn fmt_num(r: f64) -> String {
    if r == 0.0 {
        return "0".into();
    }
    if r < 0.0 {
        format!("-{}", float_display(-r))
    } else {
        float_display(r)
    }
}

fn num3(v: f32) -> String {
    fmt_num(round_prec(v as f64, 3))
}

fn deg(v: f32) -> String {
    format!("{}deg", fmt_num(round_prec(v as f64, 2)))
}

pub fn to_u8(v: f32) -> u8 {
    (v.clamp(0.0, 1.0) * 255.0).round() as u8
}

pub fn repr_color(c: &Color) -> String {
    match c {
        Color::Luma(l, a) => {
            if *a == 1.0 {
                format!("luma({})", pct(*l))
            } else {
                format!("luma({}, {})", pct(*l), pct(*a))
            }
        }
        Color::Rgb(..) => format!("rgb(\"{}\")", to_hex(c)),
        Color::Cmyk(cc, m, y, k) => format!("cmyk({}, {}, {}, {})", pct(*cc), pct(*m), pct(*y), pct(*k)),
        Color::Oklab(l, a, b, al) => {
            if *al == 1.0 {
                format!("oklab({}, {}, {})", pct(*l), num3(*a), num3(*b))
            } else {
                format!("oklab({}, {}, {}, {})", pct(*l), num3(*a), num3(*b), pct(*al))
            }
        }
        Color::Oklch(l, ch, h, al) => {
            if *al == 1.0 {
                format!("oklch({}, {}, {})", pct(*l), num3(*ch), deg(*h))
            } else {
                format!("oklch({}, {}, {}, {})", pct(*l), num3(*ch), deg(*h), pct(*al))
            }
        }
        Color::LinearRgb(r, g, b, a) => {
            if *a == 1.0 {
                format!("color.linear-rgb({}, {}, {})", pct(*r), pct(*g), pct(*b))
            } else {
                format!("color.linear-rgb({}, {}, {}, {})", pct(*r), pct(*g), pct(*b), pct(*a))
            }
        }
        Color::Hsl(h, s, l, a) => {
            if *a == 1.0 {
                format!("color.hsl({}, {}, {})", deg(*h), pct(*s), pct(*l))
            } else {
                format!("color.hsl({}, {}, {}, {})", deg(*h), pct(*s), pct(*l), pct(*a))
            }
        }
        Color::Hsv(h, s, v, a) => {
            if *a == 1.0 {
                format!("color.hsv({}, {}, {})", deg(*h), pct(*s), pct(*v))
            } else {
                format!("color.hsv({}, {}, {}, {})", deg(*h), pct(*s), pct(*v), pct(*a))
            }
        }
    }
}

pub fn to_hex(c: &Color) -> String {
    let (r, g, b, a) = to_rgb(c);
    let mut s = format!("#{:02x}{:02x}{:02x}", to_u8(r), to_u8(g), to_u8(b));
    if a != 1.0 {
        s.push_str(&format!("{:02x}", to_u8(a)));
    }
    s
}

pub fn color_eq(a: &Color, b: &Color) -> bool {
    a == b
}

fn srgb_to_lin(c: f32) -> f32 {
    if c <= 0.04045 {
        c / 12.92
    } else {
        ((c + 0.055) / 1.055).powf(2.4)
    }
}

fn lin_to_srgb(c: f32) -> f32 {
    if c <= 0.0031308 {
        c * 12.92
    } else {
        1.055 * c.powf(1.0 / 2.4) - 0.055
    }
}

fn hsv_to_rgb(h: f32, s: f32, v: f32) -> (f32, f32, f32) {
    let h = ((h % 360.0) + 360.0) % 360.0;
    let c = v * s;
    let hp = h / 60.0;
    let x = c * (1.0 - ((hp % 2.0) - 1.0).abs());
    let (r, g, b) = match hp as i32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = v - c;
    (r + m, g + m, b + m)
}

fn rgb_to_hsv(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;
    let h = if d == 0.0 {
        0.0
    } else if max == r {
        60.0 * (((g - b) / d) % 6.0)
    } else if max == g {
        60.0 * ((b - r) / d + 2.0)
    } else {
        60.0 * ((r - g) / d + 4.0)
    };
    let h = if h < 0.0 { h + 360.0 } else { h };
    let s = if max == 0.0 { 0.0 } else { d / max };
    (h, s, max)
}

fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
    let v = l + s * l.min(1.0 - l);
    let sv = if v == 0.0 { 0.0 } else { 2.0 * (1.0 - l / v) };
    hsv_to_rgb(h, sv, v)
}

fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let (h, sv, v) = rgb_to_hsv(r, g, b);
    let l = v * (1.0 - sv / 2.0);
    let s = if l == 0.0 || l == 1.0 { 0.0 } else { (v - l) / l.min(1.0 - l) };
    (h, s, l)
}

fn lin_to_oklab(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let (r, g, b) = (r as f64, g as f64, b as f64);
    let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
    let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
    let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
    let (l, m, s) = (l.cbrt(), m.cbrt(), s.cbrt());
    (
        (0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s) as f32,
        (1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s) as f32,
        (0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s) as f32,
    )
}

fn oklab_to_lin(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
    let (l, a, b) = (l as f64, a as f64, b as f64);
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;
    let (l, m, s) = (l_ * l_ * l_, m_ * m_ * m_, s_ * s_ * s_);
    (
        (4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s) as f32,
        (-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s) as f32,
        (-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s) as f32,
    )
}

/// Convert to sRGB components (r, g, b, a).
pub fn to_rgb(c: &Color) -> (f32, f32, f32, f32) {
    match *c {
        Color::Luma(l, a) => (l, l, l, a),
        Color::Rgb(r, g, b, a) => (r, g, b, a),
        Color::LinearRgb(r, g, b, a) => (lin_to_srgb(r), lin_to_srgb(g), lin_to_srgb(b), a),
        Color::Cmyk(cc, m, y, k) => ((1.0 - cc) * (1.0 - k), (1.0 - m) * (1.0 - k), (1.0 - y) * (1.0 - k), 1.0),
        Color::Hsl(h, s, l, a) => {
            let (r, g, b) = hsl_to_rgb(h, s, l);
            (r, g, b, a)
        }
        Color::Hsv(h, s, v, a) => {
            let (r, g, b) = hsv_to_rgb(h, s, v);
            (r, g, b, a)
        }
        Color::Oklab(l, aa, bb, a) => {
            let (r, g, b) = oklab_to_lin(l, aa, bb);
            (lin_to_srgb(r.clamp(0.0, 1.0)), lin_to_srgb(g.clamp(0.0, 1.0)), lin_to_srgb(b.clamp(0.0, 1.0)), a)
        }
        Color::Oklch(l, ch, h, a) => {
            let hr = h.to_radians();
            to_rgb(&Color::Oklab(l, ch * hr.cos(), ch * hr.sin(), a))
        }
    }
}

pub fn to_oklab(c: &Color) -> (f32, f32, f32, f32) {
    match *c {
        Color::Oklab(l, a, b, al) => (l, a, b, al),
        Color::Oklch(l, ch, h, al) => {
            let hr = h.to_radians();
            (l, ch * hr.cos(), ch * hr.sin(), al)
        }
        Color::LinearRgb(r, g, b, al) => {
            let (l, a, bb) = lin_to_oklab(r, g, b);
            (l, a, bb, al)
        }
        _ => {
            let (r, g, b, al) = to_rgb(c);
            let (l, a, bb) = lin_to_oklab(srgb_to_lin(r), srgb_to_lin(g), srgb_to_lin(b));
            (l, a, bb, al)
        }
    }
}

fn space_name(c: &Color) -> &'static str {
    match c {
        Color::Luma(..) => "luma",
        Color::Oklab(..) => "oklab",
        Color::Oklch(..) => "oklch",
        Color::Rgb(..) => "rgb",
        Color::LinearRgb(..) => "linear-rgb",
        Color::Cmyk(..) => "cmyk",
        Color::Hsl(..) => "hsl",
        Color::Hsv(..) => "hsv",
    }
}

fn alpha(c: &Color) -> f32 {
    match *c {
        Color::Luma(_, a) | Color::Oklab(_, _, _, a) | Color::Oklch(_, _, _, a) | Color::Rgb(_, _, _, a)
        | Color::LinearRgb(_, _, _, a) | Color::Hsl(_, _, _, a) | Color::Hsv(_, _, _, a) => a,
        Color::Cmyk(..) => 1.0,
    }
}

pub fn convert(c: &Color, space: &str) -> Color {
    let (r, g, b, a) = to_rgb(c);
    match space {
        "rgb" => Color::Rgb(r, g, b, a),
        "luma" => {
            let y = 0.2126 * srgb_to_lin(r) + 0.7152 * srgb_to_lin(g) + 0.0722 * srgb_to_lin(b);
            Color::Luma(lin_to_srgb(y), a)
        }
        "linear-rgb" => match c {
            Color::LinearRgb(..) => c.clone(),
            _ => Color::LinearRgb(srgb_to_lin(r), srgb_to_lin(g), srgb_to_lin(b), a),
        },
        "cmyk" => {
            let k = 1.0 - r.max(g).max(b);
            if k >= 1.0 {
                Color::Cmyk(0.0, 0.0, 0.0, 1.0)
            } else {
                Color::Cmyk((1.0 - r - k) / (1.0 - k), (1.0 - g - k) / (1.0 - k), (1.0 - b - k) / (1.0 - k), k)
            }
        }
        "hsl" => {
            let (h, s, l) = rgb_to_hsl(r, g, b);
            Color::Hsl(h, s, l, a)
        }
        "hsv" => {
            let (h, s, v) = rgb_to_hsv(r, g, b);
            Color::Hsv(h, s, v, a)
        }
        "oklab" => {
            let (l, aa, bb, al) = to_oklab(c);
            Color::Oklab(l, aa, bb, al)
        }
        "oklch" => {
            let (l, aa, bb, al) = to_oklab(c);
            let ch = (aa * aa + bb * bb).sqrt();
            let mut h = bb.atan2(aa).to_degrees();
            if h < 0.0 {
                h += 360.0;
            }
            Color::Oklch(l, ch, h, al)
        }
        _ => c.clone(),
    }
}

pub fn convert_method(v: Value, space: &str) -> StrResult<Value> {
    match v {
        Value::Color(c) => Ok(Value::Color(convert(&c, space))),
        _ => Err("expected color".into()),
    }
}

pub fn named_colors() -> Vec<(&'static str, Color)> {
    let rgb = |h: u32| {
        Color::Rgb(
            ((h >> 16) & 0xff) as f32 / 255.0,
            ((h >> 8) & 0xff) as f32 / 255.0,
            (h & 0xff) as f32 / 255.0,
            1.0,
        )
    };
    vec![
        ("black", Color::Luma(0.0, 1.0)),
        ("gray", Color::Luma(170.0 / 255.0, 1.0)),
        ("silver", Color::Luma(221.0 / 255.0, 1.0)),
        ("white", Color::Luma(1.0, 1.0)),
        ("navy", rgb(0x001f3f)),
        ("blue", rgb(0x0074d9)),
        ("aqua", rgb(0x7fdbff)),
        ("teal", rgb(0x39cccc)),
        ("eastern", rgb(0x239dad)),
        ("purple", rgb(0xb10dc9)),
        ("fuchsia", rgb(0xf012be)),
        ("maroon", rgb(0x85144b)),
        ("red", rgb(0xff4136)),
        ("orange", rgb(0xff851b)),
        ("yellow", rgb(0xffdc00)),
        ("olive", rgb(0x3d9970)),
        ("green", rgb(0x2ecc40)),
        ("lime", rgb(0x01ff70)),
    ]
}

static COMPONENT: Cast = Cast::Or(&[Cast::Int, Cast::Ratio]);

fn component(v: Value) -> StrResult<f32> {
    match v {
        Value::Int(i) => {
            if (0..=255).contains(&i) {
                Ok(i as f32 / 255.0)
            } else {
                Err("number must be between 0 and 255".into())
            }
        }
        Value::Ratio(r) => {
            if (0.0..=1.0).contains(&r) {
                Ok(r as f32)
            } else {
                Err("ratio must be between 0% and 100%".into())
            }
        }
        _ => Err("expected integer or ratio".into()),
    }
}

fn ratio_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Ratio(r) => {
            if (0.0..=1.0).contains(&r) {
                Ok(r as f32)
            } else {
                Err("ratio must be between 0% and 100%".into())
            }
        }
        _ => Err("expected ratio".into()),
    }
}

fn float_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Int(i) => Ok(i as f32),
        Value::Float(f) => Ok(f as f32),
        Value::Ratio(r) => Ok(r as f32),
        _ => Err("expected float or ratio".into()),
    }
}

fn angle_comp(v: Value) -> StrResult<f32> {
    match v {
        Value::Angle(a) => {
            let mut d = a.to_degrees() % 360.0;
            if d < 0.0 {
                d += 360.0;
            }
            Ok(d as f32)
        }
        _ => Err("expected angle".into()),
    }
}

pub fn parse_hex(s: &str) -> StrResult<Color> {
    let h = s.strip_prefix('#').unwrap_or(s);
    if !h.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err("color string contains non-hexadecimal letters".into());
    }
    let digits: Vec<u8> = h.chars().map(|c| c.to_digit(16).unwrap() as u8).collect();
    let comps: Vec<u8> = match digits.len() {
        3 | 4 => digits.iter().map(|d| d * 17).collect(),
        6 | 8 => digits.chunks(2).map(|p| p[0] * 16 + p[1]).collect(),
        _ => return Err("color string has wrong length".into()),
    };
    let a = if comps.len() == 4 { comps[3] as f32 / 255.0 } else { 1.0 };
    Ok(Color::Rgb(comps[0] as f32 / 255.0, comps[1] as f32 / 255.0, comps[2] as f32 / 255.0, a))
}

pub fn construct(engine: &mut Engine, name: &str, args: &mut Args) -> SourceResult<Value> {
    let _ = engine;
    let span = args.span;
    // Conversion from an existing color.
    if name != "mix" {
        if let Some(first) = args.items.iter().find(|a| a.name.is_none()) {
            if let Value::Color(c) = &first.value {
                let c = c.clone();
                args.eat_raw();
                args.finish()?;
                return Ok(Value::Color(convert(&c, name)));
            }
        }
    }
    match name {
        "rgb" => {
            if let Some(a) = args.items.iter().find(|a| a.name.is_none()) {
                if let Value::Str(s) = &a.value {
                    let s = s.clone();
                    let vs = a.value_span;
                    args.eat_raw();
                    args.finish()?;
                    return parse_hex(&s).map(Value::Color).at(vs);
                }
            }
            let r = expect_comp(args, "red component", &COMPONENT, component)?;
            let g = expect_comp(args, "green component", &COMPONENT, component)?;
            let b = expect_comp(args, "blue component", &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Rgb(r, g, b, a)))
        }
        "linear-rgb" => {
            let r = expect_comp(args, "red component", &COMPONENT, component)?;
            let g = expect_comp(args, "green component", &COMPONENT, component)?;
            let b = expect_comp(args, "blue component", &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::LinearRgb(r, g, b, a)))
        }
        "luma" => {
            let l = expect_comp(args, "lightness", &COMPONENT, component)?;
            let a = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Luma(l, a)))
        }
        "cmyk" => {
            let c = expect_comp(args, "cyan component", &RATIO, ratio_comp)?;
            let m = expect_comp(args, "magenta component", &RATIO, ratio_comp)?;
            let y = expect_comp(args, "yellow component", &RATIO, ratio_comp)?;
            let k = expect_comp(args, "key component", &RATIO, ratio_comp)?;
            args.finish()?;
            Ok(Value::Color(Color::Cmyk(c, m, y, k)))
        }
        "oklab" => {
            let l = expect_comp(args, "lightness", &RATIO, ratio_comp)?;
            static F: Cast = Cast::Or(&[Cast::Float, Cast::Ratio]);
            let a = expect_comp(args, "a component", &F, float_comp)?;
            let b = expect_comp(args, "b component", &F, float_comp)?;
            let al = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Oklab(l, a, b, al)))
        }
        "oklch" => {
            let l = expect_comp(args, "lightness", &RATIO, ratio_comp)?;
            static F: Cast = Cast::Or(&[Cast::Float, Cast::Ratio]);
            let c = expect_comp(args, "chroma", &F, float_comp)?;
            let h = expect_comp(args, "hue", &ANGLE, angle_comp)?;
            let al = opt_comp(args, &RATIO, ratio_comp)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(Color::Oklch(l, c, h, al)))
        }
        "hsl" | "hsv" => {
            let h = expect_comp(args, "hue", &ANGLE, angle_comp)?;
            let s = expect_comp(args, "saturation", &COMPONENT, component)?;
            let l = expect_comp(args, if name == "hsl" { "lightness" } else { "value" }, &COMPONENT, component)?;
            let a = opt_comp(args, &COMPONENT, component)?.unwrap_or(1.0);
            args.finish()?;
            Ok(Value::Color(if name == "hsl" { Color::Hsl(h, s, l, a) } else { Color::Hsv(h, s, l, a) }))
        }
        "mix" => {
            let space = args.named("space", &ANY)?;
            let colors = args.all_strict(&ANY)?;
            args.finish()?;
            let space_name = match &space {
                Some(Value::Func(f)) => f.name().unwrap_or_else(|| "oklab".into()),
                Some(Value::Type(_)) => "oklab".into(),
                _ => "oklab".into(),
            };
            let mut items: Vec<(Color, f64)> = vec![];
            for c in colors {
                match c {
                    Value::Color(c) => items.push((c, 1.0)),
                    Value::Array(a) if a.len() == 2 => match (&a[0], &a[1]) {
                        (Value::Color(c), Value::Ratio(w)) => items.push((c.clone(), *w)),
                        (Value::Color(c), Value::Int(w)) => items.push((c.clone(), *w as f64)),
                        (Value::Color(c), Value::Float(w)) => items.push((c.clone(), *w)),
                        _ => bail!(span, "expected a color or color-weight pair"),
                    },
                    _ => bail!(span, "expected a color or color-weight pair"),
                }
            }
            if items.is_empty() {
                bail!(span, "cannot mix zero colors");
            }
            let total: f64 = items.iter().map(|x| x.1).sum();
            let conv: Vec<(Color, f64)> = items.iter().map(|(c, w)| (convert(c, &space_name), *w)).collect();
            let comps: Vec<(Vec<f32>, f64)> = conv.iter().map(|(c, w)| (components_raw(c), *w)).collect();
            let n = comps[0].0.len();
            let mut res = vec![0f32; n];
            for (cs, w) in &comps {
                for i in 0..n {
                    res[i] += cs[i] * (*w / total) as f32;
                }
            }
            Ok(Value::Color(from_components(&space_name, &res)))
        }
        _ => bail!(span, "unknown color space"),
    }
}

fn components_raw(c: &Color) -> Vec<f32> {
    match *c {
        Color::Luma(l, a) => vec![l, a],
        Color::Oklab(l, x, y, a) | Color::Oklch(l, x, y, a) | Color::Rgb(l, x, y, a) | Color::LinearRgb(l, x, y, a)
        | Color::Hsl(l, x, y, a) | Color::Hsv(l, x, y, a) => vec![l, x, y, a],
        Color::Cmyk(cc, m, y, k) => vec![cc, m, y, k],
    }
}

fn from_components(space: &str, v: &[f32]) -> Color {
    match space {
        "luma" => Color::Luma(v[0], v[1]),
        "oklch" => Color::Oklch(v[0], v[1], v[2], v[3]),
        "rgb" => Color::Rgb(v[0], v[1], v[2], v[3]),
        "linear-rgb" => Color::LinearRgb(v[0], v[1], v[2], v[3]),
        "cmyk" => Color::Cmyk(v[0], v[1], v[2], v[3]),
        "hsl" => Color::Hsl(v[0], v[1], v[2], v[3]),
        "hsv" => Color::Hsv(v[0], v[1], v[2], v[3]),
        _ => Color::Oklab(v[0], v[1], v[2], v[3]),
    }
}

fn expect_comp(args: &mut Args, what: &str, cast: &Cast, f: fn(Value) -> StrResult<f32>) -> SourceResult<f32> {
    match args.eat_raw() {
        Some(a) => {
            let v = cast.cast(a.value).at(a.value_span)?;
            f(v).at(a.value_span)
        }
        None => Err(args.missing_argument(what)),
    }
}

fn opt_comp(args: &mut Args, cast: &Cast, f: fn(Value) -> StrResult<f32>) -> SourceResult<Option<f32>> {
    match args.eat_raw() {
        Some(a) => {
            let v = cast.cast(a.value).at(a.value_span)?;
            f(v).at(a.value_span).map(Some)
        }
        None => Ok(None),
    }
}

fn map_space(c: &Color, f: impl Fn(Color) -> Color) -> Color {
    f(c.clone())
}

pub fn color_method(c: &Color, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "components" => {
            let alpha_arg = args.named("alpha", &BOOL)?;
            args.finish()?;
            let with_alpha = !matches!(alpha_arg, Some(Value::Bool(false)));
            let r = |x: f32| Value::Ratio(x as f64);
            let fl = |x: f32| Value::Float(x as f64);
            let ang = |x: f32| Value::Angle((x as f64).to_radians());
            let mut v = match *c {
                Color::Luma(l, a) => vec![r(l), r(a)],
                Color::Oklab(l, aa, bb, al) => vec![r(l), fl(aa), fl(bb), r(al)],
                Color::Oklch(l, ch, h, al) => vec![r(l), fl(ch), ang(h), r(al)],
                Color::Rgb(x, y, z, a) | Color::LinearRgb(x, y, z, a) => vec![r(x), r(y), r(z), r(a)],
                Color::Cmyk(cc, m, y, k) => vec![r(cc), r(m), r(y), r(k)],
                Color::Hsl(h, s, l, a) | Color::Hsv(h, s, l, a) => vec![ang(h), r(s), r(l), r(a)],
            };
            if !with_alpha && !matches!(c, Color::Cmyk(..)) {
                v.pop();
            }
            Ok(Value::array(v))
        }
        "space" => {
            args.finish()?;
            Ok(match space_name(c) {
                "luma" => Value::Func(crate::func::Func::builtin("std", "luma")),
                "rgb" => Value::Func(crate::func::Func::builtin("std", "rgb")),
                "cmyk" => Value::Func(crate::func::Func::builtin("std", "cmyk")),
                "oklab" => Value::Func(crate::func::Func::builtin("std", "oklab")),
                "oklch" => Value::Func(crate::func::Func::builtin("std", "oklch")),
                "linear-rgb" => Value::Func(crate::func::Func::builtin("color", "linear-rgb")),
                "hsl" => Value::Func(crate::func::Func::builtin("color", "hsl")),
                _ => Value::Func(crate::func::Func::builtin("color", "hsv")),
            })
        }
        "to-hex" => {
            args.finish()?;
            Ok(Value::str(to_hex(c)))
        }
        "lighten" | "darken" | "saturate" | "desaturate" | "transparentize" | "opacify" => {
            let f = args.expect("factor", &RATIO)?;
            args.finish()?;
            let Value::Ratio(f) = f else { unreachable!() };
            let f = f as f32;
            let res = match name {
                "lighten" => map_space(c, |c| match c {
                    Color::Luma(l, a) => Color::Luma(l + (1.0 - l) * f, a),
                    Color::Oklab(l, x, y, a) => Color::Oklab(l + (1.0 - l) * f, x, y, a),
                    Color::Oklch(l, x, y, a) => Color::Oklch(l + (1.0 - l) * f, x, y, a),
                    Color::Rgb(r, g, b, a) => Color::Rgb(r + (1.0 - r) * f, g + (1.0 - g) * f, b + (1.0 - b) * f, a),
                    Color::LinearRgb(r, g, b, a) => Color::LinearRgb(r + (1.0 - r) * f, g + (1.0 - g) * f, b + (1.0 - b) * f, a),
                    Color::Cmyk(cc, m, y, k) => Color::Cmyk(cc * (1.0 - f), m * (1.0 - f), y * (1.0 - f), k * (1.0 - f)),
                    Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l + (1.0 - l) * f, a),
                    Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v + (1.0 - v) * f, a),
                }),
                "darken" => map_space(c, |c| match c {
                    Color::Luma(l, a) => Color::Luma(l * (1.0 - f), a),
                    Color::Oklab(l, x, y, a) => Color::Oklab(l * (1.0 - f), x, y, a),
                    Color::Oklch(l, x, y, a) => Color::Oklch(l * (1.0 - f), x, y, a),
                    Color::Rgb(r, g, b, a) => Color::Rgb(r * (1.0 - f), g * (1.0 - f), b * (1.0 - f), a),
                    Color::LinearRgb(r, g, b, a) => Color::LinearRgb(r * (1.0 - f), g * (1.0 - f), b * (1.0 - f), a),
                    Color::Cmyk(cc, m, y, k) => Color::Cmyk(cc + (1.0 - cc) * f, m + (1.0 - m) * f, y + (1.0 - y) * f, k + (1.0 - k) * f),
                    Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l * (1.0 - f), a),
                    Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v * (1.0 - f), a),
                }),
                "saturate" | "desaturate" => {
                    let sat = |s: f32| if name == "saturate" { s + (1.0 - s) * f } else { s * (1.0 - f) };
                    match c {
                        Color::Hsl(h, s, l, a) => Color::Hsl(*h, sat(*s), *l, *a),
                        Color::Hsv(h, s, v, a) => Color::Hsv(*h, sat(*s), *v, *a),
                        Color::Luma(..) | Color::Cmyk(..) | Color::Oklab(..) | Color::Oklch(..) | Color::LinearRgb(..) | Color::Rgb(..) => {
                            if matches!(c, Color::Luma(..)) {
                                bail!(span, "cannot {} grayscale color", name);
                            }
                            let hsv = convert(c, "hsv");
                            let Color::Hsv(h, s, v, a) = hsv else { unreachable!() };
                            convert(&Color::Hsv(h, sat(s), v, a), space_name(c))
                        }
                    }
                }
                "transparentize" => set_alpha(c, alpha(c) * (1.0 - f)),
                _ => set_alpha(c, alpha(c) + (1.0 - alpha(c)) * f),
            };
            Ok(Value::Color(res))
        }
        "negate" => {
            let space = args.named("space", &ANY)?;
            args.finish()?;
            let sp = match &space {
                Some(Value::Func(f)) => f.name().unwrap_or_else(|| "oklab".into()),
                _ => "oklab".into(),
            };
            let res = match sp.as_str() {
                "rgb" => {
                    let (r, g, b, a) = to_rgb(c);
                    convert(&Color::Rgb(1.0 - r, 1.0 - g, 1.0 - b, a), space_name(c))
                }
                _ => {
                    let (l, aa, bb, al) = to_oklab(c);
                    let n = Color::Oklab(1.0 - l, -aa, -bb, al);
                    convert(&n, space_name(c))
                }
            };
            Ok(Value::Color(res))
        }
        "rotate" => {
            let ang = args.expect("angle", &ANGLE)?;
            let _space = args.named("space", &ANY)?;
            args.finish()?;
            let Value::Angle(a) = ang else { unreachable!() };
            let d = a.to_degrees() as f32;
            let lch = convert(c, "oklch");
            let Color::Oklch(l, ch, h, al) = lch else { unreachable!() };
            let mut nh = (h + d) % 360.0;
            if nh < 0.0 {
                nh += 360.0;
            }
            Ok(Value::Color(convert(&Color::Oklch(l, ch, nh, al), space_name(c))))
        }
        n => {
            args.finish()?;
            Ok(Value::Color(convert(c, n)))
        }
    }
}

fn set_alpha(c: &Color, a: f32) -> Color {
    match *c {
        Color::Luma(l, _) => Color::Luma(l, a),
        Color::Oklab(l, x, y, _) => Color::Oklab(l, x, y, a),
        Color::Oklch(l, x, y, _) => Color::Oklch(l, x, y, a),
        Color::Rgb(r, g, b, _) => Color::Rgb(r, g, b, a),
        Color::LinearRgb(r, g, b, _) => Color::LinearRgb(r, g, b, a),
        Color::Cmyk(..) => c.clone(),
        Color::Hsl(h, s, l, _) => Color::Hsl(h, s, l, a),
        Color::Hsv(h, s, v, _) => Color::Hsv(h, s, v, a),
    }
}
