pub fn repr_stroke(s: &Stroke) -> String {
    if s.cap.is_none() && s.join.is_none() && s.dash.is_none() && s.miter_limit.is_none() {
        return match (&s.paint, &s.thickness) {
            (Some(p), Some(t)) => format!("{} + {}", repr(t), repr(p)),
            (Some(p), None) => repr(p),
            (None, Some(t)) => repr(t),
            (None, None) => "1pt + black".into(),
        };
    }
    let mut parts = vec![];
