        parts.push(format!("paint: {}", repr(p)));
    }
    if let Some(t) = &s.thickness {
        parts.push(format!("thickness: {}", repr(t)));
    }
    if let Some(c) = &s.cap {
        parts.push(format!("cap: {}", repr(c)));
    }
    if let Some(j) = &s.join {
        parts.push(format!("join: {}", repr(j)));
    }
