}

fn repr_dash(d: &Value) -> String {
    match d {
        Value::None => "none".into(),
        Value::Dict(dd) => {
            let arr = dd.get("array").cloned().unwrap_or(Value::array(vec![]));
            let phase = dd.get("phase").cloned().unwrap_or(Value::Length(Length::zero()));
            format!("(array: {}, phase: {})", repr(&arr), repr(&phase))
        }
        v => repr(v),
    }
}

fn dash_pattern(v: Value) -> StrResult<Value> {
    let mk = |arr: Vec<Value>, phase: Value| {
        let mut d = Dict::new();
        d.insert(Rc::from("array"), Value::array(arr));
        d.insert(Rc::from("phase"), phase);
        Value::dict(d)
    };
    let pt = |x: f64| Value::Length(Length::pt(x));
    let dot = || Value::str("dot");
    match v {
        Value::None => Ok(Value::None),
        Value::Str(s) => {
            let arr = match &*s {
                "solid" => return Ok(mk(vec![], pt(0.0))),
                "dotted" => vec![dot(), pt(2.0)],
                "densely-dotted" => vec![dot(), pt(1.0)],
                "loosely-dotted" => vec![dot(), pt(4.0)],
                "dashed" => vec![pt(3.0), pt(3.0)],
                "densely-dashed" => vec![pt(3.0), pt(2.0)],
                "loosely-dashed" => vec![pt(3.0), pt(6.0)],
                "dash-dotted" => vec![pt(3.0), pt(2.0), dot(), pt(2.0)],
                "densely-dash-dotted" => vec![pt(3.0), pt(1.0), dot(), pt(1.0)],
                "loosely-dash-dotted" => vec![pt(3.0), pt(4.0), dot(), pt(4.0)],
                _ => return Err("expected \"solid\", \"dotted\", \"densely-dotted\", \"loosely-dotted\", \"dashed\", \"densely-dashed\", \"loosely-dashed\", \"dash-dotted\", \"densely-dash-dotted\", or \"loosely-dash-dotted\"".into()),
            };
            Ok(mk(arr, pt(0.0)))
        }
        Value::Array(a) => Ok(mk(a.iter().cloned().collect(), pt(0.0))),
        Value::Dict(d) => {
            let arr = d.get("array").cloned().unwrap_or(Value::array(vec![]));
            let phase = d.get("phase").cloned().unwrap_or(pt(0.0));
            let arr = match arr {
                Value::Array(a) => a.iter().cloned().collect(),
                _ => vec![],
            };
            Ok(mk(arr, phase))
        }
        v => Err(format!("expected string, array, dictionary, or none, found {}", v.type_name()).into()),
    }
}

pub fn to_stroke(v: Value) -> StrResult<Value> {
    let empty = Stroke { paint: None, thickness: None, cap: None, join: None, dash: None, miter_limit: None };
    Ok(match v {
        Value::Stroke(_) => v,
        Value::Length(_) => Value::Stroke(Rc::new(Stroke { thickness: Some(v), ..empty })),
        Value::Color(_) | Value::Gradient(_) | Value::Tiling(_) => Value::Stroke(Rc::new(Stroke { paint: Some(v), ..empty })),
        Value::Dict(d) => {
            let mut s = empty;
            for (k, val) in d.iter() {
                match &**k {
                    "paint" => s.paint = Some(PAINT.cast(val.clone())?),
                    "thickness" => s.thickness = Some(LENGTH.cast(val.clone())?),
                    "cap" => s.cap = Some(val.clone()),
                    "join" => s.join = Some(val.clone()),
                    "dash" => s.dash = Some(dash_pattern(val.clone())?),
                    "miter-limit" => s.miter_limit = Some(Cast::Float.cast(val.clone())?),
                    other => {
                        return Err(format!(
                            "unexpected key {}, valid keys are \"paint\", \"thickness\", \"cap\", \"join\", \"dash\", and \"miter-limit\"",
                            crate::repr::repr_str(other)
                        )
                        .into())
                    }
                }
            }
            Value::Stroke(Rc::new(s))
        }
        v => return Err(Cast::Stroke.error(&v)),
    })
}

pub fn construct_stroke(args: &mut Args) -> SourceResult<Value> {
    if let Some(v) = args.eat_raw() {
        args.finish()?;
        return to_stroke(v.value).at(v.value_span);
    }
    let paint = args.named("paint", &Cast::Smart(&Cast::Paint))?;
    let thickness = args.named("thickness", &Cast::Smart(&Cast::Length))?;
    let cap = args.named("cap", &Cast::Smart(&Cast::Strs(&["butt", "round", "square"])))?;
    let join = args.named("join", &Cast::Smart(&Cast::Strs(&["miter", "round", "bevel"])))?;
    let dash = args.named("dash", &ANY)?;
    let miter = args.named("miter-limit", &Cast::Smart(&Cast::Float))?;
    args.finish()?;
    let some = |v: Option<Value>| v.filter(|x| !matches!(x, Value::Auto));
    let dash = match some(dash) {
        Some(d) => Some(dash_pattern(d).at(args.span)?),
        None => None,
    };
    Ok(Value::Stroke(Rc::new(Stroke {
        paint: some(paint),
        thickness: some(thickness),
        cap: some(cap),
        join: some(join),
        dash,
