pub fn gradient_construct(engine: &mut Engine, kind: &str, args: &mut Args) -> SourceResult<Value> {
    let _ = engine;
    let span = args.span;
    let space = args.named("space", &ANY)?;
    let relative = args.named("relative", &ANY)?;
    let mut extra = vec![];
    match kind {
        "linear" => {
            if let Some(d) = args.named("dir", &DIR)? {
                extra.push(("dir", d));
            }
            if let Some(a) = args.named("angle", &ANGLE)? {
                extra.push(("angle", a));
            }
        }
        "radial" => {
            for n in ["center", "radius", "focal-center", "focal-radius"] {
                if let Some(v) = args.named(n, &ANY)? {
                    extra.push((n, v));
                }
            }
        }
        _ => {
            for n in ["angle", "center"] {
                if let Some(v) = args.named(n, &ANY)? {
                    extra.push((n, v));
                }
            }
        }
    }
    let stops = args.all_strict(&ANY)?;
    args.finish()?;
    let mut parsed: Vec<(Color, Option<f64>)> = vec![];
    for s in stops {
        match s {
            Value::Color(c) => parsed.push((c, None)),
            Value::Array(a) if a.len() == 2 => match (&a[0], &a[1]) {
                (Value::Color(c), Value::Ratio(r)) => parsed.push((c.clone(), Some(*r))),
                (Value::Color(c), Value::Angle(r)) => parsed.push((c.clone(), Some(*r / std::f64::consts::TAU))),
                _ => bail!(span, "expected color or (color, ratio) pair"),
            },
            v => bail!(span, "expected color, array, found {}", v.type_name()),
        }
    }
    if parsed.len() < 2 {
        let d = Diag::error(span, "a gradient must have at least two stops")
            .with_hint("try filling the shape with a single color instead");
        return Err(vec![d]);
    }
    let n = parsed.len();
    let all_none = parsed.iter().all(|x| x.1.is_none());
    let mut out: Vec<(Color, f64)> = vec![];
    if all_none {
        for (i, (c, _)) in parsed.into_iter().enumerate() {
            out.push((c, i as f64 / (n - 1) as f64));
        }
    } else {
        if parsed[0].1.is_some_and(|x| x != 0.0) {
            let d = Diag::error(span, "first stop must have an offset of 0").with_hint("try setting this stop to `0%`");
            return Err(vec![d]);
        }
        if parsed[n - 1].1.is_some_and(|x| x != 1.0) {
            let d = Diag::error(span, "last stop must have an offset of 100%").with_hint("try setting this stop to `100%`");
            return Err(vec![d]);
        }
        for (c, o) in parsed.into_iter() {
            out.push((c, o.unwrap_or(0.0)));
        }
    }
    let mut parts = vec![];
    for (k, v) in &extra {
        parts.push(format!("{}: {}", k, repr(v)));
    }
    if let Some(sp) = &space {
        parts.push(format!("space: {}", repr(sp)));
    }
    if let Some(r) = &relative {
        parts.push(format!("relative: {}", repr(r)));
    }
    for (c, o) in &out {
        let off = if kind == "conic" {
            crate::repr::repr_angle(o * std::f64::consts::TAU)
        } else {
            crate::repr::repr_ratio(*o)
        };
        parts.push(format!("({}, {})", crate::color::repr_color(c), off));
    }
    let repr = format!("gradient.{}({})", kind, parts.join(", "));
    let space_name: Str = match &space {
        Some(Value::Func(f)) => Rc::from(f.name().unwrap_or_else(|| "oklab".into()).as_str()),
        _ => Rc::from("oklab"),
    };
    Ok(Value::Gradient(Rc::new(Gradient {
        kind: Rc::from(kind),
        stops: out,
        repr,
        space: space_name,
        angle: None,
        relative: relative.unwrap_or(Value::Auto),
        extra: extra.into_iter().map(|(k, v)| (Rc::from(k), v)).collect(),
    })))
}

pub fn gradient_method(g: &Gradient, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "stops" => {
            args.finish()?;
            Ok(Value::array(
                g.stops
                    .iter()
                    .map(|(c, o)| Value::array(vec![Value::Color(c.clone()), if &*g.kind == "conic" { Value::Angle(o * std::f64::consts::TAU) } else { Value::Ratio(*o) }]))
                    .collect(),
            ))
        }
        "kind" => {
            args.finish()?;
            Ok(Value::Func(crate::func::Func::builtin("gradient", match &*g.kind {
                "linear" => "linear",
                "radial" => "radial",
                _ => "conic",
            })))
        }
        "relative" => {
            args.finish()?;
            Ok(g.relative.clone())
        }
        "sample" => {
            let t = args.expect("t", &Cast::Or(&[Cast::Ratio, Cast::Angle]))?;
            args.finish()?;
            let t = match t {
                Value::Ratio(r) => r,
                Value::Angle(a) => a / std::f64::consts::TAU,
                _ => 0.0,
            };
            let mut prev = &g.stops[0];
            for s in &g.stops {
                if s.1 >= t {
                    let span_ = s.1 - prev.1;
                    let f = if span_ <= 0.0 { 0.0 } else { (t - prev.1) / span_ };
                    let a = crate::color::to_oklab(&prev.0);
                    let b = crate::color::to_oklab(&s.0);
                    let lerp = |x: f32, y: f32| x + (y - x) * f as f32;
                    return Ok(Value::Color(Color::Oklab(lerp(a.0, b.0), lerp(a.1, b.1), lerp(a.2, b.2), lerp(a.3, b.3))));
                }
                prev = s;
            }
            Ok(Value::Color(g.stops.last().unwrap().0.clone()))
        }
        "space" => {
            args.finish()?;
            Ok(Value::Func(crate::func::Func::builtin("std", "oklab")))
        }
        _ => {
            args.finish()?;
            bail!(span, "gradient method `{}` is not supported", name)
        }
    }
}

pub fn call_misc(engine: &mut Engine, group: &str, name: &str, args: &mut Args) -> SourceResult<Value> {
    let _ = engine;
    let span = args.span;
    match (group, name) {
        ("image", "decode") => bail!(span, "image decoding is not supported"),
        _ => {
            let _ = args.take();
            bail!(span, "{}.{} is not supported", group, name)
        }
    }
}
