//! Symbols.

use crate::diag::*;
use crate::func::Args;
use crate::repr::{pretty_array_like, repr_str};
use crate::symdata;
use crate::value::*;
use std::rc::Rc;

fn mods_of(s: &str) -> Vec<&str> {
    if s.is_empty() {
        vec![]
    } else {
        s.split('.').collect()
    }
}

/// Find the best variant for the given modifiers.
pub fn find(variants: &[(Str, Str)], modifiers: &[&str]) -> Option<Str> {
    let mut best: Option<Str> = None;
    let mut best_total = usize::MAX;
    for (m, t) in variants {
        let set = mods_of(m);
        if modifiers.iter().all(|x| set.contains(x)) {
            let total = set.len();
            if total < best_total {
                best_total = total;
                best = Some(t.clone());
            }
        }
    }
    best
}

pub fn make_symbol(name: Option<&str>, variants: Vec<(Str, Str)>) -> Symbol {
    let text = find(&variants, &[]).unwrap_or_else(|| Rc::from(""));
    Symbol { name: name.map(Rc::from), text, variants: Rc::new(variants), modifiers: Rc::from("") }
}

fn table_symbol(name: &str, data: &[(&str, &str)]) -> Symbol {
    let vars: Vec<(Str, Str)> = data.iter().map(|(m, t)| (Rc::from(*m), Rc::from(*t))).collect();
    make_symbol(Some(name), vars)
}

pub fn sym_scope() -> Scope {
    let mut s = Scope::new();
    for (name, data) in symdata::SYM {
        s.define(*name, Value::Symbol(table_symbol(name, data)));
    }
    let mut g = Scope::new();
    for (name, data) in symdata::GENDER {
        g.define(*name, Value::Symbol(table_symbol(name, data)));
    }
    s.define(
        "gender",
        Value::Module(Rc::new(Module { name: Rc::from("gender"), scope: Rc::new(g), content: None })),
    );
    // keep alphabetical order like the reference
