                _ => bail!(span, "variant must be a string or a (modifiers, value) pair"),
            },
            other => bail!(span, "expected string or array, found {}", other.type_name()),
        };
        if crate::unicode::graphemes(&t).len() != 1 {
            let d = Diag::error(span, format!("invalid variant value: {}", repr_str(&t)))
                .with_hint("variant value must be exactly one grapheme cluster");
            return Err(vec![d]);
        }
        variants.push((Rc::from(m.as_str()), t));
    }
    Ok(Value::Symbol(make_symbol(None, variants)))
}
