//! Datetime and duration.

use crate::cast::*;
use crate::diag::*;
use crate::eval::Engine;
use crate::func::Args;
use crate::repr::pretty_array_like;
use crate::value::*;
use std::cmp::Ordering;

pub fn is_leap(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

pub fn days_in_month(y: i32, m: u8) -> u8 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

/// Days since 1970-01-01.
pub fn days_from_civil(y: i32, m: u8, d: u8) -> i64 {
    let y = if m <= 2 { y as i64 - 1 } else { y as i64 };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let m = m as i64;
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i32, u8, u8) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u8;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u8;
    ((if m <= 2 { y + 1 } else { y }) as i32, m, d)
}

pub fn repr_datetime(d: &Datetime) -> String {
    let mut parts = vec![];
    if let Some((y, m, dd)) = d.date {
        parts.push(format!("year: {y}"));
        parts.push(format!("month: {m}"));
        parts.push(format!("day: {dd}"));
    }
    if let Some((h, mi, s)) = d.time {
        parts.push(format!("hour: {h}"));
        parts.push(format!("minute: {mi}"));
        parts.push(format!("second: {s}"));
    }
    format!("datetime{}", pretty_array_like(&parts, false))
}

pub fn repr_duration(d: &Duration) -> String {
    let mut secs = d.0.round() as i64;
    let mut parts = vec![];
    let units = [("weeks", 604800i64), ("days", 86400), ("hours", 3600), ("minutes", 60), ("seconds", 1)];
    for (n, u) in units {
        let q = secs / u;
        if q != 0 {
            parts.push(format!("{n}: {q}"));
            secs -= q * u;
        }
    }
    format!("duration{}", pretty_array_like(&parts, false))
}

fn to_seconds(d: &Datetime) -> Option<i64> {
    let days = d.date.map(|(y, m, dd)| days_from_civil(y, m, dd));
    let t = d.time.map(|(h, m, s)| h as i64 * 3600 + m as i64 * 60 + s as i64);
    match (days, t) {
        (Some(days), Some(t)) => Some(days * 86400 + t),
        (Some(days), None) => Some(days * 86400),
        (None, Some(t)) => Some(t),
        (None, None) => None,
    }
}

pub fn add_duration(d: &Datetime, secs: f64) -> StrResult<Datetime> {
    let total = to_seconds(d).unwrap_or(0) + secs.round() as i64;
    let (days, rem) = (total.div_euclid(86400), total.rem_euclid(86400));
    let date = d.date.map(|_| civil_from_days(days));
    let time = d.time.map(|_| ((rem / 3600) as u8, ((rem % 3600) / 60) as u8, (rem % 60) as u8));
    Ok(Datetime { date, time })
}

pub fn sub_datetimes(a: &Datetime, b: &Datetime) -> StrResult<Duration> {
    if a.date.is_some() != b.date.is_some() || a.time.is_some() != b.time.is_some() {
        return Err("cannot subtract datetimes of different kinds".into());
    }
    Ok(Duration((to_seconds(a).unwrap_or(0) - to_seconds(b).unwrap_or(0)) as f64))
}

pub fn cmp(a: &Datetime, b: &Datetime) -> Option<Ordering> {
    if a.date.is_some() != b.date.is_some() || a.time.is_some() != b.time.is_some() {
        return None;
    }
    Some(to_seconds(a)?.cmp(&to_seconds(b)?))
}

pub fn now_utc() -> (i32, u8, u8, u8, u8, u8) {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let (y, m, d) = civil_from_days(secs.div_euclid(86400));
    let rem = secs.rem_euclid(86400);
    (y, m, d, (rem / 3600) as u8, ((rem % 3600) / 60) as u8, (rem % 60) as u8)
}

pub fn today(engine: &mut Engine, args: &mut Args) -> SourceResult<Value> {
    let offset = args.named("offset", &Cast::Smart(&Cast::Int))?;
    args.finish()?;
    let now = engine.world.now.unwrap_or_else(|| {
        let n = now_utc();
        (n.0, n.1, n.2)
    });
    let (mut y, mut m, mut d) = now;
    if let Some(Value::Int(h)) = offset {
        let n = now_utc();
        let secs = days_from_civil(n.0, n.1, n.2) * 86400 + n.3 as i64 * 3600 + n.4 as i64 * 60 + n.5 as i64 + h * 3600;
        let c = civil_from_days(secs.div_euclid(86400));
        y = c.0;
        m = c.1;
        d = c.2;
    }
    Ok(Value::Datetime(Datetime { date: Some((y, m, d)), time: None }))
}

pub fn construct_datetime(args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let year = args.named("year", &INT)?;
    let month = args.named("month", &INT)?;
    let day = args.named("day", &INT)?;
    let hour = args.named("hour", &INT)?;
    let minute = args.named("minute", &INT)?;
    let second = args.named("second", &INT)?;
    args.finish()?;
    let gi = |v: &Option<Value>| match v {
        Some(Value::Int(i)) => Some(*i),
        _ => None,
    };
    let (y, mo, d, h, mi, s) = (gi(&year), gi(&month), gi(&day), gi(&hour), gi(&minute), gi(&second));
    let date = match (y, mo, d) {
        (Some(y), Some(m), Some(d)) => {
            if !(1..=12).contains(&m) {
                bail!(span, "month is invalid");
            }
            if d < 1 || d > days_in_month(y as i32, m as u8) as i64 {
                bail!(span, "date is invalid");
            }
            Some((y as i32, m as u8, d as u8))
        }
        (None, None, None) => None,
        _ => {
            let mut missing = vec![];
            if y.is_none() {
                missing.push("`year`");
            }
            if mo.is_none() {
                missing.push("`month`");
            }
            if d.is_none() {
                missing.push("`day`");
            }
            let hint = if missing.len() == 1 {
                format!("add the {} argument to get a valid date", missing[0])
            } else {
                format!("add the {} and {} arguments to get a valid date", missing[..missing.len() - 1].join(", "), missing[missing.len() - 1])
            };
            let dg = Diag::error(span, "date is incomplete").with_hint(hint);
            return Err(vec![dg]);
        }
    };
    let time = match (h, mi, s) {
        (Some(h), Some(m), Some(s)) => {
            if !(0..24).contains(&h) || !(0..60).contains(&m) || !(0..60).contains(&s) {
                bail!(span, "time is invalid");
            }
            Some((h as u8, m as u8, s as u8))
        }
        (None, None, None) => None,
        _ => {
            let mut missing = vec![];
            if h.is_none() {
                missing.push("`hour`");
            }
            if mi.is_none() {
                missing.push("`minute`");
            }
            if s.is_none() {
                missing.push("`second`");
            }
            let hint = if missing.len() == 1 {
                format!("add the {} argument to get a valid time", missing[0])
            } else {
                format!("add the {} and {} arguments to get a valid time", missing[..missing.len() - 1].join(", "), missing[missing.len() - 1])
            };
            let dg = Diag::error(span, "time is incomplete").with_hint(hint);
            return Err(vec![dg]);
        }
    };
    if date.is_none() && time.is_none() {
        bail!(span, "at least one of date or time must be fully specified");
    }
    Ok(Value::Datetime(Datetime { date, time }))
}

pub fn construct_duration(args: &mut Args) -> SourceResult<Value> {
    let mut total = 0i64;
    for (n, u) in [("seconds", 1i64), ("minutes", 60), ("hours", 3600), ("days", 86400), ("weeks", 604800)] {
        if let Some(Value::Int(v)) = args.named(n, &INT)? {
            total += v * u;
        }
    }
    args.finish()?;
    Ok(Value::Duration(Duration(total as f64)))
}

const MONTHS: [&str; 12] = [
    "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December",
];
const WEEKDAYS: [&str; 7] = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

fn weekday(y: i32, m: u8, d: u8) -> u8 {
    // 1970-01-01 was a Thursday (index 3 with Monday=0)
    let days = days_from_civil(y, m, d);
    ((days + 3).rem_euclid(7)) as u8 + 1
}

fn ordinal(y: i32, m: u8, d: u8) -> u16 {
    (days_from_civil(y, m, d) - days_from_civil(y, 1, 1) + 1) as u16
}

pub fn display(dt: &Datetime, pattern: Option<&str>) -> StrResult<String> {
    let pat = match pattern {
        Some(p) => p.to_string(),
        None => match (dt.date, dt.time) {
            (Some(_), Some(_)) => "[year]-[month]-[day] [hour]:[minute]:[second]".into(),
            (Some(_), None) => "[year]-[month]-[day]".into(),
            _ => "[hour]:[minute]:[second]".into(),
        },
    };
    let mut out = String::new();
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '[' {
            if i + 1 < chars.len() && chars[i + 1] == '[' {
                out.push('[');
                i += 2;
                continue;
            }
            let end = match chars[i..].iter().position(|c| *c == ']') {
                Some(e) => i + e,
                None => return Err("failed to parse datetime format (expected component name)".into()),
            };
            let comp: String = chars[i + 1..end].iter().collect();
            let mut parts = comp.split_whitespace();
            let name = parts.next().unwrap_or("");
            let mut padding = "zero";
            let mut repr = "";
            for p in parts {
                if let Some((k, v)) = p.split_once(':') {
                    match k {
                        "padding" => padding = if v == "none" { "none" } else if v == "space" { "space" } else { "zero" },
                        "repr" => repr = Box::leak(v.to_string().into_boxed_str()),
                        _ => {}
                    }
                }
            }
            let pad = |n: i64, w: usize| -> String {
                match padding {
                    "none" => n.to_string(),
                    "space" => format!("{:>w$}", n, w = w),
                    _ => format!("{:0w$}", n, w = w),
                }
            };
            let date = dt.date;
            let time = dt.time;
            let need_date = || date.ok_or_else(|| HintedString::new("display requires date"));
            let need_time = || time.ok_or_else(|| HintedString::new("display requires time"));
            match name {
                "year" => {
                    let (y, _, _) = need_date()?;
                    if repr == "last_two" {
                        out.push_str(&pad((y % 100) as i64, 2));
                    } else {
                        out.push_str(&pad(y as i64, 4));
                    }
                }
                "month" => {
                    let (_, m, _) = need_date()?;
                    match repr {
                        "long" => out.push_str(MONTHS[m as usize - 1]),
                        "short" => out.push_str(&MONTHS[m as usize - 1][..3]),
                        _ => out.push_str(&pad(m as i64, 2)),
                    }
                }
                "day" => {
                    let (_, _, d) = need_date()?;
                    out.push_str(&pad(d as i64, 2));
                }
                "weekday" => {
                    let (y, m, d) = need_date()?;
                    let w = weekday(y, m, d);
                    match repr {
                        "short" => out.push_str(&WEEKDAYS[w as usize - 1][..3]),
                        "sunday" => out.push_str(&((w % 7) + 1).to_string()),
                        "monday" => out.push_str(&w.to_string()),
                        _ => out.push_str(WEEKDAYS[w as usize - 1]),
                    }
                }
                "ordinal" => {
                    let (y, m, d) = need_date()?;
                    out.push_str(&pad(ordinal(y, m, d) as i64, 3));
                }
                "hour" => {
                    let (h, _, _) = need_time()?;
                    if repr == "12" {
                        let h12 = if h % 12 == 0 { 12 } else { h % 12 };
                        out.push_str(&pad(h12 as i64, 2));
                    } else {
                        out.push_str(&pad(h as i64, 2));
                    }
                }
                "minute" => {
                    let (_, m, _) = need_time()?;
                    out.push_str(&pad(m as i64, 2));
                }
                "second" => {
                    let (_, _, s) = need_time()?;
                    out.push_str(&pad(s as i64, 2));
                }
                "period" => {
                    let (h, _, _) = need_time()?;
                    let p = if h < 12 { "AM" } else { "PM" };
                    if repr == "lower" {
                        out.push_str(&p.to_lowercase());
                    } else {
                        out.push_str(p);
                    }
                }
                _ => return Err(format!("failed to parse datetime format (invalid component)").into()),
            }
            i = end + 1;
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    Ok(out)
}

