        "month" => iv(d.date.map(|x| x.1 as i64)),
        "day" => iv(d.date.map(|x| x.2 as i64)),
        "weekday" => iv(d.date.map(|(y, m, dd)| weekday(y, m, dd) as i64)),
        "ordinal" => iv(d.date.map(|(y, m, dd)| ordinal(y, m, dd) as i64)),
        "hour" => iv(d.time.map(|x| x.0 as i64)),
        "minute" => iv(d.time.map(|x| x.1 as i64)),
        "second" => iv(d.time.map(|x| x.2 as i64)),
        _ => bail!(span, "type datetime has no method `{}`", name),
    })
}

pub fn duration_method(d: Duration, name: &str, args: &mut Args) -> SourceResult<Value> {
    args.finish()?;
    let s = d.0;
    Ok(Value::Float(match name {
