//! Decimal numbers (mantissa + scale).

use crate::value::Decimal;
use std::cmp::Ordering;

const MAX: i128 = 79228162514264337593543950335;

fn pow10(n: u32) -> i128 {
    10i128.pow(n)
}

fn check(d: Decimal) -> Option<Decimal> {
    if d.mantissa.abs() > MAX {
        // try reducing scale
        let mut d = d;
        while d.mantissa.abs() > MAX && d.scale > 0 {
            d.mantissa /= 10;
            d.scale -= 1;
        }
        if d.mantissa.abs() > MAX {
            return None;
        }
        return Some(d);
    }
    Some(d)
}

fn align(a: &Decimal, b: &Decimal) -> Option<(i128, i128, u32)> {
    let s = a.scale.max(b.scale);
    let am = a.mantissa.checked_mul(pow10(s - a.scale))?;
    let bm = b.mantissa.checked_mul(pow10(s - b.scale))?;
    Some((am, bm, s))
}

pub fn from_int(i: i64) -> Decimal {
    Decimal { mantissa: i as i128, scale: 0 }
}

pub fn from_f64(f: f64) -> Decimal {
    // 28 significant digits
    if f == 0.0 {
        return Decimal { mantissa: 0, scale: 0 };
    }
    let s = format!("{:.28e}", f);
    let (m, e) = s.split_once('e').unwrap();
    let e: i32 = e.parse().unwrap();
    let neg = m.starts_with('-');
    let digits: String = m.chars().filter(|c| c.is_ascii_digit()).collect();
    // digits = d.ddd... (29 digits), value = digits * 10^(e - 28)
    let mut mant: i128 = digits.parse().unwrap_or(0);
    let mut scale = 28 - e;
    while scale < 0 {
        mant *= 10;
        scale += 1;
    }
    let mut d = Decimal { mantissa: if neg { -mant } else { mant }, scale: scale as u32 };
    while d.scale > 28 {
        d.mantissa /= 10;
        d.scale -= 1;
    }
    // trim to max 28 scale and strip trailing zeros
    while d.scale > 0 && d.mantissa % 10 == 0 {
        d.mantissa /= 10;
        d.scale -= 1;
    }
    while d.mantissa.abs() > MAX && d.scale > 0 {
        d.mantissa /= 10;
        d.scale -= 1;
    }
    d
}

pub fn parse(s: &str) -> Option<Decimal> {
    let s = s.trim();
    let (neg, body) = if let Some(r) = s.strip_prefix('-').or_else(|| s.strip_prefix('\u{2212}')) {
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    if body.is_empty() {
        return None;
    }
    let (int, frac) = match body.split_once('.') {
        Some((i, f)) => (i, f),
        None => (body, ""),
    };
    if int.is_empty() && frac.is_empty() {
        return None;
    }
    if !int.chars().all(|c| c.is_ascii_digit()) || !frac.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let digits = format!("{int}{frac}");
    let mant: i128 = digits.parse().ok()?;
    if mant > MAX || frac.len() > 28 {
        return None;
    }
    Some(Decimal { mantissa: if neg { -mant } else { mant }, scale: frac.len() as u32 })
}

pub fn display(d: &Decimal) -> String {
    let neg = d.mantissa < 0;
    let digits = d.mantissa.abs().to_string();
    let s = if d.scale == 0 {
        digits
    } else {
        let scale = d.scale as usize;
        let padded = if digits.len() <= scale { format!("{}{}", "0".repeat(scale - digits.len() + 1), digits) } else { digits };
        let (i, f) = padded.split_at(padded.len() - scale);
        format!("{i}.{f}")
    };
    if neg {
        format!("-{s}")
    } else {
        s
    }
}

pub fn display_signed(d: &Decimal) -> String {
    let s = display(d);
    match s.strip_prefix('-') {
        Some(r) => format!("\u{2212}{r}"),
        None => s,
    }
}

pub fn to_f64(d: &Decimal) -> f64 {
    display(d).parse().unwrap_or(0.0)
}

pub fn neg(d: &Decimal) -> Decimal {
    Decimal { mantissa: -d.mantissa, scale: d.scale }
}

pub fn abs(d: &Decimal) -> Decimal {
    Decimal { mantissa: d.mantissa.abs(), scale: d.scale }
}

pub fn add(a: &Decimal, b: &Decimal) -> Option<Decimal> {
    let (x, y, s) = align(a, b)?;
    check(Decimal { mantissa: x.checked_add(y)?, scale: s })
}

pub fn sub(a: &Decimal, b: &Decimal) -> Option<Decimal> {
    let (x, y, s) = align(a, b)?;
    check(Decimal { mantissa: x.checked_sub(y)?, scale: s })
}

pub fn mul(a: &Decimal, b: &Decimal) -> Option<Decimal> {
    let m = a.mantissa.checked_mul(b.mantissa)?;
    let mut d = Decimal { mantissa: m, scale: a.scale + b.scale };
    while d.scale > 28 {
        d.mantissa /= 10;
        d.scale -= 1;
    }
    check(d)
}

pub fn div(a: &Decimal, b: &Decimal) -> Option<Decimal> {
    if b.mantissa == 0 {
        return None;
    }
    // compute a/b with up to 28 fractional digits
    let neg = (a.mantissa < 0) != (b.mantissa < 0);
    let mut num = a.mantissa.abs();
    let den = b.mantissa.abs();
    // value = (num / 10^sa) / (den / 10^sb) = num * 10^sb / (den * 10^sa)
    let mut scale: i64 = a.scale as i64 - b.scale as i64;
    let mut q = num / den;
    let mut r = num % den;
    while r != 0 && scale < 28 {
        if q > MAX / 10 {
            break;
        }
        num = r * 10;
        q = q * 10 + num / den;
        r = num % den;
        scale += 1;
    }
    while scale < 0 {
        q = q.checked_mul(10)?;
        scale += 1;
    }
    let mut d = Decimal { mantissa: if neg { -q } else { q }, scale: scale as u32 };
    if r != 0 {
        // round half even on last digit (approx: round half up)
        if r * 2 >= den {
            d.mantissa += if neg { -1 } else { 1 };
        }
    }
    let min_scale = a.scale.max(b.scale).saturating_sub(b.scale).max(0);
    while d.scale > min_scale && d.mantissa % 10 == 0 && r == 0 {
        d.mantissa /= 10;
        d.scale -= 1;
    }
    check(d)
}

pub fn cmp(a: &Decimal, b: &Decimal) -> Ordering {
    match align(a, b) {
        Some((x, y, _)) => x.cmp(&y),
        None => to_f64(a).partial_cmp(&to_f64(b)).unwrap_or(Ordering::Equal),
    }
}

pub fn round(d: &Decimal, digits: i64) -> Decimal {
    if digits < 0 {
        return d.clone();
    }
    let digits = digits as u32;
    if d.scale <= digits {
        return d.clone();
    }
    let f = pow10(d.scale - digits);
    let q = d.mantissa / f;
    let r = d.mantissa % f;
    let mut m = q;
    if r.abs() * 2 >= f {
        m += if d.mantissa < 0 { -1 } else { 1 };
    }
    Decimal { mantissa: m, scale: digits }
}

pub fn round_mode(d: &Decimal, mode: &str) -> Decimal {
    let f = pow10(d.scale);
    let q = d.mantissa / f;
    let r = d.mantissa % f;
    let m = match mode {
        "floor" if r < 0 => q - 1,
        "ceil" if r > 0 => q + 1,
        _ => q,
    };
    Decimal { mantissa: m, scale: 0 }
}

pub fn fract(d: &Decimal) -> Decimal {
    let f = pow10(d.scale);
    Decimal { mantissa: d.mantissa % f, scale: d.scale }
}

pub fn pow(d: &Decimal, e: i64) -> Option<Decimal> {
    if e < 0 {
        let p = pow(d, -e)?;
        return div(&Decimal { mantissa: 1, scale: 0 }, &p);
    }
    let mut r = Decimal { mantissa: 1, scale: 0 };
    for _ in 0..e {
        r = mul(&r, d)?;
    }
    Some(r)
}

pub fn to_int(d: &Decimal) -> Option<i64> {
    let f = pow10(d.scale);
    let q = d.mantissa / f;
    i64::try_from(q).ok()
}
