        let c = self.eat().ok_or("incomplete escape sequence")?;
        Ok(match c {
            'd' => Err(ClassItem::Digit(false)),
            'D' => Err(ClassItem::Digit(true)),
            'w' => Err(ClassItem::Word(false)),
            'W' => Err(ClassItem::Word(true)),
            's' => Err(ClassItem::Space(false)),
            'S' => Err(ClassItem::Space(true)),
            'p' | 'P' => {
                let neg = c == 'P';
                let name = if self.peek() == Some('{') {
                    self.pos += 1;
                    let mut n = String::new();
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        n.push(ch);
                    }
                    n
                } else {
                    self.eat().map(|c| c.to_string()).unwrap_or_default()
                };
                Err(ClassItem::Prop(name, neg))
            }
            'n' => Ok('\n'),
            't' => Ok('\t'),
            'r' => Ok('\r'),
            'f' => Ok('\x0c'),
            'v' => Ok('\x0b'),
            '0' => Ok('\0'),
            'x' => {
                let mut hex = String::new();
                if self.peek() == Some('{') {
                    self.pos += 1;
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        hex.push(ch);
                    }
                } else {
                    for _ in 0..2 {
                        if let Some(ch) = self.eat() {
                            hex.push(ch);
                        }
                    }
                }
                Ok(u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).ok_or("invalid hex escape")?)
            }
            'u' | 'U' => {
                let mut hex = String::new();
                if self.peek() == Some('{') {
                    self.pos += 1;
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        hex.push(ch);
                    }
                } else {
                    let n = if c == 'u' { 4 } else { 8 };
                    for _ in 0..n {
                        if let Some(ch) = self.eat() {
                            hex.push(ch);
                        }
                    }
                }
                Ok(u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).ok_or("invalid unicode escape")?)
            }
            'b' if in_class => Ok('\x08'),
            c if c.is_ascii_alphanumeric() && !in_class => {
                return Err(format!("unrecognized escape sequence"));
            }
            c => Ok(c),
        })
    }
    fn parse_class(&mut self) -> Result<Node, String> {
        let neg = if self.peek() == Some('^') {
            self.pos += 1;
            true
        } else {
            false
        };
        let mut items = vec![];
        let mut first = true;
        loop {
            let c = self.eat().ok_or("unclosed character class")?;
            if c == ']' && !first {
                break;
            }
            first = false;
            if c == '[' && self.peek() == Some(':') {
                // POSIX class
                let start = self.pos;
                let mut name = String::new();
                self.pos += 1;
                let mut negp = false;
                if self.peek() == Some('^') {
                    negp = true;
                    self.pos += 1;
                }
                while let Some(ch) = self.eat() {
                    if ch == ':' {
                        break;
                    }
                    name.push(ch);
                }
                if self.eat() == Some(']') {
                    let it = match name.as_str() {
                        "digit" => ClassItem::Digit(negp),
                        "alpha" => ClassItem::Prop("Alphabetic".into(), negp),
                        "alnum" => ClassItem::Prop("alnum".into(), negp),
                        "space" => ClassItem::Space(negp),
                        "upper" => ClassItem::Prop("Uppercase".into(), negp),
                        "lower" => ClassItem::Prop("Lowercase".into(), negp),
                        "word" => ClassItem::Word(negp),
                        "punct" => ClassItem::Prop("punct".into(), negp),
                        _ => ClassItem::Prop(name, negp),
                    };
                    items.push(it);
                    continue;
                } else {
                    self.pos = start;
                }
            }
            if c == '[' {
                // nested class: approximate by parsing as class and merging
                if let Node::Class(inner, n) = self.parse_class()? {
                    if !n {
                        items.extend(inner);
                    }
                }
                continue;
            }
            let lo = if c == '\\' {
                match self.parse_escape(true)? {
                    Ok(ch) => ch,
                    Err(item) => {
                        items.push(item);
                        continue;
                    }
                }
            } else {
                c
            };
            if self.peek() == Some('-') && self.chars.get(self.pos + 1).is_some_and(|c| *c != ']') {
                self.pos += 1;
                let hc = self.eat().ok_or("unclosed character class")?;
                let hi = if hc == '\\' {
                    match self.parse_escape(true)? {
                        Ok(ch) => ch,
                        Err(_) => return Err("invalid range".into()),
                    }
                } else {
                    hc
                };
                if hi < lo {
                    return Err("invalid character class range, the start must be <= the end".into());
                }
                items.push(ClassItem::Range(lo, hi));
            } else {
                items.push(ClassItem::Range(lo, lo));
            }
        }
        Ok(Node::Class(items, neg))
    }
    fn parse_atom(&mut self, flags: &mut Flags) -> Result<Node, String> {
        let c = self.eat().unwrap();
        Ok(match c {
            '.' => {
                if flags.s {
                    Node::Group(Box::new(Node::Any), Some(usize::MAX))
                } else {
                    Node::Any
                }
            }
            '^' => Node::Group(Box::new(Node::Start), if flags.m { Some(usize::MAX - 1) } else { None }),
            '$' => Node::Group(Box::new(Node::End), if flags.m { Some(usize::MAX - 1) } else { None }),
            '[' => {
                let cls = self.parse_class()?;
                if flags.i {
                    Node::Group(Box::new(cls), Some(usize::MAX - 2))
                } else {
                    cls
                }
            }
            '(' => {
                let mut cap = true;
                let mut name = None;
                let saved = *flags;
                if self.peek() == Some('?') {
                    self.pos += 1;
                    match self.peek() {
                        Some(':') => {
                            self.pos += 1;
                            cap = false;
                        }
                        Some('P') | Some('<') => {
                            if self.peek() == Some('P') {
                                self.pos += 1;
                            }
                            if self.eat() != Some('<') {
                                return Err("invalid group".into());
                            }
                            let mut n = String::new();
                            while let Some(ch) = self.eat() {
                                if ch == '>' {
                                    break;
                                }
                                n.push(ch);
                            }
                            name = Some(n);
                        }
                        _ => {
                            // flags
                            let mut on = true;
                            loop {
                                match self.eat() {
                                    Some('i') => flags.i = on,
                                    Some('m') => flags.m = on,
                                    Some('s') => flags.s = on,
                                    Some('x') => flags.x = on,
                                    Some('U') => {}
                                    Some('u') => {}
                                    Some('R') => {}
                                    Some('-') => on = false,
                                    Some(':') => {
                                        let inner = self.parse_alt(flags)?;
                                        *flags = saved;
                                        if self.eat() != Some(')') {
                                            return Err("unclosed group".into());
                                        }
                                        return Ok(Node::Group(Box::new(inner), None));
                                    }
                                    Some(')') => return Ok(Node::Empty),
                                    _ => return Err("unrecognized flag".into()),
                                }
                            }
                        }
                    }
                }
                let idx = if cap {
                    self.ncaps += 1;
                    self.names.push(name);
                    Some(self.ncaps)
                } else {
                    None
                };
                let inner = self.parse_alt(flags)?;
                *flags = saved;
                if self.eat() != Some(')') {
                    return Err("unclosed group".into());
                }
                Node::Group(Box::new(inner), idx)
            }
            '\\' => match self.peek() {
                Some('b') => {
                    self.pos += 1;
                    Node::WordB(true)
                }
                Some('B') => {
                    self.pos += 1;
                    Node::WordB(false)
                }
                Some('A') => {
                    self.pos += 1;
                    Node::Start
                }
                Some('z') => {
                    self.pos += 1;
                    Node::End
                }
                _ => match self.parse_escape(false)? {
                    Ok(ch) => ci_char(ch, flags.i),
                    Err(item) => Node::Class(vec![item], false),
                },
            },
            '*' | '+' | '?' => return Err("repetition operator missing expression".into()),
            ')' => return Err("unopened group".into()),
            c => ci_char(c, flags.i),
        })
    }
}

fn ci_char(c: char, i: bool) -> Node {
    if i && c.to_lowercase().ne(c.to_uppercase()) {
        let mut items = vec![];
        for x in c.to_lowercase().chain(c.to_uppercase()) {
            items.push(ClassItem::Range(x, x));
        }
        Node::Class(items, false)
    } else {
        Node::Char(c)
    }
}

fn class_match(items: &[ClassItem], neg: bool, c: char, ci: bool) -> bool {
    let test = |c: char| {
        items.iter().any(|it| match it {
            ClassItem::Range(a, b) => *a <= c && c <= *b,
            ClassItem::Digit(n) => c.is_numeric() != *n && (c.is_ascii_digit() || c.is_numeric()) != *n,
            ClassItem::Word(n) => is_word(c) != *n,
            ClassItem::Space(n) => c.is_whitespace() != *n,
            ClassItem::Prop(name, n) => {
                let r = match name.as_str() {
                    "L" | "Letter" | "Alphabetic" | "Alpha" => c.is_alphabetic(),
                    "Lu" | "Uppercase" | "Uppercase_Letter" => c.is_uppercase(),
                    "Ll" | "Lowercase" | "Lowercase_Letter" => c.is_lowercase(),
                    "N" | "Number" | "Nd" => c.is_numeric(),
                    "alnum" => c.is_alphanumeric(),
                    "P" | "Punctuation" | "punct" => c.is_ascii_punctuation() || (!c.is_alphanumeric() && !c.is_whitespace() && !c.is_control() && !c.is_ascii()),
                    "Z" | "Zs" | "White_Space" => c.is_whitespace(),
                    "Han" => crate::syntax::lexer::is_cjk_script(c),
                    "Latin" => c.is_ascii_alphabetic() || ('\u{C0}'..='\u{24F}').contains(&c),
                    "Greek" => ('\u{370}'..='\u{3FF}').contains(&c),
                    "Cyrillic" => ('\u{400}'..='\u{4FF}').contains(&c),
                    _ => false,
                };
                r != *n
            }
        })
    };
    let mut r = test(c);
    if !r && ci {
        r = c.to_lowercase().any(&test) || c.to_uppercase().any(&test);
    }
    r != neg
}

struct Compiler {
    prog: Vec<Inst>,
    classes: Vec<(Vec<ClassItem>, bool)>,
}

impl Compiler {
    fn emit(&mut self, i: Inst) -> usize {
        self.prog.push(i);
        self.prog.len() - 1
    }
    fn compile(&mut self, n: &Node, ci: bool, dotall: bool, multi: bool) {
        match n {
            Node::Empty => {}
            Node::Char(c) => {
                self.emit(Inst::Char(*c, ci));
            }
            Node::Any => {
                self.emit(Inst::Any(dotall));
            }
            Node::Class(items, neg) => {
                self.classes.push((items.clone(), *neg));
                let idx = self.classes.len() - 1;
                self.emit(Inst::Class(idx, ci));
            }
            Node::Start => {
                self.emit(Inst::Start(multi));
            }
            Node::End => {
                self.emit(Inst::End(multi));
            }
            Node::WordB(b) => {
                self.emit(Inst::WordB(*b));
            }
            Node::Group(inner, idx) => match idx {
                Some(i) if *i == usize::MAX => self.compile(inner, ci, true, multi),
                Some(i) if *i == usize::MAX - 1 => self.compile(inner, ci, dotall, true),
                Some(i) if *i == usize::MAX - 2 => self.compile(inner, true, dotall, multi),
                Some(i) => {
                    self.emit(Inst::Save(2 * i));
                    self.compile(inner, ci, dotall, multi);
                    self.emit(Inst::Save(2 * i + 1));
                }
                None => self.compile(inner, ci, dotall, multi),
            },
            Node::Concat(items) => {
                for it in items {
                    self.compile(it, ci, dotall, multi);
                }
            }
            Node::Alt(alts) => {
                let mut jumps = vec![];
                for (k, a) in alts.iter().enumerate() {
                    if k + 1 < alts.len() {
                        let split = self.emit(Inst::Split(0, 0));
                        self.compile(a, ci, dotall, multi);
                        jumps.push(self.emit(Inst::Jmp(0)));
                        let next = self.prog.len();
                        self.prog[split] = Inst::Split(split + 1, next);
                    } else {
                        self.compile(a, ci, dotall, multi);
                    }
                }
                let end = self.prog.len();
                for j in jumps {
                    self.prog[j] = Inst::Jmp(end);
                }
            }
            Node::Repeat(inner, min, max, greedy) => {
                for _ in 0..*min {
                    self.compile(inner, ci, dotall, multi);
                }
                match max {
                    None => {
                        let split = self.emit(Inst::Split(0, 0));
                        self.compile(inner, ci, dotall, multi);
                        self.emit(Inst::Jmp(split));
                        let next = self.prog.len();
                        self.prog[split] = if *greedy { Inst::Split(split + 1, next) } else { Inst::Split(next, split + 1) };
                    }
                    Some(m) => {
                        let mut splits = vec![];
                        for _ in *min..*m {
                            let split = self.emit(Inst::Split(0, 0));
                            splits.push(split);
                            self.compile(inner, ci, dotall, multi);
                        }
                        let end = self.prog.len();
                        for s in splits {
                            self.prog[s] = if *greedy { Inst::Split(s + 1, end) } else { Inst::Split(end, s + 1) };
                        }
                    }
                }
            }
        }
    }
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, String> {
        let mut p = Parser { chars: pattern.chars().collect(), pos: 0, ncaps: 0, names: vec![], _p: Default::default() };
        let mut flags = Flags::default();
        let node = p.parse_alt(&mut flags)?;
        if p.pos < p.chars.len() {
            return Err("unopened group".into());
        }
        let mut c = Compiler { prog: vec![], classes: vec![] };
        c.emit(Inst::Save(0));
        c.compile(&node, false, false, false);
        c.emit(Inst::Save(1));
        c.emit(Inst::Match);
        Ok(Regex { pattern: pattern.to_string(), prog: c.prog, classes: c.classes, ncaps: p.ncaps, names: p.names })
    }

    pub fn as_str(&self) -> &str {
        &self.pattern
    }

    fn exec_at(&self, text: &str, start: usize) -> Option<Vec<Option<usize>>> {
        let nslots = 2 * (self.ncaps + 1);
        let len = text.len();
        let plen = self.prog.len();
        let mut visited = vec![false; plen * (len + 1)];
        let mut slots: Vec<Option<usize>> = vec![None; nslots];
        // stack of (pc, pos) or restore slot
        enum Job {
            Run(usize, usize),
            Restore(usize, Option<usize>),
        }
        let mut stack = vec![Job::Run(0, start)];
        while let Some(job) = stack.pop() {
            match job {
                Job::Restore(slot, v) => slots[slot] = v,
                Job::Run(mut pc, mut pos) => loop {
                    let key = pc * (len + 1) + pos;
                    if visited[key] {
                        break;
                    }
                    visited[key] = true;
                    match &self.prog[pc] {
                        Inst::Match => return Some(slots),
                        Inst::Char(c, ci) => {
                            let Some(ch) = text[pos..].chars().next() else { break };
                            let ok = if *ci { ch == *c || ch.to_lowercase().eq(c.to_lowercase()) } else { ch == *c };
                            if !ok {
                                break;
                            }
                            pos += ch.len_utf8();
                            pc += 1;
                        }
                        Inst::Any(dotall) => {
                            let Some(ch) = text[pos..].chars().next() else { break };
                            if !dotall && ch == '\n' {
                                break;
                            }
                            pos += ch.len_utf8();
                            pc += 1;
                        }
                        Inst::Class(idx, ci) => {
                            let Some(ch) = text[pos..].chars().next() else { break };
                            let (items, neg) = &self.classes[*idx];
                            if !class_match(items, *neg, ch, *ci) {
                                break;
                            }
                            pos += ch.len_utf8();
                            pc += 1;
                        }
                        Inst::Split(a, b) => {
                            stack.push(Job::Run(*b, pos));
                            pc = *a;
                        }
                        Inst::Jmp(a) => pc = *a,
                        Inst::Save(s) => {
                            stack.push(Job::Restore(*s, slots[*s]));
                            slots[*s] = Some(pos);
                            pc += 1;
                        }
                        Inst::Start(multi) => {
                            if pos == 0 || (*multi && text[..pos].ends_with('\n')) {
                                pc += 1;
                            } else {
                                break;
                            }
                        }
                        Inst::End(multi) => {
                            if pos == len || (*multi && text[pos..].starts_with('\n')) {
                                pc += 1;
                            } else {
                                break;
                            }
                        }
                        Inst::WordB(want) => {
                            let before = text[..pos].chars().next_back().is_some_and(is_word);
                            let after = text[pos..].chars().next().is_some_and(is_word);
                            if (before != after) == *want {
                                pc += 1;
                            } else {
                                break;
                            }
                        }
                    }
                },
            }
        }
        None
    }

    /// Find the first match at or after `start`.
    pub fn find_at(&self, text: &str, start: usize) -> Option<(usize, usize, Vec<Option<(usize, usize)>>)> {
        let mut s = start;
        loop {
            if let Some(slots) = self.exec_at(text, s) {
                let st = slots[0].unwrap();
                let en = slots[1].unwrap();
                let caps = (1..=self.ncaps)
                    .map(|i| match (slots[2 * i], slots[2 * i + 1]) {
                        (Some(a), Some(b)) => Some((a, b)),
                        _ => None,
                    })
                    .collect();
                return Some((st, en, caps));
            }
            if s >= text.len() {
                return None;
            }
            s += text[s..].chars().next().unwrap().len_utf8();
        }
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.find_at(text, 0).is_some()
    }

    pub fn find_all(&self, text: &str) -> Vec<(usize, usize, Vec<Option<(usize, usize)>>)> {
        let mut out = vec![];
        let mut start = 0;
        let mut last_end: Option<usize> = None;
        while start <= text.len() {
            let Some(m) = self.find_at(text, start) else { break };
            if m.0 == m.1 && Some(m.1) == last_end {
                // skip empty match right after previous match
                if m.1 >= text.len() {
                    break;
                }
                start = m.1 + text[m.1..].chars().next().unwrap().len_utf8();
                continue;
            }
            let end = m.1;
            let empty = m.0 == m.1;
            out.push(m);
            last_end = Some(end);
            if empty {
                if end >= text.len() {
                    break;
                }
                start = end + text[end..].chars().next().unwrap().len_utf8();
            } else {
                start = end;
            }
        }
        out
    }
}
