//! A small backtracking regex engine (subset of Rust regex syntax).

#[derive(Debug, Clone)]
enum ClassItem {
    Range(char, char),
    Digit(bool),
    Word(bool),
    Space(bool),
    Prop(String, bool),
}

#[derive(Debug, Clone)]
enum Node {
    Empty,
    Char(char),
    Any,
    Class(Vec<ClassItem>, bool),
    Start,
    End,
    WordB(bool),
    Group(Box<Node>, Option<usize>),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat(Box<Node>, u32, Option<u32>, bool),
}

#[derive(Debug, Clone, Copy, Default)]
struct Flags {
    i: bool,
    m: bool,
    s: bool,
    x: bool,
}

#[derive(Debug, Clone)]
enum Inst {
    Char(char, bool),
    Any(bool),
    Class(usize, bool),
    Split(usize, usize),
    Jmp(usize),
    Save(usize),
    Start(bool),
    End(bool),
    WordB(bool),
    Match,
}

#[derive(Debug)]
pub struct Regex {
    pattern: String,
    prog: Vec<Inst>,
    classes: Vec<(Vec<ClassItem>, bool)>,
    pub ncaps: usize,
    pub names: Vec<Option<String>>,
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    ncaps: usize,
    names: Vec<Option<String>>,
    _p: std::marker::PhantomData<&'a ()>,
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn eat(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn skip_ws(&mut self, f: &Flags) {
        if f.x {
            loop {
                match self.peek() {
                    Some(c) if c.is_whitespace() => self.pos += 1,
                    Some('#') => {
                        while let Some(c) = self.eat() {
                            if c == '\n' {
                                break;
                            }
                        }
                    }
                    _ => break,
                }
            }
        }
    }
    fn parse_alt(&mut self, flags: &mut Flags) -> Result<Node, String> {
        let mut alts = vec![self.parse_concat(flags)?];
        while self.peek() == Some('|') {
            self.pos += 1;
            alts.push(self.parse_concat(flags)?);
        }
        Ok(if alts.len() == 1 { alts.pop().unwrap() } else { Node::Alt(alts) })
    }
    fn parse_concat(&mut self, flags: &mut Flags) -> Result<Node, String> {
        let mut items = vec![];
        loop {
            self.skip_ws(flags);
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            let atom = self.parse_atom(flags)?;
            self.skip_ws(flags);
            let atom = self.parse_quant(atom)?;
            items.push(atom);
        }
        Ok(if items.len() == 1 { items.pop().unwrap() } else { Node::Concat(items) })
    }
    fn parse_quant(&mut self, mut atom: Node) -> Result<Node, String> {
        loop {
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.pos += 1;
                    (0, None)
                }
                Some('+') => {
                    self.pos += 1;
                    (1, None)
                }
                Some('?') => {
                    self.pos += 1;
                    (0, Some(1))
                }
                Some('{') => {
                    let save = self.pos;
                    self.pos += 1;
                    let mut a = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            a.push(c);
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    if a.is_empty() {
                        self.pos = save;
                        return Err("repetition quantifier expects a valid decimal".into());
                    }
                    let min: u32 = a.parse().map_err(|_| "invalid repetition")?;
                    let max = if self.peek() == Some(',') {
                        self.pos += 1;
                        let mut b = String::new();
                        while let Some(c) = self.peek() {
                            if c.is_ascii_digit() {
                                b.push(c);
                                self.pos += 1;
                            } else {
                                break;
                            }
                        }
                        if b.is_empty() { None } else { Some(b.parse().map_err(|_| "invalid repetition")?) }
                    } else {
                        Some(min)
                    };
                    if self.eat() != Some('}') {
                        return Err("unclosed counted repetition".into());
                    }
                    (min, max)
                }
                _ => return Ok(atom),
            };
            let greedy = if self.peek() == Some('?') {
                self.pos += 1;
                false
            } else {
                true
            };
            if matches!(atom, Node::Start | Node::End | Node::Empty) && false {
                return Err("repetition operator missing expression".into());
            }
            atom = Node::Repeat(Box::new(atom), min, max, greedy);
        }
    }
    fn parse_escape(&mut self, in_class: bool) -> Result<Result<char, ClassItem>, String> {
        let c = self.eat().ok_or("incomplete escape sequence")?;
        Ok(match c {
            'd' => Err(ClassItem::Digit(false)),
            'D' => Err(ClassItem::Digit(true)),
            'w' => Err(ClassItem::Word(false)),
            'W' => Err(ClassItem::Word(true)),
            's' => Err(ClassItem::Space(false)),
            'S' => Err(ClassItem::Space(true)),
            'p' | 'P' => {
                let neg = c == 'P';
                let name = if self.peek() == Some('{') {
                    self.pos += 1;
                    let mut n = String::new();
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        n.push(ch);
                    }
                    n
                } else {
                    self.eat().map(|c| c.to_string()).unwrap_or_default()
                };
                Err(ClassItem::Prop(name, neg))
            }
            'n' => Ok('\n'),
            't' => Ok('\t'),
            'r' => Ok('\r'),
            'f' => Ok('\x0c'),
            'v' => Ok('\x0b'),
            '0' => Ok('\0'),
            'x' => {
                let mut hex = String::new();
                if self.peek() == Some('{') {
                    self.pos += 1;
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        hex.push(ch);
                    }
                } else {
                    for _ in 0..2 {
                        if let Some(ch) = self.eat() {
                            hex.push(ch);
                        }
                    }
                }
                Ok(u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).ok_or("invalid hex escape")?)
            }
            'u' | 'U' => {
                let mut hex = String::new();
                if self.peek() == Some('{') {
                    self.pos += 1;
                    while let Some(ch) = self.eat() {
                        if ch == '}' {
                            break;
                        }
                        hex.push(ch);
                    }
                } else {
                    let n = if c == 'u' { 4 } else { 8 };
                    for _ in 0..n {
                        if let Some(ch) = self.eat() {
                            hex.push(ch);
                        }
                    }
                }
                Ok(u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).ok_or("invalid unicode escape")?)
            }
            'b' if in_class => Ok('\x08'),
            c if c.is_ascii_alphanumeric() && !in_class => {
                return Err(format!("unrecognized escape sequence"));
            }
            c => Ok(c),
        })
    }
    fn parse_class(&mut self) -> Result<Node, String> {
        let neg = if self.peek() == Some('^') {
            self.pos += 1;
            true
        } else {
            false
        };
        let mut items = vec![];
        let mut first = true;
        loop {
            let c = self.eat().ok_or("unclosed character class")?;
            if c == ']' && !first {
                break;
            }
            first = false;
            if c == '[' && self.peek() == Some(':') {
                // POSIX class
                let start = self.pos;
                let mut name = String::new();
                self.pos += 1;
                let mut negp = false;
                if self.peek() == Some('^') {
                    negp = true;
                    self.pos += 1;
                }
                while let Some(ch) = self.eat() {
                    if ch == ':' {
                        break;
                    }
                    name.push(ch);
                }
                if self.eat() == Some(']') {
                    let it = match name.as_str() {
                        "digit" => ClassItem::Digit(negp),
                        "alpha" => ClassItem::Prop("Alphabetic".into(), negp),
                        "alnum" => ClassItem::Prop("alnum".into(), negp),
                        "space" => ClassItem::Space(negp),
                        "upper" => ClassItem::Prop("Uppercase".into(), negp),
                        "lower" => ClassItem::Prop("Lowercase".into(), negp),
                        "word" => ClassItem::Word(negp),
                        "punct" => ClassItem::Prop("punct".into(), negp),
                        _ => ClassItem::Prop(name, negp),
                    };
                    items.push(it);
                    continue;
                } else {
                    self.pos = start;
                }
            }
            if c == '[' {
                // nested class: approximate by parsing as class and merging
                if let Node::Class(inner, n) = self.parse_class()? {
