pub fn matches_selector(c: &Content, sel: &Selector) -> bool {
    match sel {
        Selector::Elem(e, fields) => {
            if !std::ptr::eq(c.elem(), *e) && c.elem().name != e.name {
                return false;
            }
            if let Some(fields) = fields {
                for (k, v) in fields {
                    match c.get(k) {
                        Some(x) if crate::ops::equal(x, v) => {}
                        _ => return false,
                    }
                }
            }
            true
        }
        Selector::Label(l) => c.label().is_some_and(|x| x == l),
        Selector::Location(l) => c.location() == Some(*l),
        Selector::Or(list) => list.iter().any(|s| matches_selector(c, s)),
        Selector::And(list) => list.iter().all(|s| matches_selector(c, s)),
        Selector::Text(t) => c.is("text") && c.get_str("text").is_some_and(|x| x.contains(&**t)),
        Selector::Regex(r) => c.is("text") && c.get_str("text").is_some_and(|x| r.is_match(&x)),
        Selector::Before { selector, .. } | Selector::After { selector, .. } => matches_selector(c, selector),
        Selector::Within { selector, .. } => matches_selector(c, selector),
        Selector::Can(_) => false,
        Selector::Func(_) => false,
    }
}

pub fn repr_selector(s: &Selector) -> String {
    match s {
        Selector::Elem(e, None) => e.name.to_string(),
        Selector::Elem(e, Some(fields)) => {
            let parts: Vec<String> = fields.iter().map(|(k, v)| format!("{}: {}", k, repr(v))).collect();
            format!("{}.where{}", e.name, crate::repr::pretty_array_like(&parts, false))
        }
        Selector::Label(l) => crate::repr::repr_label(l),
        Selector::Regex(r) => format!("regex({})", repr_str(r.as_str())),
        Selector::Text(t) => repr_str(t),
        Selector::Location(_) => "location(..)".into(),
        Selector::Can(c) => format!("can({c})"),
        Selector::Or(list) => {
            let parts: Vec<String> = list.iter().map(repr_selector).collect();
            format!("selector.or{}", crate::repr::pretty_array_like(&parts, false))
        }
        Selector::And(list) => {
            let parts: Vec<String> = list.iter().map(repr_selector).collect();
            format!("selector.and{}", crate::repr::pretty_array_like(&parts, false))
        }
        Selector::Before { selector, end, inclusive } => {
            let inc = if *inclusive { String::new() } else { ", inclusive: false".into() };
            format!("{}.before({}{})", repr_selector(selector), repr_selector(end), inc)
        }
        Selector::After { selector, start, inclusive } => {
            let inc = if *inclusive { String::new() } else { ", inclusive: false".into() };
            format!("{}.after({}{})", repr_selector(selector), repr_selector(start), inc)
        }
        Selector::Within { selector, ancestor } => format!("{}.within({})", repr_selector(selector), repr_selector(ancestor)),
        Selector::Func(f) => f.repr(),
    }
}

pub fn repr_counter(c: &Counter) -> String {
    match &c.0 {
        CounterKey::Page => "counter(page)".into(),
        CounterKey::Str(s) => format!("counter({})", repr_str(s)),
        CounterKey::Selector(s) => format!("counter({})", repr_selector(s)),
    }
}

pub fn is_locatable(e: &el::Elem) -> bool {
    matches!(
        e.name,
        "heading" | "figure" | "equation" | "footnote" | "metadata" | "cite" | "ref" | "bibliography" | "outline"
            | "counter-update" | "state-update" | "page" | "caption" | "link" | "title" | "quote" | "table" | "image"
            | "list" | "enum" | "terms" | "par" | "raw" | "context" | "document"
    )
}

pub fn to_selector(v: Value) -> StrResult<Selector> {
    Ok(match v {
        Value::Selector(s) => (*s).clone(),
        Value::Label(l) => Selector::Label(l),
        Value::Location(l) => Selector::Location(l),
        Value::Regex(r) => Selector::Regex(r),
        Value::Str(s) => {
            let escaped: String = s
                .chars()
                .flat_map(|c| {
                    if "\\.+*?()|[]{}^$#&-~".contains(c) {
                        vec!['\\', c]
                    } else {
                        vec![c]
                    }
                })
                .collect();
            Selector::Regex(Rc::new(crate::regex::Regex::new(&escaped).map_err(HintedString::new)?))
        }
        Value::Func(f) => match &f.kind {
            FuncKind::Element(e) => Selector::Elem(e, None),
            _ => return Err("only element functions can be used as selectors".into()),
        },
        Value::Type(t) => return Err(format!("expected element function, found type {}", t.long_name()).into()),
        v => {
            return Err(format!(
                "expected string, function, label, regex, location, or selector, found {}",
                v.type_name()
            )
            .into())
        }
    })
}

pub fn construct_selector(args: &mut Args) -> SourceResult<Value> {
    let a = match args.eat_raw() {
        Some(a) => a,
        None => return Err(args.missing_argument("target")),
    };
    args.finish()?;
    Ok(Value::Selector(Rc::new(to_selector(a.value).at(a.value_span)?)))
}

pub fn selector_method(v: Value, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let this = to_selector(v).at(span)?;
    match name {
        "or" | "and" => {
            let others = args.all_strict(&ANY)?;
            args.finish()?;
            let mut list = vec![];
            for o in others {
                list.push(to_selector(o).at(span)?);
            }
            list.push(this);
            Ok(Value::Selector(Rc::new(if name == "or" { Selector::Or(list) } else { Selector::And(list) })))
        }
        "before" | "after" => {
            let other = args.expect_any(if name == "before" { "end" } else { "start" })?;
            let inclusive = args.named("inclusive", &BOOL)?;
            args.finish()?;
            let other = to_selector(other).at(span)?;
            let inclusive = !matches!(inclusive, Some(Value::Bool(false)));
            Ok(Value::Selector(Rc::new(if name == "before" {
                Selector::Before { selector: Box::new(this), end: Box::new(other), inclusive }
            } else {
                Selector::After { selector: Box::new(this), start: Box::new(other), inclusive }
            })))
        }
        _ => bail!(span, "type selector has no method `{}`", name),
    }
}

pub fn construct_counter(args: &mut Args) -> SourceResult<Value> {
    let a = match args.eat_raw() {
        Some(a) => a,
        None => return Err(args.missing_argument("key")),
    };
    args.finish()?;
    let key = match a.value {
        Value::Str(s) => CounterKey::Str(s),
        Value::Func(f) if matches!(&f.kind, FuncKind::Element(e) if e.name == "page") => CounterKey::Page,
        Value::Func(f) => match &f.kind {
            FuncKind::Element(e) => {
                if !is_locatable(e) {
                    bail!(a.value_span, "{} is not locatable", e.name);
                }
                CounterKey::Selector(Selector::Elem(e, None))
            }
            _ => bail!(a.value_span, "expected string, label, function, location, or selector, found function"),
        },
        Value::Label(l) => CounterKey::Selector(Selector::Label(l)),
        Value::Location(l) => CounterKey::Selector(Selector::Location(l)),
        Value::Selector(s) => CounterKey::Selector((*s).clone()),
        v => bail!(a.value_span, "expected string, label, function, location, or selector, found {}", v.type_name()),
    };
