}

pub fn construct_state(args: &mut Args) -> SourceResult<Value> {
    let key = args.expect("key", &STR)?;
    let init = args.eat_any().unwrap_or(Value::None);
    args.finish()?;
    Ok(Value::State(Rc::new(State { key: key.as_str().map(Rc::from).unwrap(), init })))
}

fn counter_key_value(c: &Counter) -> Value {
    match &c.0 {
        CounterKey::Page => Value::Func(crate::func::Func::element(&el::PAGE)),
        CounterKey::Str(s) => Value::Str(s.clone()),
        CounterKey::Selector(s) => Value::Selector(Rc::new(s.clone())),
    }
}

pub fn counter_method(engine: &mut Engine, c: &Counter, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "step" => {
            let level = args.named("level", &POSINT)?;
            args.finish()?;
            let mut u = Dict::new();
            u.insert(Rc::from("step"), level.unwrap_or(Value::Int(1)));
            Ok(Value::Content(
                Content::new(&el::COUNTER_UPDATE).with("key", Value::str(key_str(c))).with("update", Value::dict(u)),
            ))
        }
        "update" => {
            let v = args.expect("update", &ANY)?;
            args.finish()?;
            let _ = v;
            Ok(Value::Content(Content::new(&el::COUNTER_UPDATE).with("key", Value::str(key_str(c)))))
        }
        "display" => {
            let _ = args.take();
            if engine.context.location.is_none() {
                let d = Diag::error(span, "can only be used when context is known")
                    .with_hint("try wrapping this in a `context` expression")
                    .with_hint("the `context` expression should wrap everything that depends on this function");
                return Err(vec![d]);
            }
            Ok(Value::Content(Content::text("1")))
        }
        "get" | "at" => {
            let _ = args.take();
            let vals = crate::realize::counter_value_at(engine, c, engine.context.location);
            Ok(Value::array(vals.into_iter().map(|x| Value::Int(x as i64)).collect()))
        }
        "final" => {
            args.finish()?;
            let vals = crate::realize::counter_value_at(engine, c, None);
            Ok(Value::array(vals.into_iter().map(|x| Value::Int(x as i64)).collect()))
        }
        _ => {
            let _ = counter_key_value(c);
            bail!(span, "type counter has no method `{}`", name)
        }
    }
}

fn key_str(c: &Counter) -> String {
