            Ok(Value::dict(d))
        }
        "page-numbering" => Ok(Value::None),
        _ => bail!(span, "type location has no method `{}`", name),
    }
}

pub fn query(engine: &mut Engine, args: &mut Args) -> SourceResult<Value> {
    let a = match args.eat_raw() {
        Some(a) => a,
        None => return Err(args.missing_argument("target")),
    };
    args.finish()?;
    let sel = to_selector(a.value).at(a.value_span)?;
    let r = resolve_query(engine, &sel);
    Ok(Value::array(r.into_iter().map(Value::Content).collect()))
}

pub fn resolve_query(engine: &Engine, sel: &Selector) -> Vec<Content> {
    match sel {
        Selector::Before { selector, end, inclusive } => {
            let all = engine.introspector.query(selector);
            let ends = engine.introspector.query(end);
            let Some(first_end) = ends.first() else { return all };
            let end_pos = first_end.location().and_then(|l| engine.introspector.position(l)).unwrap_or(usize::MAX);
            all.into_iter()
                .filter(|c| {
                    let p = c.location().and_then(|l| engine.introspector.position(l)).unwrap_or(0);
                    p < end_pos || (*inclusive && p == end_pos)
                })
                .collect()
        }
        Selector::After { selector, start, inclusive } => {
            let all = engine.introspector.query(selector);
            let starts = engine.introspector.query(start);
            let Some(first) = starts.first() else { return all };
            let sp = first.location().and_then(|l| engine.introspector.position(l)).unwrap_or(0);
            all.into_iter()
                .filter(|c| {
                    let p = c.location().and_then(|l| engine.introspector.position(l)).unwrap_or(0);
                    p > sp || (*inclusive && p == sp)
                })
                .collect()
        }
        _ => engine.introspector.query(sel),
    }
}

pub fn locate(engine: &mut Engine, args: &mut Args) -> SourceResult<Value> {
    let a = match args.eat_raw() {
        Some(a) => a,
        None => return Err(args.missing_argument("selector")),
    };
    args.finish()?;
    let sel = to_selector(a.value).at(a.value_span)?;
    let r = resolve_query(engine, &sel);
    match r.first() {
        Some(c) if r.len() == 1 => Ok(c.location().map(Value::Location).unwrap_or(Value::None)),
        Some(_) => bail!(a.value_span, "selector matches multiple elements"),
        None => match &sel {
            Selector::Label(l) => bail!(a.value_span, "label `{}` does not exist in the document", crate::repr::repr_label(l)),
            _ => bail!(a.value_span, "selector does not match any element"),
        },
    }
}
