use crate::repr::{repr, repr_str};
use crate::value::*;
use std::rc::Rc;

#[derive(Debug, Default)]
pub struct Introspector {
    /// All locatable elements in document order, with their page.
    pub elems: Vec<(Content, usize)>,
    pub pages: usize,
}

impl Introspector {
    pub fn empty() -> Self {
        Introspector { elems: vec![], pages: 1 }
    }
    pub fn query(&self, sel: &Selector) -> Vec<Content> {
        self.elems.iter().filter(|(c, _)| matches_selector(c, sel)).map(|(c, _)| c.clone()).collect()
    }
    pub fn position(&self, loc: Location) -> Option<usize> {
        self.elems.iter().position(|(c, _)| c.location() == Some(loc))
    }
    pub fn page_of(&self, loc: Location) -> usize {
        self.elems.iter().find(|(c, _)| c.location() == Some(loc)).map(|x| x.1).unwrap_or(1)
    }
}

pub fn matches_selector(c: &Content, sel: &Selector) -> bool {
    match sel {
        Selector::Elem(e, fields) => {
            if !std::ptr::eq(c.elem(), *e) && c.elem().name != e.name {
                return false;
            }
            if let Some(fields) = fields {
                for (k, v) in fields {
                    match c.get(k) {
                        Some(x) if crate::ops::equal(x, v) => {}
                        _ => return false,
                    }
                }
            }
            true
        }
        Selector::Label(l) => c.label().is_some_and(|x| x == l),
        Selector::Location(l) => c.location() == Some(*l),
        Selector::Or(list) => list.iter().any(|s| matches_selector(c, s)),
        Selector::And(list) => list.iter().all(|s| matches_selector(c, s)),
        Selector::Text(t) => c.is("text") && c.get_str("text").is_some_and(|x| x.contains(&**t)),
        Selector::Regex(r) => c.is("text") && c.get_str("text").is_some_and(|x| r.is_match(&x)),
        Selector::Before { selector, .. } | Selector::After { selector, .. } => matches_selector(c, selector),
        Selector::Within { selector, .. } => matches_selector(c, selector),
        Selector::Can(_) => false,
        Selector::Func(_) => false,
    }
}

pub fn repr_selector(s: &Selector) -> String {
    match s {
        Selector::Elem(e, None) => e.name.to_string(),
        Selector::Elem(e, Some(fields)) => {
            let parts: Vec<String> = fields.iter().map(|(k, v)| format!("{}: {}", k, repr(v))).collect();
            format!("{}.where{}", e.name, crate::repr::pretty_array_like(&parts, false))
        }
        Selector::Label(l) => crate::repr::repr_label(l),
        Selector::Regex(r) => format!("regex({})", repr_str(r.as_str())),
        Selector::Text(t) => repr_str(t),
        Selector::Location(_) => "location(..)".into(),
        Selector::Can(c) => format!("can({c})"),
        Selector::Or(list) => {
            let parts: Vec<String> = list.iter().map(repr_selector).collect();
            format!("selector.or{}", crate::repr::pretty_array_like(&parts, false))
        }
        Selector::And(list) => {
            let parts: Vec<String> = list.iter().map(repr_selector).collect();
            format!("selector.and{}", crate::repr::pretty_array_like(&parts, false))
        }
        Selector::Before { selector, end, inclusive } => {
            let inc = if *inclusive { String::new() } else { ", inclusive: false".into() };
            format!("{}.before({}{})", repr_selector(selector), repr_selector(end), inc)
        }
        Selector::After { selector, start, inclusive } => {
            let inc = if *inclusive { String::new() } else { ", inclusive: false".into() };
            format!("{}.after({}{})", repr_selector(selector), repr_selector(start), inc)
        }
        Selector::Within { selector, ancestor } => format!("{}.within({})", repr_selector(selector), repr_selector(ancestor)),
        Selector::Func(f) => f.repr(),
    }
}

pub fn repr_counter(c: &Counter) -> String {
    match &c.0 {
        CounterKey::Page => "counter(page)".into(),
        CounterKey::Str(s) => format!("counter({})", repr_str(s)),
        CounterKey::Selector(s) => format!("counter({})", repr_selector(s)),
    }
}

pub fn is_locatable(e: &el::Elem) -> bool {
    matches!(
