        "heading" | "figure" | "equation" | "footnote" | "metadata" | "cite" | "ref" | "bibliography" | "outline"
            | "counter-update" | "state-update" | "page" | "caption" | "link" | "title" | "quote" | "table" | "image"
            | "list" | "enum" | "terms" | "par" | "raw" | "context" | "document"
    )
}

pub fn to_selector(v: Value) -> StrResult<Selector> {
    Ok(match v {
        Value::Selector(s) => (*s).clone(),
        Value::Label(l) => Selector::Label(l),
        Value::Location(l) => Selector::Location(l),
        Value::Regex(r) => Selector::Regex(r),
        Value::Str(s) => {
            let escaped: String = s
                .chars()
                .flat_map(|c| {
                    if "\\.+*?()|[]{}^$#&-~".contains(c) {
                        vec!['\\', c]
                    } else {
                        vec![c]
                    }
                })
                .collect();
            Selector::Regex(Rc::new(crate::regex::Regex::new(&escaped).map_err(HintedString::new)?))
        }
        Value::Func(f) => match &f.kind {
            FuncKind::Element(e) => Selector::Elem(e, None),
            _ => return Err("only element functions can be used as selectors".into()),
        },
        Value::Type(t) => return Err(format!("expected element function, found type {}", t.long_name()).into()),
        v => {
            return Err(format!(
                "expected string, function, label, regex, location, or selector, found {}",
                v.type_name()
            )
            .into())
        }
    })
}

pub fn construct_selector(args: &mut Args) -> SourceResult<Value> {
