//! Element construction.

use crate::cast::*;
use crate::content::{Content, Style, Styles};
use crate::diag::*;
use crate::elements::{self as el, Elem, FK};
use crate::eval::Engine;
use crate::func::Args;
use crate::value::*;

pub fn construct(engine: &mut Engine, elem: &'static Elem, args: &mut Args) -> SourceResult<Content> {
    let span = args.span;
    let c = match elem.name {
        "text" if std::ptr::eq(elem, &el::TEXT) => return construct_text(engine, args),
        "page" if std::ptr::eq(elem, &el::PAGE) => return construct_page(engine, args),
        "document" => bail!(span, "can only be used in set rules"),
        "pad" => {
            let mut c = Content::new(elem);
            let all = args.find(&REL)?.or(args.named("rest", &REL)?);
            let x = args.named("x", &REL)?.or(all.clone());
            let y = args.named("y", &REL)?.or(all.clone());
            let left = args.named("left", &REL)?.or(x.clone());
            let top = args.named("top", &REL)?.or(y.clone());
            let right = args.named("right", &REL)?.or(x);
            let bottom = args.named("bottom", &REL)?.or(y);
            for (n, v) in [("left", left), ("top", top), ("right", right), ("bottom", bottom)] {
                if let Some(v) = v {
                    c.set(n, v);
                }
            }
            let body = args.expect("body", &CONTENT)?;
            c.set("body", body);
            c
        }
        "block" => {
            let spacing = args.named("spacing", &ANY)?;
            let mut c = generic(engine, elem, args)?;
            if let Some(s) = spacing {
                if !c.has("above") {
                    c.set("above", s.clone());
                }
                if !c.has("below") {
                    c.set("below", s);
                }
            }
            return Ok(c.spanned(span));
        }
        "circle" => {
            let radius = args.named("radius", &Cast::Length)?;
            let mut c = generic(engine, elem, args)?;
            if let Some(Value::Length(r)) = radius {
                let v = Value::Relative(Rel { rel: 0.0, abs: Length { abs: r.abs * 2.0, em: r.em * 2.0 } });
                c.set("width", v.clone());
                c.set("height", v);
            }
            return Ok(c.spanned(span));
        }
        "square" => {
            let size = args.named("size", &Cast::Smart(&Cast::Length))?;
            let mut c = generic(engine, elem, args)?;
            if let Some(v) = size {
                let v = match v {
                    Value::Length(l) => Value::Relative(Rel { rel: 0.0, abs: l }),
                    v => v,
                };
                c.set("width", v.clone());
                c.set("height", v);
            }
            return Ok(c.spanned(span));
        }
        "scale" => {
            let factor = args.find(&Cast::Smart(&Cast::Or(&[Cast::Ratio, Cast::Length])))?;
            let mut c = generic(engine, elem, args)?;
            if let Some(f) = factor {
                if !c.has("x") {
                    c.set("x", f.clone());
                }
                if !c.has("y") {
                    c.set("y", f);
                }
            }
            return Ok(c.spanned(span));
        }
        "link" => {
            let dest = args.expect("dest", &Cast::Custom {
                parts: &["string", "dictionary", "location", "label"],
                check: |v| matches!(v, Value::Str(_) | Value::Dict(_) | Value::Location(_) | Value::Label(_)),
                conv: |v| Ok(v),
            })?;
            let body = match &dest {
                Value::Str(s) => match args.eat(&CONTENT)? {
                    Some(b) => b,
                    None => Value::Content(Content::text(crate::model::link_body_text(s))),
                },
                _ => args.expect("body", &CONTENT)?,
            };
            args.finish()?;
            return Ok(Content::new(elem).with("dest", dest).with("body", body).spanned(span));
        }
        "image" => {
            let src = args.expect("source", &Cast::Custom {
                parts: &["path", "string", "bytes"],
                check: |v| matches!(v, Value::Str(_) | Value::Bytes(_)),
                conv: |v| Ok(v),
            })?;
            if let Value::Str(path) = &src {
                crate::data::check_file_access(engine, path, span)?;
            }
            let mut c = Content::new(elem).with("source", src);
            for f in elem.fields.iter().skip(1) {
                if let Some(v) = args.named(f.name, f.cast)? {
                    c.set(f.name, v);
                }
            }
            args.finish()?;
            return Ok(c.spanned(span));
        }
        _ => generic(engine, elem, args)?,
    };
    args.finish()?;
    Ok(c.spanned(span))
}

pub fn generic(engine: &mut Engine, elem: &'static Elem, args: &mut Args) -> SourceResult<Content> {
    let _ = engine;
    let mut c = Content::new(elem);
    for f in elem.fields {
        match f.kind {
            FK::R => {
                let v = args.expect(f.name, f.cast)?;
                c.set(f.name, v);
            }
            FK::P => {
                if let Some(v) = args.find(f.cast)? {
                    c.set(f.name, v);
                }
            }
            FK::N => {
                if let Some(v) = args.named(f.name, f.cast)? {
                    c.set(f.name, v);
                }
            }
            FK::NF => {
                if let Some(v) = args.named(f.name, f.cast)? {
                    c.set(f.name, v);
                } else if let Some(v) = args.find(f.cast)? {
                    c.set(f.name, v);
                }
            }
            FK::V => {
                let mut vals = vec![];
                let mut errors = vec![];
                let items = std::mem::take(&mut args.items);
                let mut rest = vec![];
                for a in items {
                    if a.name.is_some() {
                        rest.push(a);
                        continue;
                    }
                    match f.cast.cast(a.value) {
                        Ok(v) => vals.push(v),
                        Err(e) => {
                            let mut d = Diag::error(a.value_span, e.message);
                            d.hints = e.hints;
                            errors.push(d);
                        }
                    }
                }
                args.items = rest;
                if !errors.is_empty() {
                    return Err(errors);
                }
                // deprecation warnings for array conversions
                c.set(f.name, Value::array(vals));
            }
            FK::S | FK::I => {}
        }
    }
    // Deprecation warnings
    if matches!(elem.name, "enum" | "terms") && std::ptr::eq(elem, &el::ENUM) || std::ptr::eq(elem, &el::TERMS) {
        // handled in cast functions via marker
    }
    Ok(c)
}

fn construct_text(engine: &mut Engine, args: &mut Args) -> SourceResult<Content> {
    let styles = text_styles(engine, args)?;
    let body = args.expect("body", &CONTENT)?;
    args.finish()?;
    let Value::Content(body) = body else { unreachable!() };
    if styles.is_empty() {
        Ok(body)
    } else {
        Ok(body.styled(styles))
    }
}

pub fn text_styles(engine: &mut Engine, args: &mut Args) -> SourceResult<Styles> {
    let mut styles = vec![];
    for f in el::TEXT.fields {
        if f.name == "text" {
            continue;
        }
        let span = args.named_span(f.name).unwrap_or(args.span);
        let v = match f.kind {
            FK::NF => match args.named(f.name, f.cast)? {
                Some(v) => Some(v),
                None => args.find(f.cast)?,
            },
            _ => args.named(f.name, f.cast)?,
        };
        if let Some(v) = v {
            if f.name == "font" {
                crate::text::check_font_warning(engine, &v, span);
            }
            styles.push(Style::Property { elem: &el::TEXT, field: f.name, value: v, span });
        }
    }
    Ok(Styles::from(styles))
}

fn construct_page(engine: &mut Engine, args: &mut Args) -> SourceResult<Content> {
    let mut styles = vec![];
    for f in el::PAGE.fields {
        if f.name == "body" {
            continue;
        }
        if let Some(v) = args.named(f.name, f.cast)? {
            styles.push(Style::Property { elem: &el::PAGE, field: f.name, value: v, span: args.span });
        }
    }
    let body = args.expect("body", &CONTENT)?;
    args.finish()?;
    let _ = engine;
    let Value::Content(body) = body else { unreachable!() };
    let seq = Content::sequence(vec![
        Content::new(&el::PAGEBREAK).with("weak", true),
        Content::new(&el::FLUSH),
        body,
        Content::new(&el::PAGEBREAK).with("weak", true),
    ]);
    Ok(seq.styled(Styles::from(styles)))
}
