//! Type constructors.

use crate::cast::*;
use crate::diag::*;
use crate::eval::Engine;
use crate::func::Args;
use crate::value::*;
use std::rc::Rc;

pub fn construct_type(engine: &mut Engine, t: Type, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match t {
        Type::Int => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            let base = args.named("base", &INT)?;
            args.finish()?;
            let vs = a.value_span;
            Ok(Value::Int(match a.value {
                Value::Int(i) => i,
                Value::Bool(b) => b as i64,
                Value::Float(f) => {
                    if f.is_nan() || f.abs() >= 9.223372036854776e18 {
                        bail!(vs, "number too large");
                    }
                    f.trunc() as i64
                }
                Value::Decimal(d) => match crate::decimal::to_int(&d) {
                    Some(i) => i,
                    None => bail!(vs, "number too large"),
                },
                Value::Str(s) => {
                    let base = match base {
                        Some(Value::Int(b)) => b as u32,
                        _ => 10,
                    };
                    let st = s.replace('\u{2212}', "-");
                    match i64::from_str_radix(&st, base) {
                        Ok(i) => i,
                        Err(e) => {
                            let msg = match e.kind() {
                                std::num::IntErrorKind::PosOverflow | std::num::IntErrorKind::NegOverflow => "number too large",
                                std::num::IntErrorKind::Empty => "string must not be empty",
                                _ => "string contains invalid digits",
                            };
                            bail!(vs, "{}", msg)
                        }
                    }
                }
                v => bail!(vs, "expected integer, boolean, float, decimal, or string, found {}", v.type_name()),
            }))
        }
        Type::Float => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            args.finish()?;
            let vs = a.value_span;
            Ok(Value::Float(match a.value {
                Value::Int(i) => i as f64,
                Value::Float(f) => f,
                Value::Bool(b) => b as i64 as f64,
                Value::Ratio(r) => r,
                Value::Decimal(d) => crate::decimal::to_f64(&d),
                Value::Str(s) => {
                    let st = s.replace('\u{2212}', "-");
                    match st.parse::<f64>() {
                        Ok(f) if !st.trim().is_empty() && st.trim() == st => f,
                        _ => bail!(vs, "invalid float: {}", s),
                    }
                }
                v => bail!(vs, "expected integer, float, decimal, ratio, boolean, or string, found {}", v.type_name()),
            }))
        }
        Type::Str => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            let base = args.named("base", &INT)?;
            args.finish()?;
            let vs = a.value_span;
            if let Some(Value::Int(b)) = base {
                match a.value {
                    Value::Int(i) => {
                        if !(2..=36).contains(&b) {
                            bail!(vs, "base must be between 2 and 36");
                        }
                        return Ok(Value::str(format_int_base(i, b as u32)));
                    }
                    _ => bail!(vs, "base is only supported for integers"),
                }
            }
            match a.value {
                Value::Bytes(b) => match String::from_utf8((*b).clone()) {
                    Ok(s) => Ok(Value::str(s)),
                    Err(_) => bail!(vs, "bytes are not valid UTF-8"),
                },
                v => match crate::repr::display_for_str(&v) {
                    Some(s) => Ok(Value::str(s)),
                    None => bail!(
                        vs,
                        "expected integer, float, decimal, version, bytes, label, type, or string, found {}",
                        v.type_name()
                    ),
                },
            }
        }
        Type::Array => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            args.finish()?;
            match a.value {
                Value::Array(_) => Ok(a.value),
                Value::Bytes(b) => Ok(Value::array(b.iter().map(|x| Value::Int(*x as i64)).collect())),
                Value::Version(v) => Ok(Value::array(v.0.iter().map(|x| Value::Int(*x as i64)).collect())),
                v => bail!(a.value_span, "expected array, bytes, or version, found {}", v.type_name()),
            }
        }
        Type::Dict => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            args.finish()?;
            match a.value {
                Value::Module(m) => {
                    let mut d = Dict::new();
                    for (k, v) in m.scope.iter() {
                        d.insert(k.clone(), v.clone());
                    }
                    Ok(Value::dict(d))
                }
                v => bail!(a.value_span, "expected module, found {}", v.type_name()),
            }
        }
        Type::Bytes => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            args.finish()?;
            match a.value {
                Value::Str(s) => Ok(Value::Bytes(Rc::new(s.as_bytes().to_vec()))),
                Value::Bytes(_) => Ok(a.value),
                Value::Array(arr) => {
                    let mut out = vec![];
                    for x in arr.iter() {
                        match x {
                            Value::Int(i) if (0..=255).contains(i) => out.push(*i as u8),
                            Value::Int(_) => bail!(a.value_span, "number must be between 0 and 255"),
                            v => bail!(a.value_span, "expected integer, found {}", v.type_name()),
                        }
                    }
                    Ok(Value::Bytes(Rc::new(out)))
                }
                v => bail!(a.value_span, "expected string, array, or bytes, found {}", v.type_name()),
            }
        }
        Type::Decimal => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("value")),
            };
            args.finish()?;
            let vs = a.value_span;
            match a.value {
                Value::Str(s) => match crate::decimal::parse(&s) {
                    Some(d) => Ok(Value::Decimal(d)),
                    None => bail!(vs, "invalid decimal: {}", s),
                },
                Value::Int(i) => Ok(Value::Decimal(crate::decimal::from_int(i))),
                Value::Float(f) => {
                    if !f.is_finite() {
                        bail!(vs, "float is not a valid decimal: {}", crate::repr::repr_float(f));
                    }
                    Ok(Value::Decimal(crate::decimal::from_f64(f)))
                }
                Value::Decimal(_) => Ok(a.value),
                v => bail!(vs, "expected decimal, integer, float, or string, found {}", v.type_name()),
            }
        }
        Type::Datetime => crate::datetime::construct_datetime(args),
        Type::Duration => crate::datetime::construct_duration(args),
        Type::Version => {
            let mut comps = vec![];
            while let Some(a) = args.eat_raw() {
                match a.value {
                    Value::Int(i) if i >= 0 => comps.push(i as u32),
                    Value::Int(_) => bail!(a.value_span, "number must be at least zero"),
                    Value::Array(arr) => {
                        for x in arr.iter() {
                            match x {
                                Value::Int(i) if *i >= 0 => comps.push(*i as u32),
                                Value::Int(_) => bail!(a.value_span, "number must be at least zero"),
                                v => bail!(a.value_span, "expected integer or array, found {}", v.type_name()),
                            }
                        }
                    }
                    v => bail!(a.value_span, "expected integer or array, found {}", v.type_name()),
                }
            }
            args.finish()?;
            Ok(Value::Version(Version(comps)))
        }
        Type::Label => {
            let s = args.expect("name", &STR)?;
            args.finish()?;
            let s = s.as_str().unwrap();
            if s.is_empty() {
                bail!(span, "label name must not be empty");
            }
            Ok(Value::Label(Rc::from(s)))
        }
        Type::Regex => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("regex")),
            };
            args.finish()?;
            let s = STR.cast(a.value).at(a.value_span)?;
            let s = s.as_str().unwrap();
            match crate::regex::Regex::new(s) {
                Ok(r) => Ok(Value::Regex(Rc::new(r))),
                Err(e) => bail!(a.value_span, "regex parse error:\n    {}\n    ^\nerror: {}", s, e),
            }
        }
        Type::Symbol => crate::symbols::construct_symbol(args),
        Type::Args => {
            let a = args.take();
            Ok(Value::Args(Rc::new(a)))
        }
        Type::Selector => crate::introspect::construct_selector(args),
        Type::Type => {
            let v = args.expect_any("value")?;
            args.finish()?;
            Ok(Value::Type(v.ty()))
        }
        Type::Counter => crate::introspect::construct_counter(args),
        Type::State => crate::introspect::construct_state(args),
        Type::Stroke => crate::visualize::construct_stroke(args),
        Type::Tiling => {
            let _ = args.take();
            let _ = engine;
            bail!(span, "tilings are not supported")
        }
        t => bail!(span, "type {} does not have a constructor", t.long_name()),
    }
}

pub fn format_int_base(mut n: i64, base: u32) -> String {
    if n == 0 {
        return "0".into();
    }
    let neg = n < 0;
    let mut digits = vec![];
    let mut u = (n as i128).unsigned_abs();
    while u > 0 {
        let d = (u % base as u128) as u32;
        digits.push(std::char::from_digit(d, base).unwrap());
        u /= base as u128;
    }
    n = 0;
    let _ = n;
    let s: String = digits.iter().rev().collect();
    if neg {
        format!("\u{2212}{s}")
    } else {
        s
    }
}
