    vm.engine.math.get(name).cloned()
}

fn unknown_math_var(vm: &Vm, name: &str, span: Span) -> Vec<Diag> {
    let mut d = Diag::error(span, format!("unknown variable: {name}"));
    if vm.engine.std.get(name).is_some() {
        d.hints.push(format!("`{name}` is not available directly in math, but is in the standard library"));
        d.hints.push(format!("to access `{name}` in code mode you can add a hash: `#{name}`"));
        d.hints.push(format!("or access `{name}` in math mode by using the `std` module: `std.{name}`"));
    } else if name.chars().count() > 1 && !name.contains('-') {
        let spaced: Vec<String> = name.chars().map(|c| c.to_string()).collect();
        d.hints.push(format!(
            "if you meant to display multiple letters as is, try adding spaces between each letter: `{}`",
            spaced.join(" ")
        ));
        d.hints.push(format!("or if you meant to display this as text, try placing it in quotes: `\"{name}\"`"));
    }
    vec![d]
}

fn display(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Content> {
    let v = vm.eval_expr(node)?;
    Ok(display_value(&v).spanned(vm.span(node)))
}

pub fn eval_math_node(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Content> {
    let mut seq = vec![];
    for c in node.children.iter().filter(|c| is_expr_kind(c.kind)) {
        seq.push(display(vm, c)?);
    }
    Ok(Content::sequence_or_single(seq))
}

pub fn eval_math_expr(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Value> {
    let span = vm.span(node);
    Ok(match node.kind {
        K::Math => Value::Content(eval_math_node(vm, node)?),
        K::MathText => {
            let t = node.text();
            if t.chars().next().is_some_and(|c| c.is_numeric()) {
                Value::Content(Content::text(t).spanned(span))
            } else {
                Value::Content(Content::symbol(t).spanned(span))
            }
        }
        K::MathIdent => {
            let name = node.text();
            match math_lookup(vm, name) {
                Some(v) => v,
                None => return Err(unknown_math_var(vm, name, span)),
            }
        }
        K::MathShorthand => {
            let c = math_shorthand(node.text());
            Value::Symbol(crate::symbols::make_symbol(None, vec![(Rc::from(""), Rc::from(c.to_string().as_str()))]))
        }
        K::MathAlignPoint => Value::Content(Content::new(&el::ALIGN_POINT).spanned(span)),
        K::MathDelimited => {
            let ch: Vec<&SyntaxNode> = node.children.iter().filter(|c| !c.kind.is_trivia()).collect();
            let open = display(vm, ch[0])?;
            let body = match node.children.iter().find(|c| c.kind == K::Math) {
                Some(m) => eval_math_node(vm, m)?,
                None => Content::empty(),
            };
            let close = display(vm, ch[ch.len() - 1])?;
            Value::Content(Content::new(&el::LR).with("body", open.add(body).add(close)).spanned(span))
        }
        K::MathAttach => {
            let base_node = node.children.iter().find(|c| is_expr_kind(c.kind)).unwrap();
            let base = display(vm, base_node)?;
            let mut c = Content::new(&el::ATTACH).with("base", base);
            let top = node.children.iter().skip_while(|n| n.kind != K::Hat).find(|n| is_expr_kind(n.kind));
            if let Some(t) = top {
                c.set("t", Value::Content(display(vm, t)?));
            }
            let base_idx = node.children.iter().position(|c| is_expr_kind(c.kind)).unwrap();
            if let Some(p) = node.children.get(base_idx + 1) {
                if p.kind == K::MathPrimes {
                    c.set("tr", Value::Content(primes(p)));
                }
            }
            let bottom = node.children.iter().skip_while(|n| n.kind != K::Underscore).find(|n| is_expr_kind(n.kind));
            if let Some(b) = bottom {
                c.set("b", Value::Content(display(vm, b)?));
            }
            Value::Content(c.spanned(span))
        }
        K::MathPrimes => Value::Content(primes(node).spanned(span)),
        K::MathFrac => {
            let es: Vec<&SyntaxNode> = node.children.iter().filter(|c| is_expr_kind(c.kind)).collect();
            let num = display(vm, es[0])?;
            let denom = display(vm, es[es.len() - 1])?;
            Value::Content(Content::new(&el::FRAC).with("num", num).with("denom", denom).spanned(span))
        }
        K::MathRoot => {
            let root_char = node.children[0].text();
            let index = match root_char {
                "∛" => Some("3"),
                "∜" => Some("4"),
                _ => None,
            };
            let rad = node.children.iter().find(|c| is_expr_kind(c.kind)).unwrap();
            let radicand = display(vm, rad)?;
            let mut c = Content::new(&el::ROOT);
            if let Some(i) = index {
                c.set("index", Value::Content(Content::text(i)));
            }
            Value::Content(c.with("radicand", radicand).spanned(span))
        }
        _ => bail!(span, "unexpected math node"),
    })
}

fn primes(node: &SyntaxNode) -> Content {
    let count = node.children.iter().filter(|c| c.kind == K::Prime).count();
    Content::new(&el::PRIMES).with("count", Value::Int(count as i64))
}

/// Evaluate arguments in a math function call.
pub fn eval_math_args(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Args> {
    let mut args = Args { span: vm.span(node), items: vec![] };
    for item in &node.children {
        let ispan = vm.span(item);
        match item.kind {
            K::Named => {
                let name = item.children.iter().find(|c| c.kind == K::Ident).map(|n| n.text()).unwrap_or("");
                let vnode = item.children.iter().rev().find(|c| is_expr_kind(c.kind)).unwrap();
                let value = vm.eval_expr(vnode)?;
                args.items.push(Arg { span: ispan, name: Some(Rc::from(name)), value, value_span: vm.span(vnode) });
            }
            K::Spread => {
                let inner = item.children.iter().find(|c| is_expr_kind(c.kind)).unwrap();
                match vm.eval_expr(inner)? {
                    Value::None => {}
                    Value::Array(a) => {
                        for v in a.iter() {
                            args.items.push(Arg { span: ispan, name: None, value: v.clone(), value_span: ispan });
                        }
                    }
                    Value::Dict(d) => {
                        for (k, v) in d.iter() {
                            args.items.push(Arg { span: ispan, name: Some(k.clone()), value: v.clone(), value_span: ispan });
                        }
                    }
                    Value::Args(a) => {
                        for it in a.items.iter() {
                            args.items.push(it.clone());
                        }
                    }
                    v => bail!(ispan, "cannot spread {}", v.type_name()),
                }
            }
            K::Array => {
                let mut vals = vec![];
                for c in &item.children {
                    if is_expr_kind(c.kind) {
                        vals.push(vm.eval_expr(c)?);
                    }
                }
                args.items.push(Arg { span: ispan, name: None, value: Value::array(vals), value_span: ispan });
            }
            k if is_expr_kind(k) => {
                let value = vm.eval_expr(item)?;
                args.items.push(Arg { span: ispan, name: None, value, value_span: ispan });
            }
            _ => {}
        }
    }
    Ok(args)
}

pub fn wrap_args_in_math(
    vm: &mut Vm,
    callee: Value,
    callee_span: Span,
    mut args: Args,
    args_node: &SyntaxNode,
) -> SourceResult<Value> {
    let trailing_comma = {
        let non_trivia: Vec<&SyntaxNode> = args_node.children.iter().filter(|c| !c.kind.is_trivia()).collect();
        non_trivia.len() >= 2 && non_trivia[non_trivia.len() - 2].kind == K::Comma
    };
    let _ = vm;
    let mut body = Content::empty();
    let items = args.all_strict(&CONTENT)?;
    args.finish()?;
    for (i, a) in items.into_iter().enumerate() {
        if i > 0 {
            body = body.add(Content::symbol(","));
        }
        if let Value::Content(c) = a {
            body = body.add(c);
        }
    }
    if trailing_comma {
        body = body.add(Content::symbol(","));
    }
    let lr = Content::new(&el::LR).with("body", Content::symbol("(").add(body).add(Content::symbol(")")));
    Ok(Value::Content(display_value(&callee).spanned(callee_span).add(lr)))
}

fn delimited(body: Content, l: &str, r: &str) -> Content {
    Content::new(&el::LR).with("body", Content::symbol(l).add(body).add(Content::symbol(r)))
}

pub fn call_math_func(engine: &mut crate::eval::Engine, name: &str, args: &mut Args) -> SourceResult<Value> {
    let _ = engine;
    match name {
        "abs" | "norm" | "round" | "floor" | "ceil" => {
            let size = args.named("size", &REL)?;
            let body = args.expect("body", &CONTENT)?;
            args.finish()?;
            let Value::Content(body) = body else { unreachable!() };
            let (l, r) = match name {
                "abs" => ("|", "|"),
                "norm" => ("‖", "‖"),
                "round" => ("⌊", "⌉"),
                "floor" => ("⌊", "⌋"),
                _ => ("⌈", "⌉"),
            };
            let mut c = delimited(body, l, r);
            if let Some(s) = size {
                c.set("size", s);
            }
            Ok(Value::Content(c))
        }
        "sqrt" => {
            let body = args.expect("radicand", &CONTENT)?;
            args.finish()?;
            Ok(Value::Content(Content::new(&el::ROOT).with("radicand", body)))
        }
        "upright" | "bold" | "italic" | "serif" | "sans" | "scr" | "cal" | "frak" | "mono" | "bb" | "display"
        | "inline" | "script" | "sscript" => {
            let _cramped = args.named("cramped", &BOOL)?;
            let body = args.expect("body", &CONTENT)?;
            args.finish()?;
            let Value::Content(body) = body else { unreachable!() };
            Ok(Value::Content(body.styled(Styles::from(vec![Style::Internal(Rc::from(format!("math-{name}").as_str()))]))))
        }
        _ => bail!(args.span, "unknown math function"),
    }
}

pub fn accent_char(s: &str) -> Option<char> {
    let mut chars = s.chars();
    let c = chars.next()?;
    if chars.next().is_some() {
        // e.g. "→" with variation selectors
        if !s.chars().skip(1).all(|c| matches!(c, '\u{fe0e}' | '\u{fe0f}')) {
            return None;
        }
    }
    Some(match c {
        '`' | '\u{300}' => '\u{300}',
        '´' | '\u{301}' => '\u{301}',
        '^' | 'ˆ' | '\u{302}' => '\u{302}',
        '~' | '∼' | '˜' | '\u{303}' => '\u{303}',
        '¯' | '\u{304}' => '\u{304}',
        '‾' | '\u{305}' => '\u{305}',
        '˘' | '\u{306}' => '\u{306}',
        '.' | '˙' | '⋅' | '\u{307}' => '\u{307}',
        '¨' | '\u{308}' => '\u{308}',
        '∘' | '○' | '˚' | '\u{30a}' => '\u{30a}',
        '˝' | '\u{30b}' => '\u{30b}',
        'ˇ' | '\u{30c}' => '\u{30c}',
        '→' | '\u{20d7}' => '\u{20d7}',
        '←' | '\u{20d6}' => '\u{20d6}',
        '↔' | '\u{20e1}' => '\u{20e1}',
        '⇀' | '\u{20d1}' => '\u{20d1}',
        '↼' | '\u{20d0}' => '\u{20d0}',
        '\u{20db}' => '\u{20db}',
        '\u{20dc}' => '\u{20dc}',
        _ => return None,
    })
}

pub fn cast_accent(v: Value) -> StrResult<Value> {
    let s = match &v {
        Value::Str(s) => s.to_string(),
        Value::Symbol(s) => s.text.to_string(),
        Value::Content(c) => c.plain_text(),
        _ => return Err("expected symbol, string, or content".into()),
    };
    match accent_char(&s) {
        Some(c) => Ok(Value::str(c.to_string())),
        None => Ok(Value::str(s)),
    }
}

pub fn cast_delim(v: Value) -> StrResult<Value> {
    let pair = |l: Option<&str>, r: Option<&str>| {
        let f = |x: Option<&str>| x.map(Value::str).unwrap_or(Value::None);
        Value::array(vec![f(l), f(r)])
    };
    match v {
        Value::None => Ok(pair(None, None)),
        Value::Str(s) => {
            let r = match &*s {
                "(" => ")",
                "[" => "]",
                "{" => "}",
                "|" => "|",
                "||" | "‖" => "‖",
                "⟨" => "⟩",
                "⌈" => "⌉",
                "⌊" => "⌋",
                "⟦" => "⟧",
                _ => return Ok(pair(Some(&s), Some(&s))),
            };
            let l = if &*s == "||" { "‖" } else { &*s };
            Ok(pair(Some(l), Some(r)))
        }
        Value::Symbol(s) => cast_delim(Value::Str(s.text.clone())),
        Value::Array(a) => Ok(Value::Array(a)),
        v => Err(format!("expected string, array, or none, found {}", v.type_name()).into()),
    }
}

/// Calling a symbol as a function.
pub fn call_symbol(s: &Symbol, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match &*s.text {
        "⌊" | "⌈" => {
            let body = args.expect("body", &CONTENT)?;
            args.finish()?;
            let Value::Content(body) = body else { unreachable!() };
            let r = if &*s.text == "⌊" { "⌋" } else { "⌉" };
            Ok(Value::Content(delimited(body, &s.text, r)))
        }
        t => match accent_char(t) {
            Some(acc) => {
                let base = args.expect("base", &CONTENT)?;
                let size = args.named("size", &REL)?;
                args.finish()?;
                let mut c = Content::new(&el::ACCENT_ELEM).with("base", base).with("accent", Value::str(acc.to_string()));
                if let Some(sz) = size {
                    c.set("size", sz);
                }
                Ok(Value::Content(c))
            }
            None => bail!(span, "symbol {} is not callable", crate::repr::repr(&Value::Symbol(s.clone()))),
        },
    }
}
