#[derive(Debug, Clone, Copy, PartialEq)]
pub enum NumKind {
    Arabic,
    LowerLatin,
    UpperLatin,
    LowerRoman,
    UpperRoman,
    LowerGreek,
    UpperGreek,
    Symbol,
    Hebrew,
    LowerChinese,
    UpperChinese,
    HiraganaAiueo,
    HiraganaIroha,
    KatakanaAiueo,
    KatakanaIroha,
    KoreanJamo,
    KoreanSyllable,
    EasternArabic,
    EasternArabicPersian,
    Devanagari,
    Bengali,
    Circled,
    DoubleCircled,
}

fn kind_of(c: char) -> Option<NumKind> {
    use NumKind::*;
    Some(match c {
        '1' => Arabic,
        'a' => LowerLatin,
        'A' => UpperLatin,
        'i' => LowerRoman,
        'I' => UpperRoman,
        'α' => LowerGreek,
        'Α' => UpperGreek,
        '*' => Symbol,
        'א' => Hebrew,
        '一' => LowerChinese,
        '壹' => UpperChinese,
        'あ' => HiraganaAiueo,
        'い' => HiraganaIroha,
        'ア' => KatakanaAiueo,
        'イ' => KatakanaIroha,
        'ㄱ' => KoreanJamo,
        '가' => KoreanSyllable,
        '\u{0661}' => EasternArabic,
        '\u{06F1}' => EasternArabicPersian,
        '\u{0967}' => Devanagari,
        '\u{09E7}' => Bengali,
        '①' => Circled,
        '⓵' => DoubleCircled,
        _ => return None,
    })
}

fn bijective(n: u64, alphabet: &[char]) -> String {
    if n == 0 {
        return "-".into();
    }
    let base = alphabet.len() as u64;
    let mut n = n;
    let mut out = vec![];
    while n > 0 {
        n -= 1;
        out.push(alphabet[(n % base) as usize]);
        n /= base;
    }
    out.iter().rev().collect()
}

fn roman(n: u64, upper: bool) -> String {
    if n == 0 {
        return "N".into();
    }
    let table = [
        ("M̅", 1000000), ("D̅", 500000), ("C̅", 100000), ("L̅", 50000), ("X̅", 10000), ("V̅", 5000), ("I̅V̅", 4000),
        ("M", 1000), ("CM", 900), ("D", 500), ("CD", 400), ("C", 100), ("XC", 90), ("L", 50), ("XL", 40),
        ("X", 10), ("IX", 9), ("V", 5), ("IV", 4), ("I", 1),
    ];
    let mut n = n;
    let mut s = String::new();
    for (r, v) in table {
        while n >= v {
            s.push_str(r);
            n -= v;
        }
    }
    if upper {
        s
    } else {
        s.to_lowercase()
    }
}

fn chinese(n: u64, upper: bool) -> String {
    let digits: [&str; 10] = if upper {
        ["零", "壹", "贰", "叁", "肆", "伍", "陆", "柒", "捌", "玖"]
    } else {
        ["〇", "一", "二", "三", "四", "五", "六", "七", "八", "九"]
    };
    let units: [&str; 4] = if upper { ["", "拾", "佰", "仟"] } else { ["", "十", "百", "千"] };
    if n == 0 {
        return digits[0].into();
    }
    if n < 10000 {
        let ds: Vec<u64> = n.to_string().chars().map(|c| c.to_digit(10).unwrap() as u64).collect();
        let len = ds.len();
        let mut out = String::new();
        let mut zero = false;
        for (i, d) in ds.iter().enumerate() {
            let pos = len - 1 - i;
            if *d == 0 {
                zero = true;
                continue;
            }
            if zero {
                out.push_str(digits[0]);
                zero = false;
            }
            if !(len == 2 && i == 0 && *d == 1 && !upper) {
                out.push_str(digits[*d as usize]);
            }
            out.push_str(units[pos]);
        }
        return out;
    }
    n.to_string()
}

pub fn apply_kind(kind: NumKind, n: u64) -> String {
    use NumKind::*;
    match kind {
        Arabic => n.to_string(),
        LowerLatin => bijective(n, &"abcdefghijklmnopqrstuvwxyz".chars().collect::<Vec<_>>()),
        UpperLatin => bijective(n, &"ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect::<Vec<_>>()),
        LowerRoman => roman(n, false),
        UpperRoman => roman(n, true),
        LowerGreek => bijective(n, &"αβγδεζηθικλμνξοπρστυφχψω".chars().collect::<Vec<_>>()),
        UpperGreek => bijective(n, &"ΑΒΓΔΕΖΗΘΙΚΛΜΝΞΟΠΡΣΤΥΦΧΨΩ".chars().collect::<Vec<_>>()),
        Symbol => {
            if n == 0 {
                return "-".into();
            }
            let syms = ['*', '†', '‡', '§', '¶', '‖'];
            let idx = ((n - 1) % 6) as usize;
            let count = ((n - 1) / 6 + 1) as usize;
            std::iter::repeat(syms[idx]).take(count).collect()
        }
        Hebrew => n.to_string(),
        LowerChinese => chinese(n, false),
        UpperChinese => chinese(n, true),
        HiraganaAiueo => bijective(n, &"あいうえおかきくけこさしすせそたちつてとなにぬねのはひふへほまみむめもやゆよらりるれろわをん".chars().collect::<Vec<_>>()),
        HiraganaIroha => bijective(n, &"いろはにほへとちりぬるをわかよたれそつねならむうゐのおくやまけふこえてあさきゆめみしゑひもせす".chars().collect::<Vec<_>>()),
        KatakanaAiueo => bijective(n, &"アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン".chars().collect::<Vec<_>>()),
        KatakanaIroha => bijective(n, &"イロハニホヘトチリヌルヲワカヨタレソツネナラムウヰノオクヤマケフコエテアサキユメミシヱヒモセス".chars().collect::<Vec<_>>()),
        KoreanJamo => bijective(n, &"ㄱㄴㄷㄹㅁㅂㅅㅇㅈㅊㅋㅌㅍㅎ".chars().collect::<Vec<_>>()),
        KoreanSyllable => bijective(n, &"가나다라마바사아자차카타파하".chars().collect::<Vec<_>>()),
        EasternArabic => n.to_string().chars().map(|c| char::from_u32(0x0660 + c.to_digit(10).unwrap()).unwrap()).collect(),
        EasternArabicPersian => n.to_string().chars().map(|c| char::from_u32(0x06F0 + c.to_digit(10).unwrap()).unwrap()).collect(),
        Devanagari => n.to_string().chars().map(|c| char::from_u32(0x0966 + c.to_digit(10).unwrap()).unwrap()).collect(),
        Bengali => n.to_string().chars().map(|c| char::from_u32(0x09E6 + c.to_digit(10).unwrap()).unwrap()).collect(),
        Circled => {
            if (1..=20).contains(&n) {
                char::from_u32(0x2460 + n as u32 - 1).unwrap().to_string()
            } else {
                n.to_string()
            }
        }
        DoubleCircled => {
            if (1..=10).contains(&n) {
                char::from_u32(0x24F5 + n as u32 - 1).unwrap().to_string()
            } else {
                n.to_string()
            }
        }
    }
}

pub struct Pattern {
    pub pieces: Vec<(String, NumKind)>,
    pub suffix: String,
    pub trimmed: bool,
}

pub fn parse_pattern(p: &str) -> StrResult<Pattern> {
    let mut pieces = vec![];
    let mut handled = 0;
    for (i, c) in p.char_indices() {
        let Some(kind) = kind_of(c) else { continue };
        pieces.push((p[handled..i].to_string(), kind));
        handled = i + c.len_utf8();
    }
    if pieces.is_empty() {
        return Err("invalid numbering pattern".into());
    }
    Ok(Pattern { pieces, suffix: p[handled..].to_string(), trimmed: false })
}

pub fn apply_pattern(p: &Pattern, numbers: &[u64]) -> String {
    let mut fmt = String::new();
    let mut it = numbers.iter();
    for (i, ((prefix, kind), n)) in p.pieces.iter().zip(&mut it).enumerate() {
        if i > 0 || !p.trimmed {
            fmt.push_str(prefix);
        }
        fmt.push_str(&apply_kind(*kind, *n));
    }
    let last = p.pieces.last().unwrap();
    for n in it {
        if last.0.is_empty() {
            fmt.push_str(&p.suffix);
        } else {
            fmt.push_str(&last.0);
        }
        fmt.push_str(&apply_kind(last.1, *n));
    }
    if !p.trimmed {
        fmt.push_str(&p.suffix);
    }
    fmt
}

pub fn apply_numbering(engine: &mut Engine, numbering: &Value, numbers: &[u64], span: Span) -> SourceResult<Value> {
    match numbering {
        Value::Str(s) => {
            let p = parse_pattern(s).at(span)?;
            Ok(Value::str(apply_pattern(&p, numbers)))
        }
        f @ Value::Func(_) => {
            crate::func_call::call_value(engine, f, span, numbers.iter().map(|n| Value::Int(*n as i64)).collect())
        }
        _ => Ok(Value::None),
    }
}

pub fn numbering_func(engine: &mut Engine, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let numbering = args.expect("numbering", &Cast::Or(&[Cast::Str, Cast::Func]))?;
    let nums = args.all_strict(&UINT)?;
    args.finish()?;
    let numbers: Vec<u64> = nums
        .into_iter()
        .map(|v| match v {
            Value::Int(i) => i as u64,
            _ => 0,
        })
        .collect();
    if let Value::Str(s) = &numbering {
        // validate
        parse_pattern(s).at(span)?;
