                _ => return Err("expected integer, \"thin\", \"extralight\", \"light\", \"regular\", \"medium\", \"semibold\", \"bold\", \"extrabold\", or \"black\"".into()),
            };
            let _ = w;
            Ok(Value::Str(s))
        }
        _ => Err("expected integer or string".into()),
    }
}

pub fn cast_font(v: Value) -> StrResult<Value> {
    match v {
        Value::Str(s) => Ok(Value::str(s.to_lowercase())),
        Value::Array(a) => {
            let mut out = vec![];
            for x in a.iter() {
                match x {
                    Value::Str(s) => out.push(Value::str(s.to_lowercase())),
                    Value::Dict(_) => out.push(x.clone()),
                    other => return Err(format!("expected string or dictionary, found {}", other.type_name()).into()),
                }
            }
            Ok(Value::array(out))
        }
        Value::Dict(_) => Ok(v),
        _ => Err("expected string, dictionary, or array".into()),
    }
}

pub fn cast_lang(v: Value) -> StrResult<Value> {
    match &v {
        Value::Str(s) => {
            let len = s.len();
            if !(2..=3).contains(&len) || !s.chars().all(|c| c.is_ascii_alphabetic()) {
                return Err("expected two or three letter language code (ISO 639-1/2/3)".into());
            }
            Ok(Value::str(s.to_lowercase()))
        }
        _ => Err("expected string".into()),
    }
}

pub const KNOWN_FONTS: &[&str] = &[
    "dejavu sans", "dejavu sans mono", "dejavu serif", "libertinus serif", "new computer modern", "new computer modern math",
];

pub fn check_font_warning(engine: &mut Engine, v: &Value, span: Span) {
    let check = |engine: &mut Engine, name: &str| {
        if !KNOWN_FONTS.contains(&name) && !engine.world.extra_fonts.iter().any(|f| f == name) {
            engine.warn(Diag::warning(span, format!("unknown font family: {name}")));
        }
    };
    match v {
        Value::Str(s) => check(engine, s),
        Value::Array(a) => {
            for x in a.iter() {
                if let Value::Str(s) = x {
                    check(engine, s);
                }
            }
        }
        _ => {}
    }
}

pub fn case_content(c: Content, upper: bool) -> Content {
    // Approximation: transform text nodes.
    fn walk(c: &Content, upper: bool) -> Content {
        if c.is("text") {
            if let Some(Value::Str(t)) = c.get("text") {
                let nt = if upper { t.to_uppercase() } else { t.to_lowercase() };
                let mut nc = c.clone();
                nc.set("text", Value::Str(Rc::from(nt.as_str())));
                return nc;
            }
        }
        let mut nc = c.clone();
        let fields: Vec<(&'static str, Value)> = c.0.fields.clone();
        for (n, v) in fields {
            match v {
                Value::Content(inner) => nc.set(n, Value::Content(walk(&inner, upper))),
                Value::Array(arr) => {
                    let mapped: Vec<Value> = arr
                        .iter()
                        .map(|x| match x {
                            Value::Content(i) => Value::Content(walk(i, upper)),
                            o => o.clone(),
                        })
                        .collect();
                    nc.set(n, Value::array(mapped));
                }
                _ => {}
            }
        }
        nc
    }
    walk(&c, upper)
}
