//! Integer and float methods.

use crate::cast::*;
use crate::diag::*;
use crate::func::Args;
use crate::value::*;
use std::rc::Rc;

pub fn int_method(i: i64, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "signum" => {
            args.finish()?;
            Ok(Value::Int(i.signum()))
        }
        "bit-not" => {
            args.finish()?;
            Ok(Value::Int(!i))
        }
        "bit-and" | "bit-or" | "bit-xor" => {
            let o = args.expect("rhs", &INT)?;
            args.finish()?;
            let Value::Int(o) = o else { unreachable!() };
            Ok(Value::Int(match name {
                "bit-and" => i & o,
                "bit-or" => i | o,
                _ => i ^ o,
            }))
        }
        "bit-lshift" => {
            let o = args.expect("shift", &UINT)?;
            args.finish()?;
            let Value::Int(o) = o else { unreachable!() };
            match i.checked_shl(o as u32) {
                Some(v) if o < 64 => Ok(Value::Int(v)),
                _ => bail!(span, "the result is too large"),
            }
        }
        "bit-rshift" => {
            let o = args.expect("shift", &UINT)?;
            let logical = args.named("logical", &BOOL)?;
            args.finish()?;
            let Value::Int(o) = o else { unreachable!() };
            let logical = matches!(logical, Some(Value::Bool(true)));
            if o >= 64 {
                return Ok(Value::Int(if logical || i >= 0 { 0 } else { -1 }));
            }
            Ok(Value::Int(if logical { ((i as u64) >> o) as i64 } else { i >> o }))
        }
        "to-bytes" => {
            let endian = args.named("endian", &Cast::Strs(&["big", "little"]))?;
            let size = args.named("size", &UINT)?;
            args.finish()?;
            let big = matches!(&endian, Some(Value::Str(s)) if &**s == "big");
            let size = match size {
                Some(Value::Int(s)) => s as usize,
                _ => 8,
            };
            let full = if big { i.to_be_bytes().to_vec() } else { i.to_le_bytes().to_vec() };
            let bytes = if size >= 8 {
                let mut v = full.clone();
                let pad = if i < 0 { 0xff } else { 0 };
                if big {
                    let mut p = vec![pad; size - 8];
                    p.extend(v);
                    v = p;
                } else {
                    v.extend(std::iter::repeat(pad).take(size - 8));
                }
                v
            } else if big {
                full[8 - size..].to_vec()
            } else {
                full[..size].to_vec()
            };
            Ok(Value::Bytes(Rc::new(bytes)))
        }
        _ => bail!(span, "type integer has no method `{}`", name),
    }
}

pub fn float_method(f: f64, name: &str, args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    match name {
        "is-nan" => {
            args.finish()?;
            Ok(Value::Bool(f.is_nan()))
        }
        "is-infinite" => {
            args.finish()?;
            Ok(Value::Bool(f.is_infinite()))
        }
        "signum" => {
            args.finish()?;
            Ok(Value::Float(f.signum()))
        }
        "to-bytes" => {
            let endian = args.named("endian", &Cast::Strs(&["big", "little"]))?;
            let size = args.named("size", &UINT)?;
            args.finish()?;
            let big = matches!(&endian, Some(Value::Str(s)) if &**s == "big");
            let size = match size {
                Some(Value::Int(s)) => s,
                _ => 8,
            };
            let bytes = match size {
                8 => if big { f.to_be_bytes().to_vec() } else { f.to_le_bytes().to_vec() },
                4 => if big { (f as f32).to_be_bytes().to_vec() } else { (f as f32).to_le_bytes().to_vec() },
                _ => bail!(span, "size must be either 4 or 8"),
            };
            Ok(Value::Bytes(Rc::new(bytes)))
        }
        _ => bail!(span, "type float has no method `{}`", name),
    }
}

fn bytes_arg(args: &mut Args) -> SourceResult<(Vec<u8>, bool, bool)> {
    let b = args.expect("bytes", &Cast::Bytes)?;
    let endian = args.named("endian", &Cast::Strs(&["big", "little"]))?;
    let signed = args.named("signed", &BOOL)?;
    args.finish()?;
    let Value::Bytes(b) = b else { unreachable!() };
    let big = matches!(&endian, Some(Value::Str(s)) if &**s == "big");
    let signed = !matches!(signed, Some(Value::Bool(false)));
    Ok(((*b).clone(), big, signed))
}

pub fn int_from_bytes(args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let (b, big, signed) = bytes_arg(args)?;
    if b.len() > 8 {
        bail!(span, "too many bytes to convert to a 64 bit number");
    }
    if b.is_empty() {
        return Ok(Value::Int(0));
    }
    let mut buf = [0u8; 8];
    let neg = signed && if big { b[0] & 0x80 != 0 } else { b[b.len() - 1] & 0x80 != 0 };
    if neg {
        buf = [0xff; 8];
    }
    if big {
        buf[8 - b.len()..].copy_from_slice(&b);
        Ok(Value::Int(i64::from_be_bytes(buf)))
    } else {
        buf[..b.len()].copy_from_slice(&b);
        Ok(Value::Int(i64::from_le_bytes(buf)))
    }
}

pub fn float_from_bytes(args: &mut Args) -> SourceResult<Value> {
    let span = args.span;
    let b = args.expect("bytes", &Cast::Bytes)?;
    let endian = args.named("endian", &Cast::Strs(&["big", "little"]))?;
    args.finish()?;
    let Value::Bytes(b) = b else { unreachable!() };
    let big = matches!(&endian, Some(Value::Str(s)) if &**s == "big");
    match b.len() {
        8 => {
            let a: [u8; 8] = b[..].try_into().unwrap();
            Ok(Value::Float(if big { f64::from_be_bytes(a) } else { f64::from_le_bytes(a) }))
        }
        4 => {
            let a: [u8; 4] = b[..].try_into().unwrap();
            Ok(Value::Float(if big { f32::from_be_bytes(a) } else { f32::from_le_bytes(a) } as f64))
        }
        _ => bail!(span, "bytes must have a length of 4 or 8"),
    }
}
