//! Set and show rules.

use crate::content::{Style, Styles};
use crate::diag::*;
use crate::elements::FK;
use crate::eval::Engine;
use crate::func::{Args, Func, FuncKind};
use crate::value::*;
use std::rc::Rc;

pub fn set_rule(engine: &mut Engine, func: &Func, span: Span, mut args: Args) -> SourceResult<Styles> {
    let Some(elem) = func.element_def() else {
        bail!(span, "only element functions can be used in set rules");
    };
    if elem.name == "text" && std::ptr::eq(elem, &crate::elements::TEXT) {
        let styles = crate::construct::text_styles(engine, &mut args)?;
        args.finish()?;
        return Ok(styles);
    }
    let mut styles = vec![];
    let mut push = |field: &'static str, value: Value, span: Span| {
        styles.push(Style::Property { elem, field, value, span });
    };
    match elem.name {
        "block" => {
            if let Some(v) = args.named("spacing", &crate::cast::ANY)? {
                push("above", v.clone(), span);
                push("below", v, span);
            }
        }
        "pad" => {
            let all = args.named("rest", &crate::cast::REL)?;
            let x = args.named("x", &crate::cast::REL)?.or(all.clone());
            let y = args.named("y", &crate::cast::REL)?.or(all);
            if let Some(x) = x {
                push("left", x.clone(), span);
                push("right", x, span);
            }
            if let Some(y) = y {
                push("top", y.clone(), span);
                push("bottom", y, span);
            }
        }
        "document" => {
            for n in ["title", "author", "description", "keywords", "date"] {
                if let Some(v) = args.named(n, &crate::cast::ANY)? {
                    push(Box::leak(n.to_string().into_boxed_str()), v, span);
                }
            }
            args.finish()?;
            return Ok(Styles::from(styles));
        }
        _ => {}
    }
    for f in elem.fields {
        let fspan = args.named_span(f.name).unwrap_or(span);
        match f.kind {
            FK::N => {
                if let Some(v) = args.named(f.name, f.cast)? {
                    push(f.name, v, fspan);
                }
            }
            FK::NF => {
                if let Some(v) = args.named(f.name, f.cast)? {
                    push(f.name, v, fspan);
                } else if let Some(v) = args.find(f.cast)? {
                    push(f.name, v, fspan);
                }
            }
            FK::P => {
                if let Some(v) = args.find(f.cast)? {
                    push(f.name, v, fspan);
                }
            }
            _ => {}
        }
    }
    args.finish()?;
    Ok(Styles::from(styles))
}

pub fn cast_show_selector(v: Value) -> StrResult<Value> {
    match &v {
        Value::Func(f) => match &f.kind {
            FuncKind::Element(_) => Ok(v),
            _ => Err("only element functions can be used as selectors".into()),
        },
        Value::Label(_) | Value::Str(_) | Value::Regex(_) | Value::Selector(_) | Value::Symbol(_) | Value::Location(_) => Ok(v),
        _ => Err(format!(
            "expected symbol, string, label, function, regex, or selector, found {}",
            v.type_name()
        )
        .into()),
    }
}

pub fn recipe_style(sel: Option<Value>, transform: Value, span: Span) -> Style {
    Style::Recipe(Rc::new(crate::content::Recipe { selector: sel, transform, span }))
}
