//! The world: files, root, sources.

use crate::diag::*;
use crate::syntax::node::SyntaxNode;
use std::path::{Component, Path, PathBuf};
use std::rc::Rc;

pub struct Source {
    pub path: Option<PathBuf>,
    pub display: String,
    pub text: String,
    pub line_starts: Vec<usize>,
    pub root: Option<Rc<SyntaxNode>>,
}

impl Source {
    pub fn new(path: Option<PathBuf>, display: String, text: String) -> Self {
        let mut line_starts = vec![0];
        let bytes = text.as_bytes();
        let mut i = 0;
        let chars: Vec<(usize, char)> = text.char_indices().collect();
        let mut k = 0;
        while k < chars.len() {
            let (idx, c) = chars[k];
            if crate::syntax::lexer::is_newline(c) {
                let mut end = idx + c.len_utf8();
                if c == '\r' && k + 1 < chars.len() && chars[k + 1].1 == '\n' {
                    end += 1;
                    k += 1;
                }
                line_starts.push(end);
            }
            k += 1;
        }
        let _ = (bytes, &mut i);
        Source { path, display, text, line_starts, root: None }
    }

    pub fn line_of(&self, byte: usize) -> usize {
        match self.line_starts.binary_search(&byte) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }

    pub fn column_of(&self, byte: usize) -> usize {
        let line = self.line_of(byte);
        let start = self.line_starts[line];
        let end = byte.min(self.text.len());
        self.text.get(start..end).map(|s| s.chars().count()).unwrap_or(0)
    }

    pub fn line_text(&self, line: usize) -> &str {
        let start = self.line_starts[line];
        let end = self.line_starts.get(line + 1).copied().unwrap_or(self.text.len());
        let s = &self.text[start..end];
        s.trim_end_matches(['\n', '\r'])
    }
}

pub struct World {
    pub root: PathBuf,
    pub cwd: PathBuf,
    pub sources: Vec<Source>,
    pub now: Option<(i32, u8, u8)>,
    pub allow_fs: bool,
    pub extra_fonts: Vec<String>,
    pub main: Option<u16>,
}

impl World {
    pub fn new(root: PathBuf) -> Self {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        World { root, cwd, sources: vec![], now: None, allow_fs: false, extra_fonts: vec![], main: None }
    }

    pub fn source(&self, id: u16) -> Option<&Source> {
        if id == 0 {
            None
        } else {
            self.sources.get(id as usize - 1)
        }
    }

    pub fn add_source(&mut self, src: Source) -> u16 {
        self.sources.push(src);
        self.sources.len() as u16
    }

    pub fn display_path(&self, p: &Path) -> String {
        let p = normalize(p);
        if let Ok(r) = p.strip_prefix(&self.cwd) {
            return r.to_string_lossy().to_string();
        }
        // try relative with ..
        let rel = pathdiff(&p, &self.cwd);
        match rel {
            Some(r) => r.to_string_lossy().to_string(),
            None => p.to_string_lossy().to_string(),
        }
    }

    /// Resolve a path written in a file (relative to that file or absolute from root).
    pub fn resolve(&self, from_file: u16, path: &str) -> StrResult<PathBuf> {
        let base_dir = if path.starts_with('/') {
            self.root.clone()
        } else {
            match self.source(from_file).and_then(|s| s.path.clone()) {
                Some(p) => p.parent().map(|x| x.to_path_buf()).unwrap_or_else(|| self.root.clone()),
                None => self.root.clone(),
            }
        };
        let joined = base_dir.join(path.trim_start_matches('/'));
        let norm = normalize(&joined);
        let root = normalize(&self.root);
        if !norm.starts_with(&root) {
            return Err(HintedString::new(format!("path `{}` would escape the project root", crate::repr::repr_str(path)))
                .hint("cannot access files outside of the project sandbox")
                .hint("you can adjust the project root with the `--root` argument"));
        }
        Ok(norm)
    }

    pub fn read_file(&self, p: &Path) -> StrResult<Vec<u8>> {
        if p.is_dir() {
            return Err(format!("is a directory (searched at {})", p.display()).into());
        }
        std::fs::read(p).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => HintedString::new(format!("file not found (searched at {})", p.display())),
            std::io::ErrorKind::PermissionDenied => {
                HintedString::new(format!("failed to load file (access denied)"))
            }
            _ => HintedString::new(format!("failed to load file ({})", e)),
        })
    }

    pub fn find_source(&self, p: &Path) -> Option<u16> {
        self.sources.iter().position(|s| s.path.as_deref() == Some(p)).map(|i| i as u16 + 1)
    }
}

pub fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::ParentDir => {
                out.pop();
            }
            Component::CurDir => {}
            c => out.push(c.as_os_str()),
        }
    }
    out
}

fn pathdiff(path: &Path, base: &Path) -> Option<PathBuf> {
    let mut ita = path.components();
    let mut itb = base.components();
    let mut comps: Vec<Component> = vec![];
    loop {
        match (ita.next(), itb.next()) {
            (None, None) => break,
            (Some(a), None) => {
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
            (None, _) => comps.push(Component::ParentDir),
            (Some(a), Some(b)) if comps.is_empty() && a == b => (),
            (Some(a), Some(_)) => {
                comps.push(Component::ParentDir);
                for _ in itb {
                    comps.push(Component::ParentDir);
                }
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
        }
    }
    Some(comps.iter().map(|c| c.as_os_str()).collect())
}
