use crate::syntax::node::{is_expr_kind, SyntaxNode};
use crate::value::*;
use std::rc::Rc;

thread_local! {
    static IMPORT_STACK: std::cell::RefCell<Vec<u16>> = std::cell::RefCell::new(vec![]);
}

pub fn parse_source(engine: &mut Engine, id: u16) -> Rc<SyntaxNode> {
    let src = engine.world.source(id).unwrap();
    if let Some(r) = &src.root {
        return r.clone();
    }
    let root = Rc::new(crate::syntax::parser::parse(&src.text));
    engine.world.sources[id as usize - 1].root = Some(root.clone());
    root
}

pub fn syntax_errors(root: &SyntaxNode, file: u16) -> Vec<Diag> {
    root.errors()
        .into_iter()
        .map(|(e, s, end)| {
            let mut d = Diag::error(Span::new(file, s, end), e.message);
            d.hints = e.hints;
            d
        })
        .collect()
}

/// Evaluate a source file into a module.
pub fn eval_file(engine: &mut Engine, id: u16) -> SourceResult<Rc<Module>> {
    let root = parse_source(engine, id);
    let errs = syntax_errors(&root, id);
    if !errs.is_empty() {
        return Err(errs);
    }
    let name = engine
        .world
        .source(id)
        .and_then(|s| s.path.as_ref())
        .and_then(|p| p.file_stem())
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default();
    IMPORT_STACK.with(|s| s.borrow_mut().push(id));
    let std = engine.std.clone();
    let ctx = engine.context.clone();
    let mut vm = Vm { engine, scopes: Scopes::new(Some(std)), flow: None, file: id, context: ctx };
    let r = vm.eval_markup(&root);
    IMPORT_STACK.with(|s| s.borrow_mut().pop());
    let content = r?;
    if let Some(flow) = vm.flow.take() {
        match flow {
            crate::eval::Flow::Break(s) => bail!(s, "cannot break outside of loop"),
            crate::eval::Flow::Continue(s) => bail!(s, "cannot continue outside of loop"),
            crate::eval::Flow::Return(s, _) => bail!(s, "cannot return outside of function"),
        }
    }
    let scope = std::mem::take(&mut vm.scopes.top);
    Ok(Rc::new(Module { name: Rc::from(name.as_str()), scope: Rc::new(scope), content: Some(content) }))
}

fn load_module_from_path(vm: &mut Vm, path: &str, span: Span) -> SourceResult<Rc<Module>> {
    if path.starts_with('@') {
        bail!(span, "failed to download package (https://packages.typst.org/preview/{}.tar.gz: Dns Failed: resolve dns name 'packages.typst.org:443': failed to lookup address information: Temporary failure in name resolution)", path.trim_start_matches("@preview/").replace(':', "-"));
    }
    if !vm.engine.world.allow_fs {
        bail!(span, "cannot access file system from here");
    }
    let resolved = vm.engine.world.resolve(vm.file, path).at(span)?;
    let id = match vm.engine.world.find_source(&resolved) {
        Some(id) => id,
        None => {
            let bytes = vm.engine.world.read_file(&resolved).at(span)?;
            let text = String::from_utf8(bytes).map_err(|_| HintedString::new("file is not valid utf-8")).at(span)?;
            let display = vm.engine.world.display_path(&resolved);
            vm.engine.world.add_source(crate::world::Source::new(Some(resolved.clone()), display, text))
        }
    };
    if IMPORT_STACK.with(|s| s.borrow().contains(&id)) {
        bail!(span, "cyclic import");
    }
    let r = eval_file(vm.engine, id);
    add_trace(r, span, || "error occurred while importing this module".into())
}

pub fn eval_import(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Value> {
    let source_node = node.children.iter().find(|c| is_expr_kind(c.kind)).unwrap();
    let source_span = vm.span(source_node);
    let source = vm.eval_expr(source_node)?;
    let new_name = {
        let mut it = node.children.iter().skip_while(|c| c.kind != K::As);
        it.next();
        it.find(|c| c.kind == K::Ident).map(|c| c.text().to_string())
    };
    let (module_scope, default_name): (Rc<Scope>, Option<String>) = match &source {
        Value::Str(path) => {
            let m = load_module_from_path(vm, path, source_span)?;
            let name = m.name.to_string();
            let scope = m.scope.clone();
            let mv = Value::Module(m);
            if new_name.is_some() || !node.children.iter().any(|c| c.kind == K::Colon) {
                let bind = new_name.clone().unwrap_or(name.clone());
                if !crate::syntax::lexer::is_ident(&bind) && new_name.is_none() {
                    bail!(source_span, "cannot determine the module name from the file path");
                }
                vm.define(bind.as_str(), mv);
            }
            (scope, Some(name))
        }
        Value::Module(m) => {
            if new_name.is_some() || !node.children.iter().any(|c| c.kind == K::Colon) {
                let bind = new_name.clone().unwrap_or(m.name.to_string());
                vm.define(bind.as_str(), source.clone());
            }
            (m.scope.clone(), Some(m.name.to_string()))
        }
        Value::Func(f) => {
            let mut s = Scope::new();
            if let FuncKind::Element(e) = &f.kind {
                for n in ["cell", "header", "footer", "hline", "vline", "item", "caption", "entry", "line"] {
                    if let Some(v) = crate::library::func_scope_get(f, n) {
                        if e.name.len() > 0 {
                            s.define(n, v);
                        }
                    }
                }
            }
            if new_name.is_some() || !node.children.iter().any(|c| c.kind == K::Colon) {
                let bind = new_name.clone().unwrap_or(f.name().unwrap_or_default());
                vm.define(bind.as_str(), source.clone());
            }
            (Rc::new(s), f.name())
        }
        Value::Type(t) => {
            let mut s = Scope::new();
            for m in crate::methods::type_methods(*t) {
                if let Some(v) = crate::methods::type_scope_get(*t, m) {
                    s.define(*m, v);
                }
            }
            (Rc::new(s), Some(t.short_name().to_string()))
        }
        v => bail!(source_span, "expected path, module, function, or type, found {}", v.type_name()),
    };
    let _ = default_name;
    // Items
    if node.children.iter().any(|c| c.kind == K::Star) {
        for (k, v) in module_scope.iter() {
            vm.define(k.clone(), v.clone());
        }
    } else if let Some(items) = node.children.iter().find(|c| c.kind == K::ImportItems).or_else(|| {
        node.children.iter().find(|c| c.kind == K::LeftParen).and(None)
    }) {
        import_items(vm, items, &module_scope)?;
    } else {
        // items may be inside parens; search recursively
        for c in &node.children {
            if c.kind == K::ImportItems {
                import_items(vm, c, &module_scope)?;
            }
        }
    }
    Ok(Value::None)
}

fn import_items(vm: &mut Vm, items: &SyntaxNode, scope: &Rc<Scope>) -> SourceResult<()> {
    for item in &items.children {
        let (path_node, rename) = match item.kind {
            K::ImportItemPath => (item, None),
            K::RenamedImportItem => {
                let p = item.children.iter().find(|c| c.kind == K::ImportItemPath).unwrap();
                let r = item.children.iter().rev().find(|c| c.kind == K::Ident).map(|c| c.text().to_string());
                (p, r)
            }
            _ => continue,
        };
        let idents: Vec<&SyntaxNode> = path_node.children.iter().filter(|c| c.kind == K::Ident).collect();
        let mut current: Value = Value::Module(Rc::new(Module { name: Rc::from(""), scope: scope.clone(), content: None }));
        for (i, id) in idents.iter().enumerate() {
            let span = vm.span(id);
            let s = match &current {
                Value::Module(m) => m.scope.clone(),
                Value::Func(f) => {
                    let mut sc = Scope::new();
                    if let Some(v) = crate::library::func_scope_get(f, id.text()) {
                        sc.define(id.text(), v);
                    }
                    Rc::new(sc)
                }
                v => {
                    let prev = idents[i - 1];
                    bail!(vm.span(prev), "expected module, function, or type, found {}", v.type_name())
                }
            };
            match s.get(id.text()) {
                Some(v) => current = v.clone(),
                None => bail!(span, "unresolved import"),
            }
        }
        let name = rename.unwrap_or_else(|| idents.last().map(|i| i.text().to_string()).unwrap_or_default());
        vm.define(name.as_str(), current);
    }
    Ok(())
}

pub fn eval_include(vm: &mut Vm, node: &SyntaxNode) -> SourceResult<Value> {
    let source_node = node.children.iter().find(|c| is_expr_kind(c.kind)).unwrap();
    let span = vm.span(source_node);
    let source = vm.eval_expr(source_node)?;
    match source {
        Value::Str(path) => {
            let m = load_module_from_path(vm, &path, span)?;
            Ok(Value::Content(m.content.clone().unwrap_or_else(crate::content::Content::empty)))
        }
        Value::Module(m) => Ok(Value::Content(m.content.clone().unwrap_or_else(crate::content::Content::empty))),
        v => bail!(span, "expected path or module, found {}", v.type_name()),
    }
}

pub fn eval_string(engine: &mut Engine, args: &mut Args) -> SourceResult<Value> {
    let source = args.expect("source", &STR)?;
    let mode = args.named("mode", &Cast::Strs(&["code", "markup", "math"]))?;
    let scope = args.named("scope", &DICT)?;
    args.finish()?;
    let text = source.as_str().unwrap().to_string();
    let mode = mode.as_ref().and_then(|m| m.as_str().map(|s| s.to_string())).unwrap_or_else(|| "code".into());
    let root = match mode.as_str() {
        "markup" => crate::syntax::parser::parse(&text),
        "math" => crate::syntax::parser::parse_math(&text),
        _ => crate::syntax::parser::parse_code(&text),
    };
    let errs = syntax_errors(&root, 0);
    if !errs.is_empty() {
        return Err(errs);
    }
    let std = engine.std.clone();
    let ctx = engine.context.clone();
    let mut vm = Vm { engine, scopes: Scopes::new(Some(std)), flow: None, file: 0, context: ctx };
    if let Some(Value::Dict(d)) = scope {
        for (k, v) in d.iter() {
            vm.define(k.clone(), v.clone());
        }
    }
    let v = match mode.as_str() {
        "markup" => Value::Content(vm.eval_markup(&root)?),
        "math" => Value::Content(
            crate::content::Content::new(&crate::elements::EQUATION)
                .with("block", false)
                .with("body", crate::math::eval_math_node(&mut vm, &root)?),
        ),
        _ => vm.eval_code(&root)?,
    };
    if let Some(flow) = vm.flow.take() {
        match flow {
            crate::eval::Flow::Break(s) => bail!(s, "cannot break outside of loop"),
            crate::eval::Flow::Continue(s) => bail!(s, "cannot continue outside of loop"),
            crate::eval::Flow::Return(s, _) => bail!(s, "cannot return outside of function"),
        }
    }
    Ok(v)
}
