//! Data loading.

use crate::cast::*;
use crate::diag::*;
use crate::eval::Engine;
use crate::func::Args;
use crate::value::*;
use std::rc::Rc;

pub fn check_file_access(engine: &Engine, path: &str, span: Span) -> SourceResult<std::path::PathBuf> {
    if !engine.world.allow_fs {
        bail!(span, "cannot access file system from here");
    }
    let file = engine.world.main.unwrap_or(0);
    let p = engine.world.resolve(file, path).at(span)?;
    Ok(p)
}

fn load(engine: &mut Engine, args: &mut Args, what: &str) -> SourceResult<(Vec<u8>, Span)> {
    let a = match args.eat_raw() {
        Some(a) => a,
        None => return Err(args.missing_argument(what)),
    };
    match a.value {
        Value::Str(path) => {
            let p = check_file_access(engine, &path, a.value_span)?;
            let bytes = engine.world.read_file(&p).at(a.value_span)?;
