pub fn call(engine: &mut Engine, name: &str, args: &mut Args) -> SourceResult<Value> {
    match name {
        "read" => {
            let a = match args.eat_raw() {
                Some(a) => a,
                None => return Err(args.missing_argument("path")),
            };
            let enc = args.named("encoding", &Cast::Opt(&Cast::Strs(&["utf8"])))?;
            args.finish()?;
            let path = STR.cast(a.value).at(a.value_span)?;
            let p = check_file_access(engine, path.as_str().unwrap(), a.value_span)?;
            let bytes = engine.world.read_file(&p).at(a.value_span)?;
            if matches!(enc, Some(Value::None)) {
                return Ok(Value::Bytes(Rc::new(bytes)));
            }
            match String::from_utf8(bytes) {
                Ok(s) => Ok(Value::str(s)),
                Err(_) => bail!(a.value_span, "file is not valid utf-8"),
            }
        }
        "json" => {
            let (bytes, span) = load(engine, args, "source")?;
            args.finish()?;
            let s = String::from_utf8(bytes).map_err(|_| HintedString::new("file is not valid utf-8")).at(span)?;
            let mut p = JsonParser { s: s.as_bytes(), i: 0 };
            p.ws();
            let v = p.value().map_err(|e| HintedString::new(format!("failed to parse JSON ({e})"))).at(span)?;
            p.ws();
            if p.i < p.s.len() {
                bail!(span, "failed to parse JSON (trailing characters at line {} column {})", p.line(), p.col());
            }
            Ok(v)
        }
        "csv" => {
            let (bytes, span) = load(engine, args, "source")?;
            let delim = args.named("delimiter", &STR)?;
            let row_type = args.named("row-type", &ANY)?;
            args.finish()?;
            let s = String::from_utf8(bytes).map_err(|_| HintedString::new("file is not valid utf-8")).at(span)?;
            let d = delim.as_ref().and_then(|v| v.as_str()).and_then(|s| s.chars().next()).unwrap_or(',');
            let rows = parse_csv(&s, d);
            let dict_rows = matches!(&row_type, Some(Value::Type(Type::Dict)));
            if dict_rows {
                let mut it = rows.into_iter();
                let header = it.next().unwrap_or_default();
                let mut out = vec![];
                for r in it {
                    let mut dd = Dict::new();
                    for (k, v) in header.iter().zip(r.iter()) {
                        dd.insert(Rc::from(k.as_str()), Value::str(v));
                    }
                    out.push(Value::dict(dd));
                }
                return Ok(Value::array(out));
            }
            Ok(Value::array(
                rows.into_iter().map(|r| Value::array(r.into_iter().map(Value::str).collect())).collect(),
            ))
        }
        "yaml" | "toml" | "xml" | "cbor" => {
            let (_bytes, span) = load(engine, args, "source")?;
            let _ = args.take();
            bail!(span, "failed to parse {} (unsupported)", name.to_uppercase())
        }
        _ => bail!(args.span, "unknown data function"),
    }
}

fn parse_csv(s: &str, d: char) -> Vec<Vec<String>> {
    let mut rows = vec![];
    let mut row = vec![];
    let mut field = String::new();
    let mut in_q = false;
    let mut chars = s.chars().peekable();
    let mut any = false;
    while let Some(c) = chars.next() {
        any = true;
        if in_q {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    field.push('"');
                    chars.next();
                } else {
                    in_q = false;
                }
            } else {
                field.push(c);
            }
        } else if c == '"' {
            in_q = true;
        } else if c == d {
            row.push(std::mem::take(&mut field));
        } else if c == '\n' || c == '\r' {
            if c == '\r' && chars.peek() == Some(&'\n') {
                chars.next();
            }
            row.push(std::mem::take(&mut field));
            rows.push(std::mem::take(&mut row));
            any = false;
        } else {
            field.push(c);
        }
    }
    if any {
        row.push(field);
        rows.push(row);
    }
    rows
}

