//! Realization helpers (counters, states).

use crate::eval::Engine;
use crate::value::*;

pub fn counter_value_at(engine: &Engine, c: &Counter, loc: Option<Location>) -> Vec<u64> {
    match &c.0 {
        CounterKey::Page => {
            let page = match loc {
                Some(l) => engine.introspector.page_of(l),
                None => engine.introspector.pages.max(1),
            };
            vec![page as u64]
        }
        CounterKey::Selector(sel) => {
            let elems = engine.introspector.query(sel);
            let upto: Vec<_> = match loc {
                Some(l) => {
                    let pos = engine.introspector.position(l).unwrap_or(usize::MAX);
                    elems
                        .into_iter()
                        .filter(|e| e.location().and_then(|x| engine.introspector.position(x)).unwrap_or(0) <= pos)
                        .collect()
                }
                None => elems,
            };
            let is_heading = matches!(sel, Selector::Elem(e, _) if e.name == "heading");
            if is_heading {
                let mut nums: Vec<u64> = vec![];
                for h in upto {
                    let level = match h.get("level").or_else(|| h.get("depth")) {
                        Some(Value::Int(l)) => *l as usize,
                        _ => 1,
                    };
                    if nums.len() < level {
                        nums.resize(level, 0);
                    }
                    nums.truncate(level);
                    nums[level - 1] += 1;
                }
                if nums.is_empty() {
                    vec![0]
                } else {
                    nums
                }
            } else {
                vec![upto.len() as u64]
            }
        }
        CounterKey::Str(_) => vec![0],
    }
}

pub fn state_value_at(engine: &Engine, s: &State, loc: Option<Location>) -> Value {
    let _ = (engine, loc);
    s.init.clone()
}
