/// Shortest-roundtrip float formatting in the style of `ryu`.
pub fn ryu_format(f: f64) -> String {
    if f == 0.0 {
        return if f.is_sign_negative() { "-0.0".into() } else { "0.0".into() };
    }
    let s = format!("{:e}", f.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    let olength = digits.len() as i32;
    let kk = exp + 1;
    let k = kk - olength;
    let body = if 0 <= k && kk <= 16 {
        format!("{}{}.0", digits, "0".repeat(k as usize))
    } else if 0 < kk && kk <= 16 {
        format!("{}.{}", &digits[..kk as usize], &digits[kk as usize..])
    } else if -5 < kk && kk <= 0 {
        format!("0.{}{}", "0".repeat((-kk) as usize), digits)
    } else if olength == 1 {
        format!("{}e{}", digits, kk - 1)
    } else {
        format!("{}.{}e{}", &digits[..1], &digits[1..], kk - 1)
    };
    if f < 0.0 {
        format!("-{body}")
    } else {
        body
    }
}

fn json_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

fn json_scalar(s: &Ser, out: &mut String) -> bool {
    match s {
        Ser::Null => out.push_str("null"),
        Ser::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Ser::Int(i) => out.push_str(&i.to_string()),
        Ser::Float(f) => {
            if f.is_finite() {
                out.push_str(&ryu_format(*f))
            } else {
                out.push_str("null")
            }
        }
        Ser::Str(s) => json_str(s, out),
        _ => return false,
    }
    true
}

pub fn to_json(s: &Ser, pretty: bool) -> String {
    let mut out = String::new();
    write_json(s, pretty, 0, &mut out);
    out
}

fn write_json(s: &Ser, pretty: bool, indent: usize, out: &mut String) {
    if json_scalar(s, out) {
        return;
    }
    match s {
        Ser::Seq(items) => {
            if items.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, it) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&"  ".repeat(indent + 1));
                }
                write_json(it, pretty, indent + 1, out);
            }
            if pretty {
                out.push('\n');
                out.push_str(&"  ".repeat(indent));
            }
            out.push(']');
        }
        Ser::Map(items) => {
            if items.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push('{');
            for (i, (k, v)) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                if pretty {
                    out.push('\n');
                    out.push_str(&"  ".repeat(indent + 1));
                }
                json_str(k, out);
                out.push(':');
                if pretty {
                    out.push(' ');
                }
                write_json(v, pretty, indent + 1, out);
            }
            if pretty {
                out.push('\n');
                out.push_str(&"  ".repeat(indent));
            }
            out.push('}');
        }
        _ => {}
    }
}

// ---------------- YAML ----------------

fn is_yaml_null(s: &str) -> bool {
    matches!(s, "" | "~" | "null" | "Null" | "NULL")
}

fn is_yaml_bool(s: &str) -> bool {
    matches!(s, "true" | "True" | "TRUE" | "false" | "False" | "FALSE")
}

fn is_yaml_int(s: &str) -> bool {
    let t = s.strip_prefix(['+', '-']).unwrap_or(s);
    if t.is_empty() {
        return false;
    }
    if let Some(h) = t.strip_prefix("0x") {
        return !h.is_empty() && h.chars().all(|c| c.is_ascii_hexdigit());
    }
    if let Some(o) = t.strip_prefix("0o") {
        return !o.is_empty() && o.chars().all(|c| ('0'..='7').contains(&c));
    }
    if let Some(b) = t.strip_prefix("0b") {
        return !b.is_empty() && b.chars().all(|c| c == '0' || c == '1');
    }
    t.chars().all(|c| c.is_ascii_digit())
}

fn is_yaml_float(s: &str) -> bool {
    let t = s.strip_prefix(['+', '-']).unwrap_or(s);
    if matches!(t, ".inf" | ".Inf" | ".INF") || matches!(s, ".nan" | ".NaN" | ".NAN") {
        return true;
    }
    // [-+]? ( \. [0-9]+ | [0-9]+ ( \. [0-9]* )? ) ( [eE] [-+]? [0-9]+ )?
    let b = t.as_bytes();
    let mut i = 0;
    let mut digits = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
        digits += 1;
    }
    if i < b.len() && b[i] == b'.' {
        i += 1;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
            digits += 1;
        }
    }
    if digits == 0 {
        return false;
    }
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        i += 1;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            i += 1;
        }
        let st = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == st {
            return false;
        }
    }
    i == b.len()
}

#[derive(PartialEq)]
enum Style {
    Plain,
    Single,
    Double,
}

fn yaml_style(s: &str) -> Style {
    let needs_single = is_yaml_null(s) || is_yaml_bool(s) || is_yaml_int(s) || is_yaml_float(s);
    // special characters require double quotes
    let special = s.chars().any(|c| {
        let u = c as u32;
        !(c == '\n' || c == '\r' || (0x20..=0x7e).contains(&u) || (u >= 0xa0 && u <= 0xd7ff) || (0xe000..=0xfffd).contains(&u) || u >= 0x10000) || u == 0xfeff
    }) || s.contains('\t');
    if special {
        return Style::Double;
    }
    if needs_single {
        return Style::Single;
    }
    let chars: Vec<char> = s.chars().collect();
    let first = chars[0];
    if s.starts_with("---") || s.starts_with("...") {
        return Style::Single;
    }
    if matches!(first, '#' | ',' | '[' | ']' | '{' | '}' | '&' | '*' | '!' | '|' | '>' | '\'' | '"' | '%' | '@' | '`') {
        return Style::Single;
    }
    if matches!(first, '-' | '?' | ':') {
        if chars.len() == 1 || chars[1] == ' ' {
            return Style::Single;
        }
    }
    if first == ' ' || *chars.last().unwrap() == ' ' {
        return Style::Single;
    }
    for i in 0..chars.len() {
        let c = chars[i];
        let next = chars.get(i + 1).copied();
        if c == ':' && (next.is_none() || next == Some(' ')) {
            return Style::Single;
        }
        if c == '#' && i > 0 && chars[i - 1] == ' ' {
            return Style::Single;
        }
        if matches!(c, ',' | '[' | ']' | '{' | '}' | '?') && false {
            return Style::Single;
        }
    }
    Style::Plain
}

fn yaml_scalar_str(s: &str) -> String {
    match yaml_style(s) {
        Style::Plain => s.to_string(),
        Style::Single => format!("'{}'", s.replace('\'', "''")),
        Style::Double => {
            let mut out = String::from("\"");
            for c in s.chars() {
                match c {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    '\t' => out.push_str("\\t"),
                    '\0' => out.push_str("\\0"),
                    '\u{7}' => out.push_str("\\a"),
                    '\u{8}' => out.push_str("\\b"),
                    '\u{b}' => out.push_str("\\v"),
                    '\u{c}' => out.push_str("\\f"),
                    '\r' => out.push_str("\\r"),
                    '\n' => out.push_str("\\n"),
                    '\u{1b}' => out.push_str("\\e"),
                    '\u{85}' => out.push_str("\\N"),
                    '\u{a0}' => out.push_str("\\_"),
                    '\u{2028}' => out.push_str("\\L"),
                    '\u{2029}' => out.push_str("\\P"),
                    c if (c as u32) < 0x20 || (0x7f..0xa0).contains(&(c as u32)) => out.push_str(&format!("\\x{:02X}", c as u32)),
                    c if c as u32 == 0xfeff => out.push_str("\\uFEFF"),
                    c => out.push(c),
                }
            }
            out.push('"');
            out
        }
    }
}

fn yaml_scalar(s: &Ser) -> Option<String> {
    Some(match s {
        Ser::Null => "null".into(),
        Ser::Bool(b) => b.to_string(),
        Ser::Int(i) => i.to_string(),
        Ser::Float(f) => {
            if f.is_nan() {
                ".nan".into()
            } else if f.is_infinite() {
                if *f > 0.0 { ".inf".into() } else { "-.inf".into() }
            } else {
                ryu_format(*f)
            }
        }
        Ser::Str(s) => {
            if s.contains('\n') {
                return None;
            }
            yaml_scalar_str(s)
        }
        Ser::Seq(v) if v.is_empty() => "[]".into(),
        Ser::Map(v) if v.is_empty() => "{}".into(),
        _ => return None,
    })
}

fn literal_block(s: &str, indent: usize) -> String {
    let chomp = if s.ends_with("\n\n") || (s.ends_with('\n') && s.trim_end_matches('\n').is_empty()) {
        "+"
    } else if s.ends_with('\n') {
        ""
    } else {
        "-"
    };
    let ind_indicator = if s.starts_with(' ') { "2" } else { "" };
    let mut out = format!("|{ind_indicator}{chomp}");
    let body = if chomp == "" { &s[..s.len() - 1] } else if chomp == "+" { s.strip_suffix('\n').unwrap_or(s) } else { s };
    for line in body.split('\n') {
        out.push('\n');
        if !line.is_empty() {
            out.push_str(&" ".repeat(indent));
            out.push_str(line);
        }
    }
    out
}

pub fn to_yaml(s: &Ser) -> String {
    let mut out = String::new();
    match s {
        Ser::Str(st) if st.contains('\n') => {
            out.push_str(&literal_block(st, 2));
            out.push('\n');
        }
        _ => {
            if let Some(sc) = yaml_scalar(s) {
                out.push_str(&sc);
                out.push('\n');
            } else {
                write_yaml_block(s, 0, &mut out, false);
            }
        }
    }
    out
}

/// Write a block collection at the given indent. `inline_first` means the first
/// line continues the current line (after "- ").
fn write_yaml_block(s: &Ser, indent: usize, out: &mut String, inline_first: bool) {
    let pad = " ".repeat(indent);
    match s {
        Ser::Seq(items) => {
            for (i, it) in items.iter().enumerate() {
                if !(i == 0 && inline_first) {
                    out.push_str(&pad);
                }
                out.push_str("- ");
                write_yaml_value(it, indent + 2, out, true);
            }
        }
        Ser::Map(items) => {
            for (i, (k, v)) in items.iter().enumerate() {
                if !(i == 0 && inline_first) {
                    out.push_str(&pad);
                }
                let key = if k.contains('\n') { format!("? {}", yaml_scalar_str(k)) } else { yaml_scalar_str(k) };
                out.push_str(&key);
                out.push(':');
                match v {
                    Ser::Seq(x) if !x.is_empty() => {
                        out.push('\n');
                        write_yaml_block(v, indent, out, false);
                    }
                    Ser::Map(x) if !x.is_empty() => {
                        out.push('\n');
                        write_yaml_block(v, indent + 2, out, false);
                    }
                    _ => {
                        out.push(' ');
                        write_yaml_value(v, indent + 2, out, false);
                    }
                }
            }
        }
        _ => {}
    }
}

fn write_yaml_value(v: &Ser, indent: usize, out: &mut String, in_seq: bool) {
    match v {
        Ser::Str(s) if s.contains('\n') => {
            out.push_str(&literal_block(s, indent));
            out.push('\n');
        }
        Ser::Seq(x) if !x.is_empty() => {
            if in_seq {
                write_yaml_block(v, indent, out, true);
            } else {
                out.push('\n');
                write_yaml_block(v, indent, out, false);
            }
        }
        Ser::Map(x) if !x.is_empty() => {
            if in_seq {
                write_yaml_block(v, indent, out, true);
            } else {
                out.push('\n');
                write_yaml_block(v, indent, out, false);
            }
        }
        _ => {
            out.push_str(&yaml_scalar(v).unwrap_or_default());
            out.push('\n');
        }
    }
}
