/// Display width of the prefix of `line` up to char index `ci` (tab-aware).
fn display_col(line: &str, ci: usize) -> usize {
    let mut col = 0;
    for (i, c) in line.chars().enumerate() {
        if i >= ci {
            break;
        }
        if c == '\t' {
            col += 2 - (col % 2);
        } else {
            col += crate::unicode::char_width(c);
        }
    }
    col
}

