        }
    }
}

fn render_one(world: &World, kind: Kind, message: &str, span: Span, hints: &[String], colors: &Colors, out: &mut String) {
    let (name, hcode, lcode) = match kind {
        Kind::Error => ("error", "\x1b[1m\x1b[38;5;9m", "\x1b[31m"),
        Kind::Warning => ("warning", "\x1b[1m\x1b[38;5;11m", "\x1b[33m"),
        Kind::Help => ("help", "\x1b[1m\x1b[38;5;14m", "\x1b[36m"),
    };
