        out.push_str(&format!("\x1b[0m{hcode}{name}\x1b[0m\x1b[1m: {message}\x1b[0m\n"));
    } else {
        out.push_str(&format!("{name}: {message}\n"));
    }
    let src = if span.is_detached() { None } else { world.source(span.file) };
    let Some(src) = src else {
        for h in hints {
            out.push_str(&format!(" {} hint: {}\n", colors.blue("="), h));
        }
        out.push('\n');
        return;
    };
