        let line = src.line_text(start_line);
        let ls = src.line_starts[start_line];
        let s_ci = char_index(line, start - ls);
        let e_ci = char_index(line, end - ls).max(s_ci);
        let chars: Vec<char> = line.chars().collect();
        let before: String = chars[..s_ci.min(chars.len())].iter().collect();
        let mid: String = chars[s_ci.min(chars.len())..e_ci.min(chars.len())].iter().collect();
        let after: String = chars[e_ci.min(chars.len())..].iter().collect();
        let text = if colors.on && !mid.is_empty() {
            format!("{}{}{}", tab_expand(&before), label(&tab_expand(&mid)), tab_expand(&after))
        } else {
            tab_expand(line)
        };
        out.push_str(&format!("{} {} {}\n", lineno(start_line), bar, text));
        let c0 = display_col(line, s_ci);
        let c1 = display_col(line, e_ci);
        let n = (c1 - c0).max(1);
        out.push_str(&format!("{}{} {}{}\n", pad, bar, " ".repeat(c0), label(&"^".repeat(n))));
    } else {
        out.push_str(&format!("{}{}  \n", pad, bar));
        let first = src.line_text(start_line);
        let ls = src.line_starts[start_line];
        let s_ci = char_index(first, start - ls);
        let inline_top = first.chars().take(s_ci).all(char::is_whitespace);
        if inline_top {
            let text = if colors.on {
                let chars: Vec<char> = first.chars().collect();
                let b: String = chars[..s_ci].iter().collect();
                let m: String = chars[s_ci..].iter().collect();
                format!("{}{}", tab_expand(&b), label(&tab_expand(&m)))
            } else {
                tab_expand(first)
            };
            out.push_str(&format!("{} {} {} {}\n", lineno(start_line), bar, label("╭"), text));
        } else {
            let text = if colors.on {
                let chars: Vec<char> = first.chars().collect();
                let b: String = chars[..s_ci].iter().collect();
                let m: String = chars[s_ci..].iter().collect();
                format!("{}{}", tab_expand(&b), label(&tab_expand(&m)))
            } else {
                tab_expand(first)
            };
            out.push_str(&format!("{} {}   {}\n", lineno(start_line), bar, text));
            let c0 = display_col(first, s_ci);
            let top = format!("{}{}", "─".repeat(c0 + 1), "^");
            if colors.on {
                out.push_str(&format!("{}{} {}{}\n", pad, bar, label("╭"), label(&top)));
            } else {
                out.push_str(&format!("{}{} ╭{}\n", pad, bar, top));
            }
        }
        for l in start_line + 1..=end_line {
            let t = src.line_text(l);
            let text = if colors.on && l == end_line {
                let le = src.line_starts[l];
                let e_ci = char_index(t, end - le);
                let chars: Vec<char> = t.chars().collect();
                let m: String = chars[..e_ci.min(chars.len())].iter().collect();
                let a: String = chars[e_ci.min(chars.len())..].iter().collect();
                format!("{}{}", label(&tab_expand(&m)), tab_expand(&a))
            } else if colors.on {
                label(&tab_expand(t))
            } else {
                tab_expand(t)
            };
            out.push_str(&format!("{} {} {} {}\n", lineno(l), bar, label("│"), text));
        }
        let last = src.line_text(end_line);
        let le = src.line_starts[end_line];
        let e_ci = char_index(last, end - le);
        let c_last = display_col(last, e_ci.saturating_sub(1));
        let bottom = format!("{}{}", "─".repeat(c_last + 1), "^");
        if colors.on {
            out.push_str(&format!("{}{} {}{}\n", pad, bar, label("╰"), label(&bottom)));
        } else {
            out.push_str(&format!("{}{} ╰{}\n", pad, bar, bottom));
        }
    }
    if !hints.is_empty() {
        out.push_str(&format!("{}{}\n", pad, bar));
        for h in hints {
            out.push_str(&format!("{}{} hint: {}\n", pad, colors.blue("="), h));
        }
    }
    out.push('\n');
}

pub fn render_short(world: &World, diags: &[Diag], out: &mut String) {
    for d in diags {
        let sev = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        short_one(world, sev, &d.message, d.span, out);
        for (span, msg) in &d.trace {
            short_one(world, "help", msg, *span, out);
        }
    }
}

fn short_one(world: &World, sev: &str, msg: &str, span: Span, out: &mut String) {
    match if span.is_detached() { None } else { world.source(span.file) } {
        Some(src) => {
            let start = (span.start as usize).min(src.text.len());
            let line = src.line_of(start);
            let col = src.column_of(start);
            out.push_str(&format!("{}:{}:{}: {}: {}\n", src.display, line + 1, col, sev, msg));
        }
        None => out.push_str(&format!("{}: {}\n", sev, msg)),
    }
}
