//! Command line interface.

use crate::diag::*;
use crate::eval::{ContextInfo, Engine, Scopes, Vm};
use crate::render::Colors;
use crate::value::*;
use std::io::Write;
use std::path::PathBuf;
use std::rc::Rc;

pub struct Common {
    pub diag_format_short: bool,
    pub color: bool,
    pub inputs: Vec<(String, String)>,
    pub root: Option<String>,
}

pub fn make_engine(world: crate::world::World, inputs: &[(String, String)]) -> Engine {
    let mut d = Dict::new();
    for (k, v) in inputs {
        d.insert(Rc::from(k.as_str()), Value::str(v));
    }
    let std = Rc::new(crate::library::std_scope(d));
    let math = Rc::new(crate::math::math_module_scope());
    Engine {
        std,
        math,
        warnings: vec![],
        depth: 0,
        world,
        introspector: Rc::new(crate::introspect::Introspector::empty()),
        context: ContextInfo::default(),
        html: false,
    }
}

pub fn print_diags(engine: &Engine, diags: &[Diag], common: &Common) {
    let mut out = String::new();
    if common.diag_format_short {
        crate::render::render_short(&engine.world, diags, &mut out);
    } else {
        crate::render::render_human(&engine.world, diags, &Colors { on: common.color }, &mut out);
    }
    let _ = std::io::stderr().write_all(out.as_bytes());
}

pub fn run() -> i32 {
    let args: Vec<String> = std::env::args().collect();
    crate::cliargs::dispatch(args)
}

pub fn run_eval(
    expr: &str,
    input: Option<String>,
    format_yaml: bool,
    pretty: bool,
    common: &Common,
) -> i32 {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let mut world = crate::world::World::new(cwd.clone());
    world.allow_fs = false;
    let mut doc_id = None;
    if let Some(path) = &input {
        let (text, abs) = if path == "-" {
            let mut s = String::new();
            let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut s);
            (s, cwd.join("<stdin>"))
        } else {
            let abs = crate::world::normalize(&cwd.join(path));
            match std::fs::read_to_string(&abs) {
                Ok(t) => (t, abs),
                Err(_) => {
                    let mut out = String::new();
                    out.push_str(&format!("error: input file not found (searched at {})\n", path));
                    let _ = std::io::stderr().write_all(out.as_bytes());
                    return 1;
                }
            }
        };
        let root = match &common.root {
            Some(r) => crate::world::normalize(&cwd.join(r)),
            None => abs.parent().map(|p| p.to_path_buf()).unwrap_or(cwd.clone()),
        };
        world.root = root;
        let display = if path == "-" { "<stdin>".to_string() } else { world.display_path(&abs) };
        let id = world.add_source(crate::world::Source::new(Some(abs), display, text));
        world.main = Some(id);
        world.allow_fs = true;
        doc_id = Some(id);
    }
    let mut engine = make_engine(world, &common.inputs);
    if let Some(id) = doc_id {
        match crate::document::compile_document(&mut engine, id) {
            Ok(_) => {}
            Err(errs) => {
                let mut all = errs;
                all.extend(engine.warnings.clone());
                print_diags(&engine, &all, common);
                return 1;
            }
        }
    }
    let root = crate::syntax::parser::parse_code(expr);
    let errs = crate::module::syntax_errors(&root, 0);
    if !errs.is_empty() {
        print_diags(&engine, &errs, common);
        return 0;
    }
    let std = engine.std.clone();
    let mut vm = Vm { engine: &mut engine, scopes: Scopes::new(Some(std)), flow: None, file: 0, context: ContextInfo::default() };
    let result = vm.eval_code(&root);
    let flow = vm.flow.take();
    let result = match (result, flow) {
        (Ok(_), Some(crate::eval::Flow::Return(s, _))) => Err(vec![Diag::error(s, "cannot return outside of function")]),
        (Ok(_), Some(crate::eval::Flow::Break(s))) => Err(vec![Diag::error(s, "cannot break outside of loop")]),
        (Ok(_), Some(crate::eval::Flow::Continue(s))) => Err(vec![Diag::error(s, "cannot continue outside of loop")]),
        (r, _) => r,
    };
    match result {
        Ok(v) => {
            let ser = crate::serial::to_ser(&v);
            let s = if format_yaml { crate::serial::to_yaml(&ser) } else { crate::serial::to_json(&ser, pretty) };
            println!("{}", s);
            let _ = std::io::stdout().flush();
            let warnings = engine.warnings.clone();
            if !warnings.is_empty() {
                print_diags(&engine, &warnings, common);
            }
            0
        }
        Err(errs) => {
            let mut all = errs;
            all.extend(engine.warnings.clone());
            print_diags(&engine, &all, common);
            0
        }
    }
}
