//! A small clap-like argument parser for the CLI.

use std::collections::HashMap;
use std::io::Write;

#[derive(Clone)]
pub struct ArgSpec {
    pub id: &'static str,
    pub long: Option<&'static str>,
    pub short: Option<char>,
    pub value_name: &'static str,
    pub takes_value: bool,
    pub optional_value: bool,
    pub possible: &'static [&'static str],
    pub multiple: bool,
    pub env: Option<&'static str>,
    pub delimiter: Option<char>,
}

const fn flag(id: &'static str, long: &'static str) -> ArgSpec {
    ArgSpec { id, long: Some(long), short: None, value_name: "", takes_value: false, optional_value: false, possible: &[], multiple: false, env: None, delimiter: None }
}

const fn opt(id: &'static str, long: &'static str, vn: &'static str) -> ArgSpec {
    ArgSpec { id, long: Some(long), short: None, value_name: vn, takes_value: true, optional_value: false, possible: &[], multiple: false, env: None, delimiter: None }
}

pub struct PosSpec {
    pub id: &'static str,
    pub name: &'static str,
    pub required: bool,
    pub possible: &'static [&'static str],
}

pub struct CmdSpec {
    pub name: &'static str,
    pub aliases: &'static [&'static str],
    pub opts: Vec<ArgSpec>,
    pub pos: Vec<PosSpec>,
}

#[derive(Default, Debug)]
pub struct Matches {
    pub values: HashMap<&'static str, Vec<String>>,
    pub flags: HashMap<&'static str, bool>,
}

impl Matches {
    pub fn get(&self, id: &str) -> Option<&String> {
        self.values.get(id).and_then(|v| v.last())
    }
    pub fn all(&self, id: &str) -> Vec<String> {
        self.values.get(id).cloned().unwrap_or_default()
    }
    pub fn flag(&self, id: &str) -> bool {
        self.flags.get(id).copied().unwrap_or(false)
    }
}

fn world_opts(with_compile: bool) -> Vec<ArgSpec> {
    let mut v = vec![];
    v.push(ArgSpec { env: Some("TYPST_ROOT"), ..opt("root", "root", "DIR") });
    v.push(ArgSpec { multiple: true, ..opt("input", "input", "key=value") });
    v.push(ArgSpec { env: Some("TYPST_FONT_PATHS"), multiple: true, delimiter: Some(':'), ..opt("font-path", "font-path", "DIR") });
    v.push(ArgSpec { env: Some("TYPST_IGNORE_SYSTEM_FONTS"), ..flag("ignore-system-fonts", "ignore-system-fonts") });
    v.push(ArgSpec { env: Some("TYPST_IGNORE_EMBEDDED_FONTS"), ..flag("ignore-embedded-fonts", "ignore-embedded-fonts") });
    v.push(ArgSpec { env: Some("TYPST_PACKAGE_PATH"), ..opt("package-path", "package-path", "DIR") });
    v.push(ArgSpec { env: Some("TYPST_PACKAGE_CACHE_PATH"), ..opt("package-cache-path", "package-cache-path", "DIR") });
    v.push(ArgSpec { env: Some("SOURCE_DATE_EPOCH"), ..opt("creation-timestamp", "creation-timestamp", "UNIX_TIMESTAMP") });
    if with_compile {
        v.push(opt("pages", "pages", "PAGES"));
        v.push(ArgSpec {
            possible: &["1.4", "1.5", "1.6", "1.7", "2.0", "a-1b", "a-1a", "a-2b", "a-2u", "a-2a", "a-3b", "a-3u", "a-3a", "a-4", "a-4f", "a-4e", "ua-1"],
            multiple: true,
            delimiter: Some(','),
            ..opt("pdf-standard", "pdf-standard", "PDF_STANDARD")
        });
        v.push(flag("no-pdf-tags", "no-pdf-tags"));
        v.push(opt("ppi", "ppi", "PPI"));
        v.push(opt("deps", "deps", "PATH"));
        v.push(ArgSpec { possible: &["json", "zero", "make"], ..opt("deps-format", "deps-format", "DEPS_FORMAT") });
    }
    v.push(ArgSpec { short: Some('j'), ..opt("jobs", "jobs", "JOBS") });
    v.push(ArgSpec { env: Some("TYPST_FEATURES"), possible: &["html", "a11y-extras"], multiple: true, delimiter: Some(','), ..opt("features", "features", "FEATURES") });
    v.push(ArgSpec { possible: &["human", "short"], ..opt("diagnostic-format", "diagnostic-format", "DIAGNOSTIC_FORMAT") });
    v
}

pub fn commands() -> Vec<CmdSpec> {
    let mut compile_opts = vec![ArgSpec { short: Some('f'), possible: &["pdf", "png", "svg", "html"], ..opt("format", "format", "FORMAT") }];
    compile_opts.extend(world_opts(true));
    let mut watch_opts = compile_opts.clone();
    compile_opts.push(ArgSpec { optional_value: true, ..opt("open", "open", "VIEWER") });
    compile_opts.push(ArgSpec { optional_value: true, ..opt("timings", "timings", "OUTPUT_JSON") });
    watch_opts.push(ArgSpec { optional_value: true, ..opt("open", "open", "VIEWER") });
    watch_opts.push(ArgSpec { optional_value: true, ..opt("timings", "timings", "OUTPUT_JSON") });
    watch_opts.push(flag("no-serve", "no-serve"));
    watch_opts.push(flag("no-reload", "no-reload"));
    watch_opts.push(opt("port", "port", "PORT"));
    let mut eval_opts = vec![
        opt("in", "in", "IN"),
        ArgSpec { possible: &["paged", "html"], ..opt("target", "target", "TARGET") },
        ArgSpec { possible: &["json", "yaml"], ..opt("format", "format", "FORMAT") },
        flag("pretty", "pretty"),
    ];
    eval_opts.extend(world_opts(false));
    let io = || {
        vec![
            PosSpec { id: "input", name: "INPUT", required: true, possible: &[] },
            PosSpec { id: "output", name: "OUTPUT", required: false, possible: &[] },
        ]
    };
    vec![
        CmdSpec { name: "compile", aliases: &["c"], opts: compile_opts, pos: io() },
        CmdSpec { name: "watch", aliases: &["w"], opts: watch_opts, pos: io() },
        CmdSpec {
            name: "init",
            aliases: &[],
            opts: vec![
                ArgSpec { env: Some("TYPST_PACKAGE_PATH"), ..opt("package-path", "package-path", "DIR") },
                ArgSpec { env: Some("TYPST_PACKAGE_CACHE_PATH"), ..opt("package-cache-path", "package-cache-path", "DIR") },
            ],
            pos: vec![
                PosSpec { id: "template", name: "TEMPLATE", required: true, possible: &[] },
                PosSpec { id: "dir", name: "DIR", required: false, possible: &[] },
            ],
        },
        CmdSpec { name: "eval", aliases: &[], opts: eval_opts, pos: vec![PosSpec { id: "expression", name: "EXPRESSION", required: true, possible: &[] }] },
        CmdSpec {
            name: "fonts",
            aliases: &[],
            opts: vec![
                ArgSpec { env: Some("TYPST_FONT_PATHS"), multiple: true, delimiter: Some(':'), ..opt("font-path", "font-path", "DIR") },
                ArgSpec { env: Some("TYPST_IGNORE_SYSTEM_FONTS"), ..flag("ignore-system-fonts", "ignore-system-fonts") },
                ArgSpec { env: Some("TYPST_IGNORE_EMBEDDED_FONTS"), ..flag("ignore-embedded-fonts", "ignore-embedded-fonts") },
                flag("variants", "variants"),
            ],
            pos: vec![],
        },
        CmdSpec {
            name: "completions",
            aliases: &[],
            opts: vec![],
            pos: vec![PosSpec { id: "shell", name: "SHELL", required: true, possible: &["bash", "elvish", "fish", "powershell", "zsh"] }],
        },
        CmdSpec {
            name: "info",
            aliases: &[],
            opts: vec![ArgSpec { short: Some('f'), possible: &["json", "yaml"], ..opt("format", "format", "FORMAT") }, flag("pretty", "pretty")],
            pos: vec![],
        },
    ]
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut am = vec![false; a.len()];
    let mut bm = vec![false; b.len()];
    let mut matches = 0.0;
    for i in 0..a.len() {
        let lo = i.saturating_sub(dist);
        let hi = (i + dist + 1).min(b.len());
        for j in lo..hi {
            if !bm[j] && a[i] == b[j] {
                am[i] = true;
                bm[j] = true;
                matches += 1.0;
                break;
            }
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    let mut t = 0.0;
    let mut k = 0;
    for i in 0..a.len() {
        if am[i] {
            while !bm[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1.0;
            }
            k += 1;
        }
    }
    let t = t / 2.0;
    (matches / a.len() as f64 + matches / b.len() as f64 + (matches - t) / matches) / 3.0
}

fn did_you_mean<'a>(v: &str, candidates: impl Iterator<Item = &'a str>) -> Vec<String> {
    let mut c: Vec<(f64, String)> = candidates
        .map(|p| (jaro(v, p), p.to_string()))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.into_iter().map(|x| x.1).collect()
}

pub fn bin_name(args: &[String]) -> String {
    args.first()
        .and_then(|a| std::path::Path::new(a).file_name().map(|f| f.to_string_lossy().to_string()))
        .unwrap_or_else(|| "typst".into())
}

fn arg_display(a: &ArgSpec) -> String {
    let base = match (a.long, a.short) {
        (Some(l), _) => format!("--{l}"),
        (None, Some(s)) => format!("-{s}"),
        _ => String::new(),
    };
    if a.takes_value {
        if a.optional_value {
            format!("{base} [<{}>]", a.value_name)
        } else {
            format!("{base} <{}>", a.value_name)
        }
    } else {
        base
    }
}

fn exit_err(msg: String) -> i32 {
    let _ = std::io::stderr().write_all(msg.as_bytes());
    2
}

pub fn full_usage(bin: &str, cmd: &CmdSpec) -> String {
    let mut s = format!("{bin} {}", cmd.name);
    if !cmd.opts.is_empty() {
        s.push_str(" [OPTIONS]");
    }
    for p in &cmd.pos {
        if p.required {
            s.push_str(&format!(" <{}>", p.name));
        } else {
            s.push_str(&format!(" [{}]", p.name));
        }
    }
    s
}

fn smart_usage(bin: &str, cmd: &CmdSpec) -> String {
    let mut s = format!("{bin} {}", cmd.name);
    for p in &cmd.pos {
        if p.required {
            s.push_str(&format!(" <{}>", p.name));
        }
    }
    s
}

pub fn parse_cmd(bin: &str, cmd: &CmdSpec, args: &[String]) -> Result<Matches, i32> {
    let mut m = Matches::default();
    let mut pos_values: Vec<String> = vec![];
    let mut used = false;
    let mut i = 0;
    let mut only_pos = false;
    while i < args.len() {
        let a = &args[i];
        i += 1;
        if only_pos {
            pos_values.push(a.clone());
            used = true;
            continue;
        }
        if a == "--" {
            only_pos = true;
            continue;
        }
        if a == "--help" || a == "-h" {
            let name = if a == "--help" { "long" } else { "short" };
            crate::cliapp::print_help(bin, cmd.name, name);
            return Err(0);
        }
        let (spec, inline): (Option<&ArgSpec>, Option<String>) = if let Some(rest) = a.strip_prefix("--") {
            let (name, inline) = match rest.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (rest, None),
            };
            match cmd.opts.iter().find(|o| o.long == Some(name)) {
                Some(s) => (Some(s), inline),
                None => {
                    let sugg = did_you_mean(name, cmd.opts.iter().filter_map(|o| o.long).chain(["help"]));
                    let mut msg = format!("error: unexpected argument '{}' found\n\n", a);
                    if let Some(s) = sugg.last() {
                        msg.push_str(&format!("  tip: a similar argument exists: '--{}'\n\n", s));
                        let usage = {
                            let mut u = format!("{bin} {}", cmd.name);
                            if let Some(o) = cmd.opts.iter().find(|o| o.long == Some(s.as_str())) {
                                u.push_str(&format!(" {}", arg_display(o)));
                            }
                            for p in &cmd.pos {
                                if p.required {
                                    u.push_str(&format!(" <{}>", p.name));
                                } else {
                                    u.push_str(&format!(" [{}]", p.name));
                                }
                            }
                            u
                        };
                        msg.push_str(&format!("Usage: {}\n\nFor more information, try '--help'.\n", usage));
                    } else {
                        msg.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", a, a));
                        let usage = if used { smart_usage(bin, cmd) } else { full_usage(bin, cmd) };
                        msg.push_str(&format!("Usage: {}\n\nFor more information, try '--help'.\n", usage));
                    }
                    return Err(exit_err(msg));
                }
            }
        } else if a.starts_with('-') && a.len() > 1 {
            let c = a.chars().nth(1).unwrap();
            match cmd.opts.iter().find(|o| o.short == Some(c)) {
                Some(s) => {
                    let rest = &a[1 + c.len_utf8()..];
                    let inline = if rest.is_empty() { None } else { Some(rest.trim_start_matches('=').to_string()) };
                    (Some(s), inline)
                }
                None => {
                    let shown = format!("-{c}");
                    let mut msg = format!("error: unexpected argument '{}' found\n\n", shown);
                    msg.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", shown, shown));
                    let usage = if used { smart_usage(bin, cmd) } else { full_usage(bin, cmd) };
                    msg.push_str(&format!("Usage: {}\n\nFor more information, try '--help'.\n", usage));
                    return Err(exit_err(msg));
                }
            }
        } else {
            pos_values.push(a.clone());
            used = true;
            continue;
        };
        let spec = spec.unwrap();
        if spec.takes_value {
            let value = match inline {
                Some(v) => Some(v),
                None => {
                    if i < args.len() && !(args[i].starts_with('-') && args[i].len() > 1) {
                        i += 1;
                        Some(args[i - 1].clone())
                    } else {
                        None
                    }
                }
            };
            let value = match value {
                Some(v) => v,
                None if spec.optional_value => String::new(),
                None => {
                    let mut msg = format!("error: a value is required for '{}' but none was supplied\n", arg_display(spec));
                    if !spec.possible.is_empty() {
                        msg.push_str(&format!("  [possible values: {}]\n", spec.possible.join(", ")));
                    }
                    msg.push_str("\nFor more information, try '--help'.\n");
                    return Err(exit_err(msg));
                }
            };
            let parts: Vec<String> = match spec.delimiter {
                Some(d) => value.split(d).map(|s| s.to_string()).collect(),
                None => vec![value],
            };
            for p in &parts {
                if !spec.possible.is_empty() && !spec.possible.contains(&p.as_str()) {
                    let mut msg = format!("error: invalid value '{}' for '{}'\n", p, arg_display(spec));
                    msg.push_str(&format!("  [possible values: {}]\n", spec.possible.join(", ")));
                    let sugg = did_you_mean(p, spec.possible.iter().copied());
                    if let Some(s) = sugg.last() {
                        msg.push_str(&format!("\n  tip: a similar value exists: '{}'\n", s));
                    }
                    msg.push_str("\nFor more information, try '--help'.\n");
                    return Err(exit_err(msg));
                }
            }
            if !spec.multiple && m.values.contains_key(spec.id) {
                let msg = format!(
                    "error: the argument '{}' cannot be used multiple times\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                    arg_display(spec),
                    full_usage(bin, cmd)
                );
                return Err(exit_err(msg));
            }
            m.values.entry(spec.id).or_default().extend(parts);
        } else {
            if m.flags.contains_key(spec.id) {
                let msg = format!(
                    "error: the argument '{}' cannot be used multiple times\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                    arg_display(spec),
                    full_usage(bin, cmd)
                );
                return Err(exit_err(msg));
            }
            m.flags.insert(spec.id, true);
        }
        used = true;
    }
    // positionals
    for (k, v) in pos_values.iter().enumerate() {
        if k < cmd.pos.len() {
            let p = &cmd.pos[k];
            if !p.possible.is_empty() && !p.possible.contains(&v.as_str()) {
                let mut msg = format!("error: invalid value '{}' for '<{}>'\n", v, p.name);
                msg.push_str(&format!("  [possible values: {}]\n", p.possible.join(", ")));
                let sugg = did_you_mean(v, p.possible.iter().copied());
                if let Some(s) = sugg.last() {
                    msg.push_str(&format!("\n  tip: a similar value exists: '{}'\n", s));
                }
                msg.push_str("\nFor more information, try '--help'.\n");
                return Err(exit_err(msg));
            }
            m.values.insert(p.id, vec![v.clone()]);
        } else {
            let msg = format!(
                "error: unexpected argument '{}' found\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                v,
                full_usage(bin, cmd)
            );
            return Err(exit_err(msg));
        }
    }
    // env fallbacks
    for o in &cmd.opts {
        if let Some(env) = o.env {
            if let Ok(val) = std::env::var(env) {
                if o.takes_value {
                    if !m.values.contains_key(o.id) && !val.is_empty() {
                        let parts: Vec<String> = match o.delimiter {
                            Some(d) => val.split(d).map(|s| s.to_string()).collect(),
                            None => vec![val],
                        };
                        m.values.insert(o.id, parts);
                    }
                } else if !m.flags.contains_key(o.id) {
                    let t = !matches!(val.as_str(), "" | "0" | "false" | "no" | "off" | "n" | "f");
                    if t {
                        m.flags.insert(o.id, true);
                    }
                }
            }
        }
    }
    // required check
    let missing: Vec<&PosSpec> = cmd.pos.iter().filter(|p| p.required && !m.values.contains_key(p.id)).collect();
    if !missing.is_empty() {
        let mut msg = String::from("error: the following required arguments were not provided:\n");
        for p in &missing {
            msg.push_str(&format!("  <{}>\n", p.name));
        }
        msg.push_str(&format!("\nUsage: {}\n\nFor more information, try '--help'.\n", smart_usage(bin, cmd)));
        return Err(exit_err(msg));
    }
    Ok(m)
}

pub fn dispatch(args: Vec<String>) -> i32 {
    crate::cliapp::main(args)
}
EOF
echo ok"}

