use crate::content::{Content, Style};
use crate::diag::*;
use crate::introspect::Introspector;

#[derive(Clone, Default)]
pub struct StyleChain {
    pub styles: Vec<Style>,
}

impl StyleChain {
    pub fn get(&self, elem: &str, field: &str) -> Option<Value> {
        for s in self.styles.iter().rev() {
            if let Style::Property { elem: e, field: f, value, .. } = s {
                if e.name == elem && *f == field {
                    return Some(value.clone());
                }
            }
        }
        None
    }
}

/// Walk the content tree, assign locations, synthesize fields for
/// locatable elements and register them in the introspector.
pub fn realize_doc(engine: &mut Engine, content: &Content, intro: &mut Introspector, pages: &mut usize) -> SourceResult<Content> {
    let chain = StyleChain::default();
    walk(engine, content, &chain, intro, pages)
}

fn synthesize(c: &Content, chain: &StyleChain) -> Content {
    let mut c = c.clone();
    let name = c.func_name();
    if name == "heading" {
        let depth = match c.get("depth") {
            Some(Value::Int(d)) => *d,
            _ => 1,
        };
        let offset = match c.get("offset").cloned().or_else(|| chain.get("heading", "offset")) {
            Some(Value::Int(o)) => o,
            _ => 0,
        };
        let level = match c.get("level").cloned().or_else(|| chain.get("heading", "level")) {
            Some(Value::Int(l)) => l,
            _ => depth + offset,
        };
        c.set("level", Value::Int(level));
        c.set("depth", Value::Int(depth));
        c.set("offset", Value::Int(offset));
        for (f, default) in [
            ("numbering", Value::None),
            ("supplement", Value::Content(Content::text("Section"))),
            ("outlined", Value::Bool(true)),
            ("bookmarked", Value::Auto),
            ("hanging-indent", Value::Auto),
        ] {
            if !c.has(f) {
                let v = chain.get("heading", f).unwrap_or(default);
                let v = if f == "supplement" && matches!(v, Value::Auto) { Value::Content(Content::text("Section")) } else { v };
                c.set(f, v);
            }
        }
    }
    c
}

fn walk(engine: &mut Engine, c: &Content, chain: &StyleChain, intro: &mut Introspector, pages: &mut usize) -> SourceResult<Content> {
    let name = c.func_name();
    match name {
        "sequence" => {
            let mut out = vec![];
            for ch in c.children() {
                out.push(walk(engine, &ch, chain, intro, pages)?);
            }
            return Ok(Content::sequence(out));
        }
        "styled" => {
            let mut chain2 = chain.clone();
            if let Some(Value::Styles(s)) = c.get("styles") {
                chain2.styles.extend(s.0.iter().cloned());
            }
            let child = match c.get("child") {
                Some(Value::Content(ch)) => walk(engine, ch, &chain2, intro, pages)?,
                _ => Content::empty(),
            };
            let mut nc = c.clone();
            nc.set("child", Value::Content(child));
            return Ok(nc);
        }
        "pagebreak" => {
            let weak = matches!(c.get("weak"), Some(Value::Bool(true)));
            if !weak {
                *pages += 1;
            }
        }
        _ => {}
    }
    let mut nc = if crate::introspect::is_locatable(c.elem()) { synthesize(c, chain) } else { c.clone() };
    // Recurse into content fields.
    let fields = nc.0.fields.clone();
    for (f, v) in fields {
        match v {
            Value::Content(inner) => {
                let r = walk(engine, &inner, chain, intro, pages)?;
                nc.set(f, Value::Content(r));
            }
            Value::Array(arr) if arr.iter().any(|x| matches!(x, Value::Content(_))) => {
                let mut out = vec![];
                for x in arr.iter() {
                    match x {
                        Value::Content(i) => out.push(Value::Content(walk(engine, i, chain, intro, pages)?)),
                        o => out.push(o.clone()),
                    }
                }
                nc.set(f, Value::array(out));
            }
            _ => {}
        }
    }
    if crate::introspect::is_locatable(nc.elem()) && nc.location().is_none() {
        nc.set_location(Location(fresh_id()));
        intro.elems.push((nc.clone(), *pages));
    }
    Ok(nc)
}
