//! CLI application entry.

use crate::cli::Common;
use crate::cliargs::*;
use std::io::Write;

static MAIN_HELP: &str = include_str!("help/main_long.txt");
static WELCOME: &str = "Welcome to Typst, we are glad to have you here! ❤️

If you are new to Typst, start with the tutorial at https://typst.app/docs/tutorial/.
To get a quick start with your first project, choose a template on https://typst.app/universe/.

Here are the most important commands you will be using:

- Compile a file once: typst compile file.typ
- Compile a file on every change: typst watch file.typ
- Set up a project from a template: typst init @preview/<TEMPLATE>

Learn more about these commands by running typst help.

If you have a question, we and our community would be glad to help you out on
the Typst Forum at https://forum.typst.app/.

Happy Typsting!
";

fn help_text(cmd: &str, kind: &str) -> Option<&'static str> {
    Some(match (cmd, kind) {
        ("compile", "long") => include_str!("help/compile_long.txt"),
        ("compile", _) => include_str!("help/compile_short.txt"),
        ("watch", "long") => include_str!("help/watch_long.txt"),
        ("watch", _) => include_str!("help/watch_short.txt"),
        ("init", "long") => include_str!("help/init_long.txt"),
        ("init", _) => include_str!("help/init_short.txt"),
        ("eval", "long") => include_str!("help/eval_long.txt"),
        ("eval", _) => include_str!("help/eval_short.txt"),
        ("fonts", "long") => include_str!("help/fonts_long.txt"),
        ("fonts", _) => include_str!("help/fonts_short.txt"),
        ("completions", "long") => include_str!("help/completions_long.txt"),
        ("completions", _) => include_str!("help/completions_short.txt"),
        ("info", "long") => include_str!("help/info_long.txt"),
        ("info", _) => include_str!("help/info_short.txt"),
        _ => return None,
    })
}

fn subst(s: &str, bin: &str) -> String {
    s.replace("Usage: executable", &format!("Usage: {bin}"))
}

pub fn print_help(bin: &str, cmd: &str, kind: &str) {
    if let Some(t) = help_text(cmd, kind) {
        let _ = std::io::stdout().write_all(subst(t, bin).as_bytes());
    }
}

const VERSION: &str = "typst 0.14.2 (97ac4370)";

pub fn main(args: Vec<String>) -> i32 {
    let bin = bin_name(&args);
    let mut i = 1;
    let mut color = "auto".to_string();
    let main_usage = format!("{bin} [OPTIONS] <COMMAND>");
    while i < args.len() {
        let a = &args[i];
        if a == "--help" || a == "-h" {
            let _ = std::io::stdout().write_all(subst(MAIN_HELP, &bin).as_bytes());
            return 0;
        }
        if a == "--version" || a == "-V" {
            println!("{VERSION}");
            return 0;
        }
        if a == "--color" || a.starts_with("--color=") {
            let v = if let Some(v) = a.strip_prefix("--color=") {
                Some(v.to_string())
            } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                i += 1;
                Some(args[i].clone())
            } else {
                None
            };
            match v {
                Some(v) if matches!(v.as_str(), "auto" | "always" | "never") => color = v,
                Some(v) => {
                    let msg = format!("error: invalid value '{v}' for '--color <COLOR>'\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n");
                    let _ = std::io::stderr().write_all(msg.as_bytes());
                    return 2;
                }
                None => {
                    let msg = "error: a value is required for '--color <COLOR>' but none was supplied\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n";
                    let _ = std::io::stderr().write_all(msg.as_bytes());
                    return 2;
                }
            }
            i += 1;
            continue;
        }
        if a == "--cert" || a.starts_with("--cert=") {
            if !a.contains('=') {
                i += 1;
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') {
            let shown = if a.starts_with("--") { a.split('=').next().unwrap().to_string() } else { a.chars().take(2).collect() };
            let sugg = if a.starts_with("--") {
                let name = &shown[2..];
                let mut best: Option<&str> = None;
                let mut best_score = 0.7;
                for c in ["color", "cert", "help", "version"] {
                    let s = jaro_pub(name, c);
                    if s > best_score {
                        best_score = s;
                        best = Some(c);
                    }
                }
                best
            } else {
                None
            };
            let mut msg = format!("error: unexpected argument '{shown}' found\n\n");
            match sugg {
                Some(s) => {
                    msg.push_str(&format!("  tip: a similar argument exists: '--{s}'\n\n"));
                    msg.push_str(&format!("Usage: {bin} <--color <COLOR>|--cert <CERT>> <COMMAND>\n\nFor more information, try '--help'.\n"));
                }
                None => {
                    if a.starts_with("--") {
                        msg.push_str(&format!("  tip: to pass '{shown}' as a value, use '-- {shown}'\n\n"));
                    }
                    msg.push_str(&format!("Usage: {main_usage}\n\nFor more information, try '--help'.\n"));
                }
            }
            let _ = std::io::stderr().write_all(msg.as_bytes());
            return 2;
        }
        break;
    }
    if i >= args.len() {
        print!("{WELCOME}");
        return 0;
    }
    let sub = args[i].clone();
    let rest = &args[i + 1..];
    let cmds = commands();
    if sub == "help" {
        if rest.is_empty() {
            let _ = std::io::stdout().write_all(subst(MAIN_HELP, &bin).as_bytes());
            return 0;
        }
        let name = &rest[0];
        let resolved = cmds.iter().find(|c| c.name == name.as_str() || c.aliases.contains(&name.as_str()));
        match resolved {
            Some(c) => {
                print_help(&bin, c.name, "long");
                return 0;
            }
            None if name == "help" => {
                println!("Print this message or the help of the given subcommand(s)\n\nUsage: {bin} help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)");
                return 0;
            }
            None => {
                let msg = format!("error: unrecognized subcommand '{name}'\n\nUsage: {main_usage}\n\nFor more information, try '--help'.\n");
                let _ = std::io::stderr().write_all(msg.as_bytes());
                return 2;
            }
        }
    }
    let Some(cmd) = cmds.iter().find(|c| c.name == sub.as_str() || c.aliases.contains(&sub.as_str())) else {
        let mut cands: Vec<(f64, &str)> = vec![];
        for c in &cmds {
            for n in std::iter::once(c.name).chain(c.aliases.iter().copied()) {
                let s = jaro_pub(&sub, n);
                if s > 0.7 {
                    cands.push((s, n));
                }
            }
        }
        for n in ["help"] {
            let s = jaro_pub(&sub, n);
            if s > 0.7 {
                cands.push((s, n));
            }
        }
        cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap().then(a.1.cmp(b.1)));
        let mut msg = format!("error: unrecognized subcommand '{sub}'\n\n");
        if cands.len() == 1 {
            msg.push_str(&format!("  tip: a similar subcommand exists: '{}'\n\n", cands[0].1));
        } else if cands.len() > 1 {
            let mut names: Vec<&str> = cands.iter().map(|c| c.1).collect();
            names.sort();
            let list: Vec<String> = names.iter().map(|n| format!("'{n}'")).collect();
            msg.push_str(&format!("  tip: some similar subcommands exist: {}\n\n", list.join(", ")));
        }
        msg.push_str(&format!("Usage: {main_usage}\n\nFor more information, try '--help'.\n"));
        let _ = std::io::stderr().write_all(msg.as_bytes());
        return 2;
    };
    let m = match parse_cmd(&bin, cmd, rest) {
        Ok(m) => m,
        Err(code) => return code,
    };
    let use_color = match color.as_str() {
        "always" => true,
        "never" => false,
        _ => false,
    };
    let use_color = use_color && std::env::var("NO_COLOR").map(|v| v.is_empty()).unwrap_or(true) || color == "always";
    let mut inputs = vec![];
    for kv in m.all("input") {
        match kv.split_once('=') {
            Some((k, v)) => inputs.push((k.to_string(), v.to_string())),
            None => {
                let msg = format!("error: invalid value '{kv}' for '--input <key=value>': input must be a key and a value separated by an equal sign\n\nFor more information, try '--help'.\n");
                let _ = std::io::stderr().write_all(msg.as_bytes());
                return 2;
            }
        }
    }
    let common = Common {
        diag_format_short: m.get("diagnostic-format").map(|s| s == "short").unwrap_or(false),
        color: use_color,
        inputs,
        root: m.get("root").cloned(),
    };
    match cmd.name {
        "eval" => crate::cli::run_eval(
            m.get("expression").unwrap(),
            m.get("in").cloned(),
            m.get("format").map(|f| f == "yaml").unwrap_or(false),
            m.flag("pretty"),
            &common,
        ),
        "compile" | "watch" => crate::compile::run_compile(&bin, &m, &common, cmd.name == "watch"),
        "fonts" => crate::compile::run_fonts(&m),
        "info" => crate::compile::run_info(&m),
        "completions" => {
            let shell = m.get("shell").unwrap();
            let text = match shell.as_str() {
                "bash" => include_str!("help/completions_bash.txt"),
                "elvish" => include_str!("help/completions_elvish.txt"),
                "fish" => include_str!("help/completions_fish.txt"),
                "powershell" => include_str!("help/completions_powershell.txt"),
                _ => include_str!("help/completions_zsh.txt"),
            };
            let _ = std::io::stdout().write_all(text.replace("executable", &bin).as_bytes());
            0
        }
        "init" => crate::compile::run_init(&m),
        _ => 0,
    }
}

pub fn jaro_pub(a: &str, b: &str) -> f64 {
    crate::cliargs::jaro_score(a, b)
}
