pub fn compile_document(engine: &mut Engine, id: u16) -> SourceResult<Document> {
    let module = crate::module::eval_file(engine, id)?;
    let content = module.content.clone().unwrap_or_else(Content::empty);
    // Realize: assign locations, synthesize fields.
    let mut intro = crate::introspect::Introspector::empty();
    let mut pages = 1usize;
    let realized = crate::realize::realize_doc(engine, &content, &mut intro, &mut pages)?;
    intro.pages = pages;
    engine.introspector = Rc::new(intro);
    Ok(Document { content: realized, pages })
}

pub fn unused(_v: Value) {}
