            let v = if let Some(v) = a.strip_prefix("--color=") {
                Some(v.to_string())
            } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                i += 1;
                Some(args[i].clone())
            } else {
                None
            };
            match v {
                Some(v) if matches!(v.as_str(), "auto" | "always" | "never") => color = v,
                Some(v) => {
                    let msg = format!("error: invalid value '{v}' for '--color <COLOR>'\n  [possible values: auto, always, never]\n\nFor more information, try '--help'.\n");
