            if s > 0.7 {
                cands.push((s, n));
            }
        }
        cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap().then(a.1.cmp(b.1)));
        let mut msg = format!("error: unrecognized subcommand '{sub}'\n\n");
        if cands.len() == 1 {
            msg.push_str(&format!("  tip: a similar subcommand exists: '{}'\n\n", cands[0].1));
        } else if cands.len() > 1 {
            let mut names: Vec<&str> = cands.iter().map(|c| c.1).collect();
            names.sort();
            let list: Vec<String> = names.iter().map(|n| format!("'{n}'")).collect();
            msg.push_str(&format!("  tip: some similar subcommands exist: {}\n\n", list.join(", ")));
        }
        msg.push_str(&format!("Usage: {main_usage}\n\nFor more information, try '--help'.\n"));
        let _ = std::io::stderr().write_all(msg.as_bytes());
        return 2;
    };
    let m = match parse_cmd(&bin, cmd, rest) {
        Ok(m) => m,
        Err(code) => return code,
    };
    let use_color = match color.as_str() {
        "always" => true,
        "never" => false,
        _ => false,
    };
    let use_color = use_color && std::env::var("NO_COLOR").map(|v| v.is_empty()).unwrap_or(true) || color == "always";
    let mut inputs = vec![];
    for kv in m.all("input") {
        match kv.split_once('=') {
            Some((k, v)) => inputs.push((k.to_string(), v.to_string())),
            None => {
                let msg = format!("error: invalid value '{kv}' for '--input <key=value>': input must be a key and a value separated by an equal sign\n\nFor more information, try '--help'.\n");
                let _ = std::io::stderr().write_all(msg.as_bytes());
                return 2;
            }
        }
    }
    let common = Common {
        diag_format_short: m.get("diagnostic-format").map(|s| s == "short").unwrap_or(false),
        color: use_color,
        inputs,
        root: m.get("root").cloned(),
    };
    match cmd.name {
        "eval" => crate::cli::run_eval(
            m.get("expression").unwrap(),
            m.get("in").cloned(),
            m.get("format").map(|f| f == "yaml").unwrap_or(false),
            m.flag("pretty"),
            &common,
        ),
        "compile" | "watch" => crate::compile::run_compile(&bin, &m, &common, cmd.name == "watch"),
        "fonts" => crate::compile::run_fonts(&m),
        "info" => crate::compile::run_info(&m),
        "completions" => {
            let shell = m.get("shell").unwrap();
            let text = match shell.as_str() {
                "bash" => include_str!("help/completions_bash.txt"),
                "elvish" => include_str!("help/completions_elvish.txt"),
                "fish" => include_str!("help/completions_fish.txt"),
                "powershell" => include_str!("help/completions_powershell.txt"),
                _ => include_str!("help/completions_zsh.txt"),
            };
            let _ = std::io::stdout().write_all(text.replace("executable", &bin).as_bytes());
            0
        }
        "init" => crate::compile::run_init(&m),
        _ => 0,
    }
}

