pub fn run_compile(bin: &str, m: &Matches, common: &Common, _watch: bool) -> i32 {
    let input = m.get("input").unwrap().clone();
    let output = m.get("output").cloned();
    if input == "-" && output.is_none() {
        eprint(&format!(
            "error: the following required arguments were not provided:\n  <OUTPUT>\n\nUsage: {bin} compile <INPUT> <OUTPUT>\n\nFor more information, try '--help'.\n"
        ));
        return 2;
    }
    let features = m.all("features");
    let html_feature = features.iter().any(|f| f == "html");
    let format = match m.get("format") {
        Some(f) => f.clone(),
        None => {
            let path = output.clone().unwrap_or_else(|| input.clone());
            if output.is_none() {
                "pdf".to_string()
            } else if path == "-" {
                "pdf".to_string()
            } else {
                let ext = Path::new(&path).extension().map(|e| e.to_string_lossy().to_lowercase());
                match ext.as_deref() {
                    Some("pdf") => "pdf".into(),
                    Some("png") => "png".into(),
                    Some("svg") => "svg".into(),
                    Some("html") => "html".into(),
                    _ => {
                        eprint(&format!(
                            "error: could not infer output format for path {}.\nconsider providing the format manually with `--format/-f`\n",
                            path
                        ));
                        return 1;
                    }
                }
            }
        }
    };
    if format == "html" && !html_feature {
        eprint("error: html export is only available when `--features html` is passed\n = hint: html export is under active development and incomplete\n = hint: see https://github.com/typst/typst/issues/5512 for more information\n\n");
        return 1;
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let (text, abs) = if input == "-" {
        let mut s = String::new();
        let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut s);
        (s, cwd.join("<stdin>"))
    } else {
        let abs = crate::world::normalize(&cwd.join(&input));
        match std::fs::read(&abs) {
            Ok(b) => match String::from_utf8(b) {
                Ok(t) => (t, abs),
                Err(_) => {
                    eprint("error: file is not valid utf-8\n");
                    return 1;
                }
            },
            Err(_) => {
                eprint(&format!("error: input file not found (searched at {})\n", input));
                return 1;
            }
        }
    };
    let root = match &common.root {
        Some(r) => crate::world::normalize(&cwd.join(r)),
        None => {
            if input == "-" {
                cwd.clone()
            } else {
                abs.parent().map(|p| p.to_path_buf()).unwrap_or(cwd.clone())
            }
        }
    };
    let mut world = crate::world::World::new(root);
    world.allow_fs = true;
    let display = if input == "-" { "<stdin>".to_string() } else { world.display_path(&abs) };
    let id = world.add_source(crate::world::Source::new(Some(abs.clone()), display, text));
    world.main = Some(id);
    let mut engine = make_engine(world, &common.inputs);
    engine.html = format == "html";
    if format == "html" {
        engine.warnings.push(
            Diag::warning(Span::detached(), "html export is under active development and incomplete")
                .with_hint("its behaviour may change at any time")
                .with_hint("do not rely on this feature for production use cases")
                .with_hint("see https://github.com/typst/typst/issues/5512 for more information"),
        );
    }
    let doc = match crate::document::compile_document(&mut engine, id) {
        Ok(d) => d,
        Err(errs) => {
            let mut all = errs;
            all.extend(engine.warnings.clone());
            print_diags(&engine, &all, common);
            return 1;
        }
    };
    // Determine output path.
    let out_path = match &output {
        Some(o) => o.clone(),
        None => {
            let p = Path::new(&input);
            p.with_extension(&format).to_string_lossy().to_string()
        }
    };
    let result: Result<(), String> = match format.as_str() {
        "html" => {
            let html = crate::html::export(&mut engine, &doc);
            match html {
                Ok(h) => write_out(&out_path, h.as_bytes()),
                Err(errs) => {
                    let mut all = errs;
                    all.extend(engine.warnings.clone());
                    print_diags(&engine, &all, common);
                    return 1;
                }
            }
        }
        "svg" | "png" => {
            let multi = doc.pages > 1;
            if multi && !out_path.contains("{p}") && !out_path.contains("{0p}") && out_path != "-" {
                let mut all = vec![Diag::error(
                    Span::detached(),
                    "cannot export multiple images without a page number template ({p}, {0p}) in the output path",
                )];
                all.extend(engine.warnings.clone());
                print_diags(&engine, &all, common);
                return 1;
            }
            let mut r = Ok(());
            for page in 1..=doc.pages {
                let path = out_path
                    .replace("{0p}", &format!("{:0w$}", page, w = doc.pages.to_string().len()))
                    .replace("{p}", &page.to_string())
                    .replace("{t}", &doc.pages.to_string());
                let bytes = if format == "svg" { crate::export::svg_page(&doc, page) } else { crate::export::png_page(&doc, page) };
                r = write_out(&path, &bytes);
                if r.is_err() {
                    break;
                }
            }
            r
        }
        _ => write_out(&out_path, &crate::export::pdf(&doc)),
    };
    if let Err(e) = result {
        eprint(&format!("error: {e}\n"));
        return 1;
    }
    if !engine.warnings.is_empty() {
        let w = engine.warnings.clone();
        print_diags(&engine, &w, common);
    }
    0
}

fn write_out(path: &str, bytes: &[u8]) -> Result<(), String> {
    if path == "-" {
        let _ = std::io::stdout().write_all(bytes);
        return Ok(());
    }
    std::fs::write(path, bytes).map_err(|e| format!("failed to write to file ({e})"))
}

