//! Font discovery for the `fonts` command.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

pub struct Variant {
    pub style: String,
    pub weight: u16,
    pub stretch: u16,
    pub path: String,
}

fn u16_at(d: &[u8], o: usize) -> Option<u16> {
    Some(u16::from_be_bytes([*d.get(o)?, *d.get(o + 1)?]))
}
fn u32_at(d: &[u8], o: usize) -> Option<u32> {
    Some(u32::from_be_bytes([*d.get(o)?, *d.get(o + 1)?, *d.get(o + 2)?, *d.get(o + 3)?]))
}

fn table(d: &[u8], base: usize, tag: &[u8; 4]) -> Option<(usize, usize)> {
    let num = u16_at(d, base + 4)? as usize;
    for i in 0..num {
        let rec = base + 12 + i * 16;
        if d.get(rec..rec + 4)? == tag {
            let off = u32_at(d, rec + 8)? as usize;
            let len = u32_at(d, rec + 12)? as usize;
            return Some((off, len));
        }
    }
    None
}

fn name_string(d: &[u8], base: usize, id: u16) -> Option<String> {
    let (off, _) = table(d, base, b"name")?;
    let count = u16_at(d, off + 2)? as usize;
    let str_off = off + u16_at(d, off + 4)? as usize;
    let mut fallback = None;
    for i in 0..count {
        let r = off + 6 + i * 12;
        let platform = u16_at(d, r)?;
        let encoding = u16_at(d, r + 2)?;
        let lang = u16_at(d, r + 4)?;
        let nid = u16_at(d, r + 6)?;
        let len = u16_at(d, r + 8)? as usize;
        let o = u16_at(d, r + 10)? as usize;
        if nid != id {
            continue;
        }
        let bytes = d.get(str_off + o..str_off + o + len)?;
        if platform == 3 || platform == 0 {
            let u: Vec<u16> = bytes.chunks(2).map(|c| u16::from_be_bytes([c[0], *c.get(1).unwrap_or(&0)])).collect();
            let s = String::from_utf16_lossy(&u);
            if platform == 3 && lang == 0x409 {
                return Some(s);
            }
            if fallback.is_none() {
                fallback = Some(s);
            }
        } else if platform == 1 && encoding == 0 && fallback.is_none() {
            fallback = Some(bytes.iter().map(|b| *b as char).collect());
        }
    }
    fallback
}

fn parse_face(d: &[u8], base: usize, path: &str) -> Option<(String, Variant)> {
    let family = name_string(d, base, 16).or_else(|| name_string(d, base, 1))?;
    let (os2, _) = table(d, base, b"OS/2").unwrap_or((0, 0));
    let (weight, width, fs) = if os2 > 0 {
        (u16_at(d, os2 + 4).unwrap_or(400), u16_at(d, os2 + 6).unwrap_or(5), u16_at(d, os2 + 62).unwrap_or(0))
    } else {
        (400, 5, 0)
    };
    let style = if fs & 1 != 0 {
        "Italic"
    } else if fs & (1 << 9) != 0 {
        "Oblique"
    } else {
        let sub = name_string(d, base, 2).unwrap_or_default().to_lowercase();
        if sub.contains("italic") {
            "Italic"
        } else if sub.contains("oblique") {
            "Oblique"
        } else {
            "Normal"
        }
    };
    let stretch = match width {
        1 => 500,
        2 => 625,
        3 => 750,
        4 => 875,
        5 => 1000,
        6 => 1125,
        7 => 1250,
        8 => 1500,
        9 => 2000,
        _ => 1000,
    };
    let weight = weight.clamp(100, 900);
    Some((family, Variant { style: style.into(), weight, stretch, path: path.to_string() }))
}

fn parse_file(p: &Path, out: &mut Vec<(String, Variant)>) {
    let Ok(d) = std::fs::read(p) else { return };
    let path = p.to_string_lossy().to_string();
    if d.starts_with(b"ttcf") {
        let n = u32_at(&d, 8).unwrap_or(0) as usize;
        for i in 0..n {
            if let Some(off) = u32_at(&d, 12 + i * 4) {
                if let Some(f) = parse_face(&d, off as usize, &path) {
                    out.push(f);
                }
            }
        }
    } else if let Some(f) = parse_face(&d, 0, &path) {
        out.push(f);
    }
}

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
    entries.sort();
    for e in entries {
        if e.is_dir() {
            walk(&e, out);
        } else if let Some(ext) = e.extension() {
            let ext = ext.to_string_lossy().to_lowercase();
            if matches!(ext.as_str(), "ttf" | "otf" | "ttc" | "otc") {
                out.push(e);
            }
        }
    }
}

pub fn discover(custom: &[String], system: bool, embedded: bool) -> BTreeMap<String, Vec<Variant>> {
    let mut faces: Vec<(String, Variant)> = vec![];
    let mut files = vec![];
    for c in custom {
        if c.is_empty() {
            continue;
        }
        walk(Path::new(c), &mut files);
