#!/usr/bin/env python3
"""Compare reference and our binary on test cases.
Case format (JSON list): each item is {"args": [...], "files": {name: content}, "stdin": str?}
or a plain string -> eval expression.
"""
import json, sys, os, subprocess, hashlib, tempfile, concurrent.futures

REF = '/workspace/executable'
OURS = '/workspace/target/release/typst-cli'
CACHE = '/tmp/refcache.json'

def norm(case):
    if isinstance(case, str):
        return {"args": ["eval", case], "files": {}}
    return case

def key(case):
    return hashlib.sha1(json.dumps(case, sort_keys=True).encode()).hexdigest()

def run(binary, case):
    d = tempfile.mkdtemp(prefix='cmp')
    for name, content in case.get("files", {}).items():
        p = os.path.join(d, name)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, 'w').write(content)
    try:
        r = subprocess.run([binary] + case["args"], cwd=d, capture_output=True, timeout=60,
                           input=case.get("stdin", "").encode())
        out = r.stdout.decode('utf-8', 'replace')
        err = r.stderr.decode('utf-8', 'replace')
        res = {"out": out, "err": err, "rc": r.returncode}
    except subprocess.TimeoutExpired:
        res = {"out": "", "err": "TIMEOUT", "rc": -1}
    # collect output files
    outs = {}
    for name in case.get("collect", []):
        p = os.path.join(d, name)
        outs[name] = open(p, 'rb').read().decode('utf-8', 'replace') if os.path.exists(p) else None
    res["files"] = outs
    subprocess.run(['rm', '-rf', d])
    return res

def main():
    cases = [norm(c) for c in json.load(open(sys.argv[1]))]
    cache = json.load(open(CACHE)) if os.path.exists(CACHE) else {}
    todo = [c for c in cases if key(c) not in cache]
    with concurrent.futures.ThreadPoolExecutor(12) as ex:
        for c, r in zip(todo, ex.map(lambda c: run(REF, c), todo)):
            cache[key(c)] = r
    json.dump(cache, open(CACHE, 'w'))
    with concurrent.futures.ThreadPoolExecutor(8) as ex:
        ours = list(ex.map(lambda c: run(OURS, c), cases))
    fails = 0
    verbose = '-v' in sys.argv
    for c, o in zip(cases, ours):
        r = cache[key(c)]
        if r != o:
            fails += 1
            print("=" * 60)
            print("ARGS:", c["args"], "FILES:", json.dumps(c.get("files", {}))[:300])
            for k in ("out", "err", "rc", "files"):
                if r[k] != o[k]:
                    print(f"--- {k} expected:\n{r[k]}\n--- {k} got:\n{o[k]}")
    print(f"{len(cases) - fails}/{len(cases)} passed")

main()
EOF
