//! Realization: show rules, contexts, counters, states, synthesis.

use crate::content::{Content, Recipe, Style};
use crate::diag::*;
use crate::elements as el;
use crate::eval::{ContextInfo, Engine};
use crate::func::{Args, Func};
use crate::introspect::{matches_selector, Introspector};
use crate::value::*;
use std::collections::HashSet;
use std::rc::Rc;

#[derive(Clone, Default)]
pub struct StyleChain {
    pub styles: Vec<Style>,
}

impl StyleChain {
    pub fn get(&self, elem: &str, field: &str) -> Option<Value> {
        for s in self.styles.iter().rev() {
            if let Style::Property { elem: e, field: f, value, .. } = s {
                if e.name == elem && *f == field {
                    return Some(value.clone());
                }
            }
        }
        None
    }
}

// ---------------- counters & states ----------------

fn counter_eq(a: &Counter, b: &Counter) -> bool {
    crate::introspect::repr_counter(a) == crate::introspect::repr_counter(b)
}

fn step(nums: &mut Vec<u64>, level: usize) {
    let level = level.max(1);
    if nums.len() < level {
        nums.resize(level, 0);
    }
    nums.truncate(level);
    *nums.last_mut().unwrap() += 1;
}

fn apply_update(engine: &mut Engine, nums: &mut Vec<u64>, update: &Value) {
    match update {
        Value::Dict(d) => {
            if let Some(Value::Int(l)) = d.get("step") {
                step(nums, *l as usize);
            }
        }
        Value::Int(i) => *nums = vec![(*i).max(0) as u64],
        Value::Array(a) => {
            *nums = a.iter().map(|x| if let Value::Int(i) = x { (*i).max(0) as u64 } else { 0 }).collect();
        }
        f @ Value::Func(_) => {
            let args: Vec<Value> = nums.iter().map(|n| Value::Int(*n as i64)).collect();
            if let Ok(v) = crate::func_call::call_value(engine, f, Span::detached(), args) {
                match v {
                    Value::Int(i) => *nums = vec![i.max(0) as u64],
                    Value::Array(a) => {
                        *nums = a.iter().map(|x| if let Value::Int(i) = x { (*i).max(0) as u64 } else { 0 }).collect();
                    }
                    _ => {}
                }
            }
        }
        _ => {}
    }
}

pub fn counter_value_at(engine: &mut Engine, c: &Counter, loc: Option<Location>) -> Vec<u64> {
    let intro = engine.introspector.clone();
    if let CounterKey::Page = &c.0 {
        let page = match loc {
            Some(l) => intro.page_of(l),
            None => intro.pages.max(1),
        };
        return vec![page as u64];
    }
    let mut nums: Vec<u64> = vec![0];
    for (e, _) in intro.elems.iter() {
        if e.is("counter-update") {
            if let Some(Value::Counter(other)) = e.get("counter") {
                if counter_eq(other, c) {
                    if let Some(u) = e.get("update") {
                        apply_update(engine, &mut nums, &u.clone());
                    }
                }
            }
        } else if let CounterKey::Selector(sel) = &c.0 {
            if matches_selector(e, sel) {
                let level = if e.is("heading") {
                    match e.get("level") {
                        Some(Value::Int(l)) => *l as usize,
                        _ => 1,
                    }
                } else {
                    1
                };
                step(&mut nums, level);
            }
        }
        if loc.is_some() && e.location() == loc {
            break;
        }
    }
    nums
}

pub fn state_value_at(engine: &mut Engine, s: &State, loc: Option<Location>) -> Value {
    let intro = engine.introspector.clone();
    let mut v = s.init.clone();
    for (e, _) in intro.elems.iter() {
        if e.is("state-update") {
            if let Some(Value::State(other)) = e.get("state") {
                if other.key == s.key {
                    match e.get("update") {
                        Some(f @ Value::Func(_)) => {
                            let f = f.clone();
                            if let Ok(nv) = crate::func_call::call_value(engine, &f, Span::detached(), vec![v.clone()]) {
                                v = nv;
                            }
                        }
                        Some(x) => v = x.clone(),
                        None => {}
                    }
                }
            }
        }
        if loc.is_some() && e.location() == loc {
            break;
        }
    }
    v
}

// ---------------- synthesis ----------------

fn text(s: &str) -> Value {
    Value::Content(Content::text(s))
}

fn figure_kind(body: &Content) -> Value {
    fn find(c: &Content) -> Option<&'static str> {
        match c.func_name() {
            "image" => return Some("image"),
            "table" => return Some("table"),
            "raw" => return Some("raw"),
            _ => {}
        }
        if c.is_sequence() {
            for ch in c.children() {
                if let Some(k) = find(&ch) {
                    return Some(k);
                }
            }
        }
        if let Some(Value::Content(b)) = c.get("body").or(c.get("child")) {
            return find(b);
        }
        None
    }
    let k = find(body).unwrap_or("image");
    let e: &'static el::Elem = match k {
        "table" => &el::TABLE,
        "raw" => &el::RAW,
        _ => &el::IMAGE,
    };
    Value::Func(Func::element(e))
}

fn kind_supplement(kind: &Value) -> Value {
    match kind {
        Value::Func(f) => match f.name().as_deref() {
            Some("table") => text("Table"),
            Some("raw") => text("Listing"),
            Some("image") => text("Figure"),
            _ => text("Figure"),
        },
        _ => Value::None,
    }
}

fn figure_counter(kind: &Value) -> Value {
    let sel = Selector::Elem(&el::FIGURE, Some(vec![(Rc::from("kind"), kind.clone())]));
    Value::Counter(Rc::new(Counter(CounterKey::Selector(sel))))
}

pub fn synthesize(c: &Content, chain: &StyleChain) -> Content {
    let mut c = c.clone();
    let elem = c.elem();
    let name = elem.name;
    let get = |c: &Content, f: &str, default: Value| -> Value {
        c.get(f).cloned().or_else(|| chain.get(name, f)).unwrap_or(default)
    };
    match name {
        "heading" => {
            let depth = match c.get("depth") {
                Some(Value::Int(d)) => *d,
                _ => 1,
            };
            let offset = match get(&c, "offset", Value::Int(0)) {
                Value::Int(o) => o,
                _ => 0,
            };
            let level = match get(&c, "level", Value::Auto) {
                Value::Int(l) => l,
                _ => depth + offset,
            };
            c.set("level", Value::Int(level));
            c.set("depth", Value::Int(depth));
            c.set("offset", Value::Int(offset));
            let numbering = get(&c, "numbering", Value::None);
            c.set("numbering", numbering);
            let sup = match get(&c, "supplement", Value::Auto) {
                Value::Auto => text("Section"),
                v => v,
            };
            c.set("supplement", sup);
            c.set("outlined", get(&c, "outlined", Value::Bool(true)));
            c.set("bookmarked", get(&c, "bookmarked", Value::Auto));
            c.set("hanging-indent", get(&c, "hanging-indent", Value::Auto));
        }
        "figure" => {
            let body = c.body().unwrap_or_else(Content::empty);
            c.set("alt", get(&c, "alt", Value::None));
            c.set("placement", get(&c, "placement", Value::None));
            c.set("scope", get(&c, "scope", Value::str("column")));
            let kind = match get(&c, "kind", Value::Auto) {
                Value::Auto => figure_kind(&body),
                v => v,
            };
            let sup = match get(&c, "supplement", Value::Auto) {
                Value::Auto => kind_supplement(&kind),
                v => v,
            };
            let numbering = match get(&c, "numbering", Value::str("1")) {
                Value::Auto => Value::str("1"),
                v => v,
            };
            let counter = figure_counter(&kind);
            if let Some(Value::Content(cap)) = c.get("caption").cloned() {
                let mut cap = cap;
                if !cap.has("separator") {
                    cap.set("separator", chain.get("caption", "separator").unwrap_or(text(": ")));
                } else if matches!(cap.get("separator"), Some(Value::Auto)) {
                    cap.set("separator", text(": "));
                }
                cap.set("kind", kind.clone());
                cap.set("supplement", sup.clone());
                cap.set("numbering", numbering.clone());
                cap.set("counter", counter.clone());
                c.set("caption", Value::Content(cap));
            }
            c.set("kind", kind);
            c.set("supplement", sup);
            c.set("numbering", numbering);
            c.set("gap", get(&c, "gap", Value::Length(Length::em(0.65))));
            c.set("outlined", get(&c, "outlined", Value::Bool(true)));
            c.set("counter", counter);
        }
        "equation" => {
            c.set("block", get(&c, "block", Value::Bool(false)));
            c.set("numbering", get(&c, "numbering", Value::None));
            c.set(
                "number-align",
                get(&c, "number-align", Value::Alignment(Alignment { x: Some(Align::End), y: Some(Align::Horizon) })),
            );
            let sup = match get(&c, "supplement", Value::Auto) {
                Value::Auto => text("Equation"),
                v => v,
            };
            c.set("supplement", sup);
            c.set("alt", get(&c, "alt", Value::None));
        }
        "raw" => {
            c.set("block", get(&c, "block", Value::Bool(false)));
            c.set("lang", get(&c, "lang", Value::None));
            c.set("align", get(&c, "align", Value::Alignment(Alignment { x: Some(Align::Start), y: None })));
            c.set("syntaxes", get(&c, "syntaxes", Value::array(vec![])));
            c.set("theme", get(&c, "theme", Value::Auto));
            c.set("tab-size", get(&c, "tab-size", Value::Int(2)));
            let t = c.get_str("text").unwrap_or_else(|| Rc::from(""));
            let lines: Vec<&str> = t.split('\n').collect();
            let count = lines.len() as i64;
            let ls: Vec<Value> = lines
                .iter()
                .enumerate()
                .map(|(i, l)| {
                    Value::Content(
                        Content::new(&el::RAW_LINE)
                            .with("number", Value::Int(i as i64 + 1))
                            .with("count", Value::Int(count))
                            .with("text", Value::str(*l))
                            .with("body", Content::text(*l)),
                    )
                })
                .collect();
            c.set("lines", Value::array(ls));
        }
        "footnote" => {
            c.set("numbering", get(&c, "numbering", Value::str("1")));
        }
        "list" => {
            c.set("tight", get(&c, "tight", Value::Bool(true)));
            c.set("marker", get(&c, "marker", crate::defaults::default_value("list", "marker")));
            c.set("indent", get(&c, "indent", Value::Length(Length::zero())));
            c.set("body-indent", get(&c, "body-indent", Value::Length(Length::em(0.5))));
            c.set("spacing", get(&c, "spacing", Value::Auto));
        }
        "enum" => {
            c.set("tight", get(&c, "tight", Value::Bool(true)));
            c.set("numbering", get(&c, "numbering", Value::str("1.")));
            c.set("start", get(&c, "start", Value::Auto));
            c.set("full", get(&c, "full", Value::Bool(false)));
            c.set("reversed", get(&c, "reversed", Value::Bool(false)));
            c.set("indent", get(&c, "indent", Value::Length(Length::zero())));
            c.set("body-indent", get(&c, "body-indent", Value::Length(Length::em(0.5))));
            c.set("spacing", get(&c, "spacing", Value::Auto));
            c.set(
                "number-align",
                get(&c, "number-align", Value::Alignment(Alignment { x: Some(Align::End), y: Some(Align::Top) })),
            );
            let children: Vec<Value> = c
                .children()
                .into_iter()
                .map(|ch| {
                    let mut ch = ch;
                    if !ch.has("number") {
                        ch.set("number", Value::Auto);
                    }
                    Value::Content(ch)
                })
                .collect();
            c.set("children", Value::array(children));
        }
        "terms" => {
            c.set("tight", get(&c, "tight", Value::Bool(true)));
            c.set(
                "separator",
                get(&c, "separator", Value::Content(Content::new(&el::H).with("amount", Value::Length(Length::em(0.6))).with("weak", true))),
            );
            c.set("indent", get(&c, "indent", Value::Length(Length::zero())));
            c.set("hanging-indent", get(&c, "hanging-indent", Value::Length(Length::em(2.0))));
            c.set("spacing", get(&c, "spacing", Value::Auto));
        }
        "table" => {
            if !c.has("columns") {
                c.set("columns", chain.get("table", "columns").unwrap_or(Value::array(vec![])));
            }
            c.set("rows", get(&c, "rows", Value::array(vec![])));
            c.set("column-gutter", get(&c, "column-gutter", Value::array(vec![])));
            c.set("row-gutter", get(&c, "row-gutter", Value::array(vec![])));
            c.set("inset", get(&c, "inset", Value::Relative(Rel { rel: 0.0, abs: Length::pt(5.0) })));
            c.set("align", get(&c, "align", Value::Auto));
            c.set("fill", get(&c, "fill", Value::None));
            c.set("stroke", get(&c, "stroke", Value::Stroke(Rc::new(Stroke {
                paint: Some(Value::Color(Color::Luma(0.0, 1.0))),
                thickness: Some(Value::Length(Length::pt(1.0))),
                cap: None,
                join: None,
                dash: None,
                miter_limit: None,
            })))));
        }
        "strong" => {
            c.set("delta", get(&c, "delta", Value::Int(300)));
        }
        "quote" => {
            c.set("block", get(&c, "block", Value::Bool(false)));
            c.set("quotes", get(&c, "quotes", Value::Auto));
            c.set("attribution", get(&c, "attribution", Value::None));
        }
        "image" => {
            c.set("format", get(&c, "format", Value::Auto));
            c.set("width", get(&c, "width", Value::Auto));
            c.set("height", get(&c, "height", Value::Auto));
            c.set("alt", get(&c, "alt", Value::None));
            c.set("page", get(&c, "page", Value::Int(1)));
            c.set("fit", get(&c, "fit", Value::str("cover")));
            c.set("scaling", get(&c, "scaling", Value::Auto));
            c.set("icc", get(&c, "icc", Value::Auto));
        }
        "outline" => {
            c.set("title", get(&c, "title", Value::Auto));
            c.set("target", get(&c, "target", Value::Func(Func::element(&el::HEADING))));
            c.set("depth", get(&c, "depth", Value::None));
            c.set("indent", get(&c, "indent", Value::Auto));
        }
        "ref" => {
            c.set("supplement", get(&c, "supplement", Value::Auto));
            c.set("form", get(&c, "form", Value::str("normal")));
        }
        _ => {}
    }
    c
}

// ---------------- realization walk ----------------

pub fn is_queryable(c: &Content) -> bool {
    crate::introspect::is_locatable(c.elem()) && !matches!(c.func_name(), "par" | "context" | "document")
        || c.label().is_some()
}

struct Walker<'a> {
    engine: &'a mut Engine,
    intro: Introspector,
    pages: usize,
    next_loc: u64,
    errors: Vec<Diag>,
    final_pass: bool,
}

pub fn realize_doc(engine: &mut Engine, content: &Content, intro_out: &mut Introspector, pages_out: &mut usize) -> SourceResult<Content> {
    let mut result = Content::empty();
    for pass in 0..2 {
        let mut w = Walker {
            engine,
            intro: Introspector::empty(),
            pages: 1,
            next_loc: 1_000_000,
            errors: vec![],
            final_pass: pass == 1,
        };
        let chain = StyleChain::default();
        let r = w.walk(content, &chain, &HashSet::new())?;
        let errors = std::mem::take(&mut w.errors);
        let mut intro = std::mem::take(&mut w.intro);
        intro.pages = w.pages;
        let pages = w.pages;
        drop(w);
        engine.introspector = Rc::new(intro);
        result = r;
        *pages_out = pages;
        if pass == 1 && !errors.is_empty() {
            return Err(errors);
        }
    }
    let intro = Rc::try_unwrap(std::mem::replace(&mut engine.introspector, Rc::new(Introspector::empty())))
        .unwrap_or_else(|rc| Introspector { elems: rc.elems.clone(), pages: rc.pages });
    let elems = intro.elems.clone();
    let pages = intro.pages;
    *intro_out = Introspector { elems: elems.clone(), pages };
    engine.introspector = Rc::new(Introspector { elems, pages });
    Ok(result)
}

fn recipe_id(r: &Rc<Recipe>) -> usize {
    Rc::as_ptr(r) as usize
}

impl<'a> Walker<'a> {
    fn new_loc(&mut self) -> Location {
        self.next_loc += 1;
        Location(self.next_loc)
    }

    fn walk(&mut self, c: &Content, chain: &StyleChain, applied: &HashSet<usize>) -> SourceResult<Content> {
        let name = c.func_name();
        match name {
            "sequence" => {
                let mut out = vec![];
                for ch in c.children() {
                    out.push(self.walk(&ch, chain, applied)?);
                }
                let mut seq = Content::sequence(out);
                if let Some(l) = c.label() {
                    seq = seq.labelled(l.clone());
                }
                return Ok(seq);
            }
            "styled" => {
                let mut chain2 = chain.clone();
                if let Some(Value::Styles(s)) = c.get("styles") {
                    chain2.styles.extend(s.0.iter().cloned());
                }
                let child = match c.get("child") {
                    Some(Value::Content(ch)) => self.walk(ch, &chain2, applied)?,
                    _ => Content::empty(),
                };
                let mut nc = c.clone();
                nc.set("child", Value::Content(child));
                return Ok(nc);
            }
            "context" => {
                let loc = self.new_loc();
                let func = match c.get("func") {
                    Some(Value::Func(f)) => f.clone(),
                    _ => return Ok(Content::empty()),
                };
                let saved = self.engine.context.clone();
                self.engine.context = ContextInfo { location: Some(loc), styles: None };
                let ctx = self.engine.context.clone();
                // register a marker so `here()` positions work
                self.intro.elems.push((Content::new(&el::CONTEXT).with("func", Value::None).located(loc), self.pages));
                let r = crate::func_call::call_func(self.engine, &func, Args::new(c.span(), vec![]), &ctx);
                self.engine.context = saved;
                let v = match r {
                    Ok(v) => v,
                    Err(e) => {
                        if self.final_pass {
                            self.errors.extend(e);
                        }
                        Value::None
                    }
                };
                let content = crate::eval::display_value(&v);
                return self.walk(&content, chain, applied);
            }
            "pagebreak" => {
                let weak = matches!(c.get("weak"), Some(Value::Bool(true)));
                if !weak {
                    self.pages += 1;
                }
                return Ok(c.clone());
            }
            _ => {}
        }

        // Show rules.
        let recipes: Vec<Rc<Recipe>> = chain
            .styles
            .iter()
            .rev()
            .filter_map(|s| match s {
                Style::Recipe(r) => Some(r.clone()),
                _ => None,
            })
            .collect();
        for r in recipes {
            let id = recipe_id(&r);
            if applied.contains(&id) {
                continue;
            }
            if let Some(sel) = &r.selector {
                if self.selector_matches(sel, c) {
                    let synthesized = if is_queryable(c) { synthesize(c, chain) } else { c.clone() };
                    // locate before transforming so the element is queryable
                    let (located, _) = self.register(synthesized);
                    let mut applied2 = applied.clone();
                    applied2.insert(id);
                    let out = match self.apply_transform(&r, located.clone(), chain) {
                        Ok(o) => o,
                        Err(e) => {
                            if self.final_pass {
                                self.errors.extend(e);
                            }
                            located.clone()
                        }
                    };
                    return self.walk_after_show(&out, chain, &applied2);
                }
            }
        }

        let synthesized = if is_queryable(c) { synthesize(c, chain) } else { c.clone() };
        let (mut nc, registered) = self.register(synthesized);
        let _ = registered;
        if nc.is("ref") {
            self.check_ref(&mut nc);
        }
        // Recurse into content fields.
        let fields = nc.0.fields.clone();
        for (f, v) in fields {
            if matches!(f, "element" | "citation" | "lines") {
                continue;
            }
            match v {
                Value::Content(inner) => {
                    let r = self.walk(&inner, chain, applied)?;
                    nc.set(f, Value::Content(r));
                }
                Value::Array(arr) if arr.iter().any(|x| matches!(x, Value::Content(_))) => {
                    let mut out = vec![];
                    for x in arr.iter() {
                        match x {
                            Value::Content(i) => out.push(Value::Content(self.walk(i, chain, applied)?)),
                            o => out.push(o.clone()),
                        }
                    }
                    nc.set(f, Value::array(out));
                }
                _ => {}
            }
        }
        Ok(nc)
    }

    fn walk_after_show(&mut self, c: &Content, chain: &StyleChain, applied: &HashSet<usize>) -> SourceResult<Content> {
        self.walk(c, chain, applied)
    }

    fn register(&mut self, c: Content) -> (Content, bool) {
        if is_queryable(&c) && c.location().is_none() {
            let loc = self.new_loc();
            let c = c.located(loc);
            self.intro.elems.push((c.clone(), self.pages));
            if c.is("counter-update") || c.is("state-update") {
                return (c, true);
            }
            return (c, true);
        }
        if (c.is("counter-update") || c.is("state-update")) && c.location().is_none() {
            let loc = self.new_loc();
            let c = c.located(loc);
            self.intro.elems.push((c.clone(), self.pages));
            return (c, true);
        }
        (c, false)
    }

    fn selector_matches(&self, sel: &Value, c: &Content) -> bool {
        match sel {
            Value::Func(f) => match f.element_def() {
                Some(e) => std::ptr::eq(c.elem(), e) || (c.elem().name == e.name && !c.is("item") && !c.is("cell")),
                None => false,
            },
            Value::Label(l) => c.label().is_some_and(|x| x == l),
            Value::Selector(s) => {
                let syn = if is_queryable(c) { synthesize(c, &StyleChain::default()) } else { c.clone() };
                matches_selector(&syn, s)
            }
            Value::Str(_) | Value::Regex(_) | Value::Symbol(_) => false,
            _ => false,
        }
    }

    fn apply_transform(&mut self, r: &Recipe, target: Content, chain: &StyleChain) -> SourceResult<Content> {
        let _ = chain;
        match &r.transform {
            Value::Func(f) => {
                let loc = target.location();
                let saved = self.engine.context.clone();
                self.engine.context = ContextInfo { location: loc, styles: None };
                let ctx = self.engine.context.clone();
                let res = crate::func_call::call_func(self.engine, f, Args::new(r.span, vec![Value::Content(target)]), &ctx);
                self.engine.context = saved;
                Ok(crate::cast::to_content(res?))
            }
            Value::Styles(s) => Ok(target.styled(s.clone())),
            other => Ok(crate::cast::to_content(other.clone())),
        }
    }

    fn check_ref(&mut self, c: &mut Content) {
        let Some(Value::Label(target)) = c.get("target").cloned() else { return };
        let found = self.engine.introspector.elems.iter().find(|(e, _)| e.label().is_some_and(|l| *l == target)).map(|x| x.0.clone());
        match found {
            Some(e) => {
                if e.is("heading") && matches!(e.get("numbering"), Some(Value::None) | None) {
                    if self.final_pass {
                        let d = Diag::error(c.span(), "cannot reference heading without numbering")
                            .with_hint("you can enable heading numbering with `#set heading(numbering: \"1.\")`");
                        self.errors.push(d);
                    }
                    return;
                }
                if e.is("equation") && matches!(e.get("numbering"), Some(Value::None) | None) {
                    if self.final_pass {
                        let d = Diag::error(c.span(), "cannot reference equation without numbering")
                            .with_hint("you can enable equation numbering with `#set math.equation(numbering: \"(1)\")`");
                        self.errors.push(d);
                    }
                    return;
                }
                let cite = Content::new(&el::CITE).with("key", Value::Label(target.clone())).with("supplement", Value::None);
                c.set("citation", Value::Content(cite));
                c.set("element", Value::Content(e));
            }
            None => {
                if self.final_pass {
                    let d = Diag::error(
                        c.span(),
                        format!("label `{}` does not exist in the document", crate::repr::repr_label(&target)),
                    );
                    self.errors.push(d);
                }
            }
        }
    }
}

trait Located {
    fn located(self, loc: Location) -> Self;
}

impl Located for Content {
    fn located(mut self, loc: Location) -> Self {
        self.set_location(loc);
        self
    }
}
