{"command":"cd /workspace/src && cat > html.rs <<'EOF'
//! HTML export.

use crate::content::Content;
use crate::diag::*;
use crate::document::Document;
use crate::eval::Engine;
use crate::value::*;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum HNode {
    Elem(HElem),
    Text(String),
}

#[derive(Debug, Clone)]
pub struct HElem {
    pub tag: String,
    pub attrs: Vec<(String, String)>,
    pub children: Vec<HNode>,
}

impl HElem {
    fn new(tag: &str) -> Self {
        HElem { tag: tag.into(), attrs: vec![], children: vec![] }
    }
    fn attr(mut self, k: &str, v: &str) -> Self {
        self.attrs.push((k.into(), v.into()));
        self
    }
    fn with(mut self, children: Vec<HNode>) -> Self {
        self.children = children;
        self
    }
}

#[derive(Debug, Clone)]
enum Item {
    Inline(HNode),
    Block(HNode),
    Parbreak,
}

fn is_block_tag(tag: &str) -> bool {
    matches!(
        tag,
        "html" | "head" | "body" | "article" | "aside" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "hgroup" | "nav"
            | "section" | "dd" | "dl" | "dt" | "menu" | "ol" | "ul" | "address" | "blockquote" | "dialog" | "div"
            | "fieldset" | "figure" | "figcaption" | "footer" | "form" | "header" | "hr" | "legend" | "main" | "p"
            | "pre" | "search" | "details" | "summary"
    )
}

fn is_tabular(tag: &str) -> bool {
    matches!(tag, "table" | "thead" | "tbody" | "tfoot" | "tr" | "th" | "td" | "caption" | "col" | "colgroup")
}

fn is_metadata(tag: &str) -> bool {
    matches!(tag, "base" | "link" | "meta" | "script" | "style" | "template" | "title")
}

fn is_void(tag: &str) -> bool {
    matches!(tag, "area" | "base" | "br" | "col" | "embed" | "hr" | "img" | "input" | "link" | "meta" | "source" | "track" | "wbr")
}

fn allows_pretty_inside(tag: &str) -> bool {
    (is_block_tag(tag) && tag != "pre") || is_tabular(tag) || tag == "li"
}

fn wants_pretty_around(tag: &str) -> bool {
    allows_pretty_inside(tag) || is_metadata(tag) || tag == "pre"
}

fn escape_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn escape_text_html(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            c => out.push(c),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            c => out.push(c),
        }
    }
}

struct Writer {
    buf: String,
    pretty: bool,
    level: usize,
}

fn write_indent(w: &mut Writer) {
    if w.pretty {
        w.buf.push('\n');
        for _ in 0..w.level {
            w.buf.push_str("  ");
        }
    }
}

fn write_node(w: &mut Writer, n: &HNode, in_pre: bool) {
    match n {
        HNode::Text(t) => {
            if in_pre {
                escape_text_html(t, &mut w.buf);
            } else {
                escape_text_html(t, &mut w.buf);
            }
        }
        HNode::Elem(e) => write_elem(w, e, in_pre),
    }
}

fn write_elem(w: &mut Writer, e: &HElem, in_pre: bool) {
    let _ = escape_text;
    w.buf.push('<');
    w.buf.push_str(&e.tag);
    for (k, v) in &e.attrs {
        w.buf.push(' ');
        w.buf.push_str(k);
        w.buf.push_str("=\"");
        escape_attr(v, &mut w.buf);
        w.buf.push('"');
    }
    w.buf.push('>');
    if is_void(&e.tag) {
        return;
    }
    let pretty = w.pretty;
    if !e.children.is_empty() {
        let pretty_inside = allows_pretty_inside(&e.tag)
            && e.children.iter().any(|n| matches!(n, HNode::Elem(c) if wants_pretty_around(&c.tag)));
        w.pretty &= pretty_inside;
        let mut indent = w.pretty;
        w.level += 1;
        for c in &e.children {
            let pretty_around = match c {
                HNode::Elem(ch) => w.pretty && wants_pretty_around(&ch.tag),
                HNode::Text(_) => false,
            };
            if std::mem::take(&mut indent) || pretty_around {
                write_indent(w);
            }
            write_node(w, c, in_pre || e.tag == "pre");
            indent = pretty_around;
        }
        w.level -= 1;
        write_indent(w);
    }
    w.pretty = pretty;
    w.buf.push_str("</");
    w.buf.push_str(&e.tag);
    w.buf.push('>');
}

struct Ctx<'a> {
    engine: &'a mut Engine,
    warnings: Vec<Diag>,
    ids: HashMap<u64, String>,
    next_id: usize,
    footnotes: Vec<(String, String, Vec<HNode>)>,
    has_outline: bool,
    link_targets: Vec<Str>,
    heading_numbers: Vec<u64>,
    figure_counts: HashMap<String, u64>,
    quote_depth: Vec<char>,
    prev_char: Option<char>,
}

fn text_node(s: &str) -> HNode {
    HNode::Text(s.to_string())
}

impl<'a> Ctx<'a> {
    fn fresh_id(&mut self) -> String {
        self.next_id += 1;
        format!("loc-{}", self.next_id)
    }

    fn ignored(&mut self, c: &Content) {
        let name = c.func_name();
        let d = Diag::warning(c.span(), format!("{name} was ignored during HTML export"));
        self.warnings.push(d);
    }

    fn convert(&mut self, c: &Content, out: &mut Vec<Item>) -> SourceResult<()> {
        let name = c.func_name();
        // Labelled targets of links get a span with the label as id.
        if let Some(l) = c.label() {
            if self.link_targets.iter().any(|t| t == l) && !c.is("heading") {
                let mut inner = vec![];
                let mut c2 = c.clone();
                std::rc::Rc::make_mut(&mut c2.0).label = None;
                self.convert(&c2, &mut inner)?;
                let nodes: Vec<HNode> = inner
                    .into_iter()
                    .filter_map(|i| match i {
                        Item::Inline(n) => Some(n),
                        Item::Block(n) => Some(n),
                        Item::Parbreak => None,
                    })
                    .collect();
                out.push(Item::Inline(HNode::Elem(HElem::new("span").attr("id", l).with(nodes))));
                return Ok(());
            }
        }
        match name {
            "sequence" => {
                for ch in c.children() {
                    self.convert(&ch, out)?;
                }
            }
            "styled" => {
                if let Some(Value::Content(ch)) = c.get("child") {
                    self.convert(ch, out)?;
                }
            }
            "text" => {
                let t = c.get_str("text").unwrap_or_default();
                self.prev_char = t.chars().last().or(self.prev_char);
                out.push(Item::Inline(text_node(&t)));
            }
            "symbol" => {
                let t = c.get_str("text").unwrap_or_default();
                self.prev_char = t.chars().last().or(self.prev_char);
                out.push(Item::Inline(text_node(&t)));
            }
            "space" => {
                self.prev_char = Some(' ');
                out.push(Item::Inline(text_node(" ")));
            }
            "linebreak" => {
                self.prev_char = Some('\n');
                out.push(Item::Inline(HNode::Elem(HElem::new("br"))));
            }
            "parbreak" => {
                self.prev_char = None;
                out.push(Item::Parbreak);
            }
            "smartquote" => {
                let double = !matches!(c.get("double"), Some(Value::Bool(false)));
                let open = match self.prev_char {
                    None => true,
                    Some(p) => p.is_whitespace() || matches!(p, '(' | '[' | '{' | '“' | '‘' | '\u{a0}'),
                };
                let q = match (double, open) {
                    (true, true) => '“',
                    (true, false) => '”',
                    (false, true) => '‘',
                    (false, false) => '’',
                };
                self.prev_char = Some(q);
                out.push(Item::Inline(text_node(&q.to_string())));
            }
            "strong" | "emph" | "sub" | "super" | "strike" | "highlight" | "underline" | "overline" | "smallcaps" => {
                let tag = match name {
                    "strong" => "strong",
                    "emph" => "em",
                    "sub" => "sub",
                    "super" => "sup",
                    "strike" => "s",
                    "highlight" => "mark",
                    _ => "span",
                };
                let body = self.inline_children(c.body().as_ref())?;
                let mut e = HElem::new(tag).with(body);
                match name {
                    "underline" => e = e.attr("style", "text-decoration: underline"),
                    "overline" => e = e.attr("style", "text-decoration: overline"),
                    "smallcaps" => e = e.attr("style", "font-variant-caps: small-caps"),
                    _ => {}
                }
                out.push(Item::Inline(HNode::Elem(e)));
            }
            "raw" => {
                let t = c.get_str("text").unwrap_or_default();
                let block = matches!(c.get("block"), Some(Value::Bool(true)));
                let mut code = HElem::new("code").with(if t.is_empty() { vec![] } else { vec![text_node(&t)] });
                if block {
                    if let Some(Value::Str(l)) = c.get("lang") {
                        code = code.attr("data-lang", l);
                    }
                    out.push(Item::Block(HNode::Elem(HElem::new("pre").with(vec![HNode::Elem(code)]))));
                } else {
                    self.prev_char = t.chars().last().or(self.prev_char);
                    out.push(Item::Inline(HNode::Elem(code)));
                }
            }
            "link" => {
                let href = match c.get("dest") {
                    Some(Value::Str(s)) => s.to_string(),
                    Some(Value::Label(l)) => format!("#{l}"),
                    _ => String::new(),
                };
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Inline(HNode::Elem(HElem::new("a").attr("href", &href).with(body))));
            }
            "heading" => {
                let level = match c.get("level") {
                    Some(Value::Int(l)) => *l,
                    _ => 1,
                };
                let mut body = vec![];
                if let Some(num) = c.get("numbering").cloned() {
                    if !matches!(num, Value::None) {
                        let lv = level.max(1) as usize;
                        if self.heading_numbers.len() < lv {
                            self.heading_numbers.resize(lv, 0);
                        }
                        self.heading_numbers.truncate(lv);
                        *self.heading_numbers.last_mut().unwrap() += 1;
                        let nums = self.heading_numbers.clone();
                        let r = crate::model::apply_numbering(self.engine, &num, &nums, c.span())?;
                        let rc = crate::eval::display_value(&r);
                        body.extend(self.inline_children(Some(&rc))?);
                        body.push(text_node(" "));
                    }
                }
                body.extend(self.inline_children(c.body().as_ref())?);
                let mut e = if level <= 5 {
                    HElem::new(&format!("h{}", level + 1))
                } else {
                    let d = Diag::warning(
                        c.span(),
                        format!(
                            "heading of level {} was transformed to <div role=\"heading\" aria-level=\"{}\">, which is not supported by all assistive technology",
                            level,
                            level + 1
                        ),
                    );
                    self.warnings.push(d);
                    HElem::new("div").attr("role", "heading").attr("aria-level", &(level + 1).to_string())
                };
                if let Some(loc) = c.location() {
                    if self.has_outline {
                        let id = self.fresh_id();
                        self.ids.insert(loc.0, id.clone());
                        e.attrs.insert(0, ("id".into(), id));
                    }
                }
                if let Some(l) = c.label() {
                    if self.link_targets.iter().any(|t| t == l) && !e.attrs.iter().any(|a| a.0 == "id") {
                        e.attrs.insert(0, ("id".into(), l.to_string()));
                    }
                }
                out.push(Item::Block(HNode::Elem(e.with(body))));
            }
            "list" | "enum" => {
                let tight = !matches!(c.get("tight"), Some(Value::Bool(false)));
                let mut e = HElem::new(if name == "list" { "ul" } else { "ol" });
                if name == "enum" {
                    if let Some(Value::Int(s)) = c.get("start") {
                        if *s != 1 {
                            e = e.attr("start", &s.to_string());
                        }
                    }
                }
                let mut items = vec![];
                for it in c.children() {
                    let mut li = HElem::new("li");
                    if let Some(Value::Int(n)) = it.get("number") {
                        li = li.attr("value", &n.to_string());
                    }
                    let mut inner = vec![];
                    if let Some(b) = it.body() {
                        self.prev_char = None;
                        self.convert(&b, &mut inner)?;
                    }
                    let kids = self.flow(inner, !tight);
                    items.push(HNode::Elem(li.with(kids)));
                }
                out.push(Item::Block(HNode::Elem(e.with(items))));
            }
            "terms" => {
                let mut items = vec![];
                for it in c.children() {
                    let term = match it.get("term") {
                        Some(Value::Content(t)) => self.inline_children(Some(t))?,
                        _ => vec![],
                    };
                    items.push(HNode::Elem(HElem::new("dt").with(term)));
                    let mut inner = vec![];
                    if let Some(Value::Content(d)) = it.get("description") {
                        self.convert(d, &mut inner)?;
                    }
                    let kids = self.flow(inner, false);
                    items.push(HNode::Elem(HElem::new("dd").with(kids)));
                }
                out.push(Item::Block(HNode::Elem(HElem::new("dl").with(items))));
            }
            "table" | "grid" => {
                let cols = match c.get("columns") {
                    Some(Value::Array(a)) if !a.is_empty() => a.len(),
                    _ => 1,
                };
                let mut header_rows: Vec<Vec<HNode>> = vec![];
                let mut body_cells: Vec<HNode> = vec![];
                let mut footer_rows: Vec<Vec<HNode>> = vec![];
                for ch in c.children() {
                    match ch.func_name() {
                        "header" | "footer" => {
                            let mut cells = vec![];
                            for cell in ch.children() {
                                cells.push(self.cell(&cell, if ch.is("header") { "th" } else { "td" })?);
                            }
                            let rows: Vec<Vec<HNode>> = cells.chunks(cols).map(|r| r.to_vec()).collect();
                            if ch.is("header") {
                                header_rows.extend(rows);
                            } else {
                                footer_rows.extend(rows);
                            }
                        }
                        "hline" | "vline" => {}
                        _ => body_cells.push(self.cell(&ch, "td")?),
                    }
                }
                let mk_rows = |rows: Vec<Vec<HNode>>| -> Vec<HNode> {
                    rows.into_iter().map(|r| HNode::Elem(HElem::new("tr").with(r))).collect()
                };
                let body_rows: Vec<Vec<HNode>> = body_cells.chunks(cols).map(|r| r.to_vec()).collect();
                let mut kids = vec![];
                if !header_rows.is_empty() || !footer_rows.is_empty() {
                    if !header_rows.is_empty() {
                        kids.push(HNode::Elem(HElem::new("thead").with(mk_rows(header_rows))));
                    }
                    kids.push(HNode::Elem(HElem::new("tbody").with(mk_rows(body_rows))));
                    if !footer_rows.is_empty() {
                        kids.push(HNode::Elem(HElem::new("tfoot").with(mk_rows(footer_rows))));
                    }
                } else {
                    kids = mk_rows(body_rows);
                }
                if name == "grid" {
                    out.push(Item::Block(HNode::Elem(HElem::new("div").attr("style", "display: grid").with(kids))));
                } else {
                    out.push(Item::Block(HNode::Elem(HElem::new("table").with(kids))));
                }
            }
            "figure" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let mut kids = self.flow(inner, true);
                if let Some(Value::Content(cap)) = c.get("caption") {
                    let kind = match c.get("kind") {
                        Some(Value::Func(f)) => f.name().unwrap_or_default(),
                        Some(Value::Str(s)) => s.to_string(),
                        _ => "image".into(),
                    };
                    let n = {
                        let e = self.figure_counts.entry(kind).or_insert(0);
                        *e += 1;
                        *e
                    };
                    let mut cap_nodes = vec![];
                    if let Some(sup) = c.get("supplement").cloned() {
                        let numbering = c.get("numbering").cloned().unwrap_or(Value::None);
                        let sup_c = crate::cast::to_content(sup);
                        cap_nodes.extend(self.inline_children(Some(&sup_c))?);
                        if !matches!(numbering, Value::None) {
                            let r = crate::model::apply_numbering(self.engine, &numbering, &[n], c.span())?;
                            cap_nodes.push(text_node("\u{a0}"));
                            let rc = crate::eval::display_value(&r);
                            cap_nodes.extend(self.inline_children(Some(&rc))?);
                        }
                        if let Some(Value::Content(sep)) = cap.get("separator") {
                            cap_nodes.extend(self.inline_children(Some(sep))?);
                        }
                    }
                    cap_nodes.extend(self.inline_children(cap.body().as_ref())?);
                    kids.push(HNode::Elem(HElem::new("figcaption").with(merge_text(cap_nodes))));
                }
                out.push(Item::Block(HNode::Elem(HElem::new("figure").with(kids))));
            }
            "quote" => {
                let block = matches!(c.get("block"), Some(Value::Bool(true)));
                if block {
                    let mut inner = vec![];
                    if let Some(b) = c.body() {
                        self.convert(&b, &mut inner)?;
                    }
                    let kids = self.flow(inner, false);
                    out.push(Item::Block(HNode::Elem(HElem::new("blockquote").with(kids))));
                    if let Some(Value::Content(a)) = c.get("attribution") {
                        out.push(Item::Inline(text_node("— ")));
                        self.convert(a, out)?;
                    }
                } else {
                    out.push(Item::Inline(text_node("“")));
                    self.prev_char = Some('“');
                    if let Some(b) = c.body() {
                        self.convert(&b, out)?;
                    }
                    out.push(Item::Inline(text_node("”")));
                    self.prev_char = Some('”');
                }
            }
            "box" => {
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Inline(HNode::Elem(HElem::new("span").attr("style", "display: inline-block").with(body))));
            }
            "block" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let kids = self.flow(inner, false);
                out.push(Item::Block(HNode::Elem(HElem::new("div").with(kids))));
            }
            "par" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let kids = inline_only(inner);
                out.push(Item::Block(HNode::Elem(HElem::new("p").with(kids))));
            }
            "title" => {
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Block(HNode::Elem(HElem::new("h1").with(body))));
            }
            "image" => {
                let mut e = HElem::new("img");
                if let Some(Value::Str(src)) = c.get("source") {
                    let path = crate::data::check_file_access(self.engine, src, c.span());
                    if let Ok(p) = path {
                        if let Ok(bytes) = self.engine.world.read_file(&p) {
                            let mime = if bytes.starts_with(b"\x89PNG") {
                                "image/png"
                            } else if bytes.starts_with(&[0xff, 0xd8]) {
                                "image/jpeg"
                            } else if bytes.starts_with(b"GIF") {
                                "image/gif"
                            } else {
                                "image/svg+xml"
                            };
