                let mut e = HElem::new(&tag);
                if let Some(Value::Dict(d)) = c.get("attrs") {
                    for (k, v) in d.iter() {
                        if let Value::Str(s) = v {
                            e.attrs.push((k.to_string(), s.to_string()));
                        }
                    }
                }
                let mut inner = vec![];
                if let Some(Value::Content(b)) = c.get("body") {
                    self.convert(b, &mut inner)?;
                }
                let kids = if is_block_tag(&tag) { self.flow(inner, false) } else { inline_only(inner) };
                let node = HNode::Elem(e.with(kids));
                if is_block_tag(&tag) || is_tabular(&tag) {
                    out.push(Item::Block(node));
                } else {
                    out.push(Item::Inline(node));
                }
            }
            "outline" => {
                let nav = self.outline()?;
                out.push(Item::Block(nav));
            }
            "metadata" | "counter-update" | "state-update" | "context" | "flush" | "tag" => {}
            "equation" | "align" | "hide" | "place" | "rect" | "square" | "circle" | "ellipse" | "line" | "polygon"
            | "curve" | "path" | "move" | "rotate" | "scale" | "skew" | "h" | "v" | "pagebreak" | "colbreak"
            | "columns" | "stack" | "pad" | "repeat" | "layout" => {
                self.ignored(c);
                out.push(Item::Parbreak);
            }
            "ref" => {
                let text = match c.get("element") {
                    Some(Value::Content(e)) => {
                        let sup = e.get("supplement").cloned().map(crate::cast::to_content).map(|x| x.plain_text()).unwrap_or_default();
                        format!("{}\u{a0}1", sup)
                    }
                    _ => String::new(),
                };
                out.push(Item::Inline(text_node(&text)));
            }
            _ => {
                if let Some(b) = c.body() {
                    self.convert(&b, out)?;
                }
            }
        }
        Ok(())
    }

    fn cell(&mut self, cell: &Content, tag: &str) -> SourceResult<HNode> {
        let mut inner = vec![];
        if let Some(b) = cell.body() {
            self.prev_char = None;
            self.convert(&b, &mut inner)?;
        }
        let kids = self.flow(inner, false);
        let mut e = HElem::new(tag);
        if let Some(Value::Int(n)) = cell.get("colspan") {
            if *n > 1 {
                e = e.attr("colspan", &n.to_string());
            }
        }
        if let Some(Value::Int(n)) = cell.get("rowspan") {
            if *n > 1 {
                e = e.attr("rowspan", &n.to_string());
            }
        }
        Ok(HNode::Elem(e.with(kids)))
    }

    fn inline_children(&mut self, c: Option<&Content>) -> SourceResult<Vec<HNode>> {
        let mut inner = vec![];
        if let Some(c) = c {
            self.convert(c, &mut inner)?;
        }
        Ok(inline_only(inner))
    }

    /// Lay out items: if `force_par` or there are blocks/parbreaks, group inline runs into paragraphs.
    fn flow(&mut self, items: Vec<Item>, force_par: bool) -> Vec<HNode> {
        let has_block = items.iter().any(|i| matches!(i, Item::Block(_) | Item::Parbreak));
        if !force_par && !has_block {
            return inline_only(items);
        }
        let mut out = vec![];
        let mut run: Vec<HNode> = vec![];
        let flush = |run: &mut Vec<HNode>, out: &mut Vec<HNode>| {
            let nodes = trim_inline(merge_text(std::mem::take(run)));
            if !nodes.is_empty() {
                out.push(HNode::Elem(HElem::new("p").with(nodes)));
            }
        };
        for it in items {
            match it {
                Item::Inline(n) => run.push(n),
                Item::Block(n) => {
                    flush(&mut run, &mut out);
                    out.push(n);
                }
                Item::Parbreak => flush(&mut run, &mut out),
            }
        }
        flush(&mut run, &mut out);
        out
    }

    fn outline(&mut self) -> SourceResult<HNode> {
        let headings: Vec<Content> =
            self.engine.introspector.elems.iter().filter(|(c, _)| c.is("heading")).map(|(c, _)| c.clone()).collect();
        // Pre-assign ids in document order.
        let mut entries = vec![];
        for h in &headings {
            let loc = h.location().map(|l| l.0).unwrap_or(0);
            let id = match self.ids.get(&loc) {
                Some(i) => i.clone(),
                None => {
                    let i = self.fresh_id();
                    self.ids.insert(loc, i.clone());
                    i
                }
            };
            let level = match h.get("level") {
                Some(Value::Int(l)) => *l as usize,
                _ => 1,
            };
            let body = self.inline_children(h.body().as_ref())?;
            entries.push((level, id, body));
        }
        fn build(entries: &[(usize, String, Vec<HNode>)], i: &mut usize, level: usize) -> Vec<HNode> {
            let mut items = vec![];
            while *i < entries.len() && entries[*i].0 >= level {
                let (lv, id, body) = &entries[*i];
                *i += 1;
                let a = HNode::Elem(HElem::new("a").attr("href", &format!("#{id}")).with(body.clone()));
                let _ = lv;
                let children = build(entries, i, level + 1);
                if children.is_empty() {
                    items.push(HNode::Elem(HElem::new("li").with(vec![a])));
                } else {
                    let ol = HNode::Elem(HElem::new("ol").attr("style", "list-style-type: none").with(children));
                    items.push(HNode::Elem(HElem::new("li").with(vec![HNode::Elem(HElem::new("div").with(vec![a])), ol])));
                }
            }
            items
        }
        let mut i = 0;
        let min_level = entries.iter().map(|e| e.0).min().unwrap_or(1);
        let items = build(&entries, &mut i, min_level);
        let mut kids = vec![HNode::Elem(HElem::new("h2").with(vec![text_node("Contents")]))];
        kids.push(HNode::Elem(HElem::new("ol").attr("style", "list-style-type: none").with(items)));
        Ok(HNode::Elem(HElem::new("nav").attr("role", "doc-toc").with(kids)))
    }
}

fn css_length(v: &Value) -> Option<String> {
    match v {
        Value::Relative(r) if r.abs.is_zero() => Some(format!("{}%", crate::repr::float_display(crate::repr::round_prec(r.rel * 100.0, 2)))),
        Value::Relative(r) if r.rel == 0.0 && r.abs.em == 0.0 => Some(format!("{}pt", crate::repr::float_display(r.abs.abs))),
        Value::Length(l) if l.em == 0.0 => Some(format!("{}pt", crate::repr::float_display(l.abs))),
        Value::Ratio(r) => Some(format!("{}%", crate::repr::float_display(r * 100.0))),
        _ => None,
    }
}

fn inline_only(items: Vec<Item>) -> Vec<HNode> {
    let nodes: Vec<HNode> = items
        .into_iter()
        .filter_map(|i| match i {
            Item::Inline(n) | Item::Block(n) => Some(n),
            Item::Parbreak => None,
        })
        .collect();
    trim_inline(merge_text(nodes))
}

fn merge_text(nodes: Vec<HNode>) -> Vec<HNode> {
    let mut out: Vec<HNode> = vec![];
    for n in nodes {
        match (out.last_mut(), n) {
            (Some(HNode::Text(prev)), HNode::Text(t)) => {
                if prev.ends_with(' ') && t.starts_with(' ') {
                    prev.push_str(t.trim_start_matches(' '));
                } else {
                    prev.push_str(&t);
                }
            }
            (_, n) => out.push(n),
        }
    }
    out
}

fn trim_inline(mut nodes: Vec<HNode>) -> Vec<HNode> {
    if let Some(HNode::Text(t)) = nodes.first_mut() {
        *t = t.trim_start_matches(' ').to_string();
    }
    if let Some(HNode::Text(t)) = nodes.last_mut() {
        *t = t.trim_end_matches(' ').to_string();
    }
    nodes.retain(|n| !matches!(n, HNode::Text(t) if t.is_empty()));
    nodes
}

fn base64(data: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(data.len() * 4 / 3 + 4);
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 { T[(n >> 6) as usize & 63] as char } else { '=' });
        out.push(if chunk.len() > 2 { T[n as usize & 63] as char } else { '=' });
    }
    out
}

fn collect_link_targets(c: &Content, out: &mut Vec<Str>) {
    if c.is("link") {
        if let Some(Value::Label(l)) = c.get("dest") {
            out.push(l.clone());
        }
    }
    for (_, v) in c.0.fields.iter() {
        match v {
            Value::Content(i) => collect_link_targets(i, out),
            Value::Array(a) => {
                for x in a.iter() {
                    if let Value::Content(i) = x {
                        collect_link_targets(i, out);
                    }
                }
            }
            _ => {}
        }
    }
}

fn contains_elem(c: &Content, name: &str) -> bool {
    if c.func_name() == name {
        return true;
    }
    c.0.fields.iter().any(|(_, v)| match v {
        Value::Content(i) => contains_elem(i, name),
        Value::Array(a) => a.iter().any(|x| matches!(x, Value::Content(i) if contains_elem(i, name))),
        _ => false,
    })
}

pub fn export(engine: &mut Engine, doc: &Document) -> SourceResult<String> {
    let mut link_targets = vec![];
    collect_link_targets(&doc.content, &mut link_targets);
    let has_outline = contains_elem(&doc.content, "outline");
    let mut ctx = Ctx {
        engine,
        warnings: vec![],
        ids: HashMap::new(),
        next_id: 0,
        footnotes: vec![],
        has_outline,
        link_targets,
        heading_numbers: vec![],
        figure_counts: HashMap::new(),
        quote_depth: vec![],
        prev_char: None,
    };
    let mut items = vec![];
    ctx.convert(&doc.content, &mut items)?;
    let mut body = ctx.flow(items, true);
    if !ctx.footnotes.is_empty() {
        let notes = std::mem::take(&mut ctx.footnotes);
        let mut lis = vec![];
        let mut mapping = vec![];
        for (n, (ref_id, placeholder, content)) in notes.into_iter().enumerate() {
            let note_id = ctx.fresh_id();
            mapping.push((placeholder, note_id.clone()));
            let back = HElem::new("sup")
                .attr("role", "doc-backlink")
                .with(vec![HNode::Elem(HElem::new("a").attr("href", &format!("#{ref_id}")).with(vec![text_node(&(n + 1).to_string())]))]);
            let mut kids = vec![HNode::Elem(back)];
            kids.extend(content);
            lis.push(HNode::Elem(HElem::new("li").attr("id", &note_id).with(kids)));
        }
        fn fix(n: &mut HNode, mapping: &[(String, String)]) {
            if let HNode::Elem(e) = n {
                for a in e.attrs.iter_mut() {
                    for (p, id) in mapping {
                        if a.1 == format!("#{p}") {
                            a.1 = format!("#{id}");
                        }
                    }
                }
                for c in e.children.iter_mut() {
                    fix(c, mapping);
                }
            }
        }
        for n in body.iter_mut() {
            fix(n, &mapping);
        }
        let ol = HElem::new("ol").attr("style", "list-style-type: none").with(lis);
        body.push(HNode::Elem(HElem::new("section").attr("role", "doc-endnotes").with(vec![HNode::Elem(ol)])));
    }
    let warnings = std::mem::take(&mut ctx.warnings);
    engine.warnings.extend(warnings);
    let head = HElem::new("head").with(vec![
        HNode::Elem(HElem::new("meta").attr("charset", "utf-8")),
        HNode::Elem(HElem::new("meta").attr("name", "viewport").attr("content", "width=device-width, initial-scale=1")),
    ]);
    let html = HElem::new("html")
        .attr("lang", "en")
        .with(vec![HNode::Elem(head), HNode::Elem(HElem::new("body").with(body))]);
    let mut w = Writer { buf: String::from("<!DOCTYPE html>\n"), pretty: true, level: 0 };
    write_elem(&mut w, &html, false);
    w.buf.push('\n');
    Ok(w.buf)
}
