cd /workspace/src && cat > html.rs <<'EOF'
//! HTML export.

use crate::content::Content;
use crate::diag::*;
use crate::document::Document;
use crate::eval::Engine;
use crate::value::*;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum HNode {
    Elem(HElem),
    Text(String),
}

#[derive(Debug, Clone)]
pub struct HElem {
    pub tag: String,
    pub attrs: Vec<(String, String)>,
    pub children: Vec<HNode>,
}

impl HElem {
    fn new(tag: &str) -> Self {
        HElem { tag: tag.into(), attrs: vec![], children: vec![] }
    }
    fn attr(mut self, k: &str, v: &str) -> Self {
        self.attrs.push((k.into(), v.into()));
        self
    }
    fn with(mut self, children: Vec<HNode>) -> Self {
        self.children = children;
        self
    }
}

#[derive(Debug, Clone)]
enum Item {
    Inline(HNode),
    Block(HNode),
    Parbreak,
}

fn is_block_tag(tag: &str) -> bool {
    matches!(
        tag,
        "html" | "head" | "body" | "article" | "aside" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "hgroup" | "nav"
            | "section" | "dd" | "dl" | "dt" | "menu" | "ol" | "ul" | "address" | "blockquote" | "dialog" | "div"
            | "fieldset" | "figure" | "figcaption" | "footer" | "form" | "header" | "hr" | "legend" | "main" | "p"
            | "pre" | "search" | "details" | "summary"
    )
}

fn is_tabular(tag: &str) -> bool {
    matches!(tag, "table" | "thead" | "tbody" | "tfoot" | "tr" | "th" | "td" | "caption" | "col" | "colgroup")
}

fn is_metadata(tag: &str) -> bool {
    matches!(tag, "base" | "link" | "meta" | "script" | "style" | "template" | "title")
}

fn is_void(tag: &str) -> bool {
    matches!(tag, "area" | "base" | "br" | "col" | "embed" | "hr" | "img" | "input" | "link" | "meta" | "source" | "track" | "wbr")
}

fn allows_pretty_inside(tag: &str) -> bool {
    (is_block_tag(tag) && tag != "pre") || is_tabular(tag) || tag == "li"
}

fn wants_pretty_around(tag: &str) -> bool {
    allows_pretty_inside(tag) || is_metadata(tag) || tag == "pre"
}

fn escape_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn escape_text_html(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            c => out.push(c),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            c => out.push(c),
        }
    }
}

struct Writer {
    buf: String,
    pretty: bool,
    level: usize,
}

fn write_indent(w: &mut Writer) {
    if w.pretty {
        w.buf.push('\n');
        for _ in 0..w.level {
            w.buf.push_str("  ");
        }
    }
}

fn write_node(w: &mut Writer, n: &HNode, in_pre: bool) {
    match n {
        HNode::Text(t) => {
            if in_pre {
                escape_text_html(t, &mut w.buf);
            } else {
                escape_text_html(t, &mut w.buf);
            }
        }
        HNode::Elem(e) => write_elem(w, e, in_pre),
    }
}

fn write_elem(w: &mut Writer, e: &HElem, in_pre: bool) {
    let _ = escape_text;
    w.buf.push('<');
    w.buf.push_str(&e.tag);
    for (k, v) in &e.attrs {
        w.buf.push(' ');
        w.buf.push_str(k);
        w.buf.push_str("=\"");
        escape_attr(v, &mut w.buf);
        w.buf.push('"');
    }
    w.buf.push('>');
    if is_void(&e.tag) {
        return;
    }
    let pretty = w.pretty;
    if !e.children.is_empty() {
        let pretty_inside = allows_pretty_inside(&e.tag)
            && e.children.iter().any(|n| matches!(n, HNode::Elem(c) if wants_pretty_around(&c.tag)));
        w.pretty &= pretty_inside;
        let mut indent = w.pretty;
        w.level += 1;
        for c in &e.children {
            let pretty_around = match c {
                HNode::Elem(ch) => w.pretty && wants_pretty_around(&ch.tag),
                HNode::Text(_) => false,
            };
            if std::mem::take(&mut indent) || pretty_around {
                write_indent(w);
            }
            write_node(w, c, in_pre || e.tag == "pre");
            indent = pretty_around;
        }
        w.level -= 1;
        write_indent(w);
    }
    w.pretty = pretty;
    w.buf.push_str("</");
    w.buf.push_str(&e.tag);
    w.buf.push('>');
}

struct Ctx<'a> {
    engine: &'a mut Engine,
    warnings: Vec<Diag>,
    ids: HashMap<u64, String>,
    next_id: usize,
    footnotes: Vec<(String, String, Vec<HNode>)>,
    has_outline: bool,
    link_targets: Vec<Str>,
    heading_numbers: Vec<u64>,
    figure_counts: HashMap<String, u64>,
    quote_depth: Vec<char>,
    prev_char: Option<char>,
}

fn text_node(s: &str) -> HNode {
    HNode::Text(s.to_string())
}

impl<'a> Ctx<'a> {
    fn fresh_id(&mut self) -> String {
        self.next_id += 1;
        format!("loc-{}", self.next_id)
    }

    fn ignored(&mut self, c: &Content) {
        let name = c.func_name();
        let d = Diag::warning(c.span(), format!("{name} was ignored during HTML export"));
        self.warnings.push(d);
    }

    fn convert(&mut self, c: &Content, out: &mut Vec<Item>) -> SourceResult<()> {
        let name = c.func_name();
        // Labelled targets of links get a span with the label as id.
        if let Some(l) = c.label() {
            if self.link_targets.iter().any(|t| t == l) && !c.is("heading") {
                let mut inner = vec![];
                let mut c2 = c.clone();
                std::rc::Rc::make_mut(&mut c2.0).label = None;
                self.convert(&c2, &mut inner)?;
                let nodes: Vec<HNode> = inner
                    .into_iter()
                    .filter_map(|i| match i {
                        Item::Inline(n) => Some(n),
                        Item::Block(n) => Some(n),
                        Item::Parbreak => None,
                    })
                    .collect();
                out.push(Item::Inline(HNode::Elem(HElem::new("span").attr("id", l).with(nodes))));
                return Ok(());
            }
        }
        match name {
            "sequence" => {
                for ch in c.children() {
                    self.convert(&ch, out)?;
                }
            }
            "styled" => {
                if let Some(Value::Content(ch)) = c.get("child") {
                    self.convert(ch, out)?;
                }
            }
            "text" => {
                let t = c.get_str("text").unwrap_or_default();
                self.prev_char = t.chars().last().or(self.prev_char);
                out.push(Item::Inline(text_node(&t)));
            }
            "symbol" => {
                let t = c.get_str("text").unwrap_or_default();
                self.prev_char = t.chars().last().or(self.prev_char);
                out.push(Item::Inline(text_node(&t)));
            }
            "space" => {
                self.prev_char = Some(' ');
                out.push(Item::Inline(text_node(" ")));
            }
            "linebreak" => {
                self.prev_char = Some('\n');
                out.push(Item::Inline(HNode::Elem(HElem::new("br"))));
            }
            "parbreak" => {
                self.prev_char = None;
                out.push(Item::Parbreak);
            }
            "smartquote" => {
                let double = !matches!(c.get("double"), Some(Value::Bool(false)));
                let open = match self.prev_char {
                    None => true,
                    Some(p) => p.is_whitespace() || matches!(p, '(' | '[' | '{' | '“' | '‘' | '\u{a0}'),
                };
                let q = match (double, open) {
                    (true, true) => '“',
                    (true, false) => '”',
                    (false, true) => '‘',
                    (false, false) => '’',
                };
                self.prev_char = Some(q);
                out.push(Item::Inline(text_node(&q.to_string())));
            }
            "strong" | "emph" | "sub" | "super" | "strike" | "highlight" | "underline" | "overline" | "smallcaps" => {
                let tag = match name {
                    "strong" => "strong",
                    "emph" => "em",
                    "sub" => "sub",
                    "super" => "sup",
                    "strike" => "s",
                    "highlight" => "mark",
                    _ => "span",
                };
                let body = self.inline_children(c.body().as_ref())?;
                let mut e = HElem::new(tag).with(body);
                match name {
                    "underline" => e = e.attr("style", "text-decoration: underline"),
                    "overline" => e = e.attr("style", "text-decoration: overline"),
                    "smallcaps" => e = e.attr("style", "font-variant-caps: small-caps"),
                    _ => {}
                }
                out.push(Item::Inline(HNode::Elem(e)));
            }
            "raw" => {
                let t = c.get_str("text").unwrap_or_default();
                let block = matches!(c.get("block"), Some(Value::Bool(true)));
                let mut code = HElem::new("code").with(if t.is_empty() { vec![] } else { vec![text_node(&t)] });
                if block {
                    if let Some(Value::Str(l)) = c.get("lang") {
                        code = code.attr("data-lang", l);
                    }
                    out.push(Item::Block(HNode::Elem(HElem::new("pre").with(vec![HNode::Elem(code)]))));
                } else {
                    self.prev_char = t.chars().last().or(self.prev_char);
                    out.push(Item::Inline(HNode::Elem(code)));
                }
            }
            "link" => {
                let href = match c.get("dest") {
                    Some(Value::Str(s)) => s.to_string(),
                    Some(Value::Label(l)) => format!("#{l}"),
                    _ => String::new(),
                };
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Inline(HNode::Elem(HElem::new("a").attr("href", &href).with(body))));
            }
            "heading" => {
                let level = match c.get("level") {
                    Some(Value::Int(l)) => *l,
                    _ => 1,
                };
                let mut body = vec![];
                if let Some(num) = c.get("numbering").cloned() {
                    if !matches!(num, Value::None) {
                        let lv = level.max(1) as usize;
                        if self.heading_numbers.len() < lv {
                            self.heading_numbers.resize(lv, 0);
                        }
                        self.heading_numbers.truncate(lv);
                        *self.heading_numbers.last_mut().unwrap() += 1;
                        let nums = self.heading_numbers.clone();
                        let r = crate::model::apply_numbering(self.engine, &num, &nums, c.span())?;
                        let rc = crate::eval::display_value(&r);
                        body.extend(self.inline_children(Some(&rc))?);
                        body.push(text_node(" "));
                    }
                }
                body.extend(self.inline_children(c.body().as_ref())?);
                let mut e = if level <= 5 {
                    HElem::new(&format!("h{}", level + 1))
                } else {
                    let d = Diag::warning(
                        c.span(),
                        format!(
                            "heading of level {} was transformed to <div role=\"heading\" aria-level=\"{}\">, which is not supported by all assistive technology",
                            level,
                            level + 1
                        ),
                    );
                    self.warnings.push(d);
                    HElem::new("div").attr("role", "heading").attr("aria-level", &(level + 1).to_string())
                };
                if let Some(loc) = c.location() {
                    if self.has_outline {
                        let id = self.fresh_id();
                        self.ids.insert(loc.0, id.clone());
                        e.attrs.insert(0, ("id".into(), id));
                    }
                }
                if let Some(l) = c.label() {
                    if self.link_targets.iter().any(|t| t == l) && !e.attrs.iter().any(|a| a.0 == "id") {
                        e.attrs.insert(0, ("id".into(), l.to_string()));
                    }
                }
                out.push(Item::Block(HNode::Elem(e.with(body))));
            }
            "list" | "enum" => {
                let tight = !matches!(c.get("tight"), Some(Value::Bool(false)));
                let mut e = HElem::new(if name == "list" { "ul" } else { "ol" });
                if name == "enum" {
                    if let Some(Value::Int(s)) = c.get("start") {
                        if *s != 1 {
                            e = e.attr("start", &s.to_string());
                        }
                    }
                }
                let mut items = vec![];
                for it in c.children() {
                    let mut li = HElem::new("li");
                    if let Some(Value::Int(n)) = it.get("number") {
                        li = li.attr("value", &n.to_string());
                    }
                    let mut inner = vec![];
                    if let Some(b) = it.body() {
                        self.prev_char = None;
                        self.convert(&b, &mut inner)?;
                    }
                    let kids = self.flow(inner, !tight);
                    items.push(HNode::Elem(li.with(kids)));
                }
                out.push(Item::Block(HNode::Elem(e.with(items))));
            }
            "terms" => {
                let mut items = vec![];
                for it in c.children() {
                    let term = match it.get("term") {
                        Some(Value::Content(t)) => self.inline_children(Some(t))?,
                        _ => vec![],
                    };
                    items.push(HNode::Elem(HElem::new("dt").with(term)));
                    let mut inner = vec![];
                    if let Some(Value::Content(d)) = it.get("description") {
                        self.convert(d, &mut inner)?;
                    }
                    let kids = self.flow(inner, false);
                    items.push(HNode::Elem(HElem::new("dd").with(kids)));
                }
                out.push(Item::Block(HNode::Elem(HElem::new("dl").with(items))));
            }
            "table" | "grid" => {
                let cols = match c.get("columns") {
                    Some(Value::Array(a)) if !a.is_empty() => a.len(),
                    _ => 1,
                };
                let mut header_rows: Vec<Vec<HNode>> = vec![];
                let mut body_cells: Vec<HNode> = vec![];
                let mut footer_rows: Vec<Vec<HNode>> = vec![];
                for ch in c.children() {
                    match ch.func_name() {
                        "header" | "footer" => {
                            let mut cells = vec![];
                            for cell in ch.children() {
                                cells.push(self.cell(&cell, if ch.is("header") { "th" } else { "td" })?);
                            }
                            let rows: Vec<Vec<HNode>> = cells.chunks(cols).map(|r| r.to_vec()).collect();
                            if ch.is("header") {
                                header_rows.extend(rows);
                            } else {
                                footer_rows.extend(rows);
                            }
                        }
                        "hline" | "vline" => {}
                        _ => body_cells.push(self.cell(&ch, "td")?),
                    }
                }
                let mk_rows = |rows: Vec<Vec<HNode>>| -> Vec<HNode> {
                    rows.into_iter().map(|r| HNode::Elem(HElem::new("tr").with(r))).collect()
                };
                let body_rows: Vec<Vec<HNode>> = body_cells.chunks(cols).map(|r| r.to_vec()).collect();
                let mut kids = vec![];
                if !header_rows.is_empty() || !footer_rows.is_empty() {
                    if !header_rows.is_empty() {
                        kids.push(HNode::Elem(HElem::new("thead").with(mk_rows(header_rows))));
                    }
                    kids.push(HNode::Elem(HElem::new("tbody").with(mk_rows(body_rows))));
                    if !footer_rows.is_empty() {
                        kids.push(HNode::Elem(HElem::new("tfoot").with(mk_rows(footer_rows))));
                    }
                } else {
                    kids = mk_rows(body_rows);
                }
                if name == "grid" {
                    out.push(Item::Block(HNode::Elem(HElem::new("div").attr("style", "display: grid").with(kids))));
                } else {
                    out.push(Item::Block(HNode::Elem(HElem::new("table").with(kids))));
                }
            }
            "figure" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let mut kids = self.flow(inner, true);
                if let Some(Value::Content(cap)) = c.get("caption") {
                    let kind = match c.get("kind") {
                        Some(Value::Func(f)) => f.name().unwrap_or_default(),
                        Some(Value::Str(s)) => s.to_string(),
                        _ => "image".into(),
                    };
                    let n = {
                        let e = self.figure_counts.entry(kind).or_insert(0);
                        *e += 1;
                        *e
                    };
                    let mut cap_nodes = vec![];
                    if let Some(sup) = c.get("supplement").cloned() {
                        let numbering = c.get("numbering").cloned().unwrap_or(Value::None);
                        let sup_c = crate::cast::to_content(sup);
                        cap_nodes.extend(self.inline_children(Some(&sup_c))?);
                        if !matches!(numbering, Value::None) {
                            let r = crate::model::apply_numbering(self.engine, &numbering, &[n], c.span())?;
                            cap_nodes.push(text_node("\u{a0}"));
                            let rc = crate::eval::display_value(&r);
                            cap_nodes.extend(self.inline_children(Some(&rc))?);
                        }
                        if let Some(Value::Content(sep)) = cap.get("separator") {
                            cap_nodes.extend(self.inline_children(Some(sep))?);
                        }
                    }
                    cap_nodes.extend(self.inline_children(cap.body().as_ref())?);
                    kids.push(HNode::Elem(HElem::new("figcaption").with(merge_text(cap_nodes))));
                }
                out.push(Item::Block(HNode::Elem(HElem::new("figure").with(kids))));
            }
            "quote" => {
                let block = matches!(c.get("block"), Some(Value::Bool(true)));
                if block {
                    let mut inner = vec![];
                    if let Some(b) = c.body() {
                        self.convert(&b, &mut inner)?;
                    }
                    let kids = self.flow(inner, false);
                    out.push(Item::Block(HNode::Elem(HElem::new("blockquote").with(kids))));
                    if let Some(Value::Content(a)) = c.get("attribution") {
                        out.push(Item::Inline(text_node("— ")));
                        self.convert(a, out)?;
                    }
                } else {
                    out.push(Item::Inline(text_node("“")));
                    self.prev_char = Some('“');
                    if let Some(b) = c.body() {
                        self.convert(&b, out)?;
                    }
                    out.push(Item::Inline(text_node("”")));
                    self.prev_char = Some('”');
                }
            }
            "box" => {
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Inline(HNode::Elem(HElem::new("span").attr("style", "display: inline-block").with(body))));
            }
            "block" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let kids = self.flow(inner, false);
                out.push(Item::Block(HNode::Elem(HElem::new("div").with(kids))));
            }
            "par" => {
                let mut inner = vec![];
                if let Some(b) = c.body() {
                    self.convert(&b, &mut inner)?;
                }
                let kids = inline_only(inner);
                out.push(Item::Block(HNode::Elem(HElem::new("p").with(kids))));
            }
            "title" => {
                let body = self.inline_children(c.body().as_ref())?;
                out.push(Item::Block(HNode::Elem(HElem::new("h1").with(body))));
            }
            "image" => {
                let mut e = HElem::new("img");
                if let Some(Value::Str(src)) = c.get("source") {
                    let path = crate::data::check_file_access(self.engine, src, c.span());
                    if let Ok(p) = path {
                        if let Ok(bytes) = self.engine.world.read_file(&p) {
                            let mime = if bytes.starts_with(b"\x89PNG") {
                                "image/png"
                            } else if bytes.starts_with(&[0xff, 0xd8]) {
                                "image/jpeg"
                            } else if bytes.starts_with(b"GIF") {
                                "image/gif"
                            } else {
                                "image/svg+xml"
                            };
                            e = e.attr("src", &format!("data:{};base64,{}", mime, base64(&bytes)));
                        }
                    }
                }
                if let Some(Value::Str(alt)) = c.get("alt") {
                    e = e.attr("alt", alt);
                }
                let mut style = vec![];
                for (f, css) in [("width", "width"), ("height", "height")] {
                    if let Some(v) = c.get(f) {
                        if let Some(s) = css_length(v) {
                            style.push(format!("{css}: {s}"));
                        }
                    }
                }
                if !style.is_empty() {
                    e = e.attr("style", &style.join("; "));
                }
                out.push(Item::Inline(HNode::Elem(e)));
            }
            "footnote" => {
                let n = self.footnotes.len() + 1;
                let ref_id = self.fresh_id();
                let body = match c.get("body") {
                    Some(Value::Content(b)) => self.inline_children(Some(b))?,
                    _ => vec![],
                };
                let note_id_placeholder = format!("__note{n}");
                let sup = HElem::new("sup")
                    .attr("id", &ref_id)
                    .attr("role", "doc-noteref")
                    .with(vec![HNode::Elem(HElem::new("a").attr("href", &format!("#{note_id_placeholder}")).with(vec![text_node(&n.to_string())]))]);
                self.footnotes.push((ref_id, note_id_placeholder, body));
                out.push(Item::Inline(HNode::Elem(sup)));
            }
            "elem" => {
                let tag = c.get_str("tag").unwrap_or_default().to_string();
                let mut e = HElem::new(&tag);
                if let Some(Value::Dict(d)) = c.get("attrs") {
                    for (k, v) in d.iter() {
                        if let Value::Str(s) = v {
                            e.attrs.push((k.to_string(), s.to_string()));
                        }
                    }
                }
                let mut inner = vec![];
                if let Some(Value::Content(b)) = c.get("body") {
                    self.convert(b, &mut inner)?;
                }
                let kids = if is_block_tag(&tag) { self.flow(inner, false) } else { inline_only(inner) };
                let node = HNode::Elem(e.with(kids));
                if is_block_tag(&tag) || is_tabular(&tag) {
                    out.push(Item::Block(node));
                } else {
                    out.push(Item::Inline(node));
                }
            }
            "outline" => {
                let nav = self.outline()?;
                out.push(Item::Block(nav));
            }
            "metadata" | "counter-update" | "state-update" | "context" | "flush" | "tag" => {}
            "equation" | "align" | "hide" | "place" | "rect" | "square" | "circle" | "ellipse" | "line" | "polygon"
            | "curve" | "path" | "move" | "rotate" | "scale" | "skew" | "h" | "v" | "pagebreak" | "colbreak"
            | "columns" | "stack" | "pad" | "repeat" | "layout" => {
                self.ignored(c);
                out.push(Item::Parbreak);
            }
            "ref" => {
                let text = match c.get("element") {
                    Some(Value::Content(e)) => {
                        let sup = e.get("supplement").cloned().map(crate::cast::to_content).map(|x| x.plain_text()).unwrap_or_default();
                        format!("{}\u{a0}1", sup)
                    }
                    _ => String::new(),
                };
                out.push(Item::Inline(text_node(&text)));
            }
            _ => {
                if let Some(b) = c.body() {
                    self.convert(&b, out)?;
                }
            }
        }
        Ok(())
    }

    fn cell(&mut self, cell: &Content, tag: &str) -> SourceResult<HNode> {
        let mut inner = vec![];
        if let Some(b) = cell.body() {
            self.prev_char = None;
            self.convert(&b, &mut inner)?;
        }
        let kids = self.flow(inner, false);
        let mut e = HElem::new(tag);
        if let Some(Value::Int(n)) = cell.get("colspan") {
            if *n > 1 {
                e = e.attr("colspan", &n.to_string());
            }
        }
        if let Some(Value::Int(n)) = cell.get("rowspan") {
            if *n > 1 {
                e = e.attr("rowspan", &n.to_string());
            }
        }
        Ok(HNode::Elem(e.with(kids)))
    }

    fn inline_children(&mut self, c: Option<&Content>) -> SourceResult<Vec<HNode>> {
        let mut inner = vec![];
        if let Some(c) = c {
            self.convert(c, &mut inner)?;
        }
        Ok(inline_only(inner))
    }

    /// Lay out items: if `force_par` or there are blocks/parbreaks, group inline runs into paragraphs.
    fn flow(&mut self, items: Vec<Item>, force_par: bool) -> Vec<HNode> {
        let has_block = items.iter().any(|i| matches!(i, Item::Block(_) | Item::Parbreak));
        if !force_par && !has_block {
            return inline_only(items);
        }
        let mut out = vec![];
        let mut run: Vec<HNode> = vec![];
        let flush = |run: &mut Vec<HNode>, out: &mut Vec<HNode>| {
            let nodes = trim_inline(merge_text(std::mem::take(run)));
            if !nodes.is_empty() {
                out.push(HNode::Elem(HElem::new("p").with(nodes)));
            }
        };
        for it in items {
            match it {
                Item::Inline(n) => run.push(n),
                Item::Block(n) => {
                    flush(&mut run, &mut out);
                    out.push(n);
                }
                Item::Parbreak => flush(&mut run, &mut out),
            }
        }
        flush(&mut run, &mut out);
        out
    }

    fn outline(&mut self) -> SourceResult<HNode> {
        let headings: Vec<Content> =
            self.engine.introspector.elems.iter().filter(|(c, _)| c.is("heading")).map(|(c, _)| c.clone()).collect();
        // Pre-assign ids in document order.
        let mut entries = vec![];
        for h in &headings {
            let loc = h.location().map(|l| l.0).unwrap_or(0);
            let id = match self.ids.get(&loc) {
                Some(i) => i.clone(),
                None => {
                    let i = self.fresh_id();
                    self.ids.insert(loc, i.clone());
                    i
                }
            };
            let level = match h.get("level") {
                Some(Value::Int(l)) => *l as usize,
                _ => 1,
            };
            let body = self.inline_children(h.body().as_ref())?;
            entries.push((level, id, body));
        }
        fn build(entries: &[(usize, String, Vec<HNode>)], i: &mut usize, level: usize) -> Vec<HNode> {
            let mut items = vec![];
            while *i < entries.len() && entries[*i].0 >= level {
                let (lv, id, body) = &entries[*i];
                *i += 1;
                let a = HNode::Elem(HElem::new("a").attr("href", &format!("#{id}")).with(body.clone()));
                let _ = lv;
                let children = build(entries, i, level + 1);
                if children.is_empty() {
                    items.push(HNode::Elem(HElem::new("li").with(vec![a])));
                } else {
                    let ol = HNode::Elem(HElem::new("ol").attr("style", "list-style-type: none").with(children));
                    items.push(HNode::Elem(HElem::new("li").with(vec![HNode::Elem(HElem::new("div").with(vec![a])), ol])));
                }
            }
            items
        }
        let mut i = 0;
        let min_level = entries.iter().map(|e| e.0).min().unwrap_or(1);
        let items = build(&entries, &mut i, min_level);
        let mut kids = vec![HNode::Elem(HElem::new("h2").with(vec![text_node("Contents")]))];
        kids.push(HNode::Elem(HElem::new("ol").attr("style", "list-style-type: none").with(items)));
        Ok(HNode::Elem(HElem::new("nav").attr("role", "doc-toc").with(kids)))
    }
}

fn css_length(v: &Value) -> Option<String> {
    match v {
        Value::Relative(r) if r.abs.is_zero() => Some(format!("{}%", crate::repr::float_display(crate::repr::round_prec(r.rel * 100.0, 2)))),
        Value::Relative(r) if r.rel == 0.0 && r.abs.em == 0.0 => Some(format!("{}pt", crate::repr::float_display(r.abs.abs))),
        Value::Length(l) if l.em == 0.0 => Some(format!("{}pt", crate::repr::float_display(l.abs))),
        Value::Ratio(r) => Some(format!("{}%", crate::repr::float_display(r * 100.0))),
        _ => None,
    }
}

fn inline_only(items: Vec<Item>) -> Vec<HNode> {
    let nodes: Vec<HNode> = items
        .into_iter()
        .filter_map(|i| match i {
            Item::Inline(n) | Item::Block(n) => Some(n),
            Item::Parbreak => None,
        })
        .collect();
    trim_inline(merge_text(nodes))
}

fn merge_text(nodes: Vec<HNode>) -> Vec<HNode> {
    let mut out: Vec<HNode> = vec![];
    for n in nodes {
        match (out.last_mut(), n) {
            (Some(HNode::Text(prev)), HNode::Text(t)) => {
                if prev.ends_with(' ') && t.starts_with(' ') {
                    prev.push_str(t.trim_start_matches(' '));
                } else {
                    prev.push_str(&t);
                }
            }
            (_, n) => out.push(n),
        }
    }
    out
}

fn trim_inline(mut nodes: Vec<HNode>) -> Vec<HNode> {
    if let Some(HNode::Text(t)) = nodes.first_mut() {
        *t = t.trim_start_matches(' ').to_string();
    }
    if let Some(HNode::Text(t)) = nodes.last_mut() {
        *t = t.trim_end_matches(' ').to_string();
    }
    nodes.retain(|n| !matches!(n, HNode::Text(t) if t.is_empty()));
    nodes
}

fn base64(data: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(data.len() * 4 / 3 + 4);
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 { T[(n >> 6) as usize & 63] as char } else { '=' });
        out.push(if chunk.len() > 2 { T[n as usize & 63] as char } else { '=' });
    }
    out
}

fn collect_link_targets(c: &Content, out: &mut Vec<Str>) {
    if c.is("link") {
        if let Some(Value::Label(l)) = c.get("dest") {
            out.push(l.clone());
        }
    }
    for (_, v) in c.0.fields.iter() {
        match v {
            Value::Content(i) => collect_link_targets(i, out),
            Value::Array(a) => {
                for x in a.iter() {
                    if let Value::Content(i) = x {
                        collect_link_targets(i, out);
                    }
                }
            }
            _ => {}
        }
    }
}

fn contains_elem(c: &Content, name: &str) -> bool {
    if c.func_name() == name {
        return true;
    }
    c.0.fields.iter().any(|(_, v)| match v {
        Value::Content(i) => contains_elem(i, name),
        Value::Array(a) => a.iter().any(|x| matches!(x, Value::Content(i) if contains_elem(i, name))),
        _ => false,
    })
}

pub fn export(engine: &mut Engine, doc: &Document) -> SourceResult<String> {
    let mut link_targets = vec![];
    collect_link_targets(&doc.content, &mut link_targets);
    let has_outline = contains_elem(&doc.content, "outline");
    let mut ctx = Ctx {
        engine,
        warnings: vec![],
        ids: HashMap::new(),
        next_id: 0,
        footnotes: vec![],
        has_outline,
        link_targets,
        heading_numbers: vec![],
        figure_counts: HashMap::new(),
        quote_depth: vec![],
        prev_char: None,
    };
    let mut items = vec![];
    ctx.convert(&doc.content, &mut items)?;
    let mut body = ctx.flow(items, true);
    if !ctx.footnotes.is_empty() {
        let notes = std::mem::take(&mut ctx.footnotes);
        let mut lis = vec![];
        let mut mapping = vec![];
        for (n, (ref_id, placeholder, content)) in notes.into_iter().enumerate() {
            let note_id = ctx.fresh_id();
            mapping.push((placeholder, note_id.clone()));
            let back = HElem::new("sup")
                .attr("role", "doc-backlink")
                .with(vec![HNode::Elem(HElem::new("a").attr("href", &format!("#{ref_id}")).with(vec![text_node(&(n + 1).to_string())]))]);
            let mut kids = vec![HNode::Elem(back)];
            kids.extend(content);
            lis.push(HNode::Elem(HElem::new("li").attr("id", &note_id).with(kids)));
        }
        fn fix(n: &mut HNode, mapping: &[(String, String)]) {
            if let HNode::Elem(e) = n {
                for a in e.attrs.iter_mut() {
                    for (p, id) in mapping {
                        if a.1 == format!("#{p}") {
                            a.1 = format!("#{id}");
                        }
                    }
                }
                for c in e.children.iter_mut() {
                    fix(c, mapping);
                }
            }
        }
        for n in body.iter_mut() {
            fix(n, &mapping);
        }
        let ol = HElem::new("ol").attr("style", "list-style-type: none").with(lis);
        body.push(HNode::Elem(HElem::new("section").attr("role", "doc-endnotes").with(vec![HNode::Elem(ol)])));
    }
    let warnings = std::mem::take(&mut ctx.warnings);
    engine.warnings.extend(warnings);
    let head = HElem::new("head").with(vec![
        HNode::Elem(HElem::new("meta").attr("charset", "utf-8")),
        HNode::Elem(HElem::new("meta").attr("name", "viewport").attr("content", "width=device-width, initial-scale=1")),
    ]);
    let html = HElem::new("html")
        .attr("lang", "en")
        .with(vec![HNode::Elem(head), HNode::Elem(HElem::new("body").with(body))]);
    let mut w = Writer { buf: String::from("<!DOCTYPE html>\n"), pretty: true, level: 0 };
    write_elem(&mut w, &html, false);
    w.buf.push('\n');
    Ok(w.buf)
