pub fn bib_keys(text: &str) -> Vec<String> {
    let mut keys = vec![];
    let bytes: Vec<char> = text.chars().collect();
    let mut i = 0;
    let is_bibtex = text.contains('@');
    if is_bibtex {
        while i < bytes.len() {
            if bytes[i] == '@' {
                let mut j = i + 1;
                while j < bytes.len() && bytes[j].is_alphanumeric() {
                    j += 1;
                }
                while j < bytes.len() && bytes[j].is_whitespace() {
                    j += 1;
                }
                if j < bytes.len() && (bytes[j] == '{' || bytes[j] == '(') {
                    j += 1;
                    while j < bytes.len() && bytes[j].is_whitespace() {
                        j += 1;
                    }
                    let st = j;
                    while j < bytes.len() && bytes[j] != ',' && !bytes[j].is_whitespace() && bytes[j] != '}' {
                        j += 1;
                    }
                    let key: String = bytes[st..j].iter().collect();
                    if !key.is_empty() {
                        keys.push(key);
                    }
                }
                i = j;
            } else {
                i += 1;
            }
        }
    } else {
        for line in text.lines() {
            if !line.starts_with(' ') && !line.starts_with('#') {
                if let Some((k, _)) = line.split_once(':') {
                    let k = k.trim();
                    if !k.is_empty() {
                        keys.push(k.to_string());
                    }
                }
            }
        }
    }
    keys
}''')
