fn fb_exp(x: f64) -> f64 {
    const HALF: [f64; 2] = [0.5, -0.5];
    const LN2HI: f64 = 6.93147180369123816490e-01;
    const LN2LO: f64 = 1.90821492927058770002e-10;
    const INVLN2: f64 = 1.44269504088896338700e+00;
    const P1: f64 = 1.66666666666666019037e-01;
    const P2: f64 = -2.77777777770155933842e-03;
    const P3: f64 = 6.61375632143793436117e-05;
    const P4: f64 = -1.65339022054652515390e-06;
    const P5: f64 = 4.13813679705723846039e-08;
    let hx = (x.to_bits() >> 32) as u32;
    let sign = (hx >> 31) as usize;
    let hx = hx & 0x7fffffff;
    let (hi, lo, k);
    if hx > 0x3fd62e42 {
        if hx >= 0x3ff0a2b2 {
            k = (INVLN2 * x + HALF[sign]) as i32;
        } else {
            k = 1 - sign as i32 - sign as i32;
        }
        hi = x - k as f64 * LN2HI;
        lo = k as f64 * LN2LO;
    } else if hx > 0x3e300000 {
        k = 0;
        hi = x;
        lo = 0.0;
    } else {
        return 1.0 + x;
    }
    let xx = hi - lo;
    let t = xx * xx;
    let c = xx - t * (P1 + t * (P2 + t * (P3 + t * (P4 + t * P5))));
    let y = 1.0 + (xx * c / (2.0 - c) - lo + hi);
    if k == 0 {
        y
    } else {
        y * f64::from_bits(((0x3ff + k as i64) as u64) << 52)
    }
}

fn fb_log(x: f64) -> f64 {
    const LN2_HI: f64 = 6.93147180369123816490e-01;
    const LN2_LO: f64 = 1.90821492927058770002e-10;
    const LG1: f64 = 6.666666666666735130e-01;
    const LG2: f64 = 3.999999999940941908e-01;
    const LG3: f64 = 2.857142874366239149e-01;
    const LG4: f64 = 2.222219843214978396e-01;
    const LG5: f64 = 1.818357216161805012e-01;
    const LG6: f64 = 1.531383769920937332e-01;
    const LG7: f64 = 1.479819860511658591e-01;
    let mut ui = x.to_bits();
    let mut hx = (ui >> 32) as u32;
    let mut k: i32 = 0;
    let mut x = x;
    if hx < 0x00100000 || (hx >> 31) > 0 {
        if ui << 1 == 0 { return -1.0 / (x * x); }
        if hx >> 31 > 0 { return (x - x) / 0.0; }
        k -= 54;
        x *= f64::from_bits(0x4350000000000000);
        ui = x.to_bits();
        hx = (ui >> 32) as u32;
    } else if hx >= 0x7ff00000 {
        return x;
    } else if hx == 0x3ff00000 && ui << 32 == 0 {
        return 0.0;
    }
    hx += 0x3ff00000 - 0x3fe6a09e;
    k += ((hx >> 20) as i32) - 0x3ff;
    hx = (hx & 0x000fffff) + 0x3fe6a09e;
    ui = ((hx as u64) << 32) | (ui & 0xffffffff);
    x = f64::from_bits(ui);
    let f = x - 1.0;
    let hfsq = 0.5 * f * f;
    let s = f / (2.0 + f);
    let z = s * s;
    let w = z * z;
    let t1 = w * (LG2 + w * (LG4 + w * LG6));
    let t2 = z * (LG1 + w * (LG3 + w * (LG5 + w * LG7)));
    let r = t2 + t1;
    let dk = k as f64;
    s * (hfsq + r) + dk * LN2_LO - hfsq + f + dk * LN2_HI
}

fn main() {
    let mut e = vec![]; let mut l = vec![];
    for i in 1..=20 { e.push(format!("{:?}", fb_exp(i as f64))); l.push(format!("{:?}", fb_log(i as f64))); }
    println!("[{}]", e.join(","));
    println!("[{}]", l.join(","));
}
