//! Ports of classic FreeBSD/musl math routines, to match results bit-for-bit.

fn hi(x: f64) -> u32 {
    (x.to_bits() >> 32) as u32
}

pub fn exp(x: f64) -> f64 {
    const HALF: [f64; 2] = [0.5, -0.5];
    const LN2HI: f64 = 6.93147180369123816490e-01;
    const LN2LO: f64 = 1.90821492927058770002e-10;
    const INVLN2: f64 = 1.44269504088896338700e+00;
    const P1: f64 = 1.66666666666666019037e-01;
    const P2: f64 = -2.77777777770155933842e-03;
    const P3: f64 = 6.61375632143793436117e-05;
    const P4: f64 = -1.65339022054652515390e-06;
    const P5: f64 = 4.13813679705723846039e-08;
    if x.is_nan() {
        return x;
    }
    let hx_full = hi(x);
    let sign = (hx_full >> 31) as usize;
    let hx = hx_full & 0x7fffffff;
    if hx >= 0x4086232b {
        if x > 709.782712893383973096 {
            return f64::INFINITY;
        }
        if x < -708.39641853226410622 && x < -745.13321910194110842 {
            return 0.0;
        }
    }
    let (hi_, lo, k);
    if hx > 0x3fd62e42 {
        if hx >= 0x3ff0a2b2 {
            k = (INVLN2 * x + HALF[sign]) as i32;
        } else {
            k = 1 - sign as i32 - sign as i32;
        }
        hi_ = x - k as f64 * LN2HI;
        lo = k as f64 * LN2LO;
    } else if hx > 0x3e300000 {
        k = 0;
        hi_ = x;
        lo = 0.0;
    } else {
        return 1.0 + x;
    }
    let xx = hi_ - lo;
    let t = xx * xx;
    let c = xx - t * (P1 + t * (P2 + t * (P3 + t * (P4 + t * P5))));
    let y = 1.0 + (xx * c / (2.0 - c) - lo + hi_);
    if k == 0 {
        return y;
    }
    scalbn(y, k)
}

pub fn scalbn(x: f64, mut n: i32) -> f64 {
    let x1p1023 = f64::from_bits(0x7fe0000000000000);
    let x1p53 = f64::from_bits(0x4340000000000000);
    let x1p_1022 = f64::from_bits(0x0010000000000000);
    let mut y = x;
    if n > 1023 {
        y *= x1p1023;
        n -= 1023;
        if n > 1023 {
            y *= x1p1023;
            n -= 1023;
            if n > 1023 {
                n = 1023;
            }
        }
    } else if n < -1022 {
        y *= x1p_1022 * x1p53;
        n += 1022 - 53;
        if n < -1022 {
            y *= x1p_1022 * x1p53;
            n += 1022 - 53;
            if n < -1022 {
                n = -1022;
            }
        }
    }
    y * f64::from_bits(((0x3ff + n) as u64) << 52)
}

const LG1: f64 = 6.666666666666735130e-01;
const LG2: f64 = 3.999999999940941908e-01;
const LG3: f64 = 2.857142874366239149e-01;
const LG4: f64 = 2.222219843214978396e-01;
const LG5: f64 = 1.818357216161805012e-01;
const LG6: f64 = 1.531383769920937332e-01;
const LG7: f64 = 1.479819860511658591e-01;

/// Shared reduction: returns (f, hfsq, s, R, k) or a special value.
fn log_reduce(x: f64) -> Result<(f64, f64, f64, f64, i32), f64> {
    let mut x = x;
    let mut ui = x.to_bits();
    let mut hx = (ui >> 32) as u32;
    let mut k: i32 = 0;
    if hx < 0x00100000 || (hx >> 31) > 0 {
        if ui << 1 == 0 {
            return Err(-1.0 / (x * x));
        }
        if hx >> 31 > 0 {
            return Err((x - x) / 0.0);
        }
        k -= 54;
        x *= f64::from_bits(0x4350000000000000);
        ui = x.to_bits();
        hx = (ui >> 32) as u32;
    } else if hx >= 0x7ff00000 {
        return Err(x);
    } else if hx == 0x3ff00000 && ui << 32 == 0 {
        return Err(0.0);
    }
    hx = hx.wrapping_add(0x3ff00000 - 0x3fe6a09e);
    k += ((hx >> 20) as i32) - 0x3ff;
    hx = (hx & 0x000fffff) + 0x3fe6a09e;
    ui = ((hx as u64) << 32) | (ui & 0xffffffff);
    x = f64::from_bits(ui);
    let f = x - 1.0;
    let hfsq = 0.5 * f * f;
    let s = f / (2.0 + f);
    let z = s * s;
    let w = z * z;
    let t1 = w * (LG2 + w * (LG4 + w * LG6));
    let t2 = z * (LG1 + w * (LG3 + w * (LG5 + w * LG7)));
    Ok((f, hfsq, s, t2 + t1, k))
}

pub fn log(x: f64) -> f64 {
    const LN2_HI: f64 = 6.93147180369123816490e-01;
    const LN2_LO: f64 = 1.90821492927058770002e-10;
    match log_reduce(x) {
        Err(v) => v,
        Ok((f, hfsq, s, r, k)) => {
            let dk = k as f64;
            s * (hfsq + r) + dk * LN2_LO - hfsq + f + dk * LN2_HI
        }
    }
}

pub fn log10(x: f64) -> f64 {
    const IVLN10HI: f64 = 4.34294481878168880939e-01;
    const IVLN10LO: f64 = 2.50829467116452752298e-11;
    const LOG10_2HI: f64 = 3.01029995663611771306e-01;
    const LOG10_2LO: f64 = 3.69423907715893078616e-13;
    match log_reduce(x) {
        Err(v) => v,
        Ok((f, hfsq, s, r, k)) => {
            let mut hi_ = f - hfsq;
            hi_ = f64::from_bits(hi_.to_bits() & (u64::MAX << 32));
            let lo = f - hi_ - hfsq + s * (hfsq + r);
            let mut val_hi = hi_ * IVLN10HI;
            let dk = k as f64;
            let y = dk * LOG10_2HI;
            let mut val_lo = dk * LOG10_2LO + (lo + hi_) * IVLN10LO + lo * IVLN10HI;
            let w = y + val_hi;
            val_lo += (y - w) + val_hi;
            val_hi = w;
            val_lo + val_hi
        }
    }
}

pub fn log2(x: f64) -> f64 {
    const IVLN2HI: f64 = 1.44269504072144627571e+00;
    const IVLN2LO: f64 = 1.67517131648865118353e-10;
    match log_reduce(x) {
        Err(v) => v,
        Ok((f, hfsq, s, r, k)) => {
            let mut hi_ = f - hfsq;
            hi_ = f64::from_bits(hi_.to_bits() & (u64::MAX << 32));
            let lo = f - hi_ - hfsq + s * (hfsq + r);
            let mut val_hi = hi_ * IVLN2HI;
            let mut val_lo = (lo + hi_) * IVLN2LO + lo * IVLN2HI;
            let y = k as f64;
            let w = y + val_hi;
            val_lo += (y - w) + val_hi;
            val_hi = w;
            val_lo + val_hi
        }
    }
}

const S1: f64 = -1.66666666666666324348e-01;
const S2: f64 = 8.33333333332248946124e-03;
const S3: f64 = -1.98412698298579493134e-04;
const S4: f64 = 2.75573137070700676789e-06;
const S5: f64 = -2.50507602534068634195e-08;
const S6: f64 = 1.58969099521155010221e-10;

fn k_sin(x: f64, y: f64, iy: i32) -> f64 {
    let z = x * x;
    let w = z * z;
    let r = S2 + z * (S3 + z * S4) + z * w * (S5 + z * S6);
    let v = z * x;
    if iy == 0 {
        x + v * (S1 + z * r)
    } else {
        x - ((z * (0.5 * y - v * r) - y) - v * S1)
    }
}

const C1: f64 = 4.16666666666666019037e-02;
const C2: f64 = -1.38888888888741095749e-03;
const C3: f64 = 2.48015872894767294178e-05;
const C4: f64 = -2.75573143513906633035e-07;
const C5: f64 = 2.08757232129817482790e-09;
const C6: f64 = -1.13596475577881948265e-11;

fn k_cos(x: f64, y: f64) -> f64 {
    let z = x * x;
    let w = z * z;
    let r = z * (C1 + z * (C2 + z * C3)) + w * w * (C4 + z * (C5 + z * C6));
    let hz = 0.5 * z;
    let w = 1.0 - hz;
    w + (((1.0 - w) - hz) + (z * r - x * y))
}

const T: [f64; 13] = [
    3.33333333333334091986e-01,
    1.33333333333201242699e-01,
    5.39682539762260521377e-02,
    2.18694882948595424599e-02,
    8.86323982359930005737e-03,
    3.59207910759131235356e-03,
    1.45620945432529025516e-03,
    5.88041240820264096874e-04,
    2.46463134818469906812e-04,
    7.81794442939557092300e-05,
    7.14072491382608190305e-05,
    -1.85586374855275456654e-05,
    2.59073051863633712884e-05,
];

fn k_tan(x: f64, y: f64, odd: i32) -> f64 {
    const PIO4: f64 = 7.85398163397448278999e-01;
    const PIO4LO: f64 = 3.06161699786838301793e-17;
    let hx = hi(x);
    let big = (hx & 0x7fffffff) >= 0x3FE59428;
    let mut x = x;
    let mut y = y;
    let mut sign = false;
    if big {
        sign = hx >> 31 != 0;
        if sign {
            x = -x;
            y = -y;
        }
        x = (PIO4 - x) + (PIO4LO - y);
        y = 0.0;
    }
    let z = x * x;
    let w = z * z;
    let mut r = T[1] + w * (T[3] + w * (T[5] + w * (T[7] + w * (T[9] + w * T[11]))));
    let mut v = z * (T[2] + w * (T[4] + w * (T[6] + w * (T[8] + w * (T[10] + w * T[12])))));
    let mut s = z * x;
    r = y + z * (s * (r + v) + y) + s * T[0];
    let w = x + r;
    if big {
        s = (1 - 2 * odd) as f64;
        v = s - 2.0 * (x + (w * w) / (w + s));
        return if sign { -v } else { v };
    }
    if odd == 0 {
        return w;
    }
    let w0 = f64::from_bits(w.to_bits() & 0xffffffff00000000);
    let v = r - (w0 - x);
    let a = -1.0 / w;
    let a0 = f64::from_bits(a.to_bits() & 0xffffffff00000000);
    a0 + a * (1.0 + a0 * w0 + a0 * v)
}

/// Argument reduction for |x| < 2^20 * pi/2. Returns None for larger inputs.
fn rem_pio2(x: f64) -> Option<(i32, f64, f64)> {
    const TOINT: f64 = 1.5 / f64::EPSILON;
    const PIO4: f64 = 0.785398163397448278999;
    const INVPIO2: f64 = 6.36619772367581382433e-01;
    const PIO2_1: f64 = 1.57079632673412561417e+00;
    const PIO2_1T: f64 = 6.07710050650619224932e-11;
    const PIO2_2: f64 = 6.07710050630396597660e-11;
    const PIO2_2T: f64 = 2.02226624879595063154e-21;
    const PIO2_3: f64 = 2.02226624871116645580e-21;
    const PIO2_3T: f64 = 8.47842766036889956997e-32;
    let sign = (x.to_bits() >> 63) != 0;
    let ix = hi(x) & 0x7fffffff;
    let medium = |x: f64, ix: u32| -> (i32, f64, f64) {
        let mut f_n = x * INVPIO2 + TOINT - TOINT;
        let mut n = f_n as i32;
        let mut r = x - f_n * PIO2_1;
        let mut w = f_n * PIO2_1T;
        if r - w < -PIO4 {
            n -= 1;
            f_n -= 1.0;
            r = x - f_n * PIO2_1;
            w = f_n * PIO2_1T;
        } else if r - w > PIO4 {
            n += 1;
            f_n += 1.0;
            r = x - f_n * PIO2_1;
            w = f_n * PIO2_1T;
        }
        let mut y0 = r - w;
        let ey = ((y0.to_bits() >> 52) & 0x7ff) as i32;
        let ex = (ix >> 20) as i32;
        if ex - ey > 16 {
            let t = r;
            w = f_n * PIO2_2;
            r = t - w;
            w = f_n * PIO2_2T - ((t - r) - w);
            y0 = r - w;
            let ey = ((y0.to_bits() >> 52) & 0x7ff) as i32;
            if ex - ey > 49 {
                let t = r;
                w = f_n * PIO2_3;
                r = t - w;
                w = f_n * PIO2_3T - ((t - r) - w);
                y0 = r - w;
            }
        }
        let y1 = (r - y0) - w;
        (n, y0, y1)
    };
    if ix <= 0x400f6a7a {
        if (ix & 0xfffff) == 0x921fb {
            return Some(medium(x, ix));
        }
        if ix <= 0x4002d97c {
            if !sign {
                let z = x - PIO2_1;
                let y0 = z - PIO2_1T;
                let y1 = (z - y0) - PIO2_1T;
                return Some((1, y0, y1));
            } else {
                let z = x + PIO2_1;
                let y0 = z + PIO2_1T;
                let y1 = (z - y0) + PIO2_1T;
                return Some((-1, y0, y1));
            }
        } else if !sign {
            let z = x - 2.0 * PIO2_1;
            let y0 = z - 2.0 * PIO2_1T;
            let y1 = (z - y0) - 2.0 * PIO2_1T;
            return Some((2, y0, y1));
        } else {
            let z = x + 2.0 * PIO2_1;
            let y0 = z + 2.0 * PIO2_1T;
            let y1 = (z - y0) + 2.0 * PIO2_1T;
            return Some((-2, y0, y1));
        }
    }
    if ix <= 0x401c463b {
        if ix <= 0x4015fdbc {
            if ix == 0x4012d97c {
                return Some(medium(x, ix));
            }
            if !sign {
                let z = x - 3.0 * PIO2_1;
                let y0 = z - 3.0 * PIO2_1T;
                let y1 = (z - y0) - 3.0 * PIO2_1T;
                return Some((3, y0, y1));
            } else {
                let z = x + 3.0 * PIO2_1;
                let y0 = z + 3.0 * PIO2_1T;
                let y1 = (z - y0) + 3.0 * PIO2_1T;
                return Some((-3, y0, y1));
            }
        } else {
            if ix == 0x401921fb {
                return Some(medium(x, ix));
            }
            if !sign {
                let z = x - 4.0 * PIO2_1;
                let y0 = z - 4.0 * PIO2_1T;
                let y1 = (z - y0) - 4.0 * PIO2_1T;
                return Some((4, y0, y1));
            } else {
                let z = x + 4.0 * PIO2_1;
                let y0 = z + 4.0 * PIO2_1T;
                let y1 = (z - y0) + 4.0 * PIO2_1T;
                return Some((-4, y0, y1));
            }
        }
    }
    if ix < 0x413921fb {
        return Some(medium(x, ix));
    }
    None
}

pub fn sin(x: f64) -> f64 {
    let ix = hi(x) & 0x7fffffff;
    if ix <= 0x3fe921fb {
        if ix < 0x3e500000 {
            return x;
        }
        return k_sin(x, 0.0, 0);
    }
    if ix >= 0x7ff00000 {
        return x - x;
    }
    match rem_pio2(x) {
        Some((n, y0, y1)) => match n & 3 {
            0 => k_sin(y0, y1, 1),
            1 => k_cos(y0, y1),
            2 => -k_sin(y0, y1, 1),
            _ => -k_cos(y0, y1),
        },
        None => x.sin(),
    }
}

pub fn cos(x: f64) -> f64 {
    let ix = hi(x) & 0x7fffffff;
    if ix <= 0x3fe921fb {
        if ix < 0x3e46a09e {
            return 1.0;
        }
        return k_cos(x, 0.0);
    }
    if ix >= 0x7ff00000 {
        return x - x;
    }
    match rem_pio2(x) {
        Some((n, y0, y1)) => match n & 3 {
            0 => k_cos(y0, y1),
            1 => -k_sin(y0, y1, 1),
            2 => -k_cos(y0, y1),
            _ => k_sin(y0, y1, 1),
        },
        None => x.cos(),
    }
}

pub fn tan(x: f64) -> f64 {
    let ix = hi(x) & 0x7fffffff;
    if ix <= 0x3fe921fb {
        if ix < 0x3e400000 {
            return x;
        }
        return k_tan(x, 0.0, 0);
    }
    if ix >= 0x7ff00000 {
        return x - x;
    }
    match rem_pio2(x) {
        Some((n, y0, y1)) => k_tan(y0, y1, n & 1),
        None => x.tan(),
    }
}

pub fn cbrt(x: f64) -> f64 {
    const B1: u32 = 715094163;
    const B2: u32 = 696219795;
    const P0: f64 = 1.87595182427177009643;
    const P1: f64 = -1.88497979543377169875;
    const P2: f64 = 1.621429720105354466140;
    const P3: f64 = -0.758397934778766047437;
    const P4: f64 = 0.145996192886612446982;
    let mut ui = x.to_bits();
    let mut hx = ((ui >> 32) as u32) & 0x7fffffff;
    if hx >= 0x7ff00000 {
        return x + x;
    }
    if hx < 0x00100000 {
        ui = (x * f64::from_bits(0x4350000000000000)).to_bits();
        hx = ((ui >> 32) as u32) & 0x7fffffff;
        if hx == 0 {
            return x;
        }
        hx = hx / 3 + B2;
    } else {
        hx = hx / 3 + B1;
    }
    ui &= 1u64 << 63;
    ui |= (hx as u64) << 32;
    let mut t = f64::from_bits(ui);
    let r = (t * t) * (t / x);
    t = t * ((P0 + r * (P1 + r * P2)) + ((r * r) * r) * (P3 + r * P4));
    let ui = (t.to_bits().wrapping_add(0x80000000)) & 0xffffffffc0000000;
    t = f64::from_bits(ui);
    let s = t * t;
    let mut r = x / s;
    let w = t + t;
    r = (r - t) / (w + r);
    t + t * r
}

pub fn atan(x: f64) -> f64 {
    const ATANHI: [f64; 4] = [
        4.63647609000806093515e-01,
        7.85398163397448278999e-01,
        9.82793723247329054082e-01,
        1.57079632679489655800e+00,
    ];
    const ATANLO: [f64; 4] = [
        2.26987774529616870924e-17,
        3.06161699786838301793e-17,
        1.39033110312309984516e-17,
        6.12323399573676603587e-17,
    ];
    const AT: [f64; 11] = [
        3.33333333333329318027e-01,
        -1.99999999998764832476e-01,
        1.42857142725034663711e-01,
        -1.11111104054623557880e-01,
        9.09088713343650656196e-02,
        -7.69187620504482999495e-02,
        6.66107313738753120669e-02,
        -5.83357013379057348645e-02,
        4.97687799461593236017e-02,
        -3.65315727442169155270e-02,
        1.62858201153657823623e-02,
    ];
    let hxs = hi(x);
    let sign = hxs >> 31 != 0;
    let ix = hxs & 0x7fffffff;
    let mut x = x;
    if ix >= 0x44100000 {
        if x.is_nan() {
            return x;
        }
        let z = ATANHI[3];
        return if sign { -z } else { z };
    }
    let id: i32;
    if ix < 0x3fdc0000 {
        if ix < 0x3e400000 {
            return x;
        }
        id = -1;
    } else {
        x = x.abs();
        if ix < 0x3ff30000 {
            if ix < 0x3fe60000 {
                id = 0;
                x = (2.0 * x - 1.0) / (2.0 + x);
            } else {
                id = 1;
                x = (x - 1.0) / (x + 1.0);
            }
        } else if ix < 0x40038000 {
            id = 2;
            x = (x - 1.5) / (1.0 + 1.5 * x);
        } else {
            id = 3;
            x = -1.0 / x;
        }
    }
    let z = x * x;
    let w = z * z;
    let s1 = z * (AT[0] + w * (AT[2] + w * (AT[4] + w * (AT[6] + w * (AT[8] + w * AT[10])))));
    let s2 = w * (AT[1] + w * (AT[3] + w * (AT[5] + w * (AT[7] + w * AT[9]))));
    if id < 0 {
        return x - x * (s1 + s2);
    }
    let z = ATANHI[id as usize] - (x * (s1 + s2) - ATANLO[id as usize] - x);
    if sign {
        -z
    } else {
        z
    }
}

pub fn cosh(x: f64) -> f64 {
    let ax = x.abs();
    let w = hi(ax);
    if w < 0x3fe62e42 {
        if w < 0x3ff00000 - (26 << 20) {
            return 1.0;
        }
        let t = ax.exp_m1();
        return 1.0 + t * t / (2.0 * (1.0 + t));
    }
    if w < 0x40862e42 {
        let t = exp(ax);
        return 0.5 * (t + 1.0 / t);
    }
    ax.cosh()
}
