/// Very rough page estimation for paged documents.
pub struct PageEstimator {
    pub page: usize,
    used: f64,
    par_chars: usize,
    pub pages_of: std::collections::HashMap<u64, usize>,
    auto_height: bool,
}

const CPL: f64 = 94.5;
const LPP: f64 = 50.0;
const PAR_GAP: f64 = 0.43;

impl PageEstimator {
    pub fn new() -> Self {
        PageEstimator { page: 1, used: 0.0, par_chars: 0, pages_of: Default::default(), auto_height: false }
    }

    fn add(&mut self, lines: f64) {
        self.used += lines;
        if self.auto_height {
            return;
        }
        while self.used > LPP + 1e-9 {
            self.page += 1;
            self.used -= LPP;
        }
    }

    fn flush(&mut self) {
        if self.par_chars > 0 {
            let lines = (self.par_chars as f64 / CPL).ceil();
            self.add(lines + PAR_GAP);
            self.par_chars = 0;
        }
    }

    fn record(&mut self, c: &Content) {
        if let Some(l) = c.location() {
            self.pages_of.insert(l.0, self.page);
        }
    }

    pub fn walk(&mut self, c: &Content) {
        match c.func_name() {
            "sequence" => {
                for ch in c.children() {
                    self.walk(&ch);
                }
                self.record(c);
            }
            "styled" => {
                if let Some(Value::Styles(st)) = c.get("styles") {
                    for s in st.0.iter() {
                        if let Style::Property { elem, field, value, .. } = s {
                            if elem.name == "page" && *field == "height" && matches!(value, Value::Auto) {
                                self.auto_height = true;
                            }
                        }
                    }
                }
                if let Some(Value::Content(ch)) = c.get("child") {
                    self.walk(ch);
                }
            }
            "text" | "symbol" | "smartquote" => {
                self.par_chars += c.plain_text().chars().count();
                self.record(c);
            }
            "space" => self.par_chars += 1,
            "linebreak" => {
                let used = (self.par_chars as f64 / CPL).ceil();
                self.par_chars = 0;
                self.add(used);
            }
            "parbreak" => self.flush(),
            "pagebreak" => {
                self.flush();
                if !matches!(c.get("weak"), Some(Value::Bool(true))) || self.used > 0.0 {
                    self.page += 1;
                    self.used = 0.0;
                }
                self.record(c);
            }
            "heading" => {
                self.flush();
                let level = match c.get("level") {
                    Some(Value::Int(l)) => *l,
                    _ => 1,
                };
                let h = if level == 1 { 2.4 } else { 2.0 };
                if self.used + h > LPP && !self.auto_height {
                    self.page += 1;
                    self.used = 0.0;
                }
                self.record(c);
                self.add(h);
            }
            "list" | "enum" | "terms" => {
                self.flush();
                self.record(c);
                for it in c.children() {
                    let t = it.plain_text().chars().count().max(1);
                    self.add((t as f64 / (CPL - 3.0)).ceil() + 0.25);
                    self.record(&it);
                }
                self.add(PAR_GAP);
            }
            "equation" => {
                if matches!(c.get("block"), Some(Value::Bool(true))) {
                    self.flush();
                    self.record(c);
                    self.add(2.6);
                } else {
                    self.par_chars += 4;
                    self.record(c);
                }
            }
            "raw" => {
                if matches!(c.get("block"), Some(Value::Bool(true))) {
                    self.flush();
                    self.record(c);
                    let n = c.get_str("text").map(|t| t.split('\n').count()).unwrap_or(1);
                    self.add(n as f64 * 1.0 + PAR_GAP);
                } else {
                    self.par_chars += c.plain_text().chars().count();
                    self.record(c);
                }
            }
            "table" | "grid" => {
                self.flush();
                self.record(c);
                let cols = match c.get("columns") {
                    Some(Value::Array(a)) if !a.is_empty() => a.len(),
                    _ => 1,
                };
                let rows = (c.children().len() + cols - 1) / cols.max(1);
                self.add(rows as f64 * 1.6 + PAR_GAP);
            }
            "figure" => {
                self.flush();
                self.record(c);
                let h = match c.body() {
                    Some(b) if b.is("image") => 20.0,
                    Some(b) if b.is("table") => {
                        let cols = match b.get("columns") {
                            Some(Value::Array(a)) if !a.is_empty() => a.len(),
                            _ => 1,
                        };
                        ((b.children().len() + cols - 1) / cols.max(1)) as f64 * 1.6
                    }
                    Some(b) => (b.plain_text().chars().count() as f64 / CPL).ceil().max(1.0),
                    None => 1.0,
                };
                self.add(h + 2.5);
                if let Some(Value::Content(cap)) = c.get("caption") {
                    self.record(cap);
                }
            }
            "image" => {
                self.record(c);
                self.add(20.0);
            }
            "block" | "rect" | "box" | "align" | "pad" | "quote" | "columns" | "place" | "stack" => {
                if c.func_name() == "box" {
                    self.par_chars += c.plain_text().chars().count();
                    self.record(c);
                    return;
                }
                self.flush();
                self.record(c);
                if let Some(b) = c.body() {
                    self.walk(&b);
                }
                self.flush();
            }
            "v" => {
                self.flush();
                if let Some(Value::Length(l)) = c.get("amount") {
                    self.add(l.abs / 14.0 + l.em * 11.0 / 14.0);
                } else if let Some(Value::Fraction(_)) = c.get("amount") {
                    // fills the rest of the page
                }
            }
            _ => {
                self.record(c);
                if let Some(b) = c.body() {
                    self.walk(&b);
                }
            }
        }
    }
}
