fn strip_comment(s: &str) -> String {
    let mut out = String::new();
    let mut in_s = false;
    let mut in_d = false;
    let chars: Vec<char> = s.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if c == '\'' && !in_d {
            in_s = !in_s;
        } else if c == '"' && !in_s {
            in_d = !in_d;
        } else if c == '#' && !in_s && !in_d && (i == 0 || chars[i - 1] == ' ' || chars[i - 1] == '\t') {
            break;
        }
        out.push(c);
    }
    out.trim_end().to_string()
}

pub fn yaml_scalar(s: &str) -> Value {
    let t = s.trim();
    if t.is_empty() || t == "~" || t == "null" || t == "Null" || t == "NULL" {
        return Value::None;
    }
    match t {
        "true" | "True" | "TRUE" => return Value::Bool(true),
        "false" | "False" | "FALSE" => return Value::Bool(false),
        ".inf" | ".Inf" | ".INF" | "+.inf" => return Value::Float(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => return Value::Float(f64::NEG_INFINITY),
        ".nan" | ".NaN" | ".NAN" => return Value::Float(f64::NAN),
        _ => {}
    }
    if let Some(q) = t.strip_prefix('\'').and_then(|x| x.strip_suffix('\'')) {
        return Value::str(q.replace("''", "'"));
    }
    if t.starts_with('"') && t.ends_with('"') && t.len() >= 2 {
        return Value::str(unescape_dq(&t[1..t.len() - 1]));
    }
    let digits = t.strip_prefix(['+', '-']).unwrap_or(t);
    if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
        if let Ok(i) = t.parse::<i64>() {
            return Value::Int(i);
        }
    }
    if let Some(h) = t.strip_prefix("0x") {
        if let Ok(i) = i64::from_str_radix(h, 16) {
            return Value::Int(i);
        }
    }
    if let Some(o) = t.strip_prefix("0o") {
        if let Ok(i) = i64::from_str_radix(o, 8) {
            return Value::Int(i);
        }
    }
    if t.chars().next().is_some_and(|c| c.is_ascii_digit() || c == '-' || c == '+' || c == '.') && t.chars().any(|c| c.is_ascii_digit()) {
        if let Ok(f) = t.parse::<f64>() {
            return Value::Float(f);
        }
    }
    Value::str(t)
}

fn unescape_dq(s: &str) -> String {
    let mut out = String::new();
    let mut it = s.chars();
    while let Some(c) = it.next() {
        if c == '\\' {
            match it.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('r') => out.push('\r'),
                Some('0') => out.push('\0'),
                Some('"') => out.push('"'),
                Some('\\') => out.push('\\'),
                Some('/') => out.push('/'),
                Some('x') => {
                    let h: String = it.by_ref().take(2).collect();
                    if let Some(ch) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) {
                        out.push(ch);
                    }
                }
                Some('u') => {
                    let h: String = it.by_ref().take(4).collect();
                    if let Some(ch) = u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) {
                        out.push(ch);
                    }
                }
                Some(o) => {
                    out.push('\\');
                    out.push(o);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn split_flow(s: &str) -> Vec<String> {
    let mut parts = vec![];
    let mut depth = 0;
    let mut cur = String::new();
    let mut in_s = false;
    let mut in_d = false;
    for c in s.chars() {
        match c {
            '\'' if !in_d => in_s = !in_s,
            '"' if !in_s => in_d = !in_d,
            '[' | '{' if !in_s && !in_d => depth += 1,
            ']' | '}' if !in_s && !in_d => depth -= 1,
            ',' if depth == 0 && !in_s && !in_d => {
                parts.push(std::mem::take(&mut cur));
                continue;
            }
            _ => {}
        }
        cur.push(c);
    }
    if !cur.trim().is_empty() {
        parts.push(cur);
    }
    parts
}

fn find_colon(s: &str) -> Option<usize> {
    let mut in_s = false;
    let mut in_d = false;
    let mut depth = 0;
    let b: Vec<(usize, char)> = s.char_indices().collect();
    for (k, &(i, c)) in b.iter().enumerate() {
        match c {
            '\'' if !in_d => in_s = !in_s,
            '"' if !in_s => in_d = !in_d,
            '[' | '{' if !in_s && !in_d => depth += 1,
            ']' | '}' if !in_s && !in_d => depth -= 1,
            ':' if !in_s && !in_d && depth == 0 => {
                let next = b.get(k + 1).map(|x| x.1);
                if next.is_none() || next == Some(' ') || next == Some('\t') {
                    return Some(i);
                }
            }
            _ => {}
        }
    }
    None
}

fn yaml_flow(s: &str) -> Value {
    let t = s.trim();
    if let Some(inner) = t.strip_prefix('[').and_then(|x| x.strip_suffix(']')) {
        return Value::array(split_flow(inner).iter().map(|p| yaml_flow(p)).collect());
    }
    if let Some(inner) = t.strip_prefix('{').and_then(|x| x.strip_suffix('}')) {
        let mut d = Dict::new();
        for p in split_flow(inner) {
            let (k, v) = match find_colon(&p) {
                Some(i) => (p[..i].trim().to_string(), yaml_flow(&p[i + 1..])),
                None => (p.trim().to_string(), Value::None),
            };
            let key = match yaml_scalar(&k) {
                Value::Str(s) => s.to_string(),
                other => crate::repr::display_for_str(&other).unwrap_or(k),
            };
            d.insert(Rc::from(key.as_str()), v);
        }
        return Value::dict(d);
    }
    yaml_scalar(t)
}

struct YParser {
    lines: Vec<YLine>,
    pos: usize,
}

impl YParser {
    fn parse_node(&mut self, indent: usize) -> Result<Value, String> {
        if self.pos >= self.lines.len() {
            return Ok(Value::None);
        }
        let l = &self.lines[self.pos];
        if l.indent < indent {
            return Ok(Value::None);
        }
        let ind = l.indent;
        if l.text == "-" || l.text.starts_with("- ") {
            self.parse_seq(ind)
        } else if find_colon(&l.text).is_some() {
            self.parse_map(ind)
        } else {
            // multi-line plain scalar
            let mut parts = vec![l.text.clone()];
            self.pos += 1;
            while self.pos < self.lines.len() && self.lines[self.pos].indent >= ind && find_colon(&self.lines[self.pos].text).is_none() {
                parts.push(self.lines[self.pos].text.clone());
                self.pos += 1;
            }
            Ok(yaml_flow(&parts.join(" ")))
        }
    }

    fn block_scalar(&mut self, header: &str, parent_indent: usize) -> Value {
        let literal = header.starts_with('|');
        let chomp = if header.contains('-') { '-' } else if header.contains('+') { '+' } else { ' ' };
        let mut lines: Vec<String> = vec![];
        let mut block_indent = None;
        while self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            if l.text.is_empty() {
                lines.push(String::new());
                self.pos += 1;
                continue;
            }
            if l.indent <= parent_indent {
                break;
            }
            let bi = *block_indent.get_or_insert(l.indent);
            if l.indent < bi {
                break;
            }
            lines.push(format!("{}{}", " ".repeat(l.indent - bi), l.text));
            self.pos += 1;
        }
        while lines.last().is_some_and(|l| l.is_empty()) && chomp != '+' {
            lines.pop();
        }
        let mut text = if literal {
            lines.join("\n")
        } else {
            let mut out = String::new();
            for (i, l) in lines.iter().enumerate() {
                if i > 0 {
                    if l.is_empty() || lines[i - 1].is_empty() {
                        out.push('\n');
                    } else {
                        out.push(' ');
                    }
                }
                out.push_str(l);
            }
            out
        };
        if chomp != '-' && !text.is_empty() {
            text.push('\n');
        }
        Value::str(text)
    }

    fn value_after(&mut self, rest: &str, indent: usize) -> Result<Value, String> {
        let rest = rest.trim();
        if rest.is_empty() {
            if self.pos < self.lines.len() && (self.lines[self.pos].indent > indent || (self.lines[self.pos].indent == indent && self.lines[self.pos].text.starts_with('-'))) {
                let ni = self.lines[self.pos].indent;
                return self.parse_node(ni);
            }
            return Ok(Value::None);
        }
        if rest.starts_with('|') || rest.starts_with('>') {
            return Ok(self.block_scalar(rest, indent));
        }
        Ok(yaml_flow(rest))
    }

    fn parse_seq(&mut self, indent: usize) -> Result<Value, String> {
        let mut items = vec![];
        while self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            if l.indent != indent || !(l.text == "-" || l.text.starts_with("- ")) {
                break;
            }
            let rest = l.text[1..].trim_start().to_string();
            let item_indent = indent + (l.text.len() - rest.len());
            self.pos += 1;
            if rest.is_empty() {
                items.push(self.value_after("", indent)?);
            } else if rest == "-" || rest.starts_with("- ") || find_colon(&rest).is_some() && !rest.starts_with('{') && !rest.starts_with('[') && !rest.starts_with('"') && !rest.starts_with('\'') {
                // nested inline node: re-insert as a line
                self.pos -= 1;
                self.lines[self.pos] = YLine { indent: item_indent, text: rest, line: self.lines[self.pos].line };
                items.push(self.parse_node(item_indent)?);
            } else {
                items.push(self.value_after(&rest, indent)?);
            }
        }
        Ok(Value::array(items))
    }

    fn parse_map(&mut self, indent: usize) -> Result<Value, String> {
        let mut d = Dict::new();
        while self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            if l.indent != indent {
                if l.indent > indent {
                    return Err(format!("mapping values are not allowed in this context at line {} column {}", l.line, l.indent + 1));
                }
                break;
            }
            let Some(ci) = find_colon(&l.text) else { break };
            let key_raw = l.text[..ci].trim().to_string();
            let rest = l.text[ci + 1..].to_string();
            self.pos += 1;
            let key = match yaml_scalar(&key_raw) {
                Value::Str(s) => s.to_string(),
                other => crate::repr::display_for_str(&other).unwrap_or(key_raw),
            };
            let v = self.value_after(&rest, indent)?;
            d.insert(Rc::from(key.as_str()), v);
        }
        Ok(Value::dict(d))
    }
}

pub fn parse_yaml(text: &str) -> Result<Value, String> {
    let mut lines = vec![];
    for (i, raw) in text.lines().enumerate() {
        if raw.trim_start().starts_with('#') || raw.trim() == "---" || raw.trim() == "..." {
            continue;
        }
        let s = strip_comment(raw);
        let indent = s.len() - s.trim_start().len();
        let t = s.trim_start().to_string();
        if t.is_empty() {
            lines.push(YLine { indent: 0, text: String::new(), line: i + 1 });
            continue;
        }
        lines.push(YLine { indent, text: t, line: i + 1 });
    }
    // drop empty lines except inside block scalars (kept for block scalar handling)
    let mut p = YParser { lines, pos: 0 };
    // skip leading empties
    while p.pos < p.lines.len() && p.lines[p.pos].text.is_empty() {
        p.pos += 1;
    }
    let mut filtered = vec![];
    let mut in_block = false;
    let mut block_parent = 0;
    for l in p.lines.drain(..) {
        if l.text.is_empty() {
            if in_block {
                filtered.push(l);
            }
            continue;
        }
        if in_block && l.indent <= block_parent {
            in_block = false;
        }
        let ends_block = l.text.ends_with('|') || l.text.ends_with('>') || l.text.ends_with("|-") || l.text.ends_with(">-") || l.text.ends_with("|+") || l.text.ends_with(">+");
        if ends_block {
            in_block = true;
            block_parent = l.indent;
        }
        filtered.push(l);
    }
    let mut p = YParser { lines: filtered, pos: 0 };
    if p.lines.is_empty() {
        return Ok(Value::None);
    }
    let ind = p.lines[0].indent;
    let v = p.parse_node(ind)?;
    Ok(v)
}

// ---------------- TOML ----------------

struct TParser<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> TParser<'a> {
    fn ws(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t') {
            self.i += 1;
        }
    }
    fn ws_nl(&mut self) {
        loop {
            while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') {
                self.i += 1;
            }
            if self.i < self.s.len() && self.s[self.i] == b'#' {
                while self.i < self.s.len() && self.s[self.i] != b'\n' {
                    self.i += 1;
                }
                continue;
            }
            break;
        }
    }
    fn key(&mut self) -> Result<Vec<String>, String> {
        let mut parts = vec![];
        loop {
            self.ws();
            if self.i >= self.s.len() {
                return Err("expected key".into());
            }
            let c = self.s[self.i];
            if c == b'"' || c == b'\'' {
                parts.push(self.string()?);
            } else {
                let st = self.i;
                while self.i < self.s.len() && (self.s[self.i].is_ascii_alphanumeric() || matches!(self.s[self.i], b'_' | b'-')) {
                    self.i += 1;
                }
                if st == self.i {
                    return Err(format!("invalid key at byte {}", self.i));
                }
                parts.push(String::from_utf8_lossy(&self.s[st..self.i]).to_string());
            }
            self.ws();
            if self.i < self.s.len() && self.s[self.i] == b'.' {
                self.i += 1;
                continue;
            }
            return Ok(parts);
        }
    }
    fn string(&mut self) -> Result<String, String> {
        let q = self.s[self.i];
        let multi = self.s[self.i..].starts_with(if q == b'"' { b"\"\"\"" } else { b"'''" });
        if multi {
            self.i += 3;
            if self.i < self.s.len() && self.s[self.i] == b'\n' {
                self.i += 1;
            }
            let delim: &[u8] = if q == b'"' { b"\"\"\"" } else { b"'''" };
            let st = self.i;
            while self.i < self.s.len() && !self.s[self.i..].starts_with(delim) {
                self.i += 1;
            }
            let raw = String::from_utf8_lossy(&self.s[st..self.i]).to_string();
            self.i += 3;
            return Ok(if q == b'"' { unescape_dq(&raw) } else { raw });
        }
        self.i += 1;
        let st = self.i;
        let mut esc = false;
        while self.i < self.s.len() {
            let c = self.s[self.i];
            if c == b'\n' {
                return Err("unterminated string".into());
            }
            if q == b'"' && c == b'\\' && !esc {
                esc = true;
                self.i += 1;
                continue;
            }
            if c == q && !esc {
                break;
            }
            esc = false;
            self.i += 1;
        }
        let raw = String::from_utf8_lossy(&self.s[st..self.i]).to_string();
        self.i += 1;
        Ok(if q == b'"' { unescape_dq(&raw) } else { raw })
    }
    fn value(&mut self) -> Result<Value, String> {
        self.ws();
        if self.i >= self.s.len() {
            return Err("expected value".into());
        }
        let c = self.s[self.i];
        match c {
            b'"' | b'\'' => Ok(Value::str(self.string()?)),
            b'[' => {
                self.i += 1;
                let mut v = vec![];
                loop {
                    self.ws_nl();
                    if self.i < self.s.len() && self.s[self.i] == b']' {
                        self.i += 1;
                        break;
                    }
                    v.push(self.value()?);
                    self.ws_nl();
                    if self.i < self.s.len() && self.s[self.i] == b',' {
                        self.i += 1;
                    }
                }
                Ok(Value::array(v))
            }
            b'{' => {
                self.i += 1;
                let mut d = Dict::new();
                loop {
                    self.ws();
                    if self.i < self.s.len() && self.s[self.i] == b'}' {
                        self.i += 1;
                        break;
                    }
                    let k = self.key()?;
                    self.ws();
                    if self.i >= self.s.len() || self.s[self.i] != b'=' {
                        return Err("expected `=`".into());
                    }
                    self.i += 1;
                    let v = self.value()?;
                    insert_path(&mut d, &k, v);
                    self.ws();
                    if self.i < self.s.len() && self.s[self.i] == b',' {
                        self.i += 1;
                    }
                }
                Ok(Value::dict(d))
            }
            _ => {
                let st = self.i;
                while self.i < self.s.len() && !matches!(self.s[self.i], b',' | b']' | b'}' | b'\n' | b'\r' | b'#') {
                    self.i += 1;
                }
                let t = String::from_utf8_lossy(&self.s[st..self.i]).trim().to_string();
                match t.as_str() {
                    "true" => return Ok(Value::Bool(true)),
                    "false" => return Ok(Value::Bool(false)),
                    "inf" | "+inf" => return Ok(Value::Float(f64::INFINITY)),
                    "-inf" => return Ok(Value::Float(f64::NEG_INFINITY)),
                    "nan" | "+nan" | "-nan" => return Ok(Value::Float(f64::NAN)),
                    _ => {}
                }
                let clean = t.replace('_', "");
                if let Some(h) = clean.strip_prefix("0x") {
                    return i64::from_str_radix(h, 16).map(Value::Int).map_err(|e| e.to_string());
                }
                if let Some(h) = clean.strip_prefix("0o") {
                    return i64::from_str_radix(h, 8).map(Value::Int).map_err(|e| e.to_string());
                }
                if let Some(h) = clean.strip_prefix("0b") {
                    return i64::from_str_radix(h, 2).map(Value::Int).map_err(|e| e.to_string());
                }
                if let Ok(i) = clean.parse::<i64>() {
                    return Ok(Value::Int(i));
                }
                if let Ok(f) = clean.parse::<f64>() {
                    return Ok(Value::Float(f));
                }
                // dates
                if let Some(dt) = parse_toml_datetime(&t) {
                    return Ok(Value::Datetime(dt));
                }
                Err(format!("invalid value `{t}`"))
            }
        }
    }
}

fn parse_toml_datetime(t: &str) -> Option<Datetime> {
    let (date_part, time_part) = match t.split_once(['T', ' ']) {
        Some((d, tm)) => (Some(d), Some(tm)),
        None => {
            if t.contains(':') {
                (None, Some(t))
            } else {
                (Some(t), None)
            }
        }
    };
    let date = match date_part {
        Some(d) => {
            let p: Vec<&str> = d.split('-').collect();
            if p.len() != 3 {
                return None;
            }
            Some((p[0].parse().ok()?, p[1].parse().ok()?, p[2].parse().ok()?))
        }
        None => None,
    };
    let time = match time_part {
        Some(tm) => {
            let tm = tm.trim_end_matches('Z');
            let tm = tm.split(['+', '.']).next()?;
            let p: Vec<&str> = tm.split(':').collect();
            if p.len() < 2 {
                return None;
            }
            Some((p[0].parse().ok()?, p[1].parse().ok()?, p.get(2).and_then(|s| s.parse().ok()).unwrap_or(0)))
        }
        None => None,
    };
    Some(Datetime { date, time })
}

fn insert_path(d: &mut Dict, path: &[String], v: Value) {
    if path.len() == 1 {
        d.insert(Rc::from(path[0].as_str()), v);
        return;
    }
    let k = &path[0];
    let mut inner = match d.get(k) {
        Some(Value::Dict(x)) => (**x).clone(),
        _ => Dict::new(),
    };
    insert_path(&mut inner, &path[1..], v);
    d.insert(Rc::from(k.as_str()), Value::dict(inner));
}

fn get_table<'b>(root: &'b mut Dict, path: &[String], array_last: bool) -> &'b mut Dict {
    let mut cur = root;
    for (i, k) in path.iter().enumerate() {
        let last = i + 1 == path.len();
        if !cur.contains(k) {
            cur.insert(Rc::from(k.as_str()), if last && array_last { Value::array(vec![]) } else { Value::dict(Dict::new()) });
        }
        let slot = cur.get_mut(k).unwrap();
        match slot {
            Value::Array(a) => {
                let a = Rc::make_mut(a);
                if a.is_empty() || !matches!(a.last(), Some(Value::Dict(_))) {
                    a.push(Value::dict(Dict::new()));
                }
                let Value::Dict(d) = a.last_mut().unwrap() else { unreachable!() };
                cur = Rc::make_mut(d);
            }
            Value::Dict(d) => cur = Rc::make_mut(d),
            other => {
                *other = Value::dict(Dict::new());
                let Value::Dict(d) = other else { unreachable!() };
                cur = Rc::make_mut(d);
            }
        }
    }
    cur
}

pub fn parse_toml(text: &str) -> Result<Value, String> {
    let mut root = Dict::new();
    let mut current: Vec<String> = vec![];
    let mut p = TParser { s: text.as_bytes(), i: 0 };
    loop {
        p.ws_nl();
        if p.i >= p.s.len() {
            break;
        }
        if p.s[p.i] == b'[' {
            let arr = p.s[p.i..].starts_with(b"[[");
            p.i += if arr { 2 } else { 1 };
            let k = p.key()?;
            p.ws();
            p.i += if arr { 2 } else { 1 };
            if arr {
                // push a new table into the array
                let (parent, last) = k.split_at(k.len() - 1);
                let t = get_table(&mut root, parent, false);
                let entry = t.get_mut(&last[0]);
                match entry {
                    Some(Value::Array(a)) => Rc::make_mut(a).push(Value::dict(Dict::new())),
                    _ => t.insert(Rc::from(last[0].as_str()), Value::array(vec![Value::dict(Dict::new())])),
                }
            } else {
                get_table(&mut root, &k, false);
            }
            current = k;
            continue;
        }
        let k = p.key()?;
        p.ws();
        if p.i >= p.s.len() || p.s[p.i] != b'=' {
            return Err("expected an equals, found a newline".into());
        }
        p.i += 1;
        let v = p.value()?;
        let t = get_table(&mut root, &current, false);
        insert_path(t, &k, v);
    }
    Ok(Value::dict(root))
}

fn toml_key(k: &str) -> String {
    if !k.is_empty() && k.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
        k.to_string()
    } else {
        toml_str(k)
    }
}

fn toml_str(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn toml_value(v: &Value, pretty: bool, indent: usize) -> Result<String, String> {
    Ok(match v {
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => {
            if f.is_nan() {
                "nan".into()
            } else if f.is_infinite() {
                if *f > 0.0 { "inf".into() } else { "-inf".into() }
            } else {
                let s = format!("{:?}", f);
                s
            }
        }
        Value::Str(s) => toml_str(s),
        Value::Array(a) => {
            if a.is_empty() {
                "[]".into()
            } else if pretty {
                let mut out = String::from("[\n");
                for x in a.iter() {
                    out.push_str(&" ".repeat(indent + 4));
                    out.push_str(&toml_value(x, pretty, indent + 4)?);
                    out.push_str(",\n");
                }
                out.push_str(&" ".repeat(indent));
                out.push(']');
                out
            } else {
                let parts: Result<Vec<String>, String> = a.iter().map(|x| toml_value(x, pretty, indent)).collect();
                format!("[{}]", parts?.join(", "))
            }
        }
        Value::Dict(d) => {
            let parts: Result<Vec<String>, String> =
                d.iter().map(|(k, x)| toml_value(x, false, 0).map(|s| format!("{} = {}", toml_key(k), s))).collect();
            format!("{{ {} }}", parts?.join(", "))
        }
        Value::None => return Err("unsupported unit type".into()),
        other => toml_str(&crate::repr::repr(other)),
    })
}

fn toml_table(d: &Dict, prefix: &str, pretty: bool, out: &mut String) -> Result<(), String> {
    for (k, v) in d.iter() {
        match v {
            Value::Dict(_) => {}
            Value::Array(a) if !a.is_empty() && a.iter().all(|x| matches!(x, Value::Dict(_))) => {}
            _ => {
                out.push_str(&format!("{} = {}\n", toml_key(k), toml_value(v, pretty, 0)?));
            }
        }
    }
    for (k, v) in d.iter() {
        let name = if prefix.is_empty() { toml_key(k) } else { format!("{}.{}", prefix, toml_key(k)) };
        match v {
            Value::Dict(inner) => {
                if !out.is_empty() {
                    out.push('\n');
                }
                out.push_str(&format!("[{}]\n", name));
                toml_table(inner, &name, pretty, out)?;
            }
            Value::Array(a) if !a.is_empty() && a.iter().all(|x| matches!(x, Value::Dict(_))) => {
                for x in a.iter() {
                    if let Value::Dict(inner) = x {
                        if !out.is_empty() {
                            out.push('\n');
                        }
                        out.push_str(&format!("[[{}]]\n", name));
                        toml_table(inner, &name, pretty, out)?;
                    }
                }
            }
            _ => {}
        }
    }
    Ok(())
}

pub fn encode_toml(v: &Value, pretty: bool) -> Result<String, String> {
    match v {
        Value::Dict(d) => {
            let mut out = String::new();
            toml_table(d, "", pretty, &mut out)?;
            Ok(out)
        }
        other => Err(format!("expected dictionary, found {}", other.type_name())),
    }
}

// ---------------- XML ----------------

pub fn parse_xml(text: &str) -> Result<Value, String> {
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    fn skip_misc(chars: &[char], i: &mut usize) {
        loop {
            while *i < chars.len() && chars[*i].is_whitespace() {
                *i += 1;
            }
            let rest: String = chars[*i..chars.len().min(*i + 4)].iter().collect();
            if rest.starts_with("<?") {
                while *i < chars.len() && !(chars[*i] == '>' && chars[*i - 1] == '?') {
                    *i += 1;
                }
                *i += 1;
            } else if rest.starts_with("<!--") {
                *i += 4;
                while *i + 2 < chars.len() && !(chars[*i] == '-' && chars[*i + 1] == '-' && chars[*i + 2] == '>') {
                    *i += 1;
                }
                *i += 3;
            } else if rest.starts_with("<!") {
                while *i < chars.len() && chars[*i] != '>' {
                    *i += 1;
                }
                *i += 1;
            } else {
                break;
            }
        }
    }
    fn unescape(s: &str) -> String {
        s.replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&apos;", "'").replace("&amp;", "&")
    }
    fn elem(chars: &[char], i: &mut usize) -> Result<Value, String> {
        // at '<'
        *i += 1;
        let st = *i;
        while *i < chars.len() && !chars[*i].is_whitespace() && chars[*i] != '>' && chars[*i] != '/' {
            *i += 1;
        }
        let tag: String = chars[st..*i].iter().collect();
        let mut attrs = Dict::new();
        loop {
            while *i < chars.len() && chars[*i].is_whitespace() {
                *i += 1;
            }
            if *i >= chars.len() {
                return Err("unexpected end of input".into());
            }
            if chars[*i] == '/' {
                *i += 2;
                let mut d = Dict::new();
                d.insert(Rc::from("tag"), Value::str(&tag));
                d.insert(Rc::from("attrs"), Value::dict(attrs));
                d.insert(Rc::from("children"), Value::array(vec![]));
                return Ok(Value::dict(d));
            }
            if chars[*i] == '>' {
                *i += 1;
                break;
            }
            let ks = *i;
            while *i < chars.len() && chars[*i] != '=' && !chars[*i].is_whitespace() {
                *i += 1;
            }
            let k: String = chars[ks..*i].iter().collect();
            while *i < chars.len() && (chars[*i] == '=' || chars[*i].is_whitespace()) {
                *i += 1;
            }
            let q = chars[*i];
            *i += 1;
            let vs = *i;
            while *i < chars.len() && chars[*i] != q {
                *i += 1;
            }
            let v: String = chars[vs..*i].iter().collect();
            *i += 1;
            attrs.insert(Rc::from(k.as_str()), Value::str(unescape(&v)));
        }
        let mut children = vec![];
        loop {
            if *i >= chars.len() {
                return Err("unexpected end of input".into());
            }
            if chars[*i] == '<' {
                if chars.get(*i + 1) == Some(&'/') {
                    while *i < chars.len() && chars[*i] != '>' {
                        *i += 1;
                    }
                    *i += 1;
                    break;
                }
                if chars.get(*i + 1) == Some(&'!') {
                    skip_misc(chars, i);
                    continue;
                }
                children.push(elem(chars, i)?);
            } else {
                let ts = *i;
                while *i < chars.len() && chars[*i] != '<' {
                    *i += 1;
                }
                let t: String = chars[ts..*i].iter().collect();
                children.push(Value::str(unescape(&t)));
            }
        }
        let mut d = Dict::new();
        d.insert(Rc::from("tag"), Value::str(&tag));
        d.insert(Rc::from("attrs"), Value::dict(attrs));
        d.insert(Rc::from("children"), Value::array(children));
        Ok(Value::dict(d))
    }
    skip_misc(&chars, &mut i);
    let mut out = vec![];
    while i < chars.len() {
        if chars[i] == '<' {
            out.push(elem(&chars, &mut i)?);
            skip_misc(&chars, &mut i);
        } else {
            i += 1;
        }
    }
    Ok(Value::array(out))
}
