//! Syntax highlighting of Typst code for HTML raw output.

use crate::html::{HElem, HNode};
use crate::syntax::kind::SyntaxKind as K;
use crate::syntax::node::SyntaxNode;

#[derive(Clone)]
struct Leaf<'a> {
    node: &'a SyntaxNode,
    parents: Vec<(K, usize)>, // (kind, index of child within parent)
}

fn collect<'a>(n: &'a SyntaxNode, parents: &mut Vec<(K, usize)>, out: &mut Vec<Leaf<'a>>) {
    if n.children.is_empty() {
        out.push(Leaf { node: n, parents: parents.clone() });
        return;
    }
    for (i, c) in n.children.iter().enumerate() {
        parents.push((n.kind, i));
        collect(c, parents, out);
        parents.pop();
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Tag {
    Keyword,
    Number,
    Str,
    Function,
    Comment,
    Raw,
    Escape,
    ListMarker,
    MathDelim,
    MathOp,
    None,
}

fn color(t: Tag) -> Option<&'static str> {
    Some(match t {
        Tag::Keyword => "#d73948",
        Tag::Number => "#b60157",
        Tag::Str => "#198810",
        Tag::Function => "#4b69c6",
        Tag::Comment => "#74747c",
        Tag::Raw => "#6b6b6f",
        Tag::Escape => "#1d6c76",
        Tag::ListMarker => "#8b41b1",
        Tag::MathDelim => "#198810",
        Tag::MathOp => "#1d6c76",
        Tag::None => return None,
    })
}

fn parent_kind(l: &Leaf) -> Option<K> {
    l.parents.last().map(|p| p.0)
}

fn has_ancestor(l: &Leaf, k: K) -> bool {
    l.parents.iter().any(|p| p.0 == k)
}

fn ident_is_function(leaves: &[Leaf], i: usize) -> bool {
    if let Some(next) = leaves.get(i + 1) {
        let pk = parent_kind(next);
        if next.node.kind == K::LeftParen && matches!(pk, Some(K::Args) | Some(K::Params)) {
            return true;
        }
        if next.node.kind == K::LeftBracket && pk == Some(K::ContentBlock) && next.parents.len() >= 2 && next.parents[next.parents.len() - 2].0 == K::Args {
            return true;
        }
    }
    // show rule target
    let l = &leaves[i];
    let mut depth = l.parents.len();
    while depth > 0 && l.parents[depth - 1].0 == K::FieldAccess {
        depth -= 1;
    }
    if depth > 0 && l.parents[depth - 1].0 == K::ShowRule {
        let next_non_trivia = leaves[i + 1..].iter().find(|x| !x.node.kind.is_trivia());
        if next_non_trivia.is_some_and(|x| x.node.kind == K::Colon) {
            return true;
        }
    }
    // set rule target
    if depth > 0 && l.parents[depth - 1].0 == K::SetRule {
        return true;
    }
    false
}

fn leaf_tag(leaves: &[Leaf], i: usize) -> Tag {
    let l = &leaves[i];
    let k = l.node.kind;
    if has_ancestor(l, K::Raw) {
        return Tag::Raw;
    }
    match k {
        K::LineComment | K::BlockComment => Tag::Comment,
        K::Linebreak | K::Escape | K::Shorthand | K::Label | K::MathShorthand => Tag::Escape,
        K::RefMarker => Tag::Escape,
        K::ListMarker | K::EnumMarker | K::TermMarker => Tag::ListMarker,
        K::Dollar => Tag::MathDelim,
        K::MathAlignPoint => Tag::MathOp,
        K::Hat | K::Underscore if has_ancestor(l, K::Math) => Tag::MathOp,
        K::Slash if has_ancestor(l, K::Math) => Tag::MathOp,
        K::Hash => {
            // highlight like the following leaf
            match leaves.get(i + 1) {
                Some(_) => leaf_tag(leaves, i + 1),
                None => Tag::None,
            }
        }
        K::Let | K::Set | K::Show | K::Context | K::If | K::Else | K::For | K::In | K::While | K::Break
        | K::Continue | K::Return | K::Import | K::Include | K::As | K::None | K::Auto | K::Bool | K::Not
        | K::And | K::Or => Tag::Keyword,
        K::Plus | K::Minus | K::Slash | K::Eq | K::EqEq | K::ExclEq | K::Lt | K::LtEq | K::Gt | K::GtEq
        | K::PlusEq | K::HyphEq | K::StarEq | K::SlashEq | K::Dots | K::Arrow => Tag::Keyword,
        K::Star if !has_ancestor(l, K::Strong) => Tag::Keyword,
        K::Int | K::Float | K::Numeric => Tag::Number,
        K::Str => Tag::Str,
        K::Ident => {
            if ident_is_function(leaves, i) {
                Tag::Function
            } else {
                Tag::None
            }
        }
        _ => Tag::None,
    }
}

pub fn highlight(text: &str, lang: &str) -> Vec<HNode> {
    let root = match lang {
        "typc" => crate::syntax::parser::parse_code(text),
        "typm" => crate::syntax::parser::parse_math(text),
        _ => crate::syntax::parser::parse(text),
    };
    let mut leaves = vec![];
    collect(&root, &mut vec![], &mut leaves);
    let mut out: Vec<HNode> = vec![];
    for i in 0..leaves.len() {
        let l = &leaves[i];
        let t = l.node.full_text();
        if t.is_empty() {
            continue;
        }
        let tag = leaf_tag(&leaves, i);
        let mut node = HNode::Text(t.clone());
        let strong = has_ancestor(l, K::Strong)
            || has_ancestor(l, K::Heading)
            || (has_ancestor(l, K::TermItem) && {
                // term part: Markup before the colon
                l.parents.iter().position(|p| p.0 == K::TermItem).is_some_and(|pi| {
                    pi + 1 < l.parents.len() && l.parents[pi + 1].0 == K::Markup && l.parents[pi].1 <= 2
                })
            });
        if has_ancestor(l, K::Emph) {
            node = HNode::Elem(HElem { tag: "em".into(), attrs: vec![], children: vec![node] });
        }
        if strong && !l.node.kind.is_trivia() || (has_ancestor(l, K::Heading) && l.node.kind.is_trivia()) {
            node = HNode::Elem(HElem { tag: "strong".into(), attrs: vec![], children: vec![node] });
        }
        if has_ancestor(l, K::Heading) || l.node.kind == K::Link {
            node = HNode::Elem(HElem {
                tag: "span".into(),
                attrs: vec![("style".into(), "text-decoration: underline".into())],
                children: vec![node],
            });
        }
        if let Some(c) = color(tag) {
            node = HNode::Elem(HElem { tag: "span".into(), attrs: vec![("style".into(), format!("color: {c}"))], children: vec![node] });
        }
        // merge plain text
        match (&node, out.last_mut()) {
            (HNode::Text(t), Some(HNode::Text(prev))) => prev.push_str(t),
            _ => out.push(node),
        }
    }
    out
}
